fn document_with_field_parts(
    document_xml: &str,
    settings_xml: Option<&str>,
    custom_properties_xml: Option<&str>,
) -> Document {
    let mut seed = Document::new();
    let bytes = seed.to_bytes().unwrap();
    let mut package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).unwrap();
    package.set_part("/word/document.xml", document_xml.as_bytes().to_vec());
    if let Some(settings_xml) = settings_xml {
        package.set_part("/word/settings.xml", settings_xml.as_bytes().to_vec());
        package.content_types.add_override(
            "/word/settings.xml",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml",
        );
        package
            .get_or_create_part_rels("/word/document.xml")
            .add(oxml_opc::relationship::rel_types::SETTINGS, "settings.xml");
    }
    if let Some(custom_properties_xml) = custom_properties_xml {
        package.set_part(
            "/metadata/producer-properties.xml",
            custom_properties_xml.as_bytes().to_vec(),
        );
        package.content_types.add_override(
            "/metadata/producer-properties.xml",
            oxml_opc::content_types::CUSTOM_PROPERTIES,
        );
        package.package_rels.add(
            oxml_opc::relationship::rel_types::CUSTOM_PROPERTIES,
            "metadata/producer-properties.xml",
        );
    }
    let mut output = std::io::Cursor::new(Vec::new());
    package.write_to(&mut output).unwrap();
    Document::from_bytes(output.get_ref()).unwrap()
}

fn toc_entry_signatures(xml: &str) -> Vec<(String, String, Option<String>, Option<String>)> {
    let document = CT_Document::from_xml(xml.as_bytes()).unwrap();
    document
        .body
        .content
        .iter()
        .filter_map(|content| {
            let BodyContent::Paragraph(paragraph) = content else {
                return None;
            };
            let style = paragraph
                .properties
                .as_ref()
                .and_then(|properties| properties.style_id.as_deref())?;
            style.starts_with("TOC").then(|| {
                let mut display = paragraph.text();
                let mut page_target = None;
                for run in paragraph.runs() {
                    for content in &run.content {
                        if let rdocx_oxml::text::RunContent::Field(field) = content
                            && field.instruction.name == "PAGEREF"
                        {
                            let displayed_page = format!("\t{}", field.cached_result);
                            if !display.ends_with(&displayed_page) {
                                display.push_str(&field.cached_result);
                            }
                            page_target =
                                field.instruction.arguments.first().and_then(|argument| {
                                    let rdocx_oxml::text::FieldArgument::Text(value) = argument
                                    else {
                                        return None;
                                    };
                                    Some(value.clone())
                                });
                        }
                    }
                }
                (
                    display,
                    style.to_owned(),
                    paragraph
                        .hyperlinks
                        .first()
                        .and_then(|hyperlink| hyperlink.anchor.clone()),
                    page_target,
                )
            })
        })
        .collect()
}

fn f248_toc_records(xml: &str) -> Vec<String> {
    toc_entry_signatures(xml)
        .into_iter()
        .map(|(display, style, _, _)| {
            let (content, page) = display
                .rsplit_once('\t')
                .expect("F-248 TOC entry has a page separator");
            let title = ["Body", "Table", "Deep"]
                .into_iter()
                .find(|title| content.ends_with(title))
                .expect("F-248 TOC entry has a known title");
            let marker = content
                .strip_suffix(title)
                .unwrap()
                .trim_end_matches([' ', '\t']);
            format!("{style} | {marker} | {title} | {page}")
        })
        .collect()
}

#[test]
fn every_supported_field_matches_the_pinned_word_result() {
    assert_eq!(
        WORD_FIELD_ORACLE,
        "Microsoft Word 16.104 build 16.104.25121423"
    );
    assert_eq!(
        WORD_FIELD_ORACLE_ENVIRONMENT,
        "locale=en-US; calendar=Gregorian; decimal=.; grouping=,; timezone=UTC"
    );
    assert_eq!(WORD_FIELD_ORACLE_INPUT, "F-161-readable-field-matrix-v1");

    let body = r#"
        <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:bookmarkStart w:id="7" w:name="destination"/><w:r><w:t>Introduction</w:t></w:r><w:bookmarkEnd w:id="7"/></w:p>
        <w:p><w:fldSimple w:instr="IF &quot;10&quot; &gt;= &quot;2&quot; &quot;yes&quot; &quot;no&quot;"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="REF destination"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="PAGEREF destination"><w:r><w:t>1</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="SEQ Figure"><w:r><w:t>0</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="DOCPROPERTY Title"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="DOCVARIABLE Region"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="STYLEREF &quot;Heading 1&quot;"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="INCLUDETEXT &quot;chapter.docx&quot;"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="DATE \@ &quot;MMMM d, yyyy&quot;"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="TIME \@ &quot;h:mm AM/PM&quot;"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="FILENAME"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="AUTHOR"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="MERGEFIELD Name \* Upper"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="PAGE"><w:r><w:t>1</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="NUMPAGES"><w:r><w:t>1</w:t></w:r></w:fldSimple></w:p>
    "#;
    let settings = r#"<q:settings xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><q:docVars><q:docVar q:name="Region" q:val="West"/></q:docVars></q:settings>"#;
    let mut document = document_with_field_parts(&wrap_word_body(body), Some(settings), None);
    document.set_title("Oracle title");
    document.set_author("Ada Lovelace");
    let context = FieldEvaluationContext {
        now: Some(FieldDateTime {
            year: 2025,
            month: 12,
            day: 14,
            hour: 21,
            minute: 7,
            second: 5,
        }),
        file_name: Some("report.docx".to_owned()),
        file_path: Some("/templates/report.docx".to_owned()),
        merge_fields: BTreeMap::from([("Name".to_owned(), "Grace".to_owned())]),
        included_text: BTreeMap::from([("chapter.docx".to_owned(), "Included chapter".to_owned())]),
        merge_record_number: None,
        merge_sequence_number: None,
    };
    let actual = document
        .evaluate_fields(&context)
        .unwrap()
        .into_iter()
        .map(|evaluation| evaluation.outcome)
        .collect::<Vec<_>>();
    let expected = vec![
        FieldOutcome::Resolved("yes".to_owned()),
        FieldOutcome::Resolved("Introduction".to_owned()),
        FieldOutcome::DeferredPagination,
        FieldOutcome::Resolved("1".to_owned()),
        FieldOutcome::Resolved("Oracle title".to_owned()),
        FieldOutcome::Resolved("West".to_owned()),
        FieldOutcome::Resolved("Introduction".to_owned()),
        FieldOutcome::Resolved("Included chapter".to_owned()),
        FieldOutcome::Resolved("December 14, 2025".to_owned()),
        FieldOutcome::Resolved("9:07 PM".to_owned()),
        FieldOutcome::Resolved("report.docx".to_owned()),
        FieldOutcome::Resolved("Ada Lovelace".to_owned()),
        FieldOutcome::Resolved("GRACE".to_owned()),
        FieldOutcome::DeferredPagination,
        FieldOutcome::DeferredPagination,
    ];
    assert_eq!(actual, expected, "{WORD_FIELD_ORACLE_INPUT}");
}

fn top_level_field_caches<'a>(
    paragraphs: impl IntoIterator<Item = &'a CT_P>,
) -> Vec<(String, String, Option<bool>)> {
    paragraphs
        .into_iter()
        .flat_map(CT_P::runs)
        .flat_map(|run| &run.content)
        .filter_map(|content| match content {
            rdocx_oxml::text::RunContent::Field(field) => Some((
                field.instruction.name.clone(),
                field.cached_result.clone(),
                field.dirty,
            )),
            _ => None,
        })
        .collect()
}

#[test]
fn update_page_fields_writes_body_and_nested_caches_preserving_footer_sources() {
    fn complex_field(instruction: &str, cached: &str) -> String {
        format!(
            r#"<w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText xml:space="preserve"> {instruction} </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>{cached}</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r>"#
        )
    }

    let mut seed = Document::new();
    let mut package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap())).unwrap();
    let (first_footer_id, footer_id, even_footer_id) = {
        let relationships = package.get_or_create_part_rels("/word/document.xml");
        (
            relationships.add(oxml_opc::relationship::rel_types::FOOTER, "footer1.xml"),
            relationships.add(oxml_opc::relationship::rel_types::FOOTER, "footer1.xml"),
            relationships.add(oxml_opc::relationship::rel_types::FOOTER, "footer2.xml"),
        )
    };
    assert_ne!(first_footer_id, footer_id);
    for (part_name, paragraph) in [
        (
            "/word/footer1.xml",
            format!(
                r#"<w:r><w:t xml:space="preserve">Page </w:t></w:r>{}<w:r><w:t xml:space="preserve"> of </w:t></w:r>{}"#,
                complex_field("PAGE", "7"),
                complex_field("NUMPAGES", "9")
            ),
        ),
        ("/word/footer2.xml", complex_field("PAGE", "7")),
    ] {
        package.set_part(
            part_name,
            format!(r#"<w:ftr xmlns:w="{W_NS}"><w:p>{paragraph}</w:p></w:ftr>"#).into_bytes(),
        );
        package.content_types.add_override(
            part_name,
            "application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml",
        );
    }
    let nested_if = format!(
        r#"<w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText xml:space="preserve"> IF </w:instrText></w:r>{}<w:r><w:instrText xml:space="preserve"> = 2 "two" "other" </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>other</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r>"#,
        complex_field("PAGE", "5")
    );
    let body = format!(
        r#"<w:p><w:pPr><w:sectPr><w:footerReference w:type="default" r:id="{first_footer_id}"/></w:sectPr></w:pPr><w:r><w:t>Page one.</w:t></w:r><w:fldSimple w:instr="AUTHOR"><w:r><w:t>stale author</w:t></w:r></w:fldSimple></w:p><w:p><w:r><w:t xml:space="preserve">Body </w:t></w:r>{}{}{}{nested_if}<w:fldSimple w:instr=" NUMPAGES "><w:r><w:t>9</w:t></w:r></w:fldSimple></w:p><w:sectPr><w:footerReference w:type="default" r:id="{footer_id}"/><w:footerReference w:type="even" r:id="{even_footer_id}"/></w:sectPr>"#,
        complex_field("PAGE", "7"),
        complex_field(r"PAGE \* roman", "x"),
        complex_field(r"PAGE \* CardText", "stale words"),
    );
    package.set_part(
        "/word/document.xml",
        format!(
            r#"<?xml version="1.0"?><w:document xmlns:w="{W_NS}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body>{body}</w:body></w:document>"#
        )
        .into_bytes(),
    );
    let mut bytes = std::io::Cursor::new(Vec::new());
    package.write_to(&mut bytes).unwrap();
    let mut document = Document::from_bytes(bytes.get_ref()).unwrap();

    // The shared footer part is laid out once per relationship, and each
    // placement keeps the identity of its own relationship.
    let layout = document.layout_deterministic().unwrap();
    let placed = layout
        .layout
        .pages
        .iter()
        .map(|page| {
            let mut fields = Vec::new();
            oxml_layout::walk(&page.elements, &mut |element, _| {
                if let rdocx_layout::PositionedElement::Text(run) = element
                    && run.field_kind == Some(oxml_layout::FieldKind::Page)
                    && let Some(field) = run.field_source
                {
                    let path = layout.source_node(field.node).unwrap();
                    fields.push((path.story.clone(), path.children.clone(), field.index));
                }
            });
            fields
        })
        .collect::<Vec<_>>();
    assert_eq!(placed.len(), 2);
    let footer_story = |relationship_id: &str| rdocx_layout::WordStory::Footer {
        relationship_id: relationship_id.to_owned(),
    };
    assert_eq!(
        placed[0],
        vec![(footer_story(&first_footer_id), vec![0], 0)]
    );
    for index in 0..3 {
        assert!(placed[1].contains(&(rdocx_layout::WordStory::Document, vec![1], index)));
    }
    assert!(placed[1].contains(&(footer_story(&footer_id), vec![0], 0)));
    drop(layout);

    assert_eq!(document.update_page_fields().unwrap(), 4);
    let updated = document.to_bytes().unwrap();
    assert_eq!(document.update_page_fields().unwrap(), 4);
    assert_eq!(document.to_bytes().unwrap(), updated);

    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(updated)).unwrap();
    let document_xml = package.get_part("/word/document.xml").unwrap();
    let body = CT_Document::from_xml(document_xml).unwrap().body;
    let paragraphs = body.content.iter().filter_map(|content| match content {
        BodyContent::Paragraph(paragraph) => Some(paragraph),
        _ => None,
    });
    let caches = |values: &[(&str, &str, Option<bool>)]| {
        values
            .iter()
            .map(|(name, cached, dirty)| ((*name).to_owned(), (*cached).to_owned(), *dirty))
            .collect::<Vec<_>>()
    };
    assert_eq!(
        top_level_field_caches(paragraphs),
        caches(&[
            ("AUTHOR", "stale author", None),
            ("PAGE", "2", Some(false)),
            ("PAGE", "ii", Some(false)),
            ("PAGE", "stale words", None),
            ("IF", "other", None),
            ("NUMPAGES", "2", Some(false)),
        ])
    );
    assert!(
        !String::from_utf8_lossy(document_xml).contains("<w:t>5</w:t>"),
        "the nested instruction PAGE uses its outer field placement"
    );
    let nested_page = body
        .content
        .iter()
        .filter_map(|content| match content {
            BodyContent::Paragraph(paragraph) => Some(paragraph),
            _ => None,
        })
        .flat_map(|paragraph| &paragraph.runs)
        .flat_map(|run| &run.content)
        .find_map(|content| match content {
            rdocx_oxml::text::RunContent::Field(field) if field.instruction.name == "IF" => field
                .instruction
                .arguments
                .iter()
                .find_map(|argument| match argument {
                    rdocx_oxml::text::FieldArgument::Nested(child) => Some(child.as_ref()),
                    _ => None,
                }),
            _ => None,
        })
        .unwrap();
    assert_eq!(nested_page.instruction.name, "PAGE");
    assert_eq!(nested_page.cached_result, "2");
    assert_eq!(nested_page.dirty, Some(false));
    let footer = |part_name: &str| {
        rdocx_oxml::header_footer::CT_HdrFtr::from_xml(package.get_part(part_name).unwrap())
            .unwrap()
    };
    assert_eq!(
        top_level_field_caches(&footer("/word/footer1.xml").paragraphs),
        caches(&[("PAGE", "7", None), ("NUMPAGES", "9", None)])
    );
    assert_eq!(
        top_level_field_caches(&footer("/word/footer2.xml").paragraphs),
        caches(&[("PAGE", "7", None)]),
        "the even footer is not laid out while even and odd headers are off"
    );
}

#[test]
fn update_page_fields_formats_page_caches_in_the_owning_section() {
    let body = r#"<w:p><w:fldSimple w:instr="PAGE"><w:r><w:t>7</w:t></w:r></w:fldSimple><w:fldSimple w:instr="NUMPAGES"><w:r><w:t>9</w:t></w:r></w:fldSimple></w:p><w:sectPr><w:pgNumType w:fmt="lowerRoman"/></w:sectPr>"#;
    let mut document = document_with_field_parts(&wrap_word_body(body), None, None);
    assert_eq!(document.update_page_fields().unwrap(), 2);
    let body = body_from_document(&mut document);
    let paragraphs = body.content.iter().filter_map(|content| match content {
        BodyContent::Paragraph(paragraph) => Some(paragraph),
        _ => None,
    });
    assert_eq!(
        top_level_field_caches(paragraphs),
        vec![
            ("PAGE".to_owned(), "i".to_owned(), Some(false)),
            ("NUMPAGES".to_owned(), "1".to_owned(), Some(false)),
        ]
    );

    let mut unchanged = Document::new();
    unchanged.add_paragraph("no page fields");
    let before = unchanged.to_bytes().unwrap();
    assert_eq!(unchanged.update_page_fields().unwrap(), 0);
    assert_eq!(unchanged.to_bytes().unwrap(), before);
}

#[test]
fn layout_backed_page_fields_update_cached_results() {
    let body = r#"
        <w:p><w:fldSimple w:instr="PAGE"><w:r><w:t>stale page</w:t></w:r></w:fldSimple><w:fldSimple w:instr="NUMPAGES"><w:r><w:t>stale count</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:pPr><w:pStyle w:val="TOC1"/></w:pPr><w:fldSimple w:instr="PAGEREF destination"><w:r><w:t>stale TOC page</w:t></w:r></w:fldSimple></w:p>
        <w:tbl><w:tr><w:tc><w:p><w:fldSimple w:instr="PAGEREF destination"><w:r><w:t>stale table page</w:t></w:r></w:fldSimple></w:p></w:tc></w:tr></w:tbl>
        <w:p><w:pPr><w:pageBreakBefore/></w:pPr><w:bookmarkStart w:id="7" w:name="destination"/><w:r><w:t>Target</w:t></w:r><w:bookmarkEnd w:id="7"/></w:p>
    "#;
    let mut document = document_with_field_parts(&wrap_word_body(body), None, None);

    let report = document.update_layout_backed_fields().unwrap();
    assert_eq!(report.page_fields, 1);
    assert_eq!(report.num_pages_fields, 1);
    assert_eq!(report.page_reference_fields, 2);
    assert_eq!(report.updated_count(), 4);

    let xml = document_xml(&mut document);
    for stale in [
        "stale page",
        "stale count",
        "stale TOC page",
        "stale table page",
    ] {
        assert!(!xml.contains(stale), "{stale} cache was not refreshed");
    }
    assert!(xml.contains("<w:t>1</w:t>"), "{xml}");
    assert!(xml.matches("<w:t>2</w:t>").count() >= 3, "{xml}");
}

#[test]
fn layout_backed_pageref_updates_a_directional_cached_result() {
    let body = r#"
        <w:p><w:pPr><w:bidi/></w:pPr><w:fldSimple w:instr="PAGEREF destination"><w:r><w:rPr><w:rtl/><w:lang w:val="en-US" w:bidi="ar-SA"/></w:rPr><w:t>99</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:pPr><w:pageBreakBefore/></w:pPr><w:bookmarkStart w:id="7" w:name="destination"/><w:r><w:t>Target</w:t></w:r><w:bookmarkEnd w:id="7"/></w:p>
    "#;
    let mut document = document_with_field_parts(&wrap_word_body(body), None, None);

    let report = document.update_layout_backed_fields().unwrap();
    assert_eq!(report.page_reference_fields, 1);

    let xml = document_xml(&mut document);
    assert!(!xml.contains("<w:t>99</w:t>"), "{xml}");
    assert!(xml.contains("<w:t>2</w:t>"), "{xml}");
}

#[test]
fn extended_field_families_match_the_pinned_word_result() {
    assert_eq!(
        WORD_FIELD_ORACLE,
        "Microsoft Word 16.104 build 16.104.25121423"
    );
    assert_eq!(
        WORD_FIELD_ORACLE_ENVIRONMENT,
        "locale=en-US; calendar=Gregorian; decimal=.; grouping=,; timezone=UTC"
    );
    assert_eq!(
        EXTENDED_WORD_FIELD_ORACLE_INPUT,
        "F-231-readable-field-matrix-v1"
    );

    let body = r#"
        <w:p><w:fldSimple w:instr="= 50% + 0.5"><w:r><w:t>stored formula</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="TOC \o &quot;1-3&quot; \h"><w:r><w:t>stored toc</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="TC &quot;Alpha&quot; \l 2"><w:r><w:t>stored tc</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="NEXT"><w:r><w:t>stored next</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="NEXTIF &quot;A&quot; = &quot;A&quot;"><w:r><w:t>stored nextif</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="SKIPIF &quot;A&quot; = &quot;A&quot;"><w:r><w:t>stored skipif</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="MERGEREC"><w:r><w:t>stored record</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="MERGESEQ"><w:r><w:t>stored sequence</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="DISPLAYBARCODE 0123456789012 EAN13 \x \p STD"><w:r><w:t>stored display barcode</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="MERGEBARCODE Code QR \q 3"><w:r><w:t>stored merge barcode</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="= 0.1 + 0.2"><w:r><w:t>stored decimal formula</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="TOC \o &quot;1-3&quot; \s chapter \d &quot;:&quot;"><w:r><w:t>stored sequenced toc</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="TOC \p &quot;ab&quot;"><w:r><w:t>stored invalid toc</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="TC &quot;Entry&quot; unexpected"><w:r><w:t>stored invalid tc</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:fldSimple w:instr="DISPLAYBARCODE value QR \s 9"><w:r><w:t>stored invalid barcode</w:t></w:r></w:fldSimple></w:p>
    "#;
    let document = document_with_field_parts(&wrap_word_body(body), None, None);
    let context = FieldEvaluationContext {
        merge_fields: BTreeMap::from([("Code".to_owned(), "https://example.test/42".to_owned())]),
        merge_record_number: Some(10),
        merge_sequence_number: Some(7),
        ..Default::default()
    };
    assert_eq!(
        document.evaluate_fields(&context).unwrap()[0].outcome,
        FieldOutcome::Resolved("1".to_owned()),
    );

    let actual = document
        .evaluate_fields(&context)
        .unwrap()
        .into_iter()
        .map(|evaluation| evaluation.outcome)
        .collect::<Vec<_>>();
    assert_eq!(
        actual,
        [
            FieldOutcome::Resolved("1".to_owned()),
            FieldOutcome::TableOfContents(TocField {
                heading_levels: Some((1, 3)),
                custom_styles: Vec::new(),
                entries: TocEntrySelection::None,
                sequence_identifier: None,
                bookmark: None,
                hyperlink: true,
                use_outline_levels: false,
                omit_page_number_levels: None,
                page_number_separator: None,
                entry_page_separator: None,
            }),
            FieldOutcome::TableOfContentsEntry(TcField {
                entry: "Alpha".to_owned(),
                level: 2,
                table_identifier: None,
                omit_page_number: false,
            }),
            FieldOutcome::MailMergeControl(MailMergeControl::NextRecord { record_number: 11 }),
            FieldOutcome::MailMergeControl(MailMergeControl::NextRecordIf {
                condition: true,
                record_number: 12,
            }),
            FieldOutcome::MailMergeControl(MailMergeControl::SkipRecordIf {
                condition: true,
                record_number: 12,
            }),
            FieldOutcome::MailMergeControl(MailMergeControl::RecordNumber(12)),
            FieldOutcome::MailMergeControl(MailMergeControl::SequenceNumber(7)),
            FieldOutcome::Barcode(BarcodeField {
                value: "0123456789012".to_owned(),
                kind: BarcodeKind::Ean13,
                height: None,
                scale: None,
                error_correction: None,
                point_of_sale_style: Some(rdocx::BarcodePointOfSaleStyle::Standard),
                case_style: None,
                fix_check_digit: true,
                rotation: None,
                foreground_color: None,
                background_color: None,
                display_text: false,
                add_start_stop: false,
            }),
            FieldOutcome::Barcode(BarcodeField {
                value: "https://example.test/42".to_owned(),
                kind: BarcodeKind::Qr,
                height: None,
                scale: None,
                error_correction: Some(3),
                point_of_sale_style: None,
                case_style: None,
                fix_check_digit: false,
                rotation: None,
                foreground_color: None,
                background_color: None,
                display_text: false,
                add_start_stop: false,
            }),
            FieldOutcome::Resolved("0.3".to_owned()),
            FieldOutcome::TableOfContents(TocField {
                heading_levels: Some((1, 3)),
                custom_styles: Vec::new(),
                entries: TocEntrySelection::None,
                sequence_identifier: Some("chapter".to_owned()),
                bookmark: None,
                hyperlink: false,
                use_outline_levels: false,
                omit_page_number_levels: None,
                page_number_separator: None,
                entry_page_separator: Some(":".to_owned()),
            }),
            FieldOutcome::KeepStored {
                diagnostic: "TOC page-number separator must contain exactly one character, stored display retained".to_owned(),
            },
            FieldOutcome::KeepStored {
                diagnostic: "field TC requires 1 positional operands, stored display retained".to_owned(),
            },
            FieldOutcome::KeepStored {
                diagnostic: "DISPLAYBARCODE scale must be from 10 through 1000, stored display retained".to_owned(),
            },
        ],
        "{EXTENDED_WORD_FIELD_ORACLE_INPUT}"
    );
}

#[test]
fn extended_field_updates_preserve_instruction_and_result_scaffolding() {
    let body = concat!(
        r#"<w:p xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><q:fldSimple q:instr="DISPLAYBARCODE 0123456789012 EAN13" q:dirty="0" data-token="kept"><q:r><q:rPr><q:b/></q:rPr><q:t>stored barcode</q:t><q:inside/></q:r></q:fldSimple></w:p>"#,
        r#"<w:p>"#,
        r#"<w:r><w:rPr><w:i/></w:rPr><w:fldChar w:fldCharType="begin" w:dirty="1"/></w:r>"#,
        r#"<w:r><w:instrText xml:space="preserve">= </w:instrText></w:r>"#,
        r#"<w:r><w:fldChar w:fldCharType="begin"/></w:r>"#,
        r#"<w:r><w:instrText>MERGEFIELD Amount</w:instrText></w:r>"#,
        r#"<w:r><w:fldChar w:fldCharType="separate"/><w:t>stored amount</w:t></w:r>"#,
        r#"<w:r><w:fldChar w:fldCharType="end"/></w:r>"#,
        r#"<w:r><w:instrText xml:space="preserve"> + 2</w:instrText></w:r>"#,
        r#"<w:r><w:fldChar w:fldCharType="separate"/></w:r>"#,
        r#"<w:r><w:rPr><w:u w:val="single"/></w:rPr><w:t>stored formula</w:t></w:r>"#,
        r#"<w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>"#,
        r#"<w:p><w:fldSimple w:instr="TOC" w:dirty="0"><w:r><w:t>stored toc</w:t></w:r></w:fldSimple></w:p>"#,
        r#"<w:p><w:fldSimple w:instr="TC &quot;Entry&quot; \l 2" w:dirty="0"><w:r><w:t>stored tc</w:t></w:r></w:fldSimple></w:p>"#,
        r#"<w:p><w:fldSimple w:instr="NEXT" w:dirty="0"><w:r><w:t>stored next</w:t></w:r></w:fldSimple></w:p>"#,
        r#"<w:p><w:fldSimple w:instr="PAGE" w:dirty="0"><w:r><w:t>stored page</w:t></w:r></w:fldSimple></w:p>"#,
        r#"<w:p><w:fldSimple w:instr="DATE" w:dirty="0"><w:r><w:t>stored date</w:t></w:r></w:fldSimple></w:p>"#,
        r#"<w:p><w:fldSimple w:instr="UNKNOWN" w:dirty="0"><w:r><w:t>stored unknown</w:t></w:r></w:fldSimple></w:p>"#,
    );
    let mut document = document_with_field_parts(&wrap_word_body(body), None, None);
    let context = FieldEvaluationContext {
        merge_fields: BTreeMap::from([("Amount".to_owned(), "3".to_owned())]),
        merge_record_number: Some(4),
        merge_sequence_number: Some(2),
        ..Default::default()
    };
    assert_eq!(document.update_fields(&context).unwrap(), 9);
    let saved = document.to_bytes().unwrap();
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&saved)).unwrap();
    let xml = std::str::from_utf8(package.get_part("/word/document.xml").unwrap()).unwrap();
    assert!(xml.contains("DISPLAYBARCODE 0123456789012 EAN13"), "{xml}");
    assert!(xml.contains("stored barcode"), "{xml}");
    assert!(xml.contains("data-token=\"kept\""), "{xml}");
    assert!(xml.contains("<q:b/>"), "{xml}");
    assert!(xml.contains("<q:inside/>"), "{xml}");
    assert!(xml.contains("w:dirty=\"1\""), "{xml}");
    assert_eq!(xml.matches("w:dirty=\"1\"").count(), 7, "{xml}");
    for (instruction, cache) in [
        ("TOC", "stored toc"),
        ("TC &quot;Entry&quot; \\l 2", "stored tc"),
        ("NEXT", "stored next"),
        ("PAGE", "stored page"),
        ("DATE", "stored date"),
        ("UNKNOWN", "stored unknown"),
    ] {
        assert!(xml.contains(instruction), "missing {instruction}: {xml}");
        assert!(xml.contains(cache), "missing {cache}: {xml}");
    }
    for preserved in ["MERGEFIELD Amount", "<w:i/>", "<w:u w:val=\"single\"/>"] {
        assert!(xml.contains(preserved), "missing {preserved}: {xml}");
    }

    let reopened = Document::from_bytes(&saved).unwrap();
    let evaluations = reopened.evaluate_fields(&context).unwrap();
    assert_eq!(evaluations[1].cached_result, "5");
    assert_eq!(evaluations[2].cached_result, "3");
    assert_eq!(
        evaluations[1].outcome,
        FieldOutcome::Resolved("5".to_owned())
    );
    assert!(matches!(evaluations[0].outcome, FieldOutcome::Barcode(_)));
    assert!(matches!(
        evaluations[3].outcome,
        FieldOutcome::TableOfContents(_)
    ));
    assert!(matches!(
        evaluations[4].outcome,
        FieldOutcome::TableOfContentsEntry(_)
    ));
    assert_eq!(
        evaluations[5].outcome,
        FieldOutcome::MailMergeControl(MailMergeControl::NextRecord { record_number: 5 })
    );
    assert_eq!(evaluations[6].outcome, FieldOutcome::DeferredPagination);
    assert_eq!(
        evaluations[7].outcome,
        FieldOutcome::KeepStored {
            diagnostic: "DATE requires an explicit date and time, stored display retained"
                .to_owned()
        }
    );
    assert_eq!(
        evaluations[8].outcome,
        FieldOutcome::KeepStored {
            diagnostic: "field UNKNOWN is unsupported, stored display retained".to_owned()
        }
    );
}

#[test]
fn dynamic_toc_rebuild_matches_the_pinned_word_update() {
    assert_eq!(
        WORD_FIELD_ORACLE,
        "Microsoft Word 16.104 build 16.104.25121423"
    );
    assert_eq!(
        WORD_FIELD_ORACLE_ENVIRONMENT,
        "locale=en-US; calendar=Gregorian; decimal=.; grouping=,; timezone=UTC"
    );
    assert_eq!(
        DYNAMIC_TOC_WORD_ORACLE_INPUT,
        "F-232-dynamic-toc-rebuild-v1"
    );

    let body = r#"
        <w:p data-owner="keep"><w:r data-begin="keep"><w:fldChar w:fldCharType="begin"/></w:r><w:r data-code="keep"><w:instrText xml:space="preserve"> TOC \o "1-2" \t "Appendix,2" \u \f C \h </w:instrText></w:r><w:r data-separate="keep"><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="TOC1"/></w:pPr><w:r><w:t>stale entry</w:t></w:r></w:p>
        <w:p data-end="keep"><w:r data-end-run="keep"><w:fldChar w:fldCharType="end"/></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Overview</w:t></w:r></w:p>
        <w:tbl><w:tr><w:tc><w:p><w:pPr><w:pStyle w:val="Appendix"/></w:pPr><w:r><w:t>Appendix A</w:t></w:r></w:p></w:tc></w:tr></w:tbl>
        <w:p><w:pPr><w:outlineLvl w:val="1"/></w:pPr><w:r><w:t>Outline item</w:t></w:r></w:p>
        <w:p><w:fldSimple w:instr="TC &quot;Manual entry&quot; \f C \l 2"><w:r><w:t>hidden marker</w:t></w:r></w:fldSimple></w:p>
    "#;
    let mut document = document_with_field_parts(&wrap_word_body(body), None, None);

    let report: TocRebuildReport = document.rebuild_toc().unwrap();
    assert_eq!(
        report,
        TocRebuildReport {
            entry_count: 4,
            bookmark_count: 4,
            diagnostics: Vec::new(),
        }
    );

    let xml = document_xml(&mut document);
    assert!(!xml.contains("stale entry"), "{xml}");
    assert_eq!(
        toc_entry_signatures(&xml),
        [
            (
                "Overview\t1".to_owned(),
                "TOC1".to_owned(),
                Some("_Toc1".to_owned()),
                Some("_Toc1".to_owned())
            ),
            (
                "Appendix A\t1".to_owned(),
                "TOC2".to_owned(),
                Some("_Toc2".to_owned()),
                Some("_Toc2".to_owned())
            ),
            (
                "Outline item\t1".to_owned(),
                "TOC2".to_owned(),
                Some("_Toc3".to_owned()),
                Some("_Toc3".to_owned())
            ),
            (
                "Manual entry\t1".to_owned(),
                "TOC2".to_owned(),
                Some("_Toc4".to_owned()),
                Some("_Toc4".to_owned())
            ),
        ]
    );
    assert_eq!(xml.matches("<w:pStyle w:val=\"TOC1\"").count(), 1, "{xml}");
    assert_eq!(xml.matches("<w:pStyle w:val=\"TOC2\"").count(), 3, "{xml}");
    assert_eq!(xml.matches("w:bookmarkStart").count(), 4, "{xml}");
    assert_eq!(xml.matches("w:hyperlink").count(), 8, "{xml}");
    assert_eq!(xml.matches("PAGEREF _Toc").count(), 4, "{xml}");
    assert!(xml.contains("TOC \\o \"1-2\""), "{xml}");
    assert!(xml.contains("w:fldCharType=\"end\""), "{xml}");
    let toc_style = xml.find("<w:pStyle w:val=\"TOC1\"").unwrap();
    let toc_tabs = xml[toc_style..].find("<w:tabs>").unwrap() + toc_style;
    let toc_link = xml[toc_tabs..].find("<w:hyperlink").unwrap() + toc_tabs;
    assert!(toc_style < toc_tabs && toc_tabs < toc_link, "{xml}");
    assert!(
        xml.contains("<w:fldChar w:fldCharType=\"begin\"/>"),
        "{xml}"
    );

    let body = r#"
        <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \o "1-1" \s chapter \d ":" \h</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>old first</w:t></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \t "Appendix,2" \p </w:instrText></w:r><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>DOCVARIABLE TocSeparator</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>|</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>old second</w:t></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
        <w:p><w:fldSimple w:instr="SEQ Chapter"><w:r><w:t>1</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:bookmarkStart w:id="10" w:name="existingTarget"/><w:r><w:t>Chapter title</w:t></w:r><w:bookmarkEnd w:id="10"/></w:p>
        <w:p><w:pPr><w:pStyle w:val="Appendix"/></w:pPr><w:r><w:t>Appendix B</w:t></w:r></w:p>
    "#;
    let settings = r#"<w:settings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docVars><w:docVar w:name="TocSeparator" w:val="|"/></w:docVars></w:settings>"#;
    let mut document = document_with_field_parts(&wrap_word_body(body), Some(settings), None);
    assert_eq!(
        document.rebuild_toc().unwrap(),
        TocRebuildReport {
            entry_count: 2,
            bookmark_count: 1,
            diagnostics: Vec::new(),
        }
    );
    let xml = document_xml(&mut document);
    assert!(!xml.contains("old first"), "{xml}");
    assert!(!xml.contains("old second"), "{xml}");
    assert!(xml.contains("w:anchor=\"existingTarget\""), "{xml}");
    assert_eq!(xml.matches("w:name=\"existingTarget\"").count(), 1, "{xml}");
    assert_eq!(xml.matches("w:bookmarkStart").count(), 2, "{xml}");
    assert!(xml.contains("<w:t>:</w:t>"), "{xml}");
    assert!(xml.contains("<w:t xml:space=\"preserve\">|</w:t>"), "{xml}");
    assert_eq!(
        toc_entry_signatures(&xml),
        [
            (
                "Chapter title\t1:1".to_owned(),
                "TOC1".to_owned(),
                Some("existingTarget".to_owned()),
                Some("existingTarget".to_owned())
            ),
            (
                "Appendix B|1".to_owned(),
                "TOC2".to_owned(),
                None,
                Some("_Toc1".to_owned())
            ),
        ]
    );
}

#[test]
fn toc_rebuild_accepts_trailing_style_separator_and_duplicate_style_ids() {
    let body = r#"
        <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \t "Normal,1,"</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>stale</w:t></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Normal"/></w:pPr><w:r><w:t>First heading</w:t></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Normal"/></w:pPr><w:r><w:t>Second heading</w:t></w:r></w:p>
    "#;
    let mut source = document_with_field_parts(&wrap_word_body(body), None, None);
    let mut package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(source.to_bytes().unwrap()))
            .unwrap();
    let styles = String::from_utf8(package.get_part("/word/styles.xml").unwrap().to_vec()).unwrap();
    let normal_id = styles.find("w:styleId=\"Normal\"").unwrap();
    let normal_start = styles[..normal_id].rfind("<w:style").unwrap();
    let normal_end =
        styles[normal_start..].find("</w:style>").unwrap() + normal_start + "</w:style>".len();
    let duplicate = styles[normal_start..normal_end].to_owned();
    let styles = styles.replacen("</w:styles>", &format!("{duplicate}</w:styles>"), 1);
    package.set_part("/word/styles.xml", styles.into_bytes());
    let mut bytes = std::io::Cursor::new(Vec::new());
    package.write_to(&mut bytes).unwrap();
    let mut document = Document::from_bytes(bytes.get_ref()).unwrap();

    assert!(document.validate_style_graph().is_err());
    let report = document.rebuild_toc().unwrap();
    assert_eq!(report.entry_count, 2);
    assert_eq!(report.bookmark_count, 2);
    assert_eq!(
        report.diagnostics,
        ["duplicate style ID 'Normal' used first definition while rebuilding TOC"]
    );
    assert_eq!(toc_entry_signatures(&document_xml(&mut document)).len(), 2);

    let saved = document.to_bytes().unwrap();
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(saved)).unwrap();
    let styles = std::str::from_utf8(package.get_part("/word/styles.xml").unwrap()).unwrap();
    assert_eq!(
        styles.matches("w:styleId=\"Normal\"").count(),
        2,
        "{styles}"
    );
}

fn document_with_producer_styles(body: &str, producer_styles: &str) -> Document {
    let mut source = document_with_field_parts(&wrap_word_body(body), None, None);
    let mut package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(source.to_bytes().unwrap()))
            .unwrap();
    let mut styles =
        String::from_utf8(package.get_part("/word/styles.xml").unwrap().to_vec()).unwrap();
    // The current template already carries Subtitle. Keep the producer's
    // level-only version under that ID and move the unused template version.
    if producer_styles.contains(r#"w:styleId="Subtitle""#) {
        styles = styles.replacen(
            r#"w:styleId="Subtitle""#,
            r#"w:styleId="TemplateSubtitle""#,
            1,
        );
    }
    let styles = styles.replacen("</w:styles>", &format!("{producer_styles}</w:styles>"), 1);
    package.set_part("/word/styles.xml", styles.into_bytes());
    let mut bytes = std::io::Cursor::new(Vec::new());
    package.write_to(&mut bytes).unwrap();
    Document::from_bytes(bytes.get_ref()).unwrap()
}

#[test]
fn toc_rebuild_accepts_several_defaults_of_one_style_type_and_follows_the_layout_default() {
    let body = r#"
        <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \o "1-1" \h</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>stale</w:t></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>First heading</w:t></w:r></w:p>
        <w:p><w:r><w:t>Body.</w:t></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Second heading</w:t></w:r></w:p>
    "#;
    // Google Docs exports declare several defaults of one type. The later
    // default paragraph style would start every unstyled paragraph on a new
    // page, so the rebuilt page numbers show which default was resolved.
    let mut document = document_with_producer_styles(
        body,
        concat!(
            r#"<w:style w:type="paragraph" w:default="1" w:styleId="LaterNormal"><w:name w:val="Later Normal"/><w:pPr><w:pageBreakBefore/></w:pPr></w:style>"#,
            r#"<w:style w:type="table" w:default="1" w:styleId="TableNormal"><w:name w:val="Normal Table"/></w:style>"#,
            r#"<w:style w:type="table" w:default="1" w:styleId="TableNormal2"><w:name w:val="Normal Table 2"/></w:style>"#,
        ),
    );

    assert!(document.validate_style_graph().is_err());
    let report = document.rebuild_toc().unwrap();
    assert_eq!(report.entry_count, 2);
    assert_eq!(
        report.diagnostics,
        [
            "multiple default paragraph styles used first default 'Normal' while rebuilding TOC",
            "multiple default table styles used first default 'TableNormal' while rebuilding TOC",
        ]
    );
    let entries = toc_entry_signatures(&document_xml(&mut document))
        .into_iter()
        .map(|(display, style, _, _)| (display, style))
        .collect::<Vec<_>>();
    assert_eq!(
        entries,
        [
            ("First heading\t1".to_owned(), "TOC1".to_owned()),
            ("Second heading\t1".to_owned(), "TOC1".to_owned()),
        ]
    );

    let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.layout_deterministic().unwrap().layout.pages.len(),
        1
    );
    let defaults = reopened
        .styles()
        .iter()
        .filter(|style| style.is_default())
        .map(|style| style.style_id().to_owned())
        .collect::<Vec<_>>();
    assert_eq!(
        defaults,
        ["Normal", "LaterNormal", "TableNormal", "TableNormal2"]
    );
}

#[test]
fn toc_rebuild_accepts_identity_attributes_on_the_instruction_paragraph_runs() {
    // Word writes `w:rsidR` and `w:rsidRPr` on the runs it saves, Google Docs
    // `w:rsidR`, `w:rsidDel` and `w:rsidRPr`. The rebuild parses the
    // instruction paragraph out of its part, and the retained-attribute
    // capture used to see its `w` prefix unbound and fail the whole rebuild.
    // Any other prefix the part binds failed the same way.
    let titles = [
        ("Heading1", "Chapter 1"),
        ("Heading2", "Section 1.1"),
        ("Heading1", "Chapter 2"),
        ("Heading2", "Section 2.1"),
        ("Heading1", "Chapter 3"),
        ("Heading2", "Section 3.1"),
    ];
    let body = |field: &str, entry: &str, lead: &str, packed: bool, control: bool| {
        let begin = r#"<w:fldChar w:fldCharType="begin"/>"#;
        let instruction =
            r#"<w:instrText xml:space="preserve"> TOC \o "1-3" \h \z \u </w:instrText>"#;
        let separate = r#"<w:fldChar w:fldCharType="separate"/>"#;
        let field_code = if packed {
            format!("<w:r{field}>{begin}{instruction}{separate}</w:r>")
        } else {
            [begin, instruction, separate]
                .map(|child| format!("<w:r{field}>{child}</w:r>"))
                .concat()
        };
        let mut xml = String::new();
        for (index, (_, title)) in titles.iter().enumerate() {
            xml.push_str("<w:p>");
            if index == 0 {
                xml.push_str(lead);
                xml.push_str(&field_code);
            }
            xml.push_str(&format!(
                "<w:r{entry}><w:t>{title}</w:t><w:tab/><w:t>1</w:t></w:r>"
            ));
            if index + 1 == titles.len() {
                xml.push_str(r#"<w:r><w:fldChar w:fldCharType="end"/></w:r>"#);
            }
            xml.push_str("</w:p>");
        }
        if control {
            xml = format!(
                r#"<w:sdt><w:sdtPr><w:docPartObj><w:docPartGallery w:val="Table of Contents"/><w:docPartUnique/></w:docPartObj></w:sdtPr><w:sdtContent>{xml}</w:sdtContent></w:sdt>"#
            );
        }
        for (style, title) in titles {
            xml.push_str(&format!(
                r#"<w:p><w:pPr><w:pStyle w:val="{style}"/></w:pPr><w:r><w:t>{title}</w:t></w:r></w:p><w:p><w:r><w:t>Body text.</w:t></w:r></w:p>"#
            ));
        }
        xml
    };
    let check = |label: &str, xml: &str, kept: usize| {
        let mut document = document_with_field_parts(xml, None, None);
        let report = document
            .rebuild_toc()
            .unwrap_or_else(|error| panic!("{label}: {error}"));
        assert_eq!(report.entry_count, 6, "{label}");
        assert!(report.diagnostics.is_empty(), "{label}: {report:?}");

        // The rebuilt entries replace the cached ones, so only the runs before
        // `separate` still carry an identity, and each keeps it. The rebuild
        // keeps their bytes, so no run start tag gains a declaration.
        let saved = document_xml(&mut document);
        assert_eq!(
            saved.matches(r#"="00A1B2C3""#).count(),
            kept,
            "{label}: {saved}"
        );
        assert!(
            saved
                .split("<w:r ")
                .skip(1)
                .all(|tag| !tag[..tag.find('>').unwrap()].contains("xmlns")),
            "{label}: {saved}"
        );
        assert_eq!(
            saved.matches(r#"<w:pStyle w:val="TOC"#).count(),
            6,
            "{label}: {saved}"
        );
    };
    let rsid_r = r#" w:rsidR="00A1B2C3""#;
    let rsid_rpr = r#" w:rsidRPr="00A1B2C3""#;
    let rsid_del = r#" w:rsidDel="00A1B2C3""#;
    let lead = r#"<w:r w:rsidR="00A1B2C3"><w:t xml:space="preserve">Contents </w:t></w:r>"#;
    for (label, field, entry, lead, packed, control, kept) in [
        ("no attribute", "", "", "", false, false, 0),
        ("entry runs", "", rsid_r, "", false, false, 0),
        ("w:rsidR field runs", rsid_r, "", "", false, false, 3),
        ("w:rsidRPr field runs", rsid_rpr, "", "", false, false, 3),
        ("w:rsidDel field runs", rsid_del, "", "", false, false, 3),
        ("packed field run", rsid_r, "", "", true, false, 1),
        ("block control", rsid_r, "", "", false, true, 3),
        ("packed in a block control", rsid_r, "", "", true, true, 1),
        ("run before begin", "", "", lead, false, false, 1),
    ] {
        let xml = wrap_word_body(&body(field, entry, lead, packed, control));
        check(label, &xml, kept);
    }
    for (label, declaration, field) in [
        (
            "foreign prefix",
            r#"xmlns:x="urn:producer""#.to_owned(),
            r#" x:id="00A1B2C3""#,
        ),
        (
            "w14 prefix",
            r#"xmlns:w14="http://schemas.microsoft.com/office/word/2010/wordml""#.to_owned(),
            r#" w14:id="00A1B2C3""#,
        ),
        (
            "second Word alias",
            format!(r#"xmlns:wx="{W_NS}""#),
            r#" wx:rsidRPr="00A1B2C3""#,
        ),
    ] {
        let xml = wrap_word_body(&body(field, "", "", false, false)).replacen(
            "<w:document ",
            &format!("<w:document {declaration} "),
            1,
        );
        check(label, &xml, 3);
    }
}

const ONE_HEADING_TOC_BODY: &str = r#"
    <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \o "1-1" \h</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
    <w:p><w:r><w:t>stale</w:t></w:r></w:p>
    <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
    <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Heading</w:t></w:r></w:p>
"#;

#[test]
fn toc_rebuild_retains_every_producer_style_graph_defect_the_read_surface_accepts() {
    // One producer defect per strict check. Open, save, layout, and text
    // replacement accept each of them. The `toc 1` style has no identifier an
    // entry could reference, so the rebuild creates the canonical one.
    let producer_styles = concat!(
        r#"<w:style w:type="paragraph" w:styleId=""><w:name w:val="toc 1"/></w:style>"#,
        r#"<w:style w:type="character" w:styleId="CharacterWithParagraph"><w:name w:val="Character With Paragraph"/><w:pPr><w:jc w:val="center"/></w:pPr></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="ParagraphWithTable"><w:name w:val="Paragraph With Table"/><w:tblPr><w:tblInd w:w="0" w:type="dxa"/></w:tblPr></w:style>"#,
        r#"<w:style w:type="table" w:styleId="RepeatedRegion"><w:name w:val="Repeated Region"/><w:tblStylePr w:type="firstRow"><w:rPr><w:b/></w:rPr></w:tblStylePr><w:tblStylePr w:type="firstRow"><w:rPr><w:i/></w:rPr></w:tblStylePr></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="Orphan"><w:name w:val="Orphan"/><w:basedOn w:val="Missing"/></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="OnCharacter"><w:name w:val="On Character"/><w:basedOn w:val="CharacterWithParagraph"/></w:style>"#,
        r#"<w:style w:type="character" w:styleId="CharacterNext"><w:name w:val="Character Next"/><w:next w:val="Normal"/></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="NextMissing"><w:name w:val="Next Missing"/><w:next w:val="Missing"/></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="NextCharacter"><w:name w:val="Next Character"/><w:next w:val="CharacterNext"/></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="LinkMissing"><w:name w:val="Link Missing"/><w:link w:val="Missing"/></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="LinkParagraph"><w:name w:val="Link Paragraph"/><w:link w:val="Orphan"/></w:style>"#,
        r#"<w:style w:type="character" w:styleId="OneWay"><w:name w:val="One Way"/><w:link w:val="Normal"/></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="CycleA"><w:name w:val="Cycle A"/><w:basedOn w:val="CycleB"/></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="CycleB"><w:name w:val="Cycle B"/><w:basedOn w:val="CycleA"/></w:style>"#,
    );
    let mut document = document_with_producer_styles(ONE_HEADING_TOC_BODY, producer_styles);
    let source_style_count = document.styles().len();

    assert!(document.validate_style_graph().is_err());
    let report = document.rebuild_toc().unwrap();
    assert_eq!(report.entry_count, 1);
    assert_eq!(
        report.diagnostics,
        [
            "style IDs cannot be empty",
            "character style 'CharacterWithParagraph' cannot contain paragraph properties",
            "paragraph style 'ParagraphWithTable' cannot contain table properties",
            "table style 'RepeatedRegion' repeats conditional region 'firstRow'",
            "style 'Orphan' is based on missing style 'Missing'",
            "style 'OnCharacter' cannot be based on character style 'CharacterWithParagraph'",
            "character style 'CharacterNext' cannot declare a next style",
            "style 'NextMissing' names missing next style 'Missing'",
            "paragraph style 'NextCharacter' has non-paragraph next style 'CharacterNext'",
            "style 'LinkMissing' links to missing style 'Missing'",
            "paragraph style 'LinkParagraph' cannot link to paragraph style 'Orphan'",
            "linked styles 'OneWay' and 'Normal' are not reciprocal",
            "based-on cycle contains style 'CycleA'",
            "based-on cycle contains style 'CycleB'",
        ]
        .map(|defect| format!("{defect}, retained while rebuilding TOC"))
    );
    let xml = document_xml(&mut document);
    assert!(!xml.contains(r#"<w:pStyle w:val=""/>"#), "{xml}");
    let entries = toc_entry_signatures(&xml);
    assert_eq!(entries.len(), 1);
    assert_eq!(entries[0].1, "TOC1");

    let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.styles().len(), source_style_count + 1);
    assert!(reopened.validate_style_graph().is_err());
}

#[test]
fn toc_rebuild_rejects_a_defect_its_entry_style_introduces_behind_retained_ones() {
    // The retained dangling parent must not hide the new `TOC1` style
    // completing a producer's dangling link into a one-way link.
    let mut document = document_with_producer_styles(
        ONE_HEADING_TOC_BODY,
        concat!(
            r#"<w:style w:type="paragraph" w:styleId="Orphan"><w:name w:val="Orphan"/><w:basedOn w:val="Missing"/></w:style>"#,
            r#"<w:style w:type="character" w:styleId="TOC1Char"><w:name w:val="TOC 1 Char"/><w:link w:val="TOC1"/></w:style>"#,
        ),
    );
    let before = document.to_bytes().unwrap();

    let error = document.rebuild_toc().unwrap_err();
    assert_eq!(
        error.to_string(),
        "invalid style graph: linked styles 'TOC1Char' and 'TOC1' are not reciprocal"
    );
    assert_eq!(document.to_bytes().unwrap(), before);
}

// Google Docs exports repeat style IDs and declare several defaults of one
// type. Open, save and layout accept both, so the style mutations do too.
const REPEATED_STYLE_IDS: &str = concat!(
    r#"<w:style w:type="paragraph" w:styleId="Normal"><w:name w:val="Normal Copy"/><w:pPr><w:jc w:val="center"/></w:pPr></w:style>"#,
    r#"<w:style w:type="paragraph" w:styleId="Spare"><w:name w:val="Spare"/></w:style>"#,
    r#"<w:style w:type="paragraph" w:styleId="Spare"><w:name w:val="Spare Copy"/></w:style>"#,
    r#"<w:style w:type="table" w:default="1" w:styleId="TableNormalCopy"><w:name w:val="Normal Table Copy"/></w:style>"#,
    r#"<w:style w:type="table" w:default="1" w:styleId="TableauNormal"><w:name w:val="Tableau Normal"/></w:style>"#,
);

fn definitions<'a>(document: &'a Document, style_id: &str) -> Vec<rdocx::Style<'a>> {
    document
        .styles()
        .into_iter()
        .filter(|style| style.style_id() == style_id)
        .collect()
}

#[test]
fn style_builder_convenience_matches_typed_properties() {
    let mut document = Document::new();
    document
        .add_style(
            StyleBuilder::paragraph("Convenient", "Convenient")
                .alignment(Alignment::Center)
                .space_before(Length::inches(0.125))
                .space_after(Length::inches(0.25))
                .indent_left(Length::inches(0.5))
                .font("Aptos")
                .size(11.5)
                .bold(true)
                .color("123456"),
        )
        .unwrap();
    let style = document.style("Convenient").unwrap();
    assert_eq!(
        style.paragraph_properties(),
        Some(&CT_PPr {
            jc: Some(rdocx_oxml::shared::ST_Jc::Center),
            space_before: Some(Twips(180)),
            space_after: Some(Twips(360)),
            ind_left: Some(Twips(720)),
            ..CT_PPr::default()
        })
    );
    assert_eq!(
        style.run_properties(),
        Some(&CT_RPr {
            font_ascii: Some("Aptos".to_owned()),
            font_hansi: Some("Aptos".to_owned()),
            font_east_asia: Some("Aptos".to_owned()),
            font_cs: Some("Aptos".to_owned()),
            sz: Some(HalfPoint::from_pt(11.5)),
            sz_cs: Some(HalfPoint::from_pt(11.5)),
            bold: Some(true),
            bold_cs: Some(true),
            color: Some("123456".to_owned()),
            ..CT_RPr::default()
        })
    );

    document
        .add_style(
            StyleBuilder::paragraph("Theme", "Theme").run_properties(CT_RPr {
                font_ascii_theme: Some("majorHAnsi".to_owned()),
                font_hansi_theme: Some("majorHAnsi".to_owned()),
                font_east_asia_theme: Some("majorEastAsia".to_owned()),
                font_cs_theme: Some("majorBidi".to_owned()),
                color_theme: Some("accent1".to_owned()),
                color_theme_tint: Some(0x80),
                color_theme_shade: Some(0x20),
                ..CT_RPr::default()
            }),
        )
        .unwrap();
    document
        .set_style(
            StyleBuilder::paragraph("Theme", "Theme")
                .font("Aptos")
                .color("123456"),
        )
        .unwrap();
    let updated = document.style("Theme").unwrap();
    let rpr = updated.run_properties().unwrap();
    assert_eq!(rpr.font_ascii.as_deref(), Some("Aptos"));
    assert_eq!(rpr.font_ascii_theme, None);
    assert_eq!(rpr.font_hansi_theme, None);
    assert_eq!(rpr.font_east_asia_theme, None);
    assert_eq!(rpr.font_cs_theme, None);
    assert_eq!(rpr.color.as_deref(), Some("123456"));
    assert_eq!(rpr.color_theme, None);
    assert_eq!(rpr.color_theme_tint, None);
    assert_eq!(rpr.color_theme_shade, None);
}

#[test]
fn high_level_style_survives_save_and_reopen() {
    let mut document = Document::new();
    document
        .add_style(
            StyleBuilder::paragraph("Callout", "Callout")
                .alignment(Alignment::Center)
                .font("Aptos")
                .size(12.0)
                .bold(true),
        )
        .unwrap();
    document.add_paragraph("A callout").set_style("Callout");
    let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let style = reopened.style("Callout").unwrap();
    assert_eq!(style.run_properties().unwrap().bold, Some(true));
    assert_eq!(
        style.paragraph_properties().unwrap().jc,
        Some(rdocx_oxml::shared::ST_Jc::Center)
    );
    let paragraphs = reopened.paragraphs();
    let paragraph = &paragraphs[0];
    assert_eq!(paragraph.style_id(), Some("Callout"));
    assert_eq!(
        reopened.effective_paragraph_properties(paragraph).jc,
        Some(rdocx_oxml::shared::ST_Jc::Center)
    );
    let run = paragraph.runs().next().unwrap();
    let effective = reopened.effective_run_properties(paragraph, &run);
    assert_eq!(effective.bold, Some(true));
    assert_eq!(effective.font_ascii.as_deref(), Some("Aptos"));
    assert_eq!(effective.sz, Some(HalfPoint::from_pt(12.0)));
}

#[test]
fn issue_243_both_reporter_style_packages_accept_every_style_mutator() {
    let variants = [
        (
            "duplicate Normal",
            r#"<w:style w:type="paragraph" w:styleId="Normal"><w:name w:val="Normal Copy"/></w:style>"#,
        ),
        (
            "second table default",
            concat!(
                r#"<w:style w:type="table" w:default="1" w:styleId="TableNormal"><w:name w:val="Normal Table"/></w:style>"#,
                r#"<w:style w:type="table" w:default="1" w:styleId="TableauNormal"><w:name w:val="Tableau Normal"/></w:style>"#,
            ),
        ),
    ];
    for (label, extra_styles) in variants {
        let mut document = document_with_producer_styles(ONE_HEADING_TOC_BODY, extra_styles);
        let old_defect = document.validate_style_graph().unwrap_err().to_string();
        document
            .add_style(StyleBuilder::paragraph("Spare", "Spare"))
            .unwrap();
        document
            .set_style(StyleBuilder::paragraph("Spare", "Updated spare").based_on("Normal"))
            .unwrap();
        document
            .set_default_style(StyleType::Paragraph, "Spare")
            .unwrap();
        let definition = document
            .add_numbering_definition(&[ListLevel::decimal()])
            .unwrap();
        let instance = document.add_numbering_instance(definition, &[]).unwrap();
        document
            .link_style_to_numbering("Spare", instance, 0)
            .unwrap();
        document
            .unlink_style_from_numbering("Spare", instance, 0)
            .unwrap();
        document
            .set_default_style(StyleType::Paragraph, "Normal")
            .unwrap();
        assert!(document.remove_style("Spare").unwrap(), "{label}");
        assert_eq!(
            document.validate_style_graph().unwrap_err().to_string(),
            old_defect,
            "{label}"
        );
        let saved = document.to_bytes().unwrap();
        Document::from_bytes(&saved).unwrap();
    }
}

#[test]
fn style_mutations_retain_repeated_style_ids_and_edit_the_first_definition() {
    let mut document = document_with_producer_styles(ONE_HEADING_TOC_BODY, REPEATED_STYLE_IDS);
    let defect = "invalid style graph: duplicate style ID 'Normal'";
    assert_eq!(
        document.validate_style_graph().unwrap_err().to_string(),
        defect
    );

    document
        .add_style(StyleBuilder::paragraph("NoteBox", "Note box").based_on("Normal"))
        .unwrap();
    document
        .set_style(StyleBuilder::paragraph("Normal", "Normal").priority(7))
        .unwrap();
    let priorities = definitions(&document, "Normal")
        .iter()
        .map(|style| style.priority())
        .collect::<Vec<_>>();
    assert_eq!(priorities, [Some(7), None]);

    document
        .set_default_style(StyleType::Paragraph, "Spare")
        .unwrap();
    let defaults = definitions(&document, "Spare")
        .iter()
        .map(|style| style.is_default())
        .collect::<Vec<_>>();
    assert_eq!(defaults, [true, false]);
    document
        .set_default_style(StyleType::Paragraph, "Normal")
        .unwrap();
    assert!(document.remove_style("Spare").unwrap());
    assert!(definitions(&document, "Spare").is_empty());

    let definition = document
        .add_numbering_definition(&[ListLevel::decimal()])
        .unwrap();
    let instance = document.add_numbering_instance(definition, &[]).unwrap();
    document
        .link_style_to_numbering("NoteBox", instance, 0)
        .unwrap();
    document
        .unlink_style_from_numbering("NoteBox", instance, 0)
        .unwrap();

    assert_eq!(
        document.validate_style_graph().unwrap_err().to_string(),
        defect
    );
    let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(definitions(&reopened, "Normal").len(), 2);
    assert!(reopened.style("NoteBox").is_some());
}

#[test]
fn style_mutations_reject_a_defect_they_introduce_behind_repeated_style_ids() {
    let mut document = document_with_producer_styles(ONE_HEADING_TOC_BODY, REPEATED_STYLE_IDS);
    let before = document.to_bytes().unwrap();

    assert_eq!(
        document
            .add_style(StyleBuilder::paragraph("Normal", "Another Normal"))
            .unwrap_err()
            .to_string(),
        "style 'Normal' already exists"
    );
    assert_eq!(
        document
            .add_style(StyleBuilder::paragraph("Orphan", "Orphan").based_on("Missing"))
            .unwrap_err()
            .to_string(),
        "invalid style graph: style 'Orphan' is based on missing style 'Missing'"
    );
    assert_eq!(
        document
            .set_style(StyleBuilder::paragraph("Normal", "Normal").next_style("Missing"))
            .unwrap_err()
            .to_string(),
        "invalid style graph: style 'Normal' names missing next style 'Missing'"
    );
    assert_eq!(document.to_bytes().unwrap(), before);

    // Defects are counted. The same defect on another definition, or on a
    // new style inheriting an existing cycle, is still a new one.
    let mut shadowed_orphan = document_with_producer_styles(
        ONE_HEADING_TOC_BODY,
        r#"<w:style w:type="paragraph" w:styleId="Normal"><w:name w:val="Normal Copy"/><w:basedOn w:val="Missing"/></w:style>"#,
    );
    let before = shadowed_orphan.to_bytes().unwrap();
    assert_eq!(
        shadowed_orphan
            .set_style(StyleBuilder::paragraph("Normal", "Normal").based_on("Missing"))
            .unwrap_err()
            .to_string(),
        "invalid style graph: style 'Normal' is based on missing style 'Missing'"
    );
    assert_eq!(shadowed_orphan.to_bytes().unwrap(), before);

    let mut cycle = document_with_producer_styles(
        ONE_HEADING_TOC_BODY,
        concat!(
            r#"<w:style w:type="paragraph" w:styleId="CycleA"><w:name w:val="Cycle A"/><w:basedOn w:val="CycleB"/></w:style>"#,
            r#"<w:style w:type="paragraph" w:styleId="CycleB"><w:name w:val="Cycle B"/><w:basedOn w:val="CycleA"/></w:style>"#,
        ),
    );
    let before = cycle.to_bytes().unwrap();
    assert_eq!(
        cycle
            .add_style(StyleBuilder::paragraph("CycleC", "Cycle C").based_on("CycleA"))
            .unwrap_err()
            .to_string(),
        "invalid style graph: based-on cycle contains style 'CycleA'"
    );
    assert_eq!(cycle.to_bytes().unwrap(), before);
}

#[test]
fn appending_into_repeated_style_ids_retains_them_and_rejects_a_new_defect() {
    let mut imported = Document::new();
    imported
        .add_style(StyleBuilder::paragraph("Imported", "Imported").based_on("Normal"))
        .unwrap();
    imported.add_paragraph("imported").style("Imported");

    let mut appended = document_with_producer_styles(ONE_HEADING_TOC_BODY, REPEATED_STYLE_IDS);
    appended.append(&imported);
    let mut inserted = document_with_producer_styles(ONE_HEADING_TOC_BODY, REPEATED_STYLE_IDS);
    inserted.insert_document(0, &imported);
    for document in [&appended, &inserted] {
        assert!(document.style("Imported").is_some());
        assert_eq!(definitions(document, "Normal").len(), 2);
        assert_eq!(
            document.validate_style_graph().unwrap_err().to_string(),
            "invalid style graph: duplicate style ID 'Normal'"
        );
    }

    // A second default paragraph style is new to the destination.
    let mut conflicting = Document::new();
    conflicting
        .add_style(StyleBuilder::paragraph("SourceDefault", "Source Default"))
        .unwrap();
    conflicting
        .set_default_style(StyleType::Paragraph, "SourceDefault")
        .unwrap();
    let mut document = document_with_producer_styles(ONE_HEADING_TOC_BODY, REPEATED_STYLE_IDS);
    let before = document.to_bytes().unwrap();
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        document.append(&conflicting);
    }));
    assert!(result.is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

