/// GitHub issue #168: python-docx's default template gives `Subtitle` a
/// `w:numPr` holding a `w:ilvl` and no `w:numId`, so every numbering edit of
/// a python-docx document was refused. The style takes the instance of its
/// `basedOn` chain and is not numbered when the chain has none, which is what
/// Word renders: `1.`, `1.1)`, `1.2)`, `2.` and an unnumbered subtitle here.
#[test]
fn style_numbering_level_without_an_instance_follows_its_based_on_chain() {
    let producer_styles = concat!(
        // python-docx's `Subtitle`, without its linked character style.
        r#"<w:style w:type="paragraph" w:styleId="Subtitle"><w:name w:val="Subtitle"/>"#,
        r#"<w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:uiPriority w:val="11"/>"#,
        r#"<w:qFormat/><w:pPr><w:numPr><w:ilvl w:val="1"/></w:numPr></w:pPr></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="Base"><w:name w:val="Base"/>"#,
        r#"<w:basedOn w:val="Normal"/></w:style>"#,
        r#"<w:style w:type="paragraph" w:styleId="Derived"><w:name w:val="Derived"/>"#,
        r#"<w:basedOn w:val="Base"/><w:pPr><w:numPr><w:ilvl w:val="1"/></w:numPr></w:pPr>"#,
        r#"</w:style>"#,
    );
    let body = [
        ("Base", "Base one"),
        ("Derived", "Derived one"),
        ("Derived", "Derived two"),
        ("Base", "Base two"),
        ("Subtitle", "Subtitle text"),
    ]
    .map(|(style, text)| {
        format!(
            r#"<w:p><w:pPr><w:pStyle w:val="{style}"/></w:pPr><w:r><w:t>{text}</w:t></w:r></w:p>"#
        )
    })
    .concat();
    let mut document = document_with_producer_styles(&body, producer_styles);
    document.validate_numbering_graph().unwrap();

    let definition = document
        .add_numbering_definition(&[
            ListLevel::decimal().level_text("%1."),
            ListLevel::decimal().level_text("%1.%2)"),
        ])
        .unwrap();
    let instance = document.add_numbering_instance(definition, &[]).unwrap();
    document
        .link_style_to_numbering("Base", instance, 0)
        .unwrap();

    let markers = |document: &mut Document| {
        let layout = document.layout_deterministic().unwrap();
        (0..5)
            .map(|body_index| {
                layout
                    .document_body_paragraph_numbering(body_index)
                    .map(|numbering| numbering.marker_text.clone())
            })
            .collect::<Vec<_>>()
    };
    let expected = ["1.", "1.1)", "1.2)", "2."]
        .map(|marker| Some(marker.to_owned()))
        .into_iter()
        .chain([None])
        .collect::<Vec<_>>();
    assert_eq!(markers(&mut document), expected);

    // A level may name the inheriting style back, which records its link.
    let mut package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
            .unwrap();
    let numbering =
        String::from_utf8(package.get_part("/word/numbering.xml").unwrap().to_vec()).unwrap();
    let level = numbering.find(r#"<w:lvl w:ilvl="1""#).unwrap();
    let level_end = level + numbering[level..].find("<w:lvlText").unwrap();
    let numbering = format!(
        r#"{}<w:pStyle w:val="Derived"/>{}"#,
        &numbering[..level_end],
        &numbering[level_end..]
    );
    package.set_part("/word/numbering.xml", numbering.into_bytes());
    let mut bytes = std::io::Cursor::new(Vec::new());
    package.write_to(&mut bytes).unwrap();
    let mut document = Document::from_bytes(bytes.get_ref()).unwrap();
    document.validate_numbering_graph().unwrap();
    document
        .add_numbering_definition(&[ListLevel::decimal()])
        .unwrap();
    assert_eq!(markers(&mut document), expected);

    // Unlinking the style that the level names back removes only that name,
    // and the style stays numbered through `Base`.
    document
        .unlink_style_from_numbering("Derived", instance, 1)
        .unwrap();
    assert_eq!(markers(&mut document), expected);
    let package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
            .unwrap();
    let numbering = std::str::from_utf8(package.get_part("/word/numbering.xml").unwrap()).unwrap();
    assert!(
        !numbering.contains(r#"<w:pStyle w:val="Derived"/>"#),
        "{numbering}"
    );
    // A style that no level names is not linked, and unlinking it changes
    // nothing.
    let before = document.to_bytes().unwrap();
    document
        .unlink_style_from_numbering("Subtitle", instance, 1)
        .unwrap();
    assert_eq!(document.to_bytes().unwrap(), before);
}

/// The same rule for a style linked to a list and for a repeated template
/// paragraph. A style `w:numPr` holding only a `w:ilvl` owns no link, so a
/// link replaces it. A paragraph `w:ilvl` without a `w:numId` takes the
/// instance of its style chain, which Word renders as `1.a)` under a `Base`
/// paragraph numbered `1.`, and numbers nothing under `Normal`.
#[test]
fn link_and_template_accept_a_numbering_level_without_an_instance() {
    let producer_styles = concat!(
        r#"<w:style w:type="paragraph" w:styleId="Subtitle"><w:name w:val="Subtitle"/>"#,
        r#"<w:basedOn w:val="Normal"/><w:pPr><w:numPr><w:ilvl w:val="1"/></w:numPr></w:pPr>"#,
        r#"</w:style><w:style w:type="paragraph" w:styleId="Base"><w:name w:val="Base"/>"#,
        r#"<w:basedOn w:val="Normal"/></w:style>"#,
    );
    let body = concat!(
        r#"<w:p><w:r><w:t>{% for item in items %}</w:t></w:r></w:p>"#,
        r#"<w:p><w:pPr><w:pStyle w:val="Base"/><w:numPr><w:ilvl w:val="1"/></w:numPr></w:pPr>"#,
        r#"<w:r><w:t>{{ item }}</w:t></w:r></w:p>"#,
        r#"<w:p><w:pPr><w:numPr><w:ilvl w:val="1"/></w:numPr></w:pPr>"#,
        r#"<w:r><w:t>Note {{ item }}</w:t></w:r></w:p>"#,
        r#"<w:p><w:r><w:t>{% endfor %}</w:t></w:r></w:p>"#,
        r#"<w:p><w:pPr><w:pStyle w:val="Subtitle"/></w:pPr><w:r><w:t>Subtitle</w:t></w:r></w:p>"#,
    );
    let mut document = document_with_producer_styles(body, producer_styles);
    let levels = [
        ListLevel::decimal().level_text("%1."),
        ListLevel::decimal().level_text("%1.%2)"),
    ];
    let definition = document.add_numbering_definition(&levels).unwrap();
    let instance = document.add_numbering_instance(definition, &[]).unwrap();
    document
        .link_style_to_numbering("Base", instance, 0)
        .unwrap();
    let subtitle_definition = document
        .add_numbering_definition(&[ListLevel::decimal().level_text("S%1.")])
        .unwrap();
    let subtitle = document
        .add_numbering_instance(subtitle_definition, &[])
        .unwrap();
    document
        .link_style_to_numbering("Subtitle", subtitle, 0)
        .unwrap();

    document
        .render_template(&serde_json::json!({"items": ["one", "two"]}))
        .unwrap();
    let layout = document.layout_deterministic().unwrap();
    let markers = (0..5)
        .map(|body_index| {
            let text = document.paragraph(body_index).unwrap().text();
            let marker = layout
                .document_body_paragraph_numbering(body_index)
                .map(|numbering| numbering.marker_text.clone());
            (text, marker)
        })
        .collect::<Vec<_>>();
    let entry = |text: &str, marker: Option<&str>| (text.to_owned(), marker.map(str::to_owned));
    assert_eq!(
        markers,
        [
            entry("one", Some("1.1)")),
            entry("Note one", None),
            entry("two", Some("1.2)")),
            entry("Note two", None),
            entry("Subtitle", Some("S1.")),
        ]
    );

    // Unlinking removes the whole `w:numPr`, so the level the style held
    // before it was linked does not come back.
    document
        .unlink_style_from_numbering("Subtitle", subtitle, 0)
        .unwrap();
    let package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
            .unwrap();
    let styles = std::str::from_utf8(package.get_part("/word/styles.xml").unwrap()).unwrap();
    let subtitle_start = styles.find(r#"w:styleId="Subtitle""#).unwrap();
    let subtitle_end = subtitle_start + styles[subtitle_start..].find("</w:style>").unwrap();
    assert!(
        !styles[subtitle_start..subtitle_end].contains("numPr"),
        "{styles}"
    );
}

fn fx114_toc_document() -> Document {
    use rdocx_oxml::borders::{CT_TabStop, CT_Tabs};
    use rdocx_oxml::properties::CT_PPr;
    use rdocx_oxml::shared::{ST_TabJc, ST_TabLeader};
    use rdocx_oxml::units::Twips;

    let body = r#"
        <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \o "1-3"</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>stale</w:t></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Numbered</w:t></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Heading2"/></w:pPr><w:r><w:t>Localized fallback</w:t></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Heading3"/></w:pPr><w:r><w:t>Canonical fallback</w:t></w:r></w:p>
        <w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:left="1417" w:right="1417"/></w:sectPr>
    "#;
    let mut document = document_with_field_parts(&wrap_word_body(body), None, None);
    document
        .add_style(
            StyleBuilder::paragraph("Inhaltsverzeichnis1", "ToC 1").paragraph_properties(CT_PPr {
                tabs: Some(CT_Tabs {
                    tabs: vec![CT_TabStop {
                        val: ST_TabJc::Right,
                        pos: Twips(7777),
                        leader: Some(ST_TabLeader::Dot),
                        source_occurrence: None,
                    }],
                }),
                ..Default::default()
            }),
        )
        .unwrap();
    document
        .add_style(StyleBuilder::paragraph("SommaireDeux", "toc 2"))
        .unwrap();
    let definition = document
        .add_numbering_definition(&[ListLevel::decimal()])
        .unwrap();
    let instance = document.add_numbering_instance(definition, &[]).unwrap();
    document
        .link_style_to_numbering("Heading1", instance, 0)
        .unwrap();
    document
}

fn fx114_toc_records(bytes: &[u8]) -> Vec<String> {
    use rdocx_oxml::shared::ST_TabJc;
    use rdocx_oxml::text::RunContent;

    let package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).expect("open package");
    let document = CT_Document::from_xml(
        package
            .get_part("/word/document.xml")
            .expect("document part"),
    )
    .expect("parse document");
    let styles = rdocx_oxml::styles::CT_Styles::from_xml(
        package.get_part("/word/styles.xml").expect("styles part"),
    )
    .expect("parse styles");
    document
        .body
        .paragraphs()
        .filter_map(|paragraph| {
            let properties = paragraph.properties.as_ref()?;
            let style_id = properties.style_id.as_deref()?;
            let style = styles.get_by_id(style_id)?;
            let name = style.name.as_deref()?;
            let normalized = name.trim().to_ascii_lowercase();
            if !matches!(normalized.as_str(), "toc 1" | "toc 2" | "toc 3") {
                return None;
            }
            let direct_right_tab = properties.tabs.as_ref().and_then(|tabs| {
                tabs.tabs
                    .iter()
                    .find(|tab| tab.val == ST_TabJc::Right)
            });
            let style_right_tab = style.ppr.as_ref().and_then(|properties| {
                properties.tabs.as_ref().and_then(|tabs| {
                    tabs.tabs
                        .iter()
                        .find(|tab| tab.val == ST_TabJc::Right)
                })
            });
            let right_tab = direct_right_tab.or(style_right_tab)?.pos.0;
            let structural_tabs = paragraph
                .runs
                .iter()
                .flat_map(|run| &run.content)
                .filter(|content| matches!(content, RunContent::Tab))
                .count();
            let literal_tab = paragraph.runs.iter().any(|run| {
                run.content.iter().any(|content| match content {
                    RunContent::Text(text) => text.text.contains('\t'),
                    _ => false,
                })
            });
            let mut text = String::new();
            let mut seen_tabs = 0usize;
            for content in paragraph.runs.iter().flat_map(|run| &run.content) {
                match content {
                    RunContent::Text(value) if seen_tabs < structural_tabs => {
                        text.push_str(&value.text)
                    }
                    RunContent::Tab => {
                        text.push_str("\\t");
                        seen_tabs += 1;
                    }
                    _ => {}
                }
            }
            Some(format!(
                "{normalized} | right-tab={right_tab} | structural-tabs={structural_tabs} | literal-tab={literal_tab} | text={text}"
            ))
        })
        .collect()
}

#[test]
fn rebuilt_toc_uses_localized_styles_section_tabs_and_structural_suffixes() {
    use rdocx_oxml::shared::{ST_TabJc, ST_TabLeader};
    use rdocx_oxml::text::RunContent;
    use rdocx_oxml::units::Twips;

    assert_eq!(
        WORD_FX114_ORACLE,
        "Microsoft Word 16.113 build 16.113.26091433"
    );
    assert_eq!(
        WORD_FX114_ENVIRONMENT,
        "macOS; locale=en-GB; normalization=fx114-toc-entry-records-v1"
    );
    let mut document = fx114_toc_document();
    let preserved_style_child = r#"<producer:opaque xmlns:producer="urn:producer" producer:value="keep"><producer:child/></producer:opaque>"#;
    let bytes = document.to_bytes().unwrap();
    let mut package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).unwrap();
    let styles = std::str::from_utf8(package.get_part("/word/styles.xml").unwrap()).unwrap();
    let unrelated_style = format!(
        r#"<w:style w:type="paragraph" w:styleId="ProducerKeep"><w:name w:val="Producer keep"/>{preserved_style_child}</w:style>"#
    );
    let styles = styles.replace("</w:styles>", &format!("{unrelated_style}</w:styles>"));
    package.set_part("/word/styles.xml", styles.into_bytes());
    let mut injected = std::io::Cursor::new(Vec::new());
    package.write_to(&mut injected).unwrap();
    document = Document::from_bytes(injected.get_ref()).unwrap();

    assert_eq!(document.rebuild_toc().unwrap().entry_count, 3);
    let bytes = document.to_bytes().unwrap();
    assert_eq!(
        fx114_toc_records(&bytes)
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>(),
        WORD_FX114_RECORDS
    );
    let reopened = Document::from_bytes(&bytes).unwrap();
    assert!(reopened.style("Inhaltsverzeichnis1").is_some());
    assert!(reopened.style("SommaireDeux").is_some());
    assert!(reopened.style("TOC3").is_some());
    assert!(reopened.style("ProducerKeep").is_some());
    let saved_package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&bytes)).unwrap();
    let saved_styles =
        std::str::from_utf8(saved_package.get_part("/word/styles.xml").unwrap()).unwrap();
    assert!(
        saved_styles.contains(preserved_style_child),
        "{saved_styles}"
    );

    let body = body_from_document(&mut Document::from_bytes(&bytes).unwrap());
    let entries = body
        .paragraphs()
        .filter(|paragraph| {
            paragraph
                .properties
                .as_ref()
                .and_then(|properties| properties.style_id.as_deref())
                .is_some_and(|style| {
                    matches!(style, "Inhaltsverzeichnis1" | "SommaireDeux" | "TOC3")
                })
        })
        .collect::<Vec<_>>();
    assert_eq!(entries.len(), 3);
    for (entry, expected) in entries
        .iter()
        .zip(["Inhaltsverzeichnis1", "SommaireDeux", "TOC3"])
    {
        assert_eq!(
            entry
                .properties
                .as_ref()
                .and_then(|properties| properties.style_id.as_deref()),
            Some(expected)
        );
    }
    let numbered_tab = entries[0]
        .properties
        .as_ref()
        .and_then(|properties| properties.tabs.as_ref())
        .expect("numbered entry has a direct stop after its marker");
    assert_eq!(numbered_tab.tabs.len(), 1);
    assert_eq!(numbered_tab.tabs[0].val, ST_TabJc::Left);
    assert_eq!(numbered_tab.tabs[0].pos, Twips(480));
    for entry in &entries[1..] {
        let tabs = entry
            .properties
            .as_ref()
            .and_then(|properties| properties.tabs.as_ref())
            .expect("fallback tab");
        assert_eq!(tabs.tabs.len(), 1);
        assert_eq!(tabs.tabs[0].val, ST_TabJc::Right);
        assert_eq!(tabs.tabs[0].pos, Twips(9072));
        assert_eq!(tabs.tabs[0].leader, Some(ST_TabLeader::Dot));
    }

    let numbered = body
        .paragraphs()
        .find(|paragraph| {
            paragraph
                .properties
                .as_ref()
                .and_then(|properties| properties.style_id.as_deref())
                == Some("Inhaltsverzeichnis1")
        })
        .unwrap();
    assert!(numbered.runs.iter().all(|run| {
        run.content.iter().all(|content| match content {
            RunContent::Text(text) => !text.text.contains('\t'),
            _ => true,
        })
    }));
    assert!(numbered.runs.iter().any(|run| {
        run.content
            .iter()
            .any(|content| matches!(content, RunContent::Tab))
    }));
    assert_eq!(numbered.text(), "1.\tNumbered\t");
    reopened.layout_deterministic().unwrap();

    let extreme_body = r#"
        <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \o "1-1"</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>stale</w:t></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Extreme geometry</w:t></w:r></w:p>
        <w:sectPr><w:pgSz w:w="2147483647" w:h="16838"/><w:pgMar w:left="-2147483648" w:right="-2147483648"/></w:sectPr>
    "#;
    let mut extreme = document_with_field_parts(&wrap_word_body(extreme_body), None, None);
    assert_eq!(extreme.rebuild_toc().unwrap().entry_count, 1);
    let body = body_from_document(&mut extreme);
    let tab = body
        .paragraphs()
        .find(|paragraph| {
            paragraph
                .properties
                .as_ref()
                .and_then(|properties| properties.style_id.as_deref())
                == Some("TOC1")
        })
        .and_then(|paragraph| paragraph.properties.as_ref())
        .and_then(|properties| properties.tabs.as_ref())
        .and_then(|tabs| tabs.tabs.first())
        .expect("safe fallback tab");
    assert_eq!(tab.pos, Twips(9360));
}

#[test]
#[ignore = "requires installed Microsoft Word 16.113 GUI automation"]
fn capture_fx114_word_toc_entry_records() {
    use std::process::Command;
    use std::time::{SystemTime, UNIX_EPOCH};

    for (key, expected) in [
        ("CFBundleShortVersionString", "16.113"),
        ("CFBundleVersion", "16.113.26091433"),
    ] {
        let output = Command::new("plutil")
            .args([
                "-extract",
                key,
                "raw",
                "/Applications/Microsoft Word.app/Contents/Info.plist",
            ])
            .output()
            .unwrap();
        assert!(output.status.success());
        assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), expected);
    }

    let mut document = fx114_toc_document();
    document.rebuild_toc().unwrap();
    let nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let directory = std::path::Path::new(
        "/Users/atulsharma/Library/Containers/com.microsoft.Word/Data/Documents/rdocx-fx114-word-oracle",
    )
    .join(format!("{}-{nonce}", std::process::id()));
    std::fs::create_dir_all(&directory).unwrap();
    let source = directory.join("fx114-source.docx");
    let round_trip = directory.join("fx114-word.docx");
    document.save(&source).unwrap();

    let script = format!(
        r#"with timeout of 60 seconds
tell application "Microsoft Word"
activate
open file name "{}" read only false add to recent files false
set fx114Doc to document 1
save as fx114Doc file name "{}" file format format document default add to recent files false
set fx114Doc to active document
close fx114Doc saving no
end tell
end timeout"#,
        source.display(),
        round_trip.display(),
    );
    let output = Command::new("osascript")
        .args(["-e", &script])
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "Word round trip failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let bytes = std::fs::read(&round_trip).unwrap();
    assert_eq!(
        fx114_toc_records(&bytes)
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>(),
        WORD_FX114_RECORDS
    );
    std::fs::remove_dir_all(&directory).unwrap();
}

#[test]
fn toc_bookmark_ids_names_and_references_follow_final_heading_order() {
    let source = |reference: &str, headings: &str| {
        wrap_word_body(&format!(
            r#"
            <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \o "1-1" \h</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
            <w:p><w:r><w:t>stale</w:t></w:r></w:p>
            <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
            <w:p><w:fldSimple w:instr="REF {reference}"><w:r><w:t>reference</w:t></w:r></w:fldSimple></w:p>
            {headings}
            "#
        ))
    };
    let later =
        r#"<w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Later</w:t></w:r></w:p>"#;
    let earlier =
        r#"<w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Earlier</w:t></w:r></w:p>"#;

    let mut history = document_with_field_parts(&source("_Toc1", later), None, None);
    history.rebuild_toc().unwrap();
    let later_index = history.content_count() - 1;
    history
        .insert_paragraph(later_index, "Earlier")
        .style("Heading1");
    history.rebuild_toc().unwrap();

    let final_headings = format!("{earlier}{later}");
    let mut final_order = document_with_field_parts(&source("_Toc2", &final_headings), None, None);
    final_order.rebuild_toc().unwrap();

    let history_xml = document_xml(&mut history);
    let final_xml = document_xml(&mut final_order);
    let bookmark_pairs = |xml: &str| {
        xml.match_indices("<w:bookmarkStart")
            .map(|(start, _)| {
                let element = &xml[start..start + xml[start..].find("/>").unwrap()];
                let value = |attribute: &str| {
                    let prefix = format!(r#"{attribute}=""#);
                    let value = &element[element.find(&prefix).unwrap() + prefix.len()..];
                    value[..value.find('"').unwrap()].to_owned()
                };
                (value("w:id"), value("w:name"))
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(bookmark_pairs(&history_xml), bookmark_pairs(&final_xml));
    assert_eq!(
        bookmark_pairs(&history_xml),
        [
            ("1".to_owned(), "_Toc1".to_owned()),
            ("2".to_owned(), "_Toc2".to_owned())
        ]
    );
    assert!(history_xml.contains(r#"w:instr="REF _Toc2""#));
}

#[test]
fn toc_rebuild_uses_final_deterministic_page_targets() {
    let body = r#"
        <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText xml:space="preserve"> TOC \o "1-1" \h </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>old page</w:t></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>First page heading</w:t></w:r></w:p>
        <w:p><w:pPr><w:pageBreakBefore/></w:pPr><w:r><w:t>Page boundary</w:t></w:r></w:p>
        <w:tbl><w:tr><w:tc><w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Second page heading</w:t></w:r></w:p></w:tc></w:tr></w:tbl>
    "#;
    let mut document = document_with_field_parts(&wrap_word_body(body), None, None);

    assert_eq!(document.rebuild_toc().unwrap().entry_count, 2);
    let xml = document_xml(&mut document);
    assert_eq!(
        toc_entry_signatures(&xml),
        [
            (
                "First page heading\t1".to_owned(),
                "TOC1".to_owned(),
                Some("_Toc1".to_owned()),
                Some("_Toc1".to_owned())
            ),
            (
                "Second page heading\t2".to_owned(),
                "TOC1".to_owned(),
                Some("_Toc2".to_owned()),
                Some("_Toc2".to_owned())
            ),
        ]
    );

    let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let layout = reopened.layout_deterministic().unwrap();
    assert!(layout.layout.pages.len() >= 2);
}

#[test]
fn toc_rebuild_preserves_unowned_field_and_package_xml() {
    let body = r#"
        <w:p><w:r><q:fldChar xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main" q:fldCharType="begin"/></w:r><w:r><q:instrText xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xml:space="preserve"> TOC \o "1-1" </q:instrText></w:r><w:r><q:fldChar xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main" q:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>stale cache</w:t></w:r></w:p>
        <w:p><w:r><q:fldChar xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main" q:fldCharType="end"/></w:r></w:p>
        <w:p data-source="keep"><w:pPr><w:pStyle w:val="Heading1"/><producer:opaque xmlns:producer="urn:producer" producer:value="keep"/></w:pPr><w:r><w:t>Owned heading</w:t></w:r></w:p>
        <w:p><w:fldSimple w:instr="IF 1 = 1 &quot;yes&quot; &quot;no&quot;" producer:token="keep" xmlns:producer="urn:producer"><w:r><w:t>unowned cache</w:t></w:r></w:fldSimple></w:p>
    "#;
    let mut document = document_with_field_parts(&wrap_word_body(body), None, None);
    let before = document.to_bytes().unwrap();
    let mut package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(before)).unwrap();
    package.set_part("/custom/unrelated.bin", b"producer bytes".to_vec());
    let mut output = std::io::Cursor::new(Vec::new());
    package.write_to(&mut output).unwrap();
    let mut document = Document::from_bytes(output.get_ref()).unwrap();

    document.rebuild_toc().unwrap();
    let saved = document.to_bytes().unwrap();
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(saved)).unwrap();
    assert_eq!(
        package.get_part("/custom/unrelated.bin").unwrap(),
        b"producer bytes"
    );
    let xml = std::str::from_utf8(package.get_part("/word/document.xml").unwrap()).unwrap();
    for preserved in [
        "<q:fldChar xmlns:q=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" q:fldCharType=\"begin\"/>",
        "<q:instrText xmlns:q=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xml:space=\"preserve\">",
        "TOC \\o \"1-1\"",
        "producer:opaque",
        "producer:value=\"keep\"",
        "producer:token=\"keep\"",
        "unowned cache",
    ] {
        assert!(xml.contains(preserved), "missing {preserved}: {xml}");
    }
}

#[test]
fn toc_rebuild_rejects_ambiguous_or_malformed_sources_atomically() {
    for body in [
        r#"<w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \o "1-1"</w:instrText></w:r></w:p><w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Heading</w:t></w:r></w:p>"#,
        r#"<w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \o "1-1"</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p><w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p><w:p><w:bookmarkStart w:id="7" w:name="duplicate"/><w:bookmarkStart w:id="8" w:name="duplicate"/><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Heading</w:t></w:r><w:bookmarkEnd w:id="8"/><w:bookmarkEnd w:id="7"/></w:p>"#,
    ] {
        let mut document = document_with_field_parts(&wrap_word_body(body), None, None);
        let before = document_xml(&mut document);
        let error = document.rebuild_toc().unwrap_err();
        assert!(
            error.to_string().contains("table of contents"),
            "unexpected error: {error}"
        );
        assert_eq!(document_xml(&mut document), before);
    }

    let unsupported = r#"
        <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \x</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>stored unsupported cache</w:t></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
    "#;
    let mut document = document_with_field_parts(&wrap_word_body(unsupported), None, None);
    let before = document_xml(&mut document);
    assert_eq!(
        document.rebuild_toc().unwrap(),
        TocRebuildReport {
            entry_count: 0,
            bookmark_count: 0,
            diagnostics: vec![
                "field TOC uses unsupported switch \\x, stored display retained".to_owned()
            ],
        }
    );
    assert_eq!(document_xml(&mut document), before);

    let simple = r#"<w:p><w:fldSimple w:instr="TOC"><w:r><w:t>stored simple cache</w:t></w:r></w:fldSimple></w:p>"#;
    let mut document = document_with_field_parts(&wrap_word_body(simple), None, None);
    let before = document_xml(&mut document);
    assert_eq!(document.rebuild_toc().unwrap().diagnostic_count(), 1);
    assert_eq!(document_xml(&mut document), before);

    let mut no_toc = Document::new();
    no_toc.add_paragraph("Heading").style("Heading1");
    assert_eq!(no_toc.rebuild_toc().unwrap(), TocRebuildReport::default());
}

#[test]
fn word_default_toc_switch_rebuilds_and_reports_ordered_diagnostics() {
    let body = r#"
        <w:sdt>
          <w:sdtPr><w:id w:val="17"/><w:dropDownList producer:flag="keep"><w:listItem w:displayText="A" w:value="a"/></w:dropDownList></w:sdtPr>
          <w:sdtContent>
            <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText xml:space="preserve"> TOC \o "1-3" \h \z \u </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
            <w:p><w:r><w:t>stale cache</w:t></w:r></w:p>
            <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
          </w:sdtContent>
        </w:sdt>
        <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Alpha</w:t></w:r></w:p>
    "#;
    let mut document = document_with_field_parts(&wrap_word_body(body), None, None);

    let report = document.rebuild_toc().unwrap();
    assert_eq!(report.entry_count, 1);
    assert_eq!(report.diagnostic_count(), 0);
    assert!(report.diagnostics.is_empty());
    let bytes = document.to_bytes().unwrap();
    let mut reopened = Document::from_bytes(&bytes).unwrap();
    let repeat_report = reopened.rebuild_toc().unwrap();
    assert_eq!(repeat_report.entry_count, 1);
    assert!(repeat_report.diagnostics.is_empty());
    let xml = document_xml(&mut reopened);
    assert!(!xml.contains("stale cache"), "{xml}");
    for preserved in [
        r#" TOC \o "1-3" \h \z \u "#,
        "producer:flag=\"keep\"",
        "w:listItem",
        "w:displayText=\"A\"",
    ] {
        assert!(xml.contains(preserved), "missing {preserved}: {xml}");
    }

    let diagnostics = r#"
        <w:p><w:fldSimple w:instr="TOC"><w:r><w:t>simple cache</w:t></w:r></w:fldSimple></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \x</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>complex cache</w:t></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
    "#;
    let mut document = document_with_field_parts(&wrap_word_body(diagnostics), None, None);
    let before = document.to_bytes().unwrap();
    let report = document.rebuild_toc().unwrap();
    assert_eq!(
        report.diagnostics,
        [
            "simple table of contents fields are not rebuilt, stored display retained",
            "field TOC uses unsupported switch \\x, stored display retained",
        ]
    );
    assert_eq!(report.diagnostic_count(), 2);
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn toc_rebuild_confines_collision_safe_page_substitution_to_owned_results() {
    let token = "__RDOCX_TOC_PAGE_0_0__";
    let body = format!(
        r#"
        <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC \o "1-1"</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p>
        <w:p><w:r><w:t>old</w:t></w:r></w:p>
        <w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>{token}</w:t></w:r></w:p>
        <w:p><w:r><producer:opaque xmlns:producer="urn:producer" producer:value="{token}"/></w:r></w:p>
    "#
    );
    let mut document = document_with_field_parts(&wrap_word_body(&body), None, None);

    assert_eq!(document.rebuild_toc().unwrap().entry_count, 1);
    let xml = document_xml(&mut document);
    assert_eq!(xml.matches(token).count(), 3, "{xml}");
    assert!(
        xml.contains(&format!("producer:value=\"{token}\"")),
        "{xml}"
    );
}

#[test]
fn toc_rebuild_ignores_foreign_ancestors_and_indirect_field_markers() {
    for body in [
        r#"<x:tbl xmlns:x="urn:producer"><x:tr><x:tc><w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p><w:p><w:r><w:t>foreign cache</w:t></w:r></w:p><w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p></x:tc></x:tr></x:tbl>"#,
        r#"<x:wrapper xmlns:x="urn:producer"><w:body><w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:p><w:p><w:r><w:t>nested body cache</w:t></w:r></w:p><w:p><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p></w:body></x:wrapper>"#,
        r#"<w:p><w:r><x:wrapper xmlns:x="urn:producer"><w:fldChar w:fldCharType="begin"/></x:wrapper></w:r><w:r><w:instrText>TOC</w:instrText></w:r><w:r><x:wrapper xmlns:x="urn:producer"><w:fldChar w:fldCharType="separate"/></x:wrapper></w:r></w:p><w:p><w:r><w:t>opaque cache</w:t></w:r></w:p><w:p><w:r><x:wrapper xmlns:x="urn:producer"><w:fldChar w:fldCharType="end"/></x:wrapper></w:r></w:p>"#,
        r#"<w:p><x:wrapper xmlns:x="urn:producer"><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></x:wrapper></w:p><w:p><w:r><w:t>opaque wrapped cache</w:t></w:r></w:p><w:p><x:wrapper xmlns:x="urn:producer"><w:r><w:fldChar w:fldCharType="end"/></w:r></x:wrapper></w:p>"#,
        r#"<w:p><x:wrapper xmlns:x="urn:producer"><w:fldSimple w:instr="TOC"><w:r><w:t>opaque simple cache</w:t></w:r></w:fldSimple></x:wrapper></w:p>"#,
        r#"<w:p><w:sdtContent><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:sdtContent></w:p><w:p><w:r><w:t>opaque malformed control cache</w:t></w:r></w:p><w:p><w:sdtContent><w:r><w:fldChar w:fldCharType="end"/></w:r></w:sdtContent></w:p>"#,
        r#"<w:p><w:ins><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>TOC</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r></w:ins></w:p><w:p><w:r><w:t>opaque malformed revision cache</w:t></w:r></w:p><w:p><w:ins><w:r><w:fldChar w:fldCharType="end"/></w:r></w:ins></w:p>"#,
    ] {
        let mut document = document_with_field_parts(&wrap_word_body(body), None, None);
        let before = document_xml(&mut document);
        assert_eq!(document.rebuild_toc().unwrap(), TocRebuildReport::default());
        assert_eq!(document_xml(&mut document), before);
    }
}

