#[cfg(unix)]
#[test]
fn path_saves_replace_the_file_by_rename_and_keep_links_and_permissions() {
    use std::fs::{self, Permissions};
    use std::os::unix::fs::{MetadataExt as _, PermissionsExt as _};
    use std::path::Path;

    let directory = std::env::temp_dir().join(format!("rdocx-atomic-save-{}", std::process::id()));
    let _ = fs::remove_dir_all(&directory);
    let links = directory.join("links");
    fs::create_dir_all(&links).unwrap();
    let staging_files = |directory: &Path| {
        fs::read_dir(directory)
            .unwrap()
            .map(|entry| entry.unwrap().path())
            .filter(|path| path.extension().is_some_and(|extension| extension == "tmp"))
            .collect::<Vec<_>>()
    };
    let mode = |path: &Path| fs::metadata(path).unwrap().permissions().mode() & 0o7777;
    let mut document = Document::new();
    document.add_paragraph("replacement");

    // The plain save replaces an existing file by rename and keeps its mode.
    let destination = directory.join("existing.docx");
    fs::write(&destination, b"previous bytes").unwrap();
    fs::set_permissions(&destination, Permissions::from_mode(0o600)).unwrap();
    let previous_inode = fs::metadata(&destination).unwrap().ino();
    document.save(&destination).unwrap();
    assert_ne!(fs::metadata(&destination).unwrap().ino(), previous_inode);
    assert_eq!(mode(&destination), 0o600);
    assert_eq!(
        fs::read(&destination).unwrap(),
        document.to_bytes().unwrap()
    );

    // A save through a symbolic link replaces the file it names and keeps the link.
    let target = directory.join("linked.docx");
    fs::write(&target, b"previous bytes").unwrap();
    fs::set_permissions(&target, Permissions::from_mode(0o640)).unwrap();
    let link = links.join("link.docx");
    std::os::unix::fs::symlink("../linked.docx", &link).unwrap();
    document.save(&link).unwrap();
    assert!(
        fs::symlink_metadata(&link)
            .unwrap()
            .file_type()
            .is_symlink()
    );
    assert_eq!(fs::read_link(&link).unwrap(), Path::new("../linked.docx"));
    assert_eq!(fs::read(&target).unwrap(), document.to_bytes().unwrap());
    assert_eq!(mode(&target), 0o640);

    // The savers that already staged their output now keep the mode too.
    let flat = directory.join("existing.xml");
    fs::write(&flat, b"previous bytes").unwrap();
    fs::set_permissions(&flat, Permissions::from_mode(0o600)).unwrap();
    document.save_flat_opc(&flat).unwrap();
    assert_eq!(
        fs::read(&flat).unwrap(),
        document.to_flat_opc_bytes().unwrap()
    );
    assert_eq!(mode(&flat), 0o600);

    // A save that cannot replace its destination leaves it and no staged file.
    let occupied = directory.join("directory.docx");
    fs::create_dir(&occupied).unwrap();
    assert!(document.save(&occupied).is_err());
    assert!(occupied.is_dir());

    assert!(staging_files(&directory).is_empty());
    assert!(staging_files(&links).is_empty());
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn unused_root_default_namespace_allows_atomic_save() {
    let task_namespace = "http://schemas.microsoft.com/office/tasks/2019/documenttasks";
    let xml = format!(
        r#"<w:document xmlns:w="{W_NS}" xmlns="{task_namespace}" xmlns:x="urn:producer"><w:body><x:producer x:kept="exact"/><w:p><w:r><w:t>before</w:t></w:r></w:p></w:body></w:document>"#
    );
    let mut document = document_with_content_controls(&xml);
    assert_eq!(document.try_replace_text("before", "after").unwrap(), 1);

    let saved = document.to_bytes().unwrap();
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&saved)).unwrap();
    let saved_xml = std::str::from_utf8(package.get_part("/word/document.xml").unwrap()).unwrap();
    assert!(
        saved_xml.contains(r#"xmlns:x="urn:producer""#),
        "{saved_xml}"
    );
    assert!(
        saved_xml.contains(r#"<x:producer x:kept="exact"/>"#),
        "{saved_xml}"
    );
    assert_eq!(
        Document::from_bytes(&saved)
            .unwrap()
            .paragraph(0)
            .unwrap()
            .text(),
        "after"
    );
}

#[test]
fn used_root_default_namespace_still_fails_atomically() {
    let xml = format!(
        r#"<w:document xmlns:w="{W_NS}" xmlns="urn:used-default"><w:body><producer/><w:p><w:r><w:t>before</w:t></w:r></w:p></w:body></w:document>"#
    );
    let mut document = document_with_content_controls(&xml);
    let before = document.to_bytes().unwrap();
    let error = document.try_replace_text("before", "after").unwrap_err();
    assert!(error.to_string().contains("shadowed `default` namespace"));
    assert_eq!(document.to_bytes().unwrap(), before);
}

const ISSUE_157_UNUSED_ROOT_DEFAULT: &str =
    r#" xmlns="http://schemas.microsoft.com/office/tasks/2019/documenttasks""#;

/// A Google Docs shaped main part: extra root namespace declarations, an
/// optional `goog_rdk_0` block content control and a one-cell table.
fn issue_157_document(root_declarations: &str, content_control: bool, producer: &str) -> Document {
    let inside = "<w:p><w:r><w:t>Inside the control.</w:t></w:r></w:p>";
    let inside = if content_control {
        format!(
            r#"<w:sdt><w:sdtPr><w:tag w:val="goog_rdk_0"/></w:sdtPr><w:sdtContent>{inside}</w:sdtContent></w:sdt>"#
        )
    } else {
        inside.to_owned()
    };
    document_with_content_controls(&format!(
        r#"<w:document xmlns:w="{W_NS}"{root_declarations}><w:body>{producer}<w:p><w:r><w:t>Before the control.</w:t></w:r></w:p>{inside}<w:tbl><w:tblPr/><w:tblGrid><w:gridCol w:w="2000"/></w:tblGrid><w:tr><w:tc><w:p><w:r><w:t>cell</w:t></w:r></w:p></w:tc></w:tr></w:tbl><w:sectPr/></w:body></w:document>"#
    ))
}

fn issue_157_paragraph_summary(paragraph: &ParagraphRef<'_>) -> String {
    let has_picture = paragraph.runs().any(|run| {
        run.items()
            .any(|item| matches!(item, RunItemRef::Drawing(drawing) if drawing.is_inline()))
    });
    if has_picture {
        "picture".to_owned()
    } else {
        format!("p:{}", paragraph.text())
    }
}

fn issue_157_body_summary(document: &Document) -> Vec<String> {
    document
        .body_items()
        .map(|item| match item {
            BodyItemRef::Paragraph(paragraph) => issue_157_paragraph_summary(&paragraph),
            BodyItemRef::ContentControl(control) => format!(
                "sdt:{}:{}",
                control.tag().unwrap_or_default(),
                control.text()
            ),
            BodyItemRef::Table(table) => format!(
                "table:{}",
                table
                    .cell(0, 0)
                    .unwrap()
                    .paragraphs()
                    .map(|paragraph| issue_157_paragraph_summary(&paragraph))
                    .collect::<Vec<_>>()
                    .join("|")
            ),
            BodyItemRef::UnsupportedXml(raw) => format!("raw:{}", String::from_utf8_lossy(raw)),
        })
        .collect()
}

fn issue_157_insert_picture(
    document: &mut Document,
    story: &StoryId,
    after: Option<&ContentLocation>,
) -> rdocx::Result<ContentLocation> {
    document.insert_picture_to_story(
        story,
        after,
        b"issue 157 image payload",
        "issue_157.png",
        Some(Length::pt(12.0)),
        Some(Length::pt(8.0)),
    )
}

#[test]
fn story_picture_splice_beside_content_control_ignores_unused_root_default() {
    // A story splice publishes canonical main-part XML without the unused
    // root default. The flush that follows must classify those bytes, not
    // the declarations of the part they replaced.
    for (root_default, content_control) in [(true, true), (false, true), (true, false)] {
        let case = format!("root default {root_default}, content control {content_control}");
        let root_declarations = if root_default {
            ISSUE_157_UNUSED_ROOT_DEFAULT
        } else {
            ""
        };
        let mut document = issue_157_document(root_declarations, content_control, "");
        let body = f254_story(&document, StoryKind::Body);
        let anchor = document
            .story_items(&body)
            .unwrap()
            .into_iter()
            .find(|item| {
                if content_control {
                    item.kind() == StoryItemKind::ContentControl
                } else {
                    item.text().unwrap().as_deref() == Some("Inside the control.")
                }
            })
            .unwrap()
            .location()
            .clone();
        let after = issue_157_insert_picture(&mut document, &body, Some(&anchor))
            .unwrap_or_else(|error| panic!("{case}: picture after the anchor: {error}"));
        assert_eq!(after.item_kind(), StoryItemKind::Paragraph, "{case}");

        let cell = f254_story(&document, StoryKind::TableCell);
        issue_157_insert_picture(&mut document, &cell, None)
            .unwrap_or_else(|error| panic!("{case}: picture in the table cell: {error}"));
        let cell = f254_story(&document, StoryKind::TableCell);
        document
            .add_hyperlink_to_story(&cell, "link", "https://example.invalid/issue-157")
            .unwrap_or_else(|error| panic!("{case}: hyperlink in the table cell: {error}"));
        let body = f254_story(&document, StoryKind::Body);
        issue_157_insert_picture(&mut document, &body, None)
            .unwrap_or_else(|error| panic!("{case}: appended picture: {error}"));

        let anchor = if content_control {
            "sdt:goog_rdk_0:Inside the control."
        } else {
            "p:Inside the control."
        };
        let expected = [
            "p:Before the control.",
            anchor,
            "picture",
            "table:p:cell|picture|p:link",
            "picture",
        ];
        assert_eq!(issue_157_body_summary(&document), expected, "{case}");
        let saved = document.to_bytes().unwrap();
        let reopened = Document::from_bytes(&saved).unwrap();
        assert_eq!(issue_157_body_summary(&reopened), expected, "{case}");
    }
}

#[test]
fn rewritten_root_namespaces_block_story_splices_atomically() {
    // The canonical main-part source of a story splice drops the root
    // default and rebinds the root `w`, `r` and `mc` prefixes, so retained
    // content that uses one of those root bindings would silently change
    // namespace.
    let roots = [
        (r#" xmlns="urn:used-default""#, "<producer/>", "default"),
        (r#" xmlns:r="urn:not-relationships""#, "<r:producer/>", "r"),
        (
            r#" xmlns:mc="urn:not-compatibility""#,
            "<mc:producer/>",
            "mc",
        ),
    ];
    for (root_declarations, producer, prefix) in roots {
        for content_control in [false, true] {
            let case = format!("{prefix}, content control {content_control}");
            let mut document = issue_157_document(root_declarations, content_control, producer);
            let before = document.to_bytes().unwrap();
            let body = f254_story(&document, StoryKind::Body);
            let cell = f254_story(&document, StoryKind::TableCell);
            let errors = [
                issue_157_insert_picture(&mut document, &body, None).unwrap_err(),
                issue_157_insert_picture(&mut document, &cell, None).unwrap_err(),
                document
                    .insert_content(&ContentLocation::end(body), f254_paragraph("spliced"))
                    .unwrap_err(),
            ];
            for error in errors {
                assert!(
                    error
                        .to_string()
                        .contains(&format!("shadowed `{prefix}` namespace")),
                    "{case}: {error}"
                );
            }
            assert_eq!(document.to_bytes().unwrap(), before, "{case}");
        }
    }
}

#[test]
fn body_declarations_and_a_rebound_root_w_block_story_splices_atomically() {
    // The canonical main-part source drops every declaration on `w:body`, so
    // a raw element nested in a paragraph or run would keep an unbound
    // prefix. It also binds the root `w` prefix to WordprocessingML, so a
    // producer element under another root `w` binding would change namespace.
    for content_control in [false, true] {
        let control = |q: &str| {
            if content_control {
                format!(
                    r#"<{q}:sdt><{q}:sdtPr><{q}:tag {q}:val="goog_rdk_0"/></{q}:sdtPr><{q}:sdtContent><{q}:p><{q}:r><{q}:t>Inside the control.</{q}:t></{q}:r></{q}:p></{q}:sdtContent></{q}:sdt>"#
                )
            } else {
                String::new()
            }
        };
        let (w_control, q_control) = (control("w"), control("q"));
        let documents = [
            (
                format!(
                    r#"<w:document xmlns:w="{W_NS}"><w:body xmlns:x="urn:x"><w:p><w:r><x:producer/><w:t>run</w:t></w:r></w:p>{w_control}<w:sectPr/></w:body></w:document>"#
                ),
                "x",
            ),
            (
                format!(
                    r#"<w:document xmlns:w="{W_NS}"><w:body xmlns:x="urn:x"><w:p><x:producer/><w:r><w:t>run</w:t></w:r></w:p>{w_control}<w:sectPr/></w:body></w:document>"#
                ),
                "x",
            ),
            (
                format!(
                    r#"<q:document xmlns:q="{W_NS}" xmlns:w="urn:producer"><q:body><w:producer/><q:p><q:r><q:t>run</q:t></q:r></q:p>{q_control}<q:sectPr/></q:body></q:document>"#
                ),
                "w",
            ),
        ];
        for (xml, prefix) in documents {
            let case = format!("content control {content_control}: {xml}");
            let mut document = document_with_content_controls(&xml);
            let before = document.to_bytes().unwrap();
            let body = f254_story(&document, StoryKind::Body);
            let errors = [
                issue_157_insert_picture(&mut document, &body, None).unwrap_err(),
                document
                    .insert_content(&ContentLocation::end(body), f254_paragraph("spliced"))
                    .unwrap_err(),
            ];
            for error in errors {
                assert!(
                    error
                        .to_string()
                        .contains(&format!("shadowed `{prefix}` namespace")),
                    "{case}: {error}"
                );
            }
            assert_eq!(document.to_bytes().unwrap(), before, "{case}");
        }
    }
}

#[test]
fn try_replace_text_publishes_only_a_preflighted_candidate() {
    let mut document = Document::new();
    document.add_paragraph("before before");
    assert_eq!(document.try_replace_text("before", "after").unwrap(), 2);
    assert_eq!(document.paragraph(0).unwrap().text(), "after after");

    let bytes = document.to_bytes().unwrap();
    let reopened = Document::from_bytes(&bytes).unwrap();
    assert_eq!(reopened.paragraph(0).unwrap().text(), "after after");
}

#[test]
fn expanded_raw_markers_disambiguate_a_valid_owner_edit() {
    let xml = r#"<q:document xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><q:body>
      <q:p xmlns:x="urn:same"><x:a/><x:b mark="same"></x:b><q:r><q:t>first</q:t></q:r></q:p>
      <q:p xmlns:x="urn:same"><x:a/><x:b mark='same'></x:b><q:r><q:t>second</q:t></q:r></q:p>
    </q:body></q:document>"#;
    let mut document = document_with_content_controls(xml);
    document
        .paragraph_mut(0)
        .unwrap()
        .run_mut(0)
        .unwrap()
        .set_text("first edited");
    let saved = document.to_bytes().unwrap();
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&saved)).unwrap();
    let saved_xml = std::str::from_utf8(package.get_part("/word/document.xml").unwrap()).unwrap();
    assert!(saved_xml.contains(r#"<x:b mark="same"></x:b>"#));
    assert!(saved_xml.contains("first edited"));
    let reopened = Document::from_bytes(&saved).unwrap();
    assert_eq!(reopened.paragraph(0).unwrap().text(), "first edited");
}

#[test]
fn exact_marker_cardinality_disambiguates_a_valid_owner_edit() {
    let xml = r#"<q:document xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><q:body>
      <q:p xmlns:x="urn:same"><x:a/><x:a/><q:r><q:t>first</q:t></q:r></q:p>
      <q:p xmlns:x="urn:same"><x:a/><x:a /><q:r><q:t>second</q:t></q:r></q:p>
    </q:body></q:document>"#;
    let mut document = document_with_content_controls(xml);
    document
        .paragraph_mut(0)
        .unwrap()
        .run_mut(0)
        .unwrap()
        .set_text("first edited");
    let saved = document.to_bytes().unwrap();
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&saved)).unwrap();
    let saved_xml = std::str::from_utf8(package.get_part("/word/document.xml").unwrap()).unwrap();
    assert_eq!(saved_xml.matches("<x:a/>").count(), 3);
    assert_eq!(saved_xml.matches("<x:a />").count(), 1);
    assert!(saved_xml.contains("first edited"));
    let reopened = Document::from_bytes(&saved).unwrap();
    assert_eq!(reopened.paragraph(0).unwrap().text(), "first edited");
}

#[test]
fn nested_wp_collisions_preserve_unchanged_bytes_and_fail_closed_when_modified() {
    let xml = r#"<q:document xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
        <q:body><q:p xmlns:wp="urn:foreign"><wp:producer/><q:r><q:t>typed</q:t></q:r></q:p></q:body>
      </q:document>"#;
    let mut unchanged = document_with_content_controls(xml);
    let source = ordered_reader_snapshot(&unchanged);
    let saved = unchanged.to_bytes().unwrap();
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&saved)).unwrap();
    assert_eq!(
        package.get_part("/word/document.xml").unwrap(),
        xml.as_bytes()
    );
    let reopened = Document::from_bytes(&saved).unwrap();
    assert_eq!(ordered_reader_snapshot(&reopened), source);

    let mut modified = document_with_content_controls(xml);
    modified.add_paragraph("changed");
    let error = modified.to_bytes().unwrap_err();
    assert!(error.to_string().contains("shadowed `wp` namespace"));
}

#[test]
fn fixed_prefix_collisions_fail_closed_after_owner_insert_remove_and_reorder() {
    let xml = r#"<q:document xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><q:body>
      <q:p><q:r><q:t>decoy</q:t></q:r></q:p>
      <q:p xmlns:wp="urn:foreign"><wp:producer/><q:r><q:t>target</q:t></q:r></q:p>
    </q:body></q:document>"#;

    let mut unchanged = document_with_content_controls(xml);
    let saved = unchanged.to_bytes().unwrap();
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&saved)).unwrap();
    assert_eq!(
        package.get_part("/word/document.xml").unwrap(),
        xml.as_bytes()
    );
    Document::from_bytes(&saved).unwrap();

    for mutation in ["insert", "remove", "reorder"] {
        let mut document = document_with_content_controls(xml);
        match mutation {
            "insert" => {
                document.insert_paragraph(0, "inserted");
            }
            "remove" => {
                assert!(document.remove_content(0));
            }
            "reorder" => {
                assert!(document.remove_content(0));
                document.add_paragraph("moved decoy");
            }
            _ => unreachable!(),
        }
        let error = document.to_bytes().unwrap_err();
        assert!(
            error.to_string().contains("shadowed `wp` namespace"),
            "{mutation} must fail closed: {error}",
        );
    }
}

#[test]
fn escaped_root_namespace_uris_decode_once_across_unchanged_and_modified_saves() {
    let xml = r#"<q:document xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
                  xmlns:x="urn:a&amp;b"><q:body><x:producer/></q:body></q:document>"#;
    for modified in [false, true] {
        let mut document = document_with_content_controls(xml);
        let BodyContentRef::UnsupportedXml(fact) = document.body_content().next().unwrap() else {
            panic!("expected unsupported fact");
        };
        assert_eq!(fact.namespace_uri(), Some("urn:a&b"));
        if modified {
            document.add_paragraph("changed");
        }

        let saved = document.to_bytes().unwrap();
        let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&saved)).unwrap();
        let saved_xml =
            std::str::from_utf8(package.get_part("/word/document.xml").unwrap()).unwrap();
        assert!(saved_xml.contains(r#"xmlns:x="urn:a&amp;b""#));
        assert!(!saved_xml.contains("urn:a&amp;amp;b"));

        let reopened = Document::from_bytes(&saved).unwrap();
        let BodyContentRef::UnsupportedXml(fact) = reopened.body_content().next().unwrap() else {
            panic!("expected reopened unsupported fact");
        };
        assert_eq!(fact.namespace_uri(), Some("urn:a&b"));
        if modified {
            assert_eq!(reopened.paragraph(0).unwrap().text(), "changed");
        }
    }
}

#[test]
fn empty_modeled_controls_and_numeric_references_report_visible_content_accurately() {
    let xml = r#"<q:document xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
                  xmlns:x="urn:foreign"><q:body><q:sdt></q:sdt>
        <x:space>&#32;</x:space><x:tab>&#x9;</x:tab><x:newline>&#xA;</x:newline>
        <x:return>&#13;</x:return><x:visible>&#65;</x:visible><x:named>&amp;</x:named>
      </q:body></q:document>"#;
    let document = document_with_content_controls(xml);
    let facts = document.body_content().collect::<Vec<_>>();
    assert_eq!(facts.len(), 7);
    let BodyContentRef::UnsupportedXml(control) = &facts[0] else {
        panic!("expected modeled control fact");
    };
    assert_eq!(control.raw_xml(), None);
    assert!(!control.has_child_content());
    for fact in &facts[1..5] {
        let BodyContentRef::UnsupportedXml(fact) = fact else {
            panic!("expected raw unsupported fact");
        };
        assert!(!fact.has_child_content());
    }
    for fact in &facts[5..] {
        let BodyContentRef::UnsupportedXml(fact) = fact else {
            panic!("expected raw unsupported fact");
        };
        assert!(fact.has_child_content());
    }
}

#[test]
fn unrendered_number_formats_survive_without_decimal_coercion() {
    for (format, expected_bullet, expect_rtf_diagnostic) in [
        ("producerFormat", None, true),
        ("chicago", Some(false), false),
    ] {
        let document_xml = wrap_word_body(
            r#"<w:p><w:pPr><w:numPr><w:ilvl w:val="0"/><w:numId w:val="1"/></w:numPr></w:pPr><w:r><w:t>item</w:t></w:r></w:p>"#,
        );
        let numbering_xml = format!(
            r#"<w:numbering xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:abstractNum w:abstractNumId="1"><w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="{format}"/><w:lvlText w:val="%1."/></w:lvl></w:abstractNum><w:num w:numId="1"><w:abstractNumId w:val="1"/></w:num></w:numbering>"#
        );
        let mut seed = Document::new();
        let mut package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap()))
                .unwrap();
        package.set_part("/word/document.xml", document_xml.into_bytes());
        package.set_part("/word/numbering.xml", numbering_xml.into_bytes());
        package.content_types.add_override(
            "/word/numbering.xml",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.numbering+xml",
        );
        package.get_or_create_part_rels("/word/document.xml").add(
            oxml_opc::relationship::rel_types::NUMBERING,
            "numbering.xml",
        );
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();

        let mut document = Document::from_bytes(bytes.get_ref()).unwrap();
        assert_eq!(document.numbering_is_bullet(1), expected_bullet);
        let html = document.to_html_fragment();
        assert!(!html.contains("<ol>"));
        assert!(!html.contains("<ul>"));
        let markdown = document.to_markdown();
        assert!(!markdown.contains("1. item"));
        assert!(!markdown.contains("- item"));
        let has_rtf_diagnostic = document
            .to_rtf_bytes()
            .unwrap()
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.message.contains("numbering format"));
        assert_eq!(has_rtf_diagnostic, expect_rtf_diagnostic);

        let saved = document.to_bytes().unwrap();
        let reopened = Document::from_bytes(&saved).unwrap();
        assert_eq!(reopened.numbering_is_bullet(1), expected_bullet);
        let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(saved)).unwrap();
        let numbering =
            std::str::from_utf8(package.get_part("/word/numbering.xml").unwrap()).unwrap();
        assert!(numbering.contains(&format!(r#"<w:numFmt w:val="{format}"/>"#)));
    }
}

#[test]
fn paragraph_markers_report_whether_their_source_elements_contain_children() {
    let document = document_with_content_controls(
        r#"<q:document xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
          <q:body><q:p>
            <q:commentRangeStart q:id="1"><q:r><q:t>unexpected</q:t></q:r></q:commentRangeStart>
            <q:commentRangeEnd q:id="1"/>
            <q:bookmarkStart q:id="2" q:name="target"><q:r><q:t>unexpected</q:t></q:r></q:bookmarkStart>
            <q:bookmarkEnd q:id="2"/>
          </q:p></q:body>
        </q:document>"#,
    );
    let paragraph = document.paragraph(0).expect("paragraph");
    let markers = paragraph
        .items()
        .filter_map(|item| match item {
            ParagraphItemRef::CommentRangeStart {
                has_child_content, ..
            }
            | ParagraphItemRef::CommentRangeEnd {
                has_child_content, ..
            }
            | ParagraphItemRef::BookmarkStart {
                has_child_content, ..
            }
            | ParagraphItemRef::BookmarkEnd {
                has_child_content, ..
            } => Some(has_child_content),
            _ => None,
        })
        .collect::<Vec<_>>();

    assert_eq!(markers, [true, false, true, false]);
}

#[test]
fn mixed_run_content_reopens_and_renders_in_source_order() {
    const PNG: &[u8] = &[
        0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0x00, 0x00, 0x00, 0x0d, 0x49, 0x48, 0x44,
        0x52, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x06, 0x00, 0x00, 0x00, 0x1f,
        0x15, 0xc4, 0x89, 0x00, 0x00, 0x00, 0x0d, 0x49, 0x44, 0x41, 0x54, 0x78, 0x9c, 0x63, 0x60,
        0xf8, 0xcf, 0xf0, 0x00, 0x00, 0x04, 0x01, 0x01, 0x08, 0x9d, 0x1d, 0xe1, 0x00, 0x00, 0x00,
        0x00, 0x49, 0x45, 0x4e, 0x44, 0xae, 0x42, 0x60, 0x82,
    ];

    let mut document = Document::new();
    let relationship_id = document.embed_image(PNG, "pixel.png");
    {
        let mut paragraph = document.add_paragraph("");
        let mut run = paragraph.add_run("first");
        run.add_tab();
        run.add_break(BreakKind::Line);
        run.add_break(BreakKind::Page);
        run.add_break(BreakKind::Column);
        run.add_picture(&relationship_id, Length::pt(1.0), Length::pt(1.0));
        run.add_field("PAGE", "2").unwrap();
        run.add_symbol('§');
        run.add_text("last");
        run.set_bold(true);
        run.set_italic(true);
        run.set_underline_style(UnderlineStyle::Double);
        run.set_size(11.0);
        run.set_font("Carlito");
        run.set_language("en-GB");
        run.set_color("123456");
        run.set_highlight("yellow");
        run.set_strike(true);
        run.set_double_strike(false);
        run.set_all_caps(false);
        run.set_small_caps(false);
        run.set_superscript();
        run.set_subscript();
        run.set_character_spacing(Length::pt(0.5));
        run.set_width_scale(100);
        run.set_position(0);
        run.set_hidden(false);
        run.set_style("Emphasis");
    }

    let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let mut raw_subtrees = Vec::new();
    let paragraph = reopened.paragraph(0).unwrap();
    let snapshot = (0..paragraph.run_count())
        .map(|index| run_snapshot(paragraph.run(index).unwrap(), &mut raw_subtrees))
        .collect::<Vec<_>>()
        .join(",");
    assert_eq!(
        snapshot,
        "text:first,tab,break:line,break:page,break:column,drawing:true:false:Some(\"rId1\"):Some(\"Picture\"):None:Some(12700):Some(12700),field:PAGE:PAGE:2:None,text:§,text:last"
    );
    assert!(paragraph.run(0).unwrap().is_bold());
    assert!(paragraph.run(0).unwrap().is_italic());
    let field_run = paragraph.run(1).unwrap();
    let RunItemRef::Field(field) = field_run.items().next().unwrap() else {
        panic!("middle run must contain the authored field");
    };
    let field_segments = field.cached_display_segments();
    let field_properties = field_segments[0].properties().unwrap();
    assert_eq!(field_properties.bold, Some(true));
    assert_eq!(field_properties.italic, Some(true));
    assert!(paragraph.run(2).unwrap().is_bold());
    assert!(paragraph.run(2).unwrap().is_italic());
    assert!(
        reopened
            .to_pdf_deterministic()
            .unwrap()
            .starts_with(b"%PDF-")
    );
}

#[test]
fn run_level_page_breaks_match_word_pagination() {
    assert_eq!(
        WORD_FX101_ORACLE,
        "Microsoft Word 16.104 build 16.104.25121423"
    );
    assert_eq!(
        WORD_FX101_ENVIRONMENT,
        "macOS; locale=en-GB; normalization=fx101-run-page-break-pages-v1"
    );

    let page_texts = |document: &mut Document| {
        let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        reopened
            .layout_deterministic()
            .unwrap()
            .layout
            .pages
            .iter()
            .map(|page| f252_page_text(page))
            .collect::<Vec<_>>()
    };

    let mut inline = Document::new();
    {
        let mut paragraph = inline.add_paragraph("");
        let mut run = paragraph.add_run("Alpha");
        run.add_break(BreakKind::Page);
        run.add_text("Bravo");
    }
    assert_eq!(page_texts(&mut inline), ["Alpha", "Bravo"]);

    let mut own_paragraph = Document::new();
    own_paragraph.add_paragraph("Alpha");
    {
        let mut paragraph = own_paragraph.add_paragraph("");
        paragraph.add_run("").add_break(BreakKind::Page);
    }
    own_paragraph.add_paragraph("Bravo");
    assert_eq!(page_texts(&mut own_paragraph), ["Alpha", "Bravo"]);
}

#[test]
fn adjacent_run_and_paragraph_page_breaks_share_one_transition() {
    const ORACLE: &str = "LibreOffice 26.2.5.2";
    assert_eq!(ORACLE, "LibreOffice 26.2.5.2");

    let page_texts = |document: &mut Document| {
        let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        reopened
            .layout_deterministic()
            .unwrap()
            .layout
            .pages
            .iter()
            .map(|page| f252_page_text(page))
            .collect::<Vec<_>>()
    };
    let build = |run_break: bool, page_break_before: bool, separated: bool| {
        let mut document = Document::new();
        let mut first = document.add_paragraph("Section one body text.");
        if run_break {
            first.add_run("").add_break(BreakKind::Page);
        }
        if separated {
            document.add_paragraph("Intervening content.");
        }
        document
            .add_paragraph("Section two heading")
            .page_break_before(page_break_before);
        document.add_paragraph("Section two body text.");
        page_texts(&mut document)
    };

    assert_eq!(
        build(false, true, false),
        [
            "Section one body text.",
            "Section two headingSection two body text."
        ]
    );
    assert_eq!(
        build(true, false, false),
        [
            "Section one body text.",
            "Section two headingSection two body text."
        ]
    );
    assert_eq!(
        build(true, true, false),
        [
            "Section one body text.",
            "Section two headingSection two body text."
        ]
    );
    assert_eq!(
        build(true, true, true),
        [
            "Section one body text.",
            "Intervening content.",
            "Section two headingSection two body text."
        ]
    );
}

#[test]
fn run_page_break_pagination_reaches_fragments_fields_pdf_and_png() {
    let source = wrap_word_body(
        r#"<w:p><w:pPr><w:pStyle w:val="TOC1"/></w:pPr><w:r><w:t>TOC</w:t></w:r><w:fldSimple w:instr="PAGEREF destination"><w:r><w:t>stored TOC target</w:t></w:r></w:fldSimple></w:p><w:p><w:r><w:t>Alpha</w:t><w:br w:type="page"/></w:r><w:bookmarkStart w:id="7" w:name="destination"/><w:r><w:t>Bravo</w:t></w:r><w:fldSimple w:instr="PAGE"><w:r><w:t>stored page</w:t></w:r></w:fldSimple><w:r><w:t>/</w:t></w:r><w:fldSimple w:instr="NUMPAGES"><w:r><w:t>stored count</w:t></w:r></w:fldSimple><w:r><w:t>/</w:t></w:r><w:fldSimple w:instr="PAGEREF destination"><w:r><w:t>stored reference</w:t></w:r></w:fldSimple><w:bookmarkEnd w:id="7"/></w:p>"#,
    );
    let document = document_with_content_controls(&source);
    let layout = document.layout_deterministic().unwrap();
    let page_text = layout
        .layout
        .pages
        .iter()
        .map(|page| f252_page_text(page))
        .collect::<Vec<_>>();
    assert_eq!(page_text, ["TOC2Alpha", "Bravo2/2/2"]);
    assert_eq!(
        layout
            .body_layout_fragments(1)
            .unwrap()
            .iter()
            .map(|fragment| fragment.physical_page)
            .collect::<Vec<_>>(),
        [1, 2]
    );

    for page_index in 0..2 {
        assert!(
            document
                .render_page_to_png_deterministic(page_index, 24.0)
                .unwrap()
                .unwrap()
                .starts_with(b"\x89PNG\r\n\x1a\n")
        );
    }
    assert!(
        document
            .render_page_to_png_deterministic(2, 24.0)
            .unwrap()
            .is_none()
    );

    let pdf = document.to_pdf_deterministic().unwrap();
    let nonce = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let directory =
        std::env::temp_dir().join(format!("rdocx-fx101-pdf-{}-{nonce}", std::process::id()));
    std::fs::create_dir_all(&directory).unwrap();
    let path = directory.join("run-page-break.pdf");
    std::fs::write(&path, pdf).unwrap();
    let info = std::process::Command::new("pdfinfo")
        .arg(&path)
        .output()
        .unwrap();
    assert!(info.status.success());
    let info = String::from_utf8(info.stdout).unwrap();
    let pages = info
        .lines()
        .find_map(|line| line.strip_prefix("Pages:").map(str::trim))
        .unwrap();
    assert_eq!(pages, "2");
    std::fs::remove_dir_all(directory).unwrap();
}

#[test]
fn mixed_run_field_append_preserves_raw_boundaries_and_rejects_invalid_fields() {
    let xml = wrap_word_body(
        r#"<w:p><w:r><w:t>before</w:t><x:custom xmlns:x="urn:custom"/></w:r></w:p>"#,
    );
    let mut document = document_with_content_controls(&xml);
    {
        let mut paragraph = document.paragraph_mut(0).unwrap();
        let mut run = paragraph.run_mut(0).unwrap();
        assert!(run.add_field("", "ignored").is_err());
        assert_eq!(run.text(), "before");
        run.add_field("DATE", "today").unwrap();
        run.add_text("after");
        run.set_bold(true);
    }

    let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let paragraph = reopened.paragraph(0).unwrap();
    let mut raw_subtrees = Vec::new();
    let snapshot = (0..paragraph.run_count())
        .map(|index| run_snapshot(paragraph.run(index).unwrap(), &mut raw_subtrees))
        .collect::<Vec<_>>()
        .join(",");
    assert_eq!(
        snapshot,
        "text:before,raw:<x:custom xmlns:x=\"urn:custom\"/>,field:DATE:DATE:today:None,text:after"
    );
    assert!(paragraph.run(0).unwrap().is_bold());
    assert!(paragraph.run(2).unwrap().is_bold());
}

#[test]
fn legacy_flattened_accessors_keep_their_recursive_results() {
    let xml = wrap_word_body(
        "<w:tbl><w:tr><w:tc><w:p><w:r><w:t>direct</w:t></w:r></w:p><w:tbl><w:tr><w:tc><w:p><w:r><w:t>nested</w:t></w:r></w:p></w:tc></w:tr></w:tbl><w:sdt><w:sdtContent><w:p><w:r><w:t>control</w:t></w:r></w:p></w:sdtContent></w:sdt></w:tc></w:tr></w:tbl>",
    );
    let document = document_with_content_controls(&xml);
    let table = document.table(0).unwrap();
    let cell = table.cell(0, 0).unwrap();
    assert_eq!(
        cell.paragraphs()
            .map(|paragraph| paragraph.text())
            .collect::<Vec<_>>(),
        ["direct", "control"]
    );
    assert_eq!(
        document
            .paragraphs()
            .into_iter()
            .map(|paragraph| paragraph.text())
            .collect::<Vec<_>>(),
        Vec::<String>::new()
    );
}

fn unsupported_fact_snapshot(
    fact: UnsupportedXmlRef<'_>,
    raw_subtrees: &mut Vec<Vec<u8>>,
) -> String {
    let raw = fact.raw_xml().map(|raw| {
        raw_subtrees.push(raw.to_vec());
        std::str::from_utf8(raw).unwrap().to_owned()
    });
    format!(
        "unsupported:{:?}:{:?}:{}:{}:{raw:?}",
        fact.qualified_name(),
        fact.namespace_uri(),
        fact.local_name(),
        fact.has_child_content(),
    )
}

fn run_snapshot(run: RunRef<'_>, raw_subtrees: &mut Vec<Vec<u8>>) -> String {
    run.items()
        .map(|item| match item {
            RunItemRef::Text(text) => format!("text:{text}"),
            RunItemRef::DeletedText(text) => format!("deleted:{text}"),
            RunItemRef::Tab => "tab".to_owned(),
            RunItemRef::Break(BreakKind::Line) => "break:line".to_owned(),
            RunItemRef::Break(BreakKind::Page) => "break:page".to_owned(),
            RunItemRef::Break(BreakKind::Column) => "break:column".to_owned(),
            RunItemRef::Drawing(drawing) => format!(
                "drawing:{}:{}:{:?}:{:?}:{:?}:{:?}:{:?}",
                drawing.is_inline(),
                drawing.is_anchor(),
                drawing.relationship_id(),
                drawing.name(),
                drawing.description(),
                drawing.width().map(Length::to_emu),
                drawing.height().map(Length::to_emu),
            ),
            RunItemRef::Field(field) => format!(
                "field:{}:{}:{}:{:?}",
                field.instruction(),
                field.name(),
                field.cached_result(),
                field.dirty(),
            ),
            RunItemRef::FootnoteReference(id) => format!("footnote:{id}"),
            RunItemRef::EndnoteReference(id) => format!("endnote:{id}"),
            RunItemRef::CommentReference(id) => format!("comment:{id}"),
            RunItemRef::UnsupportedXml(raw) => {
                raw_subtrees.push(raw.to_vec());
                format!("raw:{}", std::str::from_utf8(raw).unwrap())
            }
            _ => panic!("unexpected run item"),
        })
        .collect::<Vec<_>>()
        .join(",")
}

fn hyperlink_snapshot(hyperlink: HyperlinkRef<'_>, raw_subtrees: &mut Vec<Vec<u8>>) -> String {
    let items = hyperlink
        .items()
        .map(|item| match item {
            HyperlinkItemRef::Run(run) => format!("run:[{}]", run_snapshot(run, raw_subtrees)),
            HyperlinkItemRef::Revision(revision) => format!(
                "revision:{}:{}:{:?}",
                revision.id(),
                revision.author(),
                revision.kind(),
            ),
            HyperlinkItemRef::UnsupportedXml(raw) => {
                raw_subtrees.push(raw.to_vec());
                format!("raw:{}", std::str::from_utf8(raw).unwrap())
            }
            _ => panic!("unexpected hyperlink item"),
        })
        .collect::<Vec<_>>()
        .join(",");
    format!(
        "hyperlink:{:?}:{:?}:[{items}]",
        hyperlink.relationship_id(),
        hyperlink.anchor(),
    )
}

fn paragraph_snapshot(paragraph: ParagraphRef<'_>, raw_subtrees: &mut Vec<Vec<u8>>) -> String {
    paragraph
        .items()
        .map(|item| match item {
            ParagraphItemRef::Run(run) => format!("run:[{}]", run_snapshot(run, raw_subtrees)),
            ParagraphItemRef::Hyperlink(hyperlink) => hyperlink_snapshot(hyperlink, raw_subtrees),
            ParagraphItemRef::ContentControl(control) => {
                format!("control:{}", control.text())
            }
            ParagraphItemRef::Revision(revision) => format!(
                "revision:{}:{}:{:?}",
                revision.id(),
                revision.author(),
                revision.kind(),
            ),
            ParagraphItemRef::CommentRangeStart { id, .. } => format!("comment-start:{id}"),
            ParagraphItemRef::CommentRangeEnd { id, .. } => format!("comment-end:{id}"),
            ParagraphItemRef::BookmarkStart { id, name, .. } => {
                format!("bookmark-start:{id:?}:{name:?}")
            }
            ParagraphItemRef::BookmarkEnd { id, .. } => format!("bookmark-end:{id:?}"),
            ParagraphItemRef::UnsupportedXml(raw) => {
                raw_subtrees.push(raw.to_vec());
                format!("raw:{}", std::str::from_utf8(raw).unwrap())
            }
            _ => panic!("unexpected paragraph item"),
        })
        .collect::<Vec<_>>()
        .join(",")
}

fn table_snapshot(table: TableRef<'_>, raw_subtrees: &mut Vec<Vec<u8>>) -> String {
    let rows = (0..table.row_count())
        .map(|row_index| {
            let row = table.row(row_index).unwrap();
            let cells = (0..row.cell_count())
                .map(|cell_index| cell_snapshot(row.cell(cell_index).unwrap(), raw_subtrees))
                .collect::<Vec<_>>()
                .join("|");
            format!("row:[{cells}]")
        })
        .collect::<Vec<_>>()
        .join("|");
    format!("table:[{rows}]")
}

fn cell_snapshot(cell: CellRef<'_>, raw_subtrees: &mut Vec<Vec<u8>>) -> String {
    cell.items()
        .map(|item| match item {
            CellItemRef::Paragraph(paragraph) => {
                format!(
                    "paragraph:[{}]",
                    paragraph_snapshot(paragraph, raw_subtrees)
                )
            }
            CellItemRef::Table(table) => table_snapshot(table, raw_subtrees),
            CellItemRef::ContentControl(control) => format!("control:{}", control.text()),
            CellItemRef::UnsupportedXml(raw) => {
                raw_subtrees.push(raw.to_vec());
                format!("raw:{}", std::str::from_utf8(raw).unwrap())
            }
            _ => panic!("unexpected cell item"),
        })
        .collect::<Vec<_>>()
        .join(",")
}

fn ordered_reader_snapshot(document: &Document) -> (Vec<String>, Vec<Vec<u8>>) {
    let mut raw_subtrees = Vec::new();
    let facts = document
        .body_content()
        .map(|item| match item {
            BodyContentRef::Paragraph(paragraph) => {
                format!(
                    "paragraph:[{}]",
                    paragraph_snapshot(paragraph, &mut raw_subtrees)
                )
            }
            BodyContentRef::Table(table) => table_snapshot(table, &mut raw_subtrees),
            BodyContentRef::UnsupportedXml(fact) => {
                unsupported_fact_snapshot(fact, &mut raw_subtrees)
            }
            _ => panic!("unexpected body item"),
        })
        .collect::<Vec<_>>();
    (facts, raw_subtrees)
}

#[test]
fn ordered_reader_source_survives_save_and_reopen() {
    let xml = ordered_reader_fixture();
    let mut document = document_with_content_controls(xml);
    let source = ordered_reader_snapshot(&document);
    let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let reopened = ordered_reader_snapshot(&reopened);
    assert_eq!(reopened.0, source.0, "ordered public facts changed");
    assert_eq!(reopened.1, source.1, "raw subtrees changed");
}

fn document_with_bound_content_controls(document_xml: &str, custom_xml: Option<&str>) -> Document {
    let mut seed = Document::new();
    let bytes = seed.to_bytes().unwrap();
    let mut package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).unwrap();
    package.set_part("/word/document.xml", document_xml.as_bytes().to_vec());

    if let Some(custom_xml) = custom_xml {
        package.set_part("/customXml/item1.xml", custom_xml.as_bytes().to_vec());
        package.set_part(
            "/customXml/itemProps1.xml",
            br#"<?xml version="1.0" encoding="UTF-8" standalone="no"?><ds:datastoreItem ds:itemID="{11111111-1111-1111-1111-111111111111}" xmlns:ds="http://schemas.openxmlformats.org/officeDocument/2006/customXml"><ds:schemaRefs/></ds:datastoreItem>"#
                .to_vec(),
        );
        package
            .get_or_create_part_rels("/word/document.xml")
            .add(CUSTOM_XML_REL_TYPE, "../customXml/item1.xml");
        package
            .get_or_create_part_rels("/customXml/item1.xml")
            .add(CUSTOM_XML_PROPS_REL_TYPE, "itemProps1.xml");
        package.content_types.add_override(
            "/customXml/itemProps1.xml",
            "application/vnd.openxmlformats-officedocument.customXmlProperties+xml",
        );
    }

    let mut output = std::io::Cursor::new(Vec::new());
    package.write_to(&mut output).unwrap();
    Document::from_bytes(output.get_ref()).unwrap()
}

fn wrap_word_body(body: &str) -> String {
    format!(
        r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>{body}</w:body></w:document>"#
    )
}

fn body_from_document(document: &mut Document) -> CT_Body {
    let package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
            .unwrap();
    CT_Document::from_xml(package.get_part("/word/document.xml").unwrap())
        .unwrap()
        .body
}

fn document_xml(document: &mut Document) -> String {
    let package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
            .unwrap();
    String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap()
}

#[test]
fn paragraph_run_and_section_identity_attributes_survive_noop_save() {
    let xml = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:i="http://schemas.microsoft.com/office/word/2010/wordml" xmlns:x="urn:producer"><w:body><w:p i:paraId="12345670" i:textId="76543210" w:rsidR="00AB12CD" w:rsidRDefault="00AB12CE" w:rsidP="00AB12CF" x:paragraph="kept" plain="also-kept"><w:r w:rsidRPr="00AB12D0" x:run="kept"><w:t>before</w:t></w:r></w:p><w:sectPr w:rsidR="00AB12D1" w:rsidRPr="00AB12D2" w:rsidSect="00AB12D3" x:section="kept"><w:pgSz w:w="12240" w:h="15840"/></w:sectPr></w:body></w:document>"#;
    let mut document = document_with_content_controls(xml);
    let paragraph = document.paragraph(0).unwrap();
    assert!(
        !paragraph
            .items()
            .any(|item| matches!(item, ParagraphItemRef::UnsupportedXml(_)))
    );
    assert!(
        !paragraph
            .runs()
            .next()
            .unwrap()
            .items()
            .any(|item| matches!(item, RunItemRef::UnsupportedXml(_)))
    );

    let saved = document_xml(&mut document);
    for attribute in [
        r#"i:paraId="12345670""#,
        r#"i:textId="76543210""#,
        r#"w:rsidR="00AB12CD""#,
        r#"w:rsidRDefault="00AB12CE""#,
        r#"w:rsidP="00AB12CF""#,
        r#"w:rsidRPr="00AB12D0""#,
        r#"w:rsidR="00AB12D1""#,
        r#"w:rsidRPr="00AB12D2""#,
        r#"w:rsidSect="00AB12D3""#,
        r#"x:paragraph="kept""#,
        r#"plain="also-kept""#,
        r#"x:run="kept""#,
        r#"x:section="kept""#,
    ] {
        assert!(saved.contains(attribute), "missing {attribute}: {saved}");
    }
    let paragraph = saved.find("<w:p ").unwrap();
    let run = saved.find("<w:r ").unwrap();
    let section = saved.find("<w:sectPr ").unwrap();
    assert!(
        paragraph < run && run < section,
        "schema order changed: {saved}"
    );
    let paragraph_tag = &saved[paragraph..saved[paragraph..].find('>').unwrap() + paragraph + 1];
    let paragraph_order = [
        "i:paraId=",
        "i:textId=",
        "w:rsidR=",
        "w:rsidRDefault=",
        "w:rsidP=",
        "x:paragraph=",
        "plain=",
    ]
    .map(|attribute| paragraph_tag.find(attribute).unwrap());
    assert!(
        paragraph_order.windows(2).all(|pair| pair[0] < pair[1]),
        "paragraph attribute order changed: {paragraph_tag}"
    );

    let mut reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    reopened
        .paragraph_mut(0)
        .unwrap()
        .run_mut(0)
        .unwrap()
        .set_text("after");
    let edited = document_xml(&mut reopened);
    assert!(edited.contains("<w:t>after</w:t>"));
    for attribute in [
        r#"i:paraId="12345670""#,
        r#"i:textId="76543210""#,
        r#"w:rsidRDefault="00AB12CE""#,
        r#"w:rsidSect="00AB12D3""#,
        r#"x:paragraph="kept""#,
        r#"x:run="kept""#,
        r#"x:section="kept""#,
    ] {
        assert!(
            edited.contains(attribute),
            "edit dropped {attribute}: {edited}"
        );
    }
    let mut stable = Document::from_bytes(&reopened.to_bytes().unwrap()).unwrap();
    assert_eq!(stable.to_bytes().unwrap(), reopened.to_bytes().unwrap());
}

/// An edit rewrites the part it touches. The rewrite used to indent every
/// element and declare `w` again on every element with a `w:rsid*`
/// attribute, which Word writes on nearly every paragraph and run, so one
/// replaced word doubled the part and an XML diff showed all of it.
#[test]
fn an_edited_word_part_stays_compact_and_declares_w_once() {
    let paragraph = |index: usize| {
        format!(
            r#"<w:p w:rsidR="00AB12CD" w:rsidRDefault="00AB12CE"><w:r w:rsidRPr="00AB12CF"><w:t xml:space="preserve">Paragraph {index} alpha beta. </w:t></w:r></w:p>"#
        )
    };
    let body = (0..50).map(paragraph).collect::<String>();
    let xml = format!(
        r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="{W_NS}"><w:body>{body}<w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/></w:tblPr><w:tblGrid><w:gridCol w:w="2000"/></w:tblGrid><w:tr w:rsidR="00AB12D0"><w:tc><w:p w:rsidR="00AB12D1"><w:r><w:t>cell</w:t></w:r></w:p></w:tc></w:tr></w:tbl><w:sectPr w:rsidR="00AB12D2"><w:pgSz w:w="12240" w:h="15840"/></w:sectPr></w:body></w:document>"#
    );
    let mut document = document_with_content_controls(&xml);
    assert_eq!(
        document
            .try_replace_text("Paragraph 7 ", "Paragraph seven ")
            .unwrap(),
        1
    );

    let saved = document_xml(&mut document);
    assert_eq!(saved.matches("xmlns:w=").count(), 1, "{saved}");
    assert!(!saved.contains('\n'), "{saved}");
    assert!(saved.contains(&paragraph(6)), "{saved}");
    assert!(
        saved.contains(r#"<w:p w:rsidR="00AB12CD" w:rsidRDefault="00AB12CE"><w:r w:rsidRPr="00AB12CF"><w:t xml:space="preserve">Paragraph seven alpha beta. </w:t>"#),
        "{saved}"
    );
    assert!(saved.contains(r#"<w:tr w:rsidR="00AB12D0">"#), "{saved}");
    assert!(
        saved.contains(r#"<w:sectPr w:rsidR="00AB12D2">"#),
        "{saved}"
    );
    let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened.text().contains("Paragraph seven alpha beta."));
    assert!(reopened.text().contains("cell"));
}

/// Word and Google Docs write revision-save and paragraph identities on every
/// table row. They survived only a save with no edit, because the row model
/// had no carrier for them. They are now kept like the ones on paragraphs and
/// runs, and nothing that reads a row takes them for row content.
mod table_row_identity_attribute_regressions {
    use rdocx::Document;
    use rdocx_oxml::namespace::W_NS;

    const W14_NS: &str = "http://schemas.microsoft.com/office/word/2010/wordml";
    /// Every identity Word writes on a row, in the order it writes them.
    const ALL: &str = r#" w:rsidR="00A1B2C3" w:rsidTr="00A1B2C4" w:rsidRPr="00A1B2C5" w:rsidDel="00A1B2C6" w14:paraId="1A2B3C4D" w14:textId="5E6F7A8B""#;

    /// A paragraph to edit, then a table with two direct rows, a row inside
    /// a table-level content control and a self-closing row, each carrying
    /// `attributes`. The first cell holds `word`.
    fn row_document_xml(attributes: &str, word: &str) -> String {
        let row = |first: &str, second: &str| {
            format!(
                r#"<w:tr{attributes}><w:tc><w:p><w:r><w:t>{first}</w:t></w:r></w:p></w:tc><w:tc><w:p><w:r><w:t>{second}</w:t></w:r></w:p></w:tc></w:tr>"#
            )
        };
        let rows = [
            row(word, "one"),
            row("beta", "two"),
            format!(
                r#"<w:sdt><w:sdtPr><w:alias w:val="Rows"/></w:sdtPr><w:sdtContent>{}</w:sdtContent></w:sdt>"#,
                row("gamma", "three")
            ),
            format!("<w:tr{attributes}/>"),
        ]
        .concat();
        format!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="{W_NS}" xmlns:w14="{W14_NS}"><w:body><w:p><w:r><w:t>Body text of section 3.1.</w:t></w:r></w:p><w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/></w:tblPr><w:tblGrid><w:gridCol w:w="2000"/><w:gridCol w:w="2000"/></w:tblGrid>{rows}</w:tbl><w:p><w:r><w:t>After the table.</w:t></w:r></w:p><w:sectPr><w:pgSz w:w="12240" w:h="15840"/></w:sectPr></w:body></w:document>"#
        )
    }

    fn document_with_row_attributes(attributes: &str, word: &str) -> Document {
        super::document_with_content_controls(&row_document_xml(attributes, word))
    }

    #[test]
    fn row_identity_attributes_survive_an_edit_elsewhere() {
        // The table-row rows of the identity matrix of #159, one attribute at
        // a time, then every identity Word writes together.
        for attributes in [
            r#" w:rsidR="00A1B2C3""#,
            r#" w:rsidTr="00A1B2C4""#,
            r#" w14:paraId="1A2B3C4D""#,
            r#" w14:textId="5E6F7A8B""#,
            r#" w:rsidRPr="00A1B2C5""#,
            r#" w:rsidDel="00A1B2C6""#,
            ALL,
        ] {
            let mut document = document_with_row_attributes(attributes, "alpha");
            assert_eq!(
                document
                    .try_replace_text("Body text of section 3.1.", "Body text of section three.")
                    .unwrap(),
                1
            );
            let saved = super::document_xml(&mut document);
            assert!(saved.contains("section three"), "{saved}");
            for attribute in attributes.split_whitespace() {
                assert_eq!(saved.matches(attribute).count(), 4, "{attribute}: {saved}");
            }
            assert!(!saved.contains("rdocxRootAttributes"), "{saved}");
            for tag in saved.split("<w:tr ").skip(1) {
                let tag = &tag[..tag.find('>').unwrap()];
                assert!(
                    tag.trim_end_matches('/')
                        .starts_with(attributes.trim_start()),
                    "row attribute order changed: {tag}"
                );
            }

            let bytes = document.to_bytes().unwrap();
            let mut reopened = Document::from_bytes(&bytes).unwrap();
            assert_eq!(reopened.to_bytes().unwrap(), bytes);
        }
    }

    #[test]
    fn row_identity_attributes_are_not_row_content() {
        // A row without a cell has no grid position for the exporters.
        let document = super::document_with_content_controls(
            &row_document_xml(ALL, "alpha").replace(&format!("<w:tr{ALL}/>"), ""),
        );
        let table = document.table(0).unwrap();
        for index in 0..table.row_count() {
            assert!(!table.row(index).unwrap().has_unsupported_content());
        }
        let messages = [
            document
                .to_mhtml_bytes()
                .unwrap()
                .diagnostics
                .into_iter()
                .map(|diagnostic| diagnostic.message)
                .collect::<Vec<_>>(),
            document
                .to_odt_bytes()
                .unwrap()
                .diagnostics
                .into_iter()
                .map(|diagnostic| diagnostic.message)
                .collect(),
            document
                .to_rtf_bytes()
                .unwrap()
                .diagnostics
                .into_iter()
                .map(|diagnostic| diagnostic.message)
                .collect(),
            document
                .to_epub_bytes()
                .unwrap()
                .diagnostics
                .into_iter()
                .map(|diagnostic| diagnostic.message)
                .collect(),
        ]
        .concat();
        assert!(
            messages
                .iter()
                .all(|message| !message.contains("table-row XML")
                    && message != "dropped unsupported Word table row content"),
            "{messages:?}"
        );
    }

    #[test]
    fn row_identity_differences_add_no_comparison_revision() {
        let compare = |original: &str, edited: &str, word: &str| {
            let mut compared = document_with_row_attributes(original, "alpha");
            compared
                .compare(
                    &document_with_row_attributes(edited, word),
                    "R",
                    "2026-09-27T12:00:00Z",
                )
                .unwrap_or_else(|error| panic!("{original} against {edited}: {error}"));
            compared.revisions().len()
        };
        let resaved = ALL
            .replace("00A1B2C3", "00D4E5F6")
            .replace("1A2B3C4D", "2B3C4D5E");
        // An identity-only difference, as between a file and its copy saved
        // again by Word, records nothing.
        assert_eq!(compare("", ALL, "alpha"), 0);
        assert_eq!(compare(ALL, "", "alpha"), 0);
        assert_eq!(compare(ALL, &resaved, "alpha"), 0);
        // One changed word in a row records its deletion and insertion, with
        // or without new identity values on the rows.
        assert_eq!(compare(ALL, ALL, "delta"), 2);
        assert_eq!(compare(ALL, &resaved, "delta"), 2);
    }

    #[test]
    fn w14_identities_stay_bound_when_only_their_element_declares_w14() {
        // The retained identities leave the `w14` declaration to the part
        // root, where Word and python-docx write it. A producer may declare
        // it on the row or paragraph instead, and an edit elsewhere must
        // still save a readable part.
        let local = format!(r#" xmlns:w14="{W14_NS}" w:rsidR="00A1B2C3" w14:paraId="1A2B3C4D""#);
        let xml = row_document_xml(&local, "alpha").replacen(
            &format!(r#" xmlns:w14="{W14_NS}"><w:body><w:p>"#),
            &format!("><w:body><w:p{local}>"),
            1,
        );
        let mut document = super::document_with_content_controls(&xml);
        assert_eq!(
            document
                .try_replace_text("After the table.", "After the rows.")
                .unwrap(),
            1
        );
        let bytes = document.to_bytes().unwrap();
        let saved = super::document_xml(&mut document);
        assert!(saved.contains("After the rows."), "{saved}");
        assert_eq!(
            saved.matches(r#"w14:paraId="1A2B3C4D""#).count(),
            5,
            "{saved}"
        );
        let mut reopened = Document::from_bytes(&bytes)
            .unwrap_or_else(|error| panic!("the saved part is unreadable: {error}: {saved}"));
        assert_eq!(reopened.to_bytes().unwrap(), bytes);
    }

    #[test]
    fn comparing_with_a_copy_that_declares_w14_keeps_its_identities_bound() {
        // The original part declares no `w14`, as a part rdocx wrote. Its
        // copy saved again by Word declares it on the root and adds a row
        // whose row and paragraphs carry w14 identities.
        let original =
            row_document_xml("", "alpha").replacen(&format!(r#" xmlns:w14="{W14_NS}">"#), ">", 1);
        let cell = |text: &str, id: u8| {
            format!(
                r#"<w:tc><w:p w:rsidR="00B1B2B3" w14:paraId="3C4D5E{id:02}" w14:textId="7A8B9C{id:02}"><w:r><w:t>{text}</w:t></w:r></w:p></w:tc>"#
            )
        };
        let inserted = format!(
            r#"<w:tr w:rsidR="00A1B2C3" w:rsidTr="00A1B2C4" w14:paraId="1A2B3C01" w14:textId="5E6F7A01">{}{}</w:tr>"#,
            cell("inserted", 2),
            cell("row", 3)
        );
        let edited = row_document_xml("", "alpha").replacen(
            "<w:tr/></w:tbl>",
            &format!("<w:tr/>{inserted}</w:tbl>"),
            1,
        );
        assert!(edited.contains("inserted"));
        let mut compared = super::document_with_content_controls(&original);
        compared
            .compare(
                &super::document_with_content_controls(&edited),
                "R",
                "2026-09-27T12:00:00Z",
            )
            .unwrap_or_else(|error| panic!("{error}"));
        assert!(!compared.revisions().is_empty());
        let bytes = compared.to_bytes().unwrap();
        let saved = super::document_xml(&mut compared);
        for attribute in [
            r#"w14:paraId="1A2B3C01""#,
            r#"w14:paraId="3C4D5E02""#,
            r#"w14:textId="7A8B9C03""#,
        ] {
            assert_eq!(saved.matches(attribute).count(), 1, "{attribute}: {saved}");
        }
        Document::from_bytes(&bytes)
            .unwrap_or_else(|error| panic!("the compared part is unreadable: {error}: {saved}"));

        // A header story is compared the same way.
        let table = |rows: &str| {
            format!(
                r#"<w:tbl><w:tblPr/><w:tblGrid><w:gridCol w:w="2000"/><w:gridCol w:w="2000"/></w:tblGrid><w:tr><w:tc><w:p><w:r><w:t>kept</w:t></w:r></w:p></w:tc><w:tc><w:p><w:r><w:t>row</w:t></w:r></w:p></w:tc></w:tr>{rows}</w:tbl>"#
            )
        };
        let with_header = |header: &str| {
            let mut document = super::document_with_comparison_stories("alpha");
            let mut package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(
                document.to_bytes().unwrap(),
            ))
            .unwrap();
            package.set_part("/word/header1.xml", header.as_bytes().to_vec());
            let mut bytes = std::io::Cursor::new(Vec::new());
            package.write_to(&mut bytes).unwrap();
            Document::from_bytes(bytes.get_ref()).unwrap()
        };
        let header = |root: &str, rows: &str| {
            format!(
                r#"<w:hdr xmlns:w="{W_NS}"{root}><w:p><w:r><w:t>alpha header</w:t></w:r></w:p>{}</w:hdr>"#,
                table(rows)
            )
        };
        let mut compared = with_header(&header("", ""));
        compared
            .compare(
                &with_header(&header(&format!(r#" xmlns:w14="{W14_NS}""#), &inserted)),
                "R",
                "2026-09-27T12:00:00Z",
            )
            .unwrap_or_else(|error| panic!("header: {error}"));
        let bytes = compared.to_bytes().unwrap();
        let header_xml = super::comparison_part_xml(&mut compared, "/word/header1.xml");
        assert!(
            header_xml.contains(r#"w14:paraId="1A2B3C01""#),
            "{header_xml}"
        );
        assert!(
            header_xml.contains(r#"w14:paraId="3C4D5E02""#),
            "{header_xml}"
        );
        Document::from_bytes(&bytes).unwrap_or_else(|error| {
            panic!("the compared header is unreadable: {error}: {header_xml}")
        });
    }

    #[test]
    fn mail_merge_regions_and_fragments_are_found_in_word_paragraphs_and_rows() {
        // Word writes distinct identities on every row and paragraph, and a
        // revision-save identity on the runs it edits. None of them is
        // content, so the region markers and a whole-paragraph fragment field
        // are still found.
        let paragraph = |instruction: &str, id: u8| {
            format!(
                r#"<w:p w:rsidR="00B1B2B3" w:rsidRDefault="00B1B2B3" w14:paraId="3C4D5E{id:02}" w14:textId="7A8B9C{id:02}"><w:r w:rsidR="00B1B2B4"><w:fldChar w:fldCharType="begin"/></w:r><w:r w:rsidR="00B1B2B4"><w:instrText xml:space="preserve"> MERGEFIELD {instruction} </w:instrText></w:r><w:r w:rsidR="00B1B2B4"><w:fldChar w:fldCharType="separate"/></w:r><w:r w:rsidR="00B1B2B4"><w:t>stored</w:t></w:r><w:r w:rsidR="00B1B2B4"><w:fldChar w:fldCharType="end"/></w:r></w:p>"#
            )
        };
        let row = |instruction: &str, id: u8| {
            format!(
                r#"<w:tr w:rsidR="00A1B2C3" w:rsidTr="00A1B2C4" w14:paraId="1A2B3C{id:02}" w14:textId="5E6F7A{id:02}"><w:tc><w:tcPr><w:tcW w:w="1000" w:type="dxa"/></w:tcPr>{}</w:tc></w:tr>"#,
                paragraph(instruction, id + 10)
            )
        };
        let body = format!(
            r#"{}{}{}{}<w:tbl><w:tblPr/><w:tblGrid><w:gridCol w:w="1000"/></w:tblGrid>{}{}{}</w:tbl><w:sectPr/>"#,
            paragraph("TableStart:Lines", 1),
            paragraph("Name", 2),
            paragraph("Insert", 3),
            paragraph("TableEnd:Lines", 4),
            row("TableStart:Rows", 5),
            row("RowValue", 6),
            row("TableEnd:Rows", 7)
        );
        let document =
            super::document_with_content_controls(&super::wrap_word_body(&body).replacen(
                "<w:document ",
                &format!(r#"<w:document xmlns:w14="{W14_NS}" "#),
                1,
            ));
        let mut fragment = Document::new();
        fragment.add_paragraph("fragment");
        let fragment = fragment.to_bytes().unwrap();
        let record = |name: &str, value: rdocx::MailMergeValue| rdocx::MailMergeRecord {
            values: std::collections::BTreeMap::from([(name.to_owned(), value)]),
            ..Default::default()
        };
        let lines = ["alpha", "beta"]
            .map(|name| {
                let mut line = record("Name", rdocx::MailMergeValue::Text(name.to_owned()));
                line.values.insert(
                    "Insert".to_owned(),
                    rdocx::MailMergeValue::Fragment(fragment.clone()),
                );
                line
            })
            .to_vec();
        let rows = ["first", "second"]
            .map(|value| record("RowValue", rdocx::MailMergeValue::Text(value.to_owned())))
            .to_vec();
        let data = rdocx::MailMergeData {
            records: vec![rdocx::MailMergeRecord {
                regions: std::collections::BTreeMap::from([
                    ("Lines".to_owned(), lines),
                    ("Rows".to_owned(), rows),
                ]),
                ..Default::default()
            }],
            ..Default::default()
        };
        let mut output = document
            .mail_merge_rich(&data, None)
            .unwrap_or_else(|error| panic!("{error}"))
            .remove(0);
        let paragraphs = output
            .paragraphs()
            .into_iter()
            .map(|paragraph| paragraph.text())
            .collect::<Vec<_>>();
        assert_eq!(paragraphs, ["alpha", "fragment", "beta", "fragment"]);
        let table = output.table(0).unwrap();
        assert_eq!(table.row_count(), 2);
        assert_eq!(table.cell(0, 0).unwrap().text(), "first");
        assert_eq!(table.cell(1, 0).unwrap().text(), "second");
        // Every output paragraph and row is a copy of a template element, so
        // none keeps its w14 identities. The revision-save identities stay.
        let saved = super::document_xml(&mut output);
        assert!(!saved.contains("MERGEFIELD"), "{saved}");
        assert_eq!(
            saved.matches(r#"w:rsidTr="00A1B2C4""#).count(),
            2,
            "{saved}"
        );
        assert_eq!(saved.matches(r#"w:rsidR="00B1B2B3""#).count(), 4, "{saved}");
        assert!(!saved.contains("w14:paraId"), "{saved}");
        assert!(!saved.contains("w14:textId"), "{saved}");
    }

    #[test]
    fn copied_rows_and_paragraphs_drop_their_w14_identities() {
        // Two elements must not share a `w14:paraId`, and Word assigns new
        // w14 identities to an element that has none, so a copy drops them.
        // The revision-save identities stay, since Word repeats them freely.
        let cell_paragraph =
            r#"<w:p w:rsidR="00B1B2B3" w14:paraId="3C4D5E6F" w14:textId="7A8B9C0D">"#;
        let body_paragraph =
            r#"<w:p w:rsidR="00C1C2C3" w14:paraId="4D5E6F70" w14:textId="0A1B2C3D">"#;
        // A row without a cell leaves the table without a valid topology.
        let xml = row_document_xml(ALL, "alpha")
            .replace(&format!("<w:tr{ALL}/>"), "")
            .replacen("<w:tc><w:p>", &format!("<w:tc>{cell_paragraph}"), 1)
            .replacen("<w:body><w:p>", &format!("<w:body>{body_paragraph}"), 1);
        let mut document = super::document_with_content_controls(&xml);
        assert_eq!(document.clone_table_row(0, 0, 2).unwrap(), 2);
        let body = super::f254_story(&document, rdocx::StoryKind::Body);
        let source = super::f254_item(&document, &body, 0);
        document
            .clone_content(&source, &rdocx::ContentLocation::end(body))
            .unwrap();

        let saved = super::document_xml(&mut document);
        assert_eq!(saved.matches("alpha").count(), 2, "{saved}");
        assert_eq!(
            saved.matches("Body text of section 3.1.").count(),
            2,
            "{saved}"
        );
        for (attribute, count) in [
            (r#"w14:paraId="1A2B3C4D""#, 3),
            (r#"w14:textId="5E6F7A8B""#, 3),
            (r#"w:rsidTr="00A1B2C4""#, 4),
            (r#"w:rsidDel="00A1B2C6""#, 4),
            (r#"w14:paraId="3C4D5E6F""#, 1),
            (r#"w14:textId="7A8B9C0D""#, 1),
            (r#"w:rsidR="00B1B2B3""#, 2),
            (r#"w14:paraId="4D5E6F70""#, 1),
            (r#"w14:textId="0A1B2C3D""#, 1),
            (r#"w:rsidR="00C1C2C3""#, 2),
        ] {
            assert_eq!(
                saved.matches(attribute).count(),
                count,
                "{attribute}: {saved}"
            );
        }
    }

    #[test]
    fn template_loop_copies_drop_their_w14_identities() {
        // Word writes a distinct `w14:paraId` on every paragraph and row. A
        // loop writes its body once per item, so no copy keeps them, while
        // the revision-save identities and content outside a loop stay.
        let paragraph = |text: &str, id: u8| {
            format!(
                r#"<w:p w:rsidR="00B1B2B3" w14:paraId="3C4D5E{id:02}" w14:textId="7A8B9C{id:02}"><w:r><w:t>{text}</w:t></w:r></w:p>"#
            )
        };
        let row = |text: &str, id: u8| {
            format!(
                r#"<w:tr w:rsidR="00A1B2C3" w:rsidTr="00A1B2C4" w14:paraId="1A2B3C{id:02}" w14:textId="5E6F7A{id:02}"><w:tc>{}</w:tc></w:tr>"#,
                paragraph(text, id + 10)
            )
        };
        let body = [
            paragraph("{% for item in items %}", 1),
            paragraph("{{ item }}", 2),
            paragraph("{% endfor %}", 3),
            r#"<w:tbl><w:tblPr/><w:tblGrid><w:gridCol w:w="2000"/></w:tblGrid>"#.to_owned(),
            row("{% for item in items %}", 4),
            row("{{ item }}", 5),
            row("{% endfor %}", 6),
            row("kept row", 7),
            "</w:tbl>".to_owned(),
            paragraph("kept paragraph", 8),
            "<w:sectPr/>".to_owned(),
        ]
        .concat();
        let mut document =
            super::document_with_content_controls(&super::wrap_word_body(&body).replacen(
                "<w:document ",
                &format!(r#"<w:document xmlns:w14="{W14_NS}" "#),
                1,
            ));
        document
            .render_template(&serde_json::json!({"items": ["one", "two", "three"]}))
            .unwrap();

        let saved = super::document_xml(&mut document);
        for item in ["one", "two", "three"] {
            let text = format!("<w:t>{item}</w:t>");
            assert_eq!(saved.matches(&text).count(), 2, "{item}: {saved}");
        }
        for (attribute, count) in [
            // The repeated body paragraph, row and cell paragraph.
            (r#"w14:paraId="3C4D5E02""#, 0),
            (r#"w14:paraId="1A2B3C05""#, 0),
            (r#"w14:paraId="3C4D5E15""#, 0),
            (r#"w14:textId="7A8B9C02""#, 0),
            (r#"w14:textId="5E6F7A05""#, 0),
            (r#"w14:textId="7A8B9C15""#, 0),
            // The row and paragraphs outside every loop.
            (r#"w14:paraId="1A2B3C07""#, 1),
            (r#"w14:paraId="3C4D5E17""#, 1),
            (r#"w14:paraId="3C4D5E08""#, 1),
            (r#"w14:textId="5E6F7A07""#, 1),
            (r#"w:rsidTr="00A1B2C4""#, 4),
            (r#"w:rsidR="00B1B2B3""#, 8),
        ] {
            assert_eq!(
                saved.matches(attribute).count(),
                count,
                "{attribute}: {saved}"
            );
        }
    }
}

fn document_with_comment_paragraphs(paragraphs: &str) -> (Document, i32) {
    let mut document = Document::new();
    document.add_paragraph("seed");
    let comment_id = document
        .add_comment(
            RunRange {
                start: RunPosition {
                    body_index: 0,
                    run_index: 0,
                },
                end: RunPosition {
                    body_index: 0,
                    run_index: 1,
                },
            },
            "Ada",
            None,
            "remove",
        )
        .unwrap();
    let bytes = document.to_bytes().unwrap();
    let mut package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).unwrap();
    let mut xml =
        String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
    let start = xml.find("<w:p>").unwrap();
    let end = start + xml[start..].find("</w:p>").unwrap() + "</w:p>".len();
    xml.replace_range(start..end, paragraphs);
    package.set_part("/word/document.xml", xml.into_bytes());
    let mut output = std::io::Cursor::new(Vec::new());
    package.write_to(&mut output).unwrap();
    (Document::from_bytes(output.get_ref()).unwrap(), comment_id)
}

fn body_from_xml(body: &str) -> CT_Body {
    CT_Document::from_xml(wrap_word_body(body).as_bytes())
        .unwrap()
        .body
}

#[test]
fn accepting_every_revision_matches_word_normalized_body_xml() {
    let xml = wrap_word_body(
        r#"<w:p><w:pPr><w:jc w:val="center"/><w:pPrChange w:id="5" w:author="Ada"><w:pPr><w:jc w:val="left"/></w:pPr></w:pPrChange></w:pPr><w:r><w:rPr><w:b/><w:rPrChange w:id="6" w:author="Ada"><w:rPr><w:i/></w:rPr></w:rPrChange></w:rPr><w:t>kept</w:t></w:r><w:ins w:id="1" w:author="Ada"><w:r><w:t> inserted</w:t></w:r></w:ins><w:del w:id="2" w:author="Ada"><w:r><w:delText> deleted</w:delText></w:r></w:del><w:moveFrom w:id="3" w:author="Ada"><w:r><w:t> old-place</w:t></w:r></w:moveFrom><w:moveTo w:id="4" w:author="Ada"><w:r><w:t> moved</w:t></w:r></w:moveTo></w:p><w:tbl><w:tblPr><w:jc w:val="center"/><w:tblPrChange w:id="7" w:author="Ada"><w:tblPr><w:jc w:val="right"/></w:tblPr></w:tblPrChange></w:tblPr><w:tblGrid/><w:tr><w:tc><w:p/></w:tc></w:tr></w:tbl><w:sectPr><w:titlePg/><w:sectPrChange w:id="8" w:author="Ada"><w:sectPr><w:pgSz w:w="12240" w:h="15840"/></w:sectPr></w:sectPrChange></w:sectPr>"#,
    );
    let mut document = document_with_content_controls(&xml);

    assert_eq!(document.accept_all().unwrap(), 8);
    assert!(document.revisions().is_empty());
    let expected = body_from_xml(
        r#"<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:rPr><w:b/></w:rPr><w:t>kept</w:t></w:r><w:r><w:t> inserted</w:t></w:r><w:r><w:t> moved</w:t></w:r></w:p><w:tbl><w:tblPr><w:jc w:val="center"/></w:tblPr><w:tblGrid/><w:tr><w:tc><w:p/></w:tc></w:tr></w:tbl><w:sectPr><w:titlePg/></w:sectPr>"#,
    );
    assert_eq!(
        body_from_document(&mut document),
        expected,
        "normalized body must match the pinned {WORD_REVISION_ORACLE} oracle"
    );
}

#[test]
fn rejecting_insertions_and_deletions_restores_the_recorded_content() {
    let xml = wrap_word_body(
        r#"<w:p><w:pPr><w:jc w:val="center"/><w:pPrChange w:id="5" w:author="Ada"><w:pPr><w:jc w:val="left"/></w:pPr></w:pPrChange></w:pPr><w:r><w:rPr><w:b/><w:rPrChange w:id="6" w:author="Ada"><w:rPr><w:i/></w:rPr></w:rPrChange></w:rPr><w:t>kept</w:t></w:r><w:ins w:id="1" w:author="Ada"><w:r><w:t> inserted</w:t></w:r></w:ins><w:del w:id="2" w:author="Ada"><w:r><w:delText> deleted</w:delText></w:r></w:del><w:moveFrom w:id="3" w:author="Ada"><w:r><w:t> old-place</w:t></w:r></w:moveFrom><w:moveTo w:id="4" w:author="Ada"><w:r><w:t> moved</w:t></w:r></w:moveTo></w:p><w:tbl><w:tblPr><w:jc w:val="center"/><w:tblPrChange w:id="7" w:author="Ada"><w:tblPr><w:jc w:val="right"/></w:tblPr></w:tblPrChange></w:tblPr><w:tblGrid/><w:tr><w:tc><w:p/></w:tc></w:tr></w:tbl><w:sectPr><w:titlePg/><w:sectPrChange w:id="8" w:author="Ada"><w:sectPr><w:pgSz w:w="12240" w:h="15840"/></w:sectPr></w:sectPrChange></w:sectPr>"#,
    );
    let mut document = document_with_content_controls(&xml);

    assert_eq!(document.reject_all().unwrap(), 8);
    assert!(document.revisions().is_empty());
    let expected = body_from_xml(
        r#"<w:p><w:pPr><w:jc w:val="left"/></w:pPr><w:r><w:rPr><w:i/></w:rPr><w:t>kept</w:t></w:r><w:r><w:t> deleted</w:t></w:r><w:r><w:t> old-place</w:t></w:r></w:p><w:tbl><w:tblPr><w:jc w:val="right"/></w:tblPr><w:tblGrid/><w:tr><w:tc><w:p/></w:tc></w:tr></w:tbl><w:sectPr><w:pgSz w:w="12240" w:h="15840"/></w:sectPr>"#,
    );
    assert_eq!(body_from_document(&mut document), expected);
}

#[test]
fn scoped_revision_actions_change_only_matching_revisions() {
    let xml = wrap_word_body(
        r#"<w:p><w:ins w:id="7" w:author="Ada" w:date="2026-08-17T09:00:00+01:00"><w:r><w:t>A</w:t></w:r></w:ins><w:ins w:id="7" w:author="Ben" w:date="2026-08-17T09:00:00Z"><w:r><w:t>B</w:t></w:r></w:ins><w:del w:id="8" w:author="Ada"><w:r><w:delText>C</w:delText></w:r></w:del></w:p>"#,
    );

    let mut by_author = document_with_content_controls(&xml);
    assert_eq!(by_author.accept_revisions_by_author("Ada").unwrap(), 2);
    assert!(document_xml(&mut by_author).contains(
        r#"<w:ins w:id="7" w:author="Ben" w:date="2026-08-17T09:00:00Z"><w:r><w:t>B</w:t></w:r></w:ins>"#
    ));
    assert_eq!(
        by_author
            .revisions()
            .iter()
            .map(|revision| revision.author())
            .collect::<Vec<_>>(),
        vec!["Ben"]
    );

    let mut by_id = document_with_content_controls(&xml);
    assert_eq!(by_id.reject_revision_id(7).unwrap(), 2);
    assert_eq!(
        by_id
            .revisions()
            .iter()
            .map(|revision| revision.id())
            .collect::<Vec<_>>(),
        vec![8]
    );

    let mut by_date = document_with_content_controls(&xml);
    assert_eq!(
        by_date
            .accept_revisions_in_date_range("2026-08-17T08:00:00Z", "2026-08-17T08:00:00Z")
            .unwrap(),
        1
    );
    assert_eq!(
        by_date
            .revisions()
            .iter()
            .map(|revision| revision.author())
            .collect::<Vec<_>>(),
        vec!["Ben", "Ada"]
    );

    let mut by_lowercase_date = document_with_content_controls(&xml);
    assert_eq!(
        by_lowercase_date
            .reject_revisions_in_date_range("2026-08-17t08:00:00z", "2026-08-17t08:00:00z",)
            .unwrap(),
        1
    );
}

