#[test]
fn empty_and_single_record_merges_have_stable_boundaries() {
    let body = r#"<w:p><w:fldSimple w:instr="MERGEFIELD Name"><w:r><w:t>stored</w:t></w:r></w:fldSimple></w:p><w:sectPr><w:pgSz w:w="12240" w:h="15840"/></w:sectPr>"#;
    let document = document_with_field_parts(&wrap_word_body(body), None, None);
    assert!(document.mail_merge(&[]).is_err());
    assert!(document.mail_merge_sections(&[]).is_err());

    let mut single = document
        .mail_merge_sections(&[mail_merge_record(&[("Name", "only")])])
        .unwrap();
    let xml = document_xml(&mut single);
    assert!(xml.contains(">only<"), "{xml}");
    assert!(!xml.contains(r#"<w:type w:val="nextPage"/>"#), "{xml}");
    let body = body_from_document(&mut single);
    assert!(body.sect_pr.is_some());
    assert!(body.content.iter().all(|content| {
        !matches!(content, BodyContent::Paragraph(paragraph) if paragraph.properties.as_ref().and_then(|properties| properties.sect_pr.as_ref()).is_some())
    }));

    let mut document = document_with_mail_merge_header();
    let package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
            .unwrap();
    let header_before = package.get_part("/word/header1.xml").unwrap().to_vec();
    assert!(
        document
            .evaluate_fields(&FieldEvaluationContext::default())
            .unwrap()
            .is_empty()
    );
    assert_eq!(
        document
            .update_fields(&FieldEvaluationContext::default())
            .unwrap(),
        0
    );
    let package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
            .unwrap();
    assert_eq!(
        package.get_part("/word/header1.xml").unwrap(),
        header_before
    );
    let varying = vec![
        mail_merge_record(&[("Name", "same"), ("Full Name", "one")]),
        mail_merge_record(&[("Name", "same"), ("Full Name", "two")]),
    ];
    let mut separate = document.mail_merge(&varying).unwrap();
    for output in &mut separate {
        let package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(output.to_bytes().unwrap()))
                .unwrap();
        let header = std::str::from_utf8(package.get_part("/word/header1.xml").unwrap()).unwrap();
        assert!(header.contains("stored table header"), "{header}");
        assert!(header.contains("stored control header"), "{header}");
        assert!(!header.contains(">one<"), "{header}");
        assert!(!header.contains(">two<"), "{header}");
    }
    assert!(document.mail_merge_sections(&varying).is_err());
    assert!(
        document
            .mail_merge_sections(&[
                mail_merge_record(&[("Name", "one"), ("Full Name", "same")]),
                mail_merge_record(&[("Name", "two"), ("Full Name", "same")]),
            ])
            .is_err()
    );
    assert!(
        document
            .mail_merge_sections(&[
                mail_merge_record(&[("Name", "same"), ("Full Name", "same")]),
                mail_merge_record(&[("Name", "same"), ("Full Name", "same")]),
            ])
            .is_ok()
    );
}

#[test]
fn repeated_content_produces_a_deterministic_comparison() {
    let original_xml = wrap_word_body(
        r#"<w:p><w:r><w:t>repeat</w:t></w:r><w:r><w:t>repeat</w:t></w:r></w:p><w:p><w:r><w:t>repeat</w:t></w:r></w:p><w:tbl><w:tblPr/><w:tblGrid/><w:tr><w:tc><w:p><w:r><w:t>repeat row</w:t></w:r></w:p></w:tc></w:tr><w:tr><w:tc><w:p><w:r><w:t>repeat row</w:t></w:r></w:p></w:tc></w:tr></w:tbl>"#,
    );
    let edited_xml = wrap_word_body(
        r#"<w:p><w:r><w:t>repeat</w:t></w:r><w:r><w:t>changed</w:t></w:r></w:p><w:p><w:r><w:t>repeat</w:t></w:r></w:p><w:tbl><w:tblPr/><w:tblGrid/><w:tr><w:tc><w:p><w:r><w:t>repeat row</w:t></w:r></w:p></w:tc></w:tr><w:tr><w:tc><w:p><w:r><w:t>changed row</w:t></w:r></w:p></w:tc></w:tr></w:tbl>"#,
    );
    let edited = document_with_content_controls(&edited_xml);
    let mut first = document_with_content_controls(&original_xml);
    let mut second = document_with_content_controls(&original_xml);

    assert_eq!(
        first
            .compare(&edited, "Ada", "2026-08-21T09:30:00Z")
            .unwrap(),
        second
            .compare(&edited, "Ada", "2026-08-21T09:30:00Z")
            .unwrap()
    );
    assert_eq!(first.to_bytes().unwrap(), second.to_bytes().unwrap());
}

#[test]
fn comparison_metadata_is_escaped_and_ids_do_not_collide() {
    let original_xml = wrap_word_body(
        r#"<w:p><w:bookmarkStart w:id="0" w:name="kept"/><w:r><w:t>old</w:t></w:r><w:bookmarkEnd w:id="0"/></w:p>"#,
    );
    let edited_xml = wrap_word_body(
        r#"<w:p><w:bookmarkStart w:id="0" w:name="kept"/><w:r><w:t>new</w:t></w:r><w:bookmarkEnd w:id="0"/></w:p>"#,
    );
    let edited = document_with_content_controls(&edited_xml);
    let mut document = document_with_content_controls(&original_xml);
    document
        .compare(&edited, "Ada & \"Bob\"", "2026-08-21T09:30:00+01:00")
        .unwrap();

    let xml = document_xml(&mut document);
    assert!(xml.contains(r#"w:author="Ada &amp; &quot;Bob&quot;""#));
    assert!(
        document
            .revisions()
            .iter()
            .all(|revision| revision.id() != 0)
    );
    let before = document.to_bytes().unwrap();
    assert!(document.compare(&edited, "Ada", "not-a-date").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn accepting_a_comparison_reproduces_the_edited_body_exactly() {
    let original_xml = wrap_word_body(
        r#"<w:p><w:pPr><w:numPr><w:ilvl w:val="0"/><w:numId w:val="7"/></w:numPr></w:pPr><w:r><w:t>old body</w:t></w:r></w:p><w:tbl><w:tblPr/><w:tblGrid/><w:tr><w:tc><w:p><w:r><w:t>old cell</w:t></w:r></w:p><w:tbl><w:tblPr/><w:tblGrid/><w:tr><w:tc><w:p><w:r><w:t>old nested</w:t></w:r></w:p></w:tc></w:tr></w:tbl><w:p/></w:tc></w:tr></w:tbl><w:sdt><w:sdtPr><w:tag w:val="scope"/></w:sdtPr><w:sdtContent><w:p><w:r><w:t>old control</w:t></w:r></w:p></w:sdtContent></w:sdt>"#,
    );
    let edited_xml = wrap_word_body(
        r#"<w:p><w:pPr><w:numPr><w:ilvl w:val="1"/><w:numId w:val="7"/></w:numPr></w:pPr><w:r><w:t>new body</w:t></w:r></w:p><w:tbl><w:tblPr/><w:tblGrid/><w:tr><w:tc><w:p><w:r><w:t>new cell</w:t></w:r></w:p><w:tbl><w:tblPr/><w:tblGrid/><w:tr><w:tc><w:p><w:r><w:t>new nested</w:t></w:r></w:p></w:tc></w:tr></w:tbl><w:p/></w:tc></w:tr></w:tbl><w:sdt><w:sdtPr><w:tag w:val="scope"/></w:sdtPr><w:sdtContent><w:p><w:r><w:t>new control</w:t></w:r></w:p><w:p><w:r><w:t>added control child</w:t></w:r></w:p></w:sdtContent></w:sdt>"#,
    );
    let edited = document_with_content_controls(&edited_xml);
    let mut compared = document_with_content_controls(&original_xml);
    compared
        .compare(&edited, "Ada", "2026-08-21T09:30:00Z")
        .unwrap();
    assert!(!compared.revisions().is_empty());
    compared.accept_all().unwrap();
    assert!(
        compared
            .compare(&edited, "postcondition", "2026-08-21T09:31:00Z")
            .unwrap()
            .is_empty()
    );
    assert!(compared.revisions().is_empty());
}

#[test]
fn rejecting_a_comparison_reproduces_the_original_body_exactly() {
    let original_xml = wrap_word_body(
        r#"<w:p><w:r><w:t>one</w:t></w:r><w:r><w:t>two</w:t></w:r></w:p><w:tbl><w:tblPr/><w:tblGrid/><w:tr><w:tc><w:p><w:r><w:t>row</w:t></w:r></w:p></w:tc></w:tr></w:tbl>"#,
    );
    let edited_xml = wrap_word_body(
        r#"<w:p><w:r><w:t>one</w:t></w:r><w:r><w:t>changed</w:t></w:r></w:p><w:tbl><w:tblPr/><w:tblGrid/><w:tr><w:tc><w:p><w:r><w:t>changed row</w:t></w:r></w:p></w:tc></w:tr></w:tbl>"#,
    );
    let original = document_with_content_controls(&original_xml);
    let edited = document_with_content_controls(&edited_xml);
    let mut compared = document_with_content_controls(&original_xml);
    compared
        .compare(&edited, "Ada", "2026-08-21T09:30:00Z")
        .unwrap();
    compared.reject_all().unwrap();
    assert!(
        compared
            .compare(&original, "postcondition", "2026-08-21T09:31:00Z")
            .unwrap()
            .is_empty()
    );
    assert!(compared.revisions().is_empty());
}

#[test]
fn comparison_appends_multiple_terminal_paragraphs_without_residue() {
    let reconstruct = |mut original: Document, edited: Document| {
        let original_bytes = original.to_bytes().unwrap();
        let mut compared = Document::from_bytes(&original_bytes).unwrap();
        let diagnostics = compared
            .compare(&edited, "Ada", "2026-09-16T09:30:00Z")
            .unwrap();
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        let tracked = compared.to_bytes().unwrap();

        let mut accepted = Document::from_bytes(&tracked).unwrap();
        accepted.accept_all().unwrap();
        assert!(
            accepted
                .compare(&edited, "postcondition", "2026-09-16T09:31:00Z")
                .unwrap()
                .is_empty()
        );
        let accepted = accepted.to_bytes().unwrap();

        let mut rejected = Document::from_bytes(&tracked).unwrap();
        rejected.reject_all().unwrap();
        assert!(
            rejected
                .compare(&original, "postcondition", "2026-09-16T09:31:00Z")
                .unwrap()
                .is_empty()
        );
        let rejected = rejected.to_bytes().unwrap();
        (tracked, accepted, rejected)
    };

    let mut original = Document::new();
    original.add_paragraph("anchor");
    let mut edited = Document::new();
    edited.add_paragraph("inserted at start");
    edited.add_paragraph("anchor");
    reconstruct(original, edited);

    let mut original = Document::new();
    original.add_paragraph("first");
    original.add_paragraph("last");
    let mut edited = Document::new();
    edited.add_paragraph("first");
    edited.add_paragraph("inserted in middle");
    edited.add_paragraph("last");
    reconstruct(original, edited);

    for appended in 1..=3 {
        let mut original = Document::new();
        original.add_paragraph("anchor");
        let original_bytes = original.to_bytes().unwrap();
        let mut edited = Document::from_bytes(&original_bytes).unwrap();
        for index in 0..appended {
            edited.add_paragraph(&format!("appended {index}"));
        }
        reconstruct(original, edited);
    }

    let mut original = Document::new();
    let relationship_id = original.embed_image(b"stable image", "stable.png");
    {
        let mut paragraph = original.add_paragraph("");
        let mut run = paragraph.add_run("anchor");
        run.add_field("AUTHOR", "Ada").unwrap();
        run.add_picture(&relationship_id, Length::pt(1.0), Length::pt(1.0));
    }
    original.add_paragraph("");
    let mut package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(original.to_bytes().unwrap()))
            .unwrap();
    package.set_part("/custom/keep.bin", b"unrelated bytes".to_vec());
    package
        .content_types
        .add_override("/custom/keep.bin", "application/octet-stream");
    let mut original_bytes = std::io::Cursor::new(Vec::new());
    package.write_to(&mut original_bytes).unwrap();
    let original_bytes = original_bytes.into_inner();
    let original = Document::from_bytes(&original_bytes).unwrap();
    let mut edited = Document::from_bytes(&original_bytes).unwrap();
    edited.add_paragraph("first appended");
    edited.add_paragraph("second appended");
    let (tracked, accepted, rejected) = reconstruct(original, edited);
    for bytes in [&tracked, &accepted, &rejected] {
        let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).unwrap();
        assert_eq!(
            package.get_part("/custom/keep.bin").unwrap(),
            b"unrelated bytes"
        );
        let xml = std::str::from_utf8(package.get_part("/word/document.xml").unwrap()).unwrap();
        assert!(xml.contains("AUTHOR"), "{xml}");
        assert!(xml.contains("<w:drawing"), "{xml}");
    }
}

/// Compare, then check that accepting every revision gives the edited
/// document and rejecting every one gives the original. Returns the tracked
/// main story.
fn compare_and_resolve(
    original_bytes: &[u8],
    edited_bytes: &[u8],
    options: &rdocx::ComparisonOptions,
) -> String {
    let original = Document::from_bytes(original_bytes).unwrap();
    let edited = Document::from_bytes(edited_bytes).unwrap();
    let mut compared = Document::from_bytes(original_bytes).unwrap();
    let diagnostics = compared
        .compare_with_options(&edited, "Ada", "2026-09-30T09:30:00Z", options)
        .unwrap_or_else(|error| panic!("{options:?}: {error}"));
    assert!(diagnostics.is_empty(), "{diagnostics:?}");
    assert!(!compared.revisions().is_empty());
    let tracked = compared.to_bytes().unwrap();

    let mut accepted = Document::from_bytes(&tracked).unwrap();
    accepted.accept_all().unwrap();
    assert_eq!(accepted.text(), edited.text());
    assert!(
        accepted
            .compare(&edited, "postcondition", "2026-09-30T09:31:00Z")
            .unwrap()
            .is_empty()
    );
    let mut rejected = Document::from_bytes(&tracked).unwrap();
    rejected.reject_all().unwrap();
    assert_eq!(rejected.text(), original.text());
    assert!(
        rejected
            .compare(&original, "postcondition", "2026-09-30T09:31:00Z")
            .unwrap()
            .is_empty()
    );
    document_xml(&mut compared)
}

#[test]
fn comparison_tracks_a_rebuilt_table_of_contents() {
    // The rebuild moves the field begin into a paragraph of its own, writes
    // each entry with a PAGEREF field, as a hyperlink under `\h`, and
    // bookmarks each heading. Each of those paragraphs refused the pair as a
    // paragraph boundary or modeled field change. Word writes the field end
    // in a paragraph of its own, which the rebuild keeps unchanged.
    let titles = [
        ("Heading1", "Chapter 1"),
        ("Heading2", "Section 1.1"),
        ("Heading1", "Chapter 2"),
    ];
    for (switches, own_end_paragraph) in [
        (r#""1-3" \h \z \u"#, false),
        (r#""1-3" \z \u"#, false),
        (r#""1-3" \h \z \u"#, true),
    ] {
        let mut entries = String::new();
        for (index, (_, title)) in titles.iter().enumerate() {
            entries.push_str(r#"<w:p><w:pPr><w:pStyle w:val="TOC1"/></w:pPr>"#);
            if index == 0 {
                entries.push_str(&format!(
                    r#"<w:r><w:fldChar w:fldCharType="begin"/><w:instrText xml:space="preserve"> TOC \o {switches} </w:instrText><w:fldChar w:fldCharType="separate"/></w:r>"#
                ));
            }
            entries.push_str(&format!(
                "<w:r><w:t>{title}</w:t><w:tab/><w:t>9</w:t></w:r>"
            ));
            if index + 1 == titles.len() && !own_end_paragraph {
                entries.push_str(r#"<w:r><w:fldChar w:fldCharType="end"/></w:r>"#);
            }
            entries.push_str("</w:p>");
        }
        if own_end_paragraph {
            entries.push_str(
                r#"<w:p><w:r><w:rPr><w:b/><w:noProof/></w:rPr><w:fldChar w:fldCharType="end"/></w:r></w:p>"#,
            );
        }
        let mut body = format!(
            r#"<w:sdt><w:sdtPr><w:docPartObj><w:docPartGallery w:val="Table of Contents"/><w:docPartUnique/></w:docPartObj></w:sdtPr><w:sdtContent><w:p><w:pPr><w:pStyle w:val="TOCHeading"/></w:pPr><w:r><w:t>Contents</w:t></w:r></w:p>{entries}</w:sdtContent></w:sdt>"#
        );
        for (style, title) in titles {
            body.push_str(&format!(
                r#"<w:p><w:pPr><w:pStyle w:val="{style}"/></w:pPr><w:r><w:t>{title}</w:t></w:r></w:p><w:p><w:r><w:t>Body text.</w:t></w:r></w:p>"#
            ));
        }
        let label = format!("{switches}, end in its own paragraph: {own_end_paragraph}");
        let original_bytes = document_with_field_parts(&wrap_word_body(&body), None, None)
            .to_bytes()
            .unwrap();
        let mut edited = Document::from_bytes(&original_bytes).unwrap();
        assert_eq!(edited.rebuild_toc().unwrap().entry_count, 3, "{label}");
        let edited_bytes = edited.to_bytes().unwrap();

        for granularity in [
            rdocx::ComparisonGranularity::Run,
            rdocx::ComparisonGranularity::Word,
        ] {
            let options = rdocx::ComparisonOptions {
                granularity,
                ..Default::default()
            };
            let xml = compare_and_resolve(&original_bytes, &edited_bytes, &options);
            // Every cached entry, and the field end, is deleted before any
            // rebuilt entry is inserted, so each side keeps one whole TOC
            // field, and the deleted field code is Word's `w:delInstrText`.
            let control =
                &xml[xml.find("<w:sdtContent>").unwrap()..xml.find("</w:sdtContent>").unwrap()];
            assert!(
                control.rfind("<w:delText").unwrap() < control.find("PAGEREF").unwrap(),
                "{label}: {control}"
            );
            assert_eq!(
                control.matches("<w:delInstrText").count(),
                1,
                "{label}: {control}"
            );
            assert_eq!(
                control.matches("<w:instrText").count(),
                1,
                "{label}: {control}"
            );
            for character in ["begin", "separate", "end"] {
                let character = format!(r#"w:fldCharType="{character}""#);
                assert_eq!(control.matches(&character).count(), 2, "{label}: {control}");
            }
            // A paragraph mark both deleted and inserted lists `w:ins`
            // first, as the schema orders them.
            for properties in xml.split("<w:rPr>").skip(1) {
                let properties = &properties[..properties.find("</w:rPr>").unwrap_or(0)];
                if let (Some(inserted), Some(deleted)) =
                    (properties.find("<w:ins "), properties.find("<w:del "))
                {
                    assert!(inserted < deleted, "{label}: {properties}");
                }
            }
        }
    }
}

#[test]
fn comparison_carries_bookmarks_and_whole_fields_in_whole_paragraph_changes() {
    // A whole inserted, deleted or moved paragraph kept only its runs, so a
    // bookmark in it failed the acceptance or rejection check, and so did a
    // field that spans whole inserted or deleted paragraphs.
    let plain = r#"<w:p><w:r><w:t>Alpha</w:t></w:r></w:p>"#;
    let last = r#"<w:p><w:r><w:t>Omega</w:t></w:r></w:p>"#;
    let bookmarked = r#"<w:p><w:bookmarkStart w:id="5" w:name="target"/><w:r><w:t>Marked</w:t></w:r><w:r><w:tab/></w:r><w:r><w:t>text</w:t></w:r><w:bookmarkEnd w:id="5"/></w:p>"#;
    let moved = r#"<w:p><w:r><w:t>Moved text</w:t></w:r></w:p>"#;
    let begin = r#"<w:p><w:r><w:fldChar w:fldCharType="begin"/><w:instrText xml:space="preserve"> TOC \o "1-3" \h </w:instrText><w:fldChar w:fldCharType="separate"/></w:r>"#;
    let end = r#"<w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>"#;
    // A field inserted whole, with a hyperlink and a simple field inside.
    let field = format!(
        r#"{begin}<w:hyperlink w:anchor="target"><w:r><w:t>Entry</w:t></w:r></w:hyperlink><w:r><w:tab/></w:r><w:fldSimple w:instr=" PAGEREF target \h "><w:r><w:t>1</w:t></w:r></w:fldSimple></w:p><w:p>{end}"#
    );
    // A cached field whose first entry becomes a hyperlink, with its end in
    // a paragraph the edit leaves unchanged.
    let cached =
        |first: &str| format!(r#"{begin}{first}</w:p><w:p><w:r><w:t>Entry two</w:t></w:r>{end}"#);
    let control = |content: &str| {
        format!(
            r#"<w:sdt><w:sdtPr><w:tag w:val="kept"/></w:sdtPr><w:sdtContent>{content}</w:sdtContent></w:sdt>{last}"#
        )
    };
    let cases = [
        (
            "inserted",
            format!("{plain}{last}"),
            format!("{plain}{bookmarked}{last}"),
        ),
        (
            "appended",
            format!("{plain}{last}"),
            format!("{plain}{last}{bookmarked}"),
        ),
        (
            "deleted",
            format!("{plain}{bookmarked}{last}"),
            format!("{plain}{last}"),
        ),
        (
            "moved",
            format!("{moved}{plain}{last}"),
            format!("{plain}{last}{moved}"),
        ),
        (
            "whole field inserted",
            format!("{plain}{last}"),
            format!("{plain}{field}{last}"),
        ),
        (
            "whole field deleted",
            format!("{plain}{field}{last}"),
            format!("{plain}{last}"),
        ),
        (
            "field entry becomes a hyperlink",
            format!(
                r#"{plain}{}{last}"#,
                cached("<w:r><w:t>Entry one</w:t></w:r>")
            ),
            format!(
                r#"{plain}{}{last}"#,
                cached(
                    r#"<w:hyperlink w:anchor="a"><w:r><w:t>Entry one</w:t></w:r></w:hyperlink>"#
                )
            ),
        ),
        (
            "two paragraphs appended to a control",
            control(plain),
            control(&format!("{plain}{bookmarked}{moved}")),
        ),
    ];
    for (name, original_body, edited_body) in cases {
        let original_bytes = document_with_content_controls(&wrap_word_body(&original_body))
            .to_bytes()
            .unwrap();
        let edited_bytes = document_with_content_controls(&wrap_word_body(&edited_body))
            .to_bytes()
            .unwrap();
        for granularity in [
            rdocx::ComparisonGranularity::Run,
            rdocx::ComparisonGranularity::Word,
        ] {
            let options = rdocx::ComparisonOptions {
                granularity,
                ..Default::default()
            };
            let xml = compare_and_resolve(&original_bytes, &edited_bytes, &options);
            assert!(
                xml.contains("<w:bookmarkStart")
                    || xml.contains("fldCharType")
                    || xml.contains("<w:moveTo "),
                "{name}: {xml}"
            );
            // Each side keeps its complex fields whole, so a field ended in
            // an unchanged paragraph is deleted and inserted with it.
            assert_eq!(
                xml.matches(r#"w:fldCharType="begin""#).count(),
                xml.matches(r#"w:fldCharType="end""#).count(),
                "{name}: {xml}"
            );
        }
    }
}

#[test]
fn comparison_refuses_whole_paragraph_structures_word_cannot_resolve() {
    // A hyperlink or simple field may not sit in a revision wrapper. Word
    // reads either as a field whose codes stay untracked, so accepting a
    // deleted one or rejecting an inserted one leaves an empty field, unless
    // a field deleted or inserted whole around it goes with it. A moved
    // paragraph's bookmark would be held by both ends of the move.
    let plain = r#"<w:p><w:r><w:t>Alpha</w:t></w:r></w:p>"#;
    let last = r#"<w:p><w:r><w:t>Omega</w:t></w:r></w:p>"#;
    let linked = r#"<w:p><w:r><w:t xml:space="preserve">See </w:t></w:r><w:hyperlink w:anchor="elsewhere"><w:r><w:t>there</w:t></w:r></w:hyperlink></w:p>"#;
    let paged = r#"<w:p><w:r><w:t xml:space="preserve">Page </w:t></w:r><w:fldSimple w:instr=" PAGE "><w:r><w:t>1</w:t></w:r></w:fldSimple></w:p>"#;
    let bookmarked = r#"<w:p><w:bookmarkStart w:id="5" w:name="target"/><w:r><w:t>Moved text</w:t></w:r><w:bookmarkEnd w:id="5"/></w:p>"#;
    let cases = [
        (
            "hyperlink inserted",
            format!("{plain}{last}"),
            format!("{plain}{linked}{last}"),
            "hyperlink or simple field outside a field",
        ),
        (
            "simple field deleted",
            format!("{plain}{paged}{last}"),
            format!("{plain}{last}"),
            "hyperlink or simple field outside a field",
        ),
        (
            "bookmarked paragraph moved",
            format!("{bookmarked}{plain}{last}"),
            format!("{plain}{last}{bookmarked}"),
            "cannot move a paragraph that holds a bookmark",
        ),
    ];
    for (name, original_body, edited_body, message) in cases {
        let edited = document_with_content_controls(&wrap_word_body(&edited_body));
        let mut compared = document_with_content_controls(&wrap_word_body(&original_body));
        let before = compared.to_bytes().unwrap();
        let error = compared
            .compare(&edited, "Ada", "2026-09-30T09:30:00Z")
            .expect_err(name);
        assert!(error.to_string().contains(message), "{name}: {error}");
        assert_eq!(compared.to_bytes().unwrap(), before, "{name}");
    }
}

#[test]
fn comparison_replaces_a_paragraph_that_gains_a_hyperlink() {
    let original = document_with_content_controls(&wrap_word_body(
        "<w:p><w:r><w:t>Alpha</w:t></w:r></w:p><w:p><w:r><w:t>Omega</w:t></w:r></w:p>",
    ))
    .to_bytes()
    .unwrap();
    let edited = document_with_content_controls(&wrap_word_body(
        "<w:p><w:r><w:t xml:space=\"preserve\">See </w:t></w:r><w:hyperlink w:anchor=\"elsewhere\"><w:r><w:t>there</w:t></w:r></w:hyperlink></w:p><w:p><w:r><w:t>Omega</w:t></w:r></w:p>",
    )).to_bytes().unwrap();
    let tracked = compare_and_resolve(&original, &edited, &rdocx::ComparisonOptions::default());
    assert!(tracked.contains("w:hyperlink"));
}

#[test]
fn ignored_story_does_not_carry_a_hyperlink_named_only_in_bookmark() {
    let url = "https://example.com/ignored";
    let mut original = Document::new();
    original.add_paragraph("literal");
    let mut probe = Document::from_bytes(&original.to_bytes().unwrap()).unwrap();
    let id = probe.add_hyperlink_relationship(url);
    let mut source =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(original.to_bytes().unwrap()))
            .unwrap();
    let xml = String::from_utf8(source.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
    let paragraph = xml.find("<w:p").unwrap();
    let opening_end = paragraph + xml[paragraph..].find('>').unwrap() + 1;
    let closing = xml[opening_end..].find("</w:p>").unwrap() + opening_end;
    let xml = format!(
        "{}<w:bookmarkStart w:id=\"1\" w:name=\"{id}\"/>{}<w:bookmarkEnd w:id=\"1\"/>{}",
        &xml[..opening_end],
        &xml[opening_end..closing],
        &xml[closing..]
    );
    source.set_part("/word/document.xml", xml.into_bytes());
    let mut original_bytes = std::io::Cursor::new(Vec::new());
    source.write_to(&mut original_bytes).unwrap();
    let original_bytes = original_bytes.into_inner();
    let mut edited = Document::from_bytes(&original_bytes).unwrap();
    edited.append_hyperlink("ignored edit", url);
    let edited_package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(edited.to_bytes().unwrap()))
            .unwrap();
    assert_eq!(
        edited_package
            .get_part_rels("/word/document.xml")
            .unwrap()
            .items
            .iter()
            .find(|rel| rel.target == url)
            .unwrap()
            .id,
        id
    );

    let options = rdocx::ComparisonOptions {
        ignored_stories: vec![rdocx::ComparisonStoryKind::Main],
        ..Default::default()
    };
    let mut compared = Document::from_bytes(&original_bytes).unwrap();
    compared
        .compare_with_options(&edited, "Ada", "2026-10-01T09:30:00Z", &options)
        .unwrap();
    let tracked =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(compared.to_bytes().unwrap()))
            .unwrap();
    assert!(
        tracked
            .get_part_rels("/word/document.xml")
            .is_none_or(|rels| rels.items.iter().all(|rel| rel.target != url)),
        "ignored hyperlink must not survive through bookmark name"
    );
}

#[test]
fn comparison_carries_the_relationship_of_an_inserted_external_hyperlink() {
    // The redline is staged on the original package, so an inserted table
    // kept the edited hyperlink's r:id without its relationship, and Word
    // refused to open the result.
    let mut original = Document::new();
    original.add_paragraph("Alpha");
    original.add_paragraph("Omega");
    let original_bytes = original.to_bytes().unwrap();
    let mut package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(original_bytes.clone())).unwrap();
    let id = package
        .get_or_create_part_rels("/word/document.xml")
        .add_external(
            oxml_opc::relationship::rel_types::HYPERLINK,
            "https://example.com/new",
        );
    let xml = String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
    let table = format!(
        r#"<w:tbl><w:tblPr/><w:tblGrid><w:gridCol w:w="4000"/></w:tblGrid><w:tr><w:tc><w:p><w:hyperlink xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:id="{id}"><w:r><w:t>link</w:t></w:r></w:hyperlink></w:p></w:tc></w:tr></w:tbl>"#
    );
    let at = xml.find("<w:p").unwrap();
    let at = at + xml[at..].find("</w:p>").unwrap() + "</w:p>".len();
    package.set_part(
        "/word/document.xml",
        format!("{}{table}{}", &xml[..at], &xml[at..]).into_bytes(),
    );
    let mut edited_bytes = std::io::Cursor::new(Vec::new());
    package.write_to(&mut edited_bytes).unwrap();
    let edited_bytes = edited_bytes.into_inner();

    compare_and_resolve(&original_bytes, &edited_bytes, &Default::default());
    let edited = Document::from_bytes(&edited_bytes).unwrap();
    let mut compared = Document::from_bytes(&original_bytes).unwrap();
    compared
        .compare(&edited, "Ada", "2026-09-30T09:30:00Z")
        .unwrap();
    let tracked =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(compared.to_bytes().unwrap()))
            .unwrap();
    let xml = std::str::from_utf8(tracked.get_part("/word/document.xml").unwrap()).unwrap();
    let linked = &xml[xml.find("<w:hyperlink").unwrap()..];
    let linked = &linked[linked.find("r:id=\"").unwrap() + 6..];
    let linked = &linked[..linked.find('"').unwrap()];
    let relationship = tracked
        .get_part_rels("/word/document.xml")
        .unwrap()
        .get_by_id(linked)
        .unwrap_or_else(|| panic!("{linked} has no relationship"));
    assert_eq!(relationship.target, "https://example.com/new");
    assert_eq!(relationship.target_mode.as_deref(), Some("External"));
}

#[test]
fn modeled_formatting_changes_are_tracked_without_diagnostics() {
    let original_xml =
        wrap_word_body(r#"<w:p><w:r><w:rPr><w:b/></w:rPr><w:t>same</w:t></w:r></w:p>"#);
    let edited_xml =
        wrap_word_body(r#"<w:p><w:r><w:rPr><w:i/></w:rPr><w:t>same</w:t></w:r></w:p>"#);
    let original = document_with_content_controls(&original_xml);
    let edited = document_with_content_controls(&edited_xml);
    let mut compared = document_with_content_controls(&original_xml);
    let diagnostics = compared
        .compare(&edited, "Ada", "2026-08-21T09:30:00Z")
        .unwrap();

    assert!(diagnostics.is_empty(), "{diagnostics:?}");
    assert!(!compared.revisions().is_empty());
    let tracked_bytes = compared.to_bytes().unwrap();
    assert!(document_xml(&mut compared).contains("<w:rPrChange"));

    let mut accepted = Document::from_bytes(&tracked_bytes).unwrap();
    accepted.accept_all().unwrap();
    assert!(
        accepted
            .compare(&edited, "postcondition", "2026-08-21T09:31:00Z")
            .unwrap()
            .is_empty()
    );
    let mut rejected = Document::from_bytes(&tracked_bytes).unwrap();
    rejected.reject_all().unwrap();
    assert!(
        rejected
            .compare(&original, "postcondition", "2026-08-21T09:31:00Z")
            .unwrap()
            .is_empty()
    );
}

#[test]
fn a_failed_comparison_leaves_the_original_package_unchanged() {
    let existing_xml = wrap_word_body(
        r#"<w:p><w:ins w:id="4" w:author="prior"><w:r><w:t>tracked</w:t></w:r></w:ins></w:p>"#,
    );
    let edited = Document::new();
    let mut document = document_with_content_controls(&existing_xml);
    let before = document.to_bytes().unwrap();

    assert!(
        document
            .compare(&edited, "Ada", "2026-08-21T09:30:00Z")
            .is_err()
    );
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn comparison_of_byte_identical_stories_is_a_true_no_op() {
    let mut original = Document::new();
    original.add_paragraph("same");
    let before = original.to_bytes().expect("serialize original");
    let edited = Document::from_bytes(&before).expect("reopen identical edit");

    let diagnostics = original
        .compare(&edited, "Ada", "2026-09-14T09:02:00Z")
        .expect("compare identical stories");

    assert!(diagnostics.is_empty(), "{diagnostics:?}");
    assert_eq!(original.to_bytes().expect("serialize comparison"), before);
}

#[test]
fn comparison_preserves_unmodelled_xml_byte_for_byte() {
    let body_raw = r#"<x:bodyOpaque xmlns:x="urn:comparison-body" x:value="keep"/>"#;
    let paragraph_raw =
        r#"<x:paragraphOpaque xmlns:x="urn:comparison-paragraph"><x:nested/></x:paragraphOpaque>"#;
    let table_raw = r#"<x:tableOpaque xmlns:x="urn:comparison-table" x:value="keep"/>"#;
    let cell_raw = r#"<x:cellOpaque xmlns:x="urn:comparison-cell" x:value="keep"/>"#;
    let control_raw =
        r#"<x:controlOpaque xmlns:x="urn:comparison-control"><x:nested/></x:controlOpaque>"#;
    let body = |value: &str| {
        wrap_word_body(&format!(
            r#"{body_raw}<w:p><w:r><w:t>{value} body</w:t>{paragraph_raw}</w:r></w:p><w:tbl><w:tblPr/><w:tblGrid/>{table_raw}<w:tr><w:tc>{cell_raw}<w:p><w:r><w:t>{value} cell</w:t></w:r></w:p></w:tc></w:tr></w:tbl><w:sdt><w:sdtPr><w:tag w:val="raw-scope"/></w:sdtPr><w:sdtContent>{control_raw}<w:p><w:r><w:t>{value} control</w:t></w:r></w:p></w:sdtContent></w:sdt>"#,
        ))
    };
    let original_xml = body("old");
    let edited_xml = body("new");
    let edited = document_with_content_controls(&edited_xml);
    let mut document = document_with_content_controls(&original_xml);
    document
        .compare(&edited, "Ada", "2026-08-21T09:30:00Z")
        .unwrap();

    let xml = document_xml(&mut document);
    for raw in [body_raw, table_raw, cell_raw, control_raw] {
        assert_eq!(xml.matches(raw).count(), 1, "{xml}");
    }
    assert_eq!(xml.matches(paragraph_raw).count(), 2, "{xml}");
    let mut reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let reopened_xml = document_xml(&mut reopened);
    for raw in [body_raw, table_raw, cell_raw, control_raw] {
        assert_eq!(reopened_xml.matches(raw).count(), 1, "{reopened_xml}");
    }
    assert_eq!(reopened_xml.matches(paragraph_raw).count(), 2);
}

#[test]
fn inserted_and_deleted_body_blocks_resolve_without_empty_containers() {
    let original_xml = wrap_word_body(
        r#"<w:p><w:r><w:t>first</w:t></w:r></w:p><w:p><w:r><w:t>last</w:t></w:r></w:p>"#,
    );
    let edited_xml = wrap_word_body(
        r#"<w:p><w:r><w:t>first</w:t></w:r></w:p><w:p><w:r><w:t>inserted</w:t></w:r></w:p><w:p><w:r><w:t>last</w:t></w:r></w:p>"#,
    );
    let original = document_with_content_controls(&original_xml);
    let edited = document_with_content_controls(&edited_xml);
    let mut inserted = document_with_content_controls(&original_xml);
    inserted
        .compare(&edited, "Ada", "2026-08-21T09:30:00Z")
        .unwrap();
    let mut accepted = Document::from_bytes(&inserted.to_bytes().unwrap()).unwrap();
    accepted.accept_all().unwrap();
    let diagnostics = accepted
        .compare(&edited, "postcondition", "2026-08-21T09:31:00Z")
        .unwrap();
    assert!(diagnostics.is_empty(), "{diagnostics:?}");
    let mut rejected = Document::from_bytes(&inserted.to_bytes().unwrap()).unwrap();
    rejected.reject_all().unwrap();
    let diagnostics = rejected
        .compare(&original, "postcondition", "2026-08-21T09:31:00Z")
        .unwrap();
    assert!(diagnostics.is_empty(), "{diagnostics:?}");

    let empty_xml = wrap_word_body(r#"<w:p><w:r><w:t>anchor</w:t></w:r></w:p>"#);
    let table_xml = wrap_word_body(
        r#"<w:tbl><w:tblPr/><w:tblGrid/><w:tr><w:tc><w:p><w:r><w:t>only row</w:t></w:r></w:p></w:tc></w:tr></w:tbl><w:p><w:r><w:t>anchor</w:t></w:r></w:p>"#,
    );
    let empty = document_with_content_controls(&empty_xml);
    let table = document_with_content_controls(&table_xml);
    let mut inserted_table = document_with_content_controls(&empty_xml);
    inserted_table
        .compare(&table, "Ada", "2026-08-21T09:30:00Z")
        .unwrap();
    inserted_table.reject_all().unwrap();
    assert!(
        inserted_table
            .compare(&empty, "postcondition", "2026-08-21T09:31:00Z")
            .unwrap()
            .is_empty()
    );

    let final_xml = wrap_word_body(
        r#"<w:p><w:r><w:t>first</w:t></w:r></w:p><w:p><w:r><w:t>final</w:t></w:r></w:p>"#,
    );
    let final_document = document_with_content_controls(&final_xml);
    let mut inserted_final = document_with_content_controls(&empty_xml);
    inserted_final
        .compare(&final_document, "Ada", "2026-08-21T09:30:00Z")
        .unwrap();
    inserted_final.reject_all().unwrap();
    assert!(
        inserted_final
            .compare(&empty, "postcondition", "2026-08-21T09:31:00Z")
            .unwrap()
            .is_empty()
    );
}

#[test]
fn comparison_revises_nested_control_content_without_replacing_its_shell() {
    let body = |value: &str, paragraph_tag: &str| {
        wrap_word_body(&format!(
            r#"<w:p><w:sdt><w:sdtPr><w:tag w:val="{paragraph_tag}"/></w:sdtPr><w:sdtContent><w:r><w:t>{value} paragraph control</w:t></w:r></w:sdtContent></w:sdt></w:p><w:tbl><w:tblPr/><w:tblGrid/><w:sdt><w:sdtPr><w:tag w:val="table-control"/></w:sdtPr><w:sdtContent><w:tr><w:tc><w:p><w:r><w:t>{value} table control</w:t></w:r></w:p></w:tc></w:tr></w:sdtContent></w:sdt><w:tr><w:sdt><w:sdtPr><w:tag w:val="row-control"/></w:sdtPr><w:sdtContent><w:tc><w:p><w:r><w:t>{value} row control</w:t></w:r></w:p></w:tc></w:sdtContent></w:sdt><w:tc><w:sdt><w:sdtPr><w:tag w:val="cell-control"/></w:sdtPr><w:sdtContent><w:p><w:r><w:t>{value} cell control</w:t></w:r></w:p></w:sdtContent></w:sdt></w:tc></w:tr></w:tbl>"#,
        ))
    };
    let original_xml = body("old", "paragraph-control");
    let edited_xml = body("new", "paragraph-control");
    let original = document_with_content_controls(&original_xml);
    let edited = document_with_content_controls(&edited_xml);
    let mut compared = document_with_content_controls(&original_xml);
    compared
        .compare(&edited, "Ada", "2026-08-21T09:30:00Z")
        .unwrap();
    let tracked_xml = document_xml(&mut compared);
    for tag in [
        "paragraph-control",
        "table-control",
        "row-control",
        "cell-control",
    ] {
        assert_eq!(tracked_xml.matches(&format!(r#"w:val="{tag}""#)).count(), 1);
    }
    let mut accepted = Document::from_bytes(&compared.to_bytes().unwrap()).unwrap();
    accepted.accept_all().unwrap();
    let diagnostics = accepted
        .compare(&edited, "postcondition", "2026-08-21T09:31:00Z")
        .unwrap();
    assert!(diagnostics.is_empty(), "{diagnostics:?}");
    let mut rejected = Document::from_bytes(&compared.to_bytes().unwrap()).unwrap();
    rejected.reject_all().unwrap();
    let diagnostics = rejected
        .compare(&original, "postcondition", "2026-08-21T09:31:00Z")
        .unwrap();
    assert!(diagnostics.is_empty(), "{diagnostics:?}");

    // A tag is metadata: the original shell stays and the change is reported.
    let changed_shell_xml = body("old", "changed-shell");
    let changed_shell = document_with_content_controls(&changed_shell_xml);
    let mut unchanged = document_with_content_controls(&original_xml);
    let diagnostics = unchanged
        .compare(&changed_shell, "Ada", "2026-08-21T09:30:00Z")
        .unwrap();
    assert_eq!(
        diagnostics,
        vec![rdocx::ComparisonDiagnostic {
            location: "body/paragraph[0]/content-control[0]".to_owned(),
            message: "content-control tag differs and the original tag was retained".to_owned(),
        }]
    );
    assert!(unchanged.revisions().is_empty());
    let kept_xml = document_xml(&mut unchanged);
    assert!(
        kept_xml.contains(r#"w:val="paragraph-control""#),
        "{kept_xml}"
    );
    assert!(!kept_xml.contains("changed-shell"), "{kept_xml}");
}

