fn f249_open_error(label: &str, package: oxml_opc::OpcPackage) -> String {
    let mut output = std::io::Cursor::new(Vec::new());
    package.write_to(&mut output).unwrap();
    let bytes = output.into_inner();
    let parsed = f249_package(&bytes);
    Document::from_bytes(&bytes)
        .err()
        .unwrap_or_else(|| {
            panic!(
                "{label} collision package must fail to open: {:?}",
                parsed.part_rels
            )
        })
        .to_string()
}

fn f249_equivalent_document(reverse: bool) -> Document {
    let mut document = Document::new();
    document.add_paragraph("first");
    document.add_paragraph("second");
    document.add_paragraph("third");
    document.add_paragraph("fourth");
    let range = |body_index| RunRange {
        start: RunPosition {
            body_index,
            run_index: 0,
        },
        end: RunPosition {
            body_index,
            run_index: 1,
        },
    };

    let (red_image, blue_image) = if reverse {
        let blue = document.embed_image(b"blue-image", "blue.png");
        let red = document.embed_image(b"red-image", "red.png");
        (red, blue)
    } else {
        let red = document.embed_image(b"red-image", "red.png");
        let blue = document.embed_image(b"blue-image", "blue.png");
        (red, blue)
    };
    let (bullet, decimal) = if reverse {
        let decimal = document.add_list_definition(&[ListLevel::decimal()]);
        let bullet = document.add_list_definition(&[ListLevel::bullet()]);
        (bullet, decimal)
    } else {
        let bullet = document.add_list_definition(&[ListLevel::bullet()]);
        let decimal = document.add_list_definition(&[ListLevel::decimal()]);
        (bullet, decimal)
    };
    if reverse {
        document.add_bookmark("Second", range(1)).unwrap();
        document.add_bookmark("First", range(0)).unwrap();
    } else {
        document.add_bookmark("First", range(0)).unwrap();
        document.add_bookmark("Second", range(1)).unwrap();
    }
    // Comment IDs are caller-visible stable identities, so equivalent-package
    // construction keeps their allocation order fixed.
    document
        .add_comment(range(2), "Author", Some("A"), "First comment")
        .unwrap();
    document
        .add_comment(range(3), "Author", Some("A"), "Second comment")
        .unwrap();
    document.add_paragraph("bullet").set_numbering(bullet, 0);
    document.add_paragraph("decimal").set_numbering(decimal, 0);
    let mut table = document.add_table(1, 2);
    table
        .cell(0, 0)
        .unwrap()
        .add_picture(&red_image, Length::inches(1.0), Length::inches(1.0));
    table
        .cell(0, 1)
        .unwrap()
        .add_picture(&blue_image, Length::inches(1.0), Length::inches(1.0));
    document
}

#[test]
fn equivalent_construction_orders_allocate_declared_stable_identifiers() {
    let left = f249_equivalent_document(false).to_bytes().unwrap();
    let right = f249_equivalent_document(true).to_bytes().unwrap();
    if left != right {
        let left_package = f249_package(&left);
        let right_package = f249_package(&right);
        let mut different = left_package
            .parts
            .iter()
            .filter_map(|(name, bytes)| {
                (right_package.get_part(name) != Some(bytes)).then_some(name.as_str())
            })
            .collect::<Vec<_>>();
        if left_package.package_rels.items != right_package.package_rels.items {
            different.push("/_rels/.rels");
        }
        for (owner, relationships) in &left_package.part_rels {
            if right_package
                .get_part_rels(owner)
                .is_none_or(|right| right.items != relationships.items)
            {
                different.push(owner);
            }
        }
        panic!(
            "equivalent packages differ in {different:?}\nLEFT DOC\n{}\nRIGHT DOC\n{}\nLEFT COMMENTS\n{}\nRIGHT COMMENTS\n{}",
            String::from_utf8_lossy(left_package.get_part("/word/document.xml").unwrap()),
            String::from_utf8_lossy(right_package.get_part("/word/document.xml").unwrap()),
            String::from_utf8_lossy(left_package.get_part("/word/comments.xml").unwrap()),
            String::from_utf8_lossy(right_package.get_part("/word/comments.xml").unwrap())
        );
    }

    let package = f249_package(&left);
    let document_xml =
        std::str::from_utf8(package.get_part("/word/document.xml").unwrap()).unwrap();
    let comments_xml =
        std::str::from_utf8(package.get_part("/word/comments.xml").unwrap()).unwrap();
    let numbering_xml =
        std::str::from_utf8(package.get_part("/word/numbering.xml").unwrap()).unwrap();
    assert!(
        document_xml.contains(r#"<w:bookmarkStart w:id="0""#),
        "{document_xml}"
    );
    assert!(
        document_xml.contains(r#"<w:bookmarkStart w:id="1""#),
        "{document_xml}"
    );
    assert!(
        document_xml.contains(r#"<wp:docPr id="1""#),
        "{document_xml}"
    );
    assert!(
        document_xml.contains(r#"<wp:docPr id="2""#),
        "{document_xml}"
    );
    assert!(comments_xml.contains(r#"w:id="0""#), "{comments_xml}");
    assert!(comments_xml.contains(r#"w:id="1""#), "{comments_xml}");
    assert!(comments_xml.find("First comment") < comments_xml.find("Second comment"));
    assert!(
        numbering_xml.contains(r#"<w:abstractNum w:abstractNumId="0""#),
        "{numbering_xml}"
    );
    assert!(
        numbering_xml.contains(r#"<w:abstractNum w:abstractNumId="1""#),
        "{numbering_xml}"
    );
    assert!(
        numbering_xml.contains(r#"<w:num w:numId="1""#),
        "{numbering_xml}"
    );
    assert!(
        numbering_xml.contains(r#"<w:num w:numId="2""#),
        "{numbering_xml}"
    );
    let relationships = package.get_part_rels("/word/document.xml").unwrap();
    let images = relationships
        .items
        .iter()
        .filter(|relationship| relationship.rel_type == oxml_opc::relationship::rel_types::IMAGE)
        .map(|relationship| (relationship.id.as_str(), relationship.target.as_str()))
        .collect::<Vec<_>>();
    assert_eq!(
        images,
        [("rId1", "media/image1.png"), ("rId2", "media/image2.png")]
    );
    assert_eq!(
        package.get_part("/word/media/image1.png"),
        Some(b"red-image".as_slice())
    );
    assert_eq!(
        package.get_part("/word/media/image2.png"),
        Some(b"blue-image".as_slice())
    );
    assert_eq!(
        package
            .content_types
            .defaults
            .get("png")
            .map(String::as_str),
        Some("image/png")
    );
}

#[test]
fn repeated_saves_are_byte_identical_after_allocation() {
    let mut document = f249_equivalent_document(false);
    let first = document.to_bytes().unwrap();
    let second = document.to_bytes().unwrap();
    assert_eq!(first, second);
    let mut reopened = Document::from_bytes(&first).unwrap();
    let reopened_bytes = reopened.to_bytes().unwrap();
    if first != reopened_bytes {
        let left = f249_package(&first);
        let right = f249_package(&reopened_bytes);
        let mut names = left
            .parts
            .keys()
            .chain(right.parts.keys())
            .collect::<Vec<_>>();
        names.sort();
        names.dedup();
        let different = names
            .into_iter()
            .filter(|name| left.get_part(name) != right.get_part(name))
            .cloned()
            .collect::<Vec<_>>();
        panic!(
            "reopened package differs in {different:?}\nFIRST:\n{}\nREOPENED:\n{}",
            String::from_utf8_lossy(left.get_part("/word/document.xml").unwrap()),
            String::from_utf8_lossy(right.get_part("/word/document.xml").unwrap())
        );
    }
}

#[test]
fn internal_reopen_mutations_preserve_minimal_bundle_history() {
    f249_assert_mutation_history("comparison", |list_before| {
        let mut original = f249_minimal_document("original");
        let mut edited = f249_minimal_document("edited");
        if list_before {
            original.add_list_definition(&[ListLevel::decimal()]);
            edited.add_list_definition(&[ListLevel::decimal()]);
        }
        original
            .compare(&edited, "Ada", "2026-09-07T09:00:00Z")
            .unwrap();
        if !list_before {
            original.add_list_definition(&[ListLevel::decimal()]);
        }
        original
    });

    f249_assert_mutation_history("revision", |list_before| {
        let mut original = f249_minimal_document("original");
        let mut edited = f249_minimal_document("edited");
        if list_before {
            original.add_list_definition(&[ListLevel::decimal()]);
            edited.add_list_definition(&[ListLevel::decimal()]);
        }
        original
            .compare(&edited, "Ada", "2026-09-07T09:00:00Z")
            .unwrap();
        assert!(original.accept_all().unwrap() > 0);
        if !list_before {
            original.add_list_definition(&[ListLevel::decimal()]);
        }
        original
    });

    f249_assert_mutation_history("redaction", |list_before| {
        let mut document = f249_minimal_document("secret");
        if list_before {
            document.add_list_definition(&[ListLevel::decimal()]);
        }
        assert_eq!(document.redact_text("secret").unwrap().total(), 1);
        if !list_before {
            document.add_list_definition(&[ListLevel::decimal()]);
        }
        document
    });

    f249_assert_mutation_history("TOC rebuild", |list_before| {
        let mut document = f249_minimal_toc_document();
        if list_before {
            document.add_list_definition(&[ListLevel::decimal()]);
        }
        assert_eq!(document.rebuild_toc().unwrap().entry_count, 1);
        if !list_before {
            document.add_list_definition(&[ListLevel::decimal()]);
        }
        document
    });

    f249_assert_mutation_history("embedded replacement", |list_before| {
        let mut document = f249_minimal_embedded_document();
        if list_before {
            document.add_list_definition(&[ListLevel::decimal()]);
        }
        document
            .replace_embedded_content(
                "/word/document.xml",
                "ole-rel",
                b"after",
                EmbeddedMutationPolicy::PreserveInvalidatedSignatures,
            )
            .unwrap();
        if !list_before {
            document.add_list_definition(&[ListLevel::decimal()]);
        }
        document
    });

    f249_assert_mutation_history("building block replacement", |list_before| {
        let mut document = f249_minimal_building_block_document();
        if list_before {
            document.add_list_definition(&[ListLevel::decimal()]);
        }
        let mut replacement = document.building_blocks().unwrap()[0].block.clone();
        replacement.name = "replacement".to_owned();
        document
            .replace_building_block("/word/glossary/document.xml", 0, replacement)
            .unwrap();
        if !list_before {
            document.add_list_definition(&[ListLevel::decimal()]);
        }
        document
    });
}

#[test]
fn imported_and_preserved_collisions_fail_before_mutation() {
    let mut document = f249_equivalent_document(false);
    let bytes = document.to_bytes().unwrap();

    let mut relationship_collision = f249_package(&bytes);
    let duplicate = relationship_collision
        .get_part_rels("/word/document.xml")
        .unwrap()
        .items
        .iter()
        .find(|relationship| relationship.rel_type == oxml_opc::relationship::rel_types::IMAGE)
        .unwrap()
        .clone();
    relationship_collision
        .get_or_create_part_rels("/word/document.xml")
        .items
        .push(duplicate);
    let mut output = std::io::Cursor::new(Vec::new());
    assert!(matches!(
        relationship_collision.write_to(&mut output),
        Err(oxml_opc::OpcError::InvalidRelationship)
    ));
    assert!(output.into_inner().is_empty());

    let mut package = f249_package(&bytes);
    let xml = String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
    let collided = xml.replacen(r#"<wp:docPr id="2""#, r#"<wp:docPr id="1""#, 1);
    assert_ne!(xml, collided, "second drawing id must be present");
    package.set_part("/word/document.xml", collided.into_bytes());
    let mut output = std::io::Cursor::new(Vec::new());
    package.write_to(&mut output).unwrap();
    // A producer may repeat a drawing id within one part. It opens, and
    // `repeated_drawing_ids_in_one_part_do_not_block_document_open` covers it.
    Document::from_bytes(&output.into_inner()).unwrap();

    let mut package = f249_package(&bytes);
    let xml = String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
    let collided = xml.replacen(
        r#"<w:bookmarkStart w:id="1""#,
        r#"<w:bookmarkStart w:id="0""#,
        1,
    );
    assert_ne!(xml, collided, "second bookmark id must be present");
    package.set_part("/word/document.xml", collided.into_bytes());
    let error = f249_open_error("bookmark", package);
    assert!(error.contains("duplicate bookmark id 0"), "{error}");

    let mut package = f249_package(&bytes);
    let xml = String::from_utf8(package.get_part("/word/comments.xml").unwrap().to_vec()).unwrap();
    let collided = xml.replacen(r#"w:id="1""#, r#"w:id="0""#, 1);
    assert_ne!(xml, collided, "second comment id must be present");
    package.set_part("/word/comments.xml", collided.into_bytes());
    let error = f249_open_error("comment", package);
    assert!(error.contains("duplicate comment id 0"), "{error}");

    let mut package = f249_package(&bytes);
    let xml = String::from_utf8(package.get_part("/word/numbering.xml").unwrap().to_vec()).unwrap();
    let collided = xml.replacen(
        r#"<w:abstractNum w:abstractNumId="1""#,
        r#"<w:abstractNum w:abstractNumId="0""#,
        1,
    );
    assert_ne!(
        xml, collided,
        "second abstract numbering id must be present"
    );
    package.set_part("/word/numbering.xml", collided.into_bytes());
    let error = f249_open_error("abstract numbering", package);
    assert!(
        error.contains("duplicate abstract numbering id 0"),
        "{error}"
    );

    let mut package = f249_package(&bytes);
    let xml = String::from_utf8(package.get_part("/word/numbering.xml").unwrap().to_vec()).unwrap();
    let collided = xml.replacen(r#"<w:num w:numId="2""#, r#"<w:num w:numId="1""#, 1);
    assert_ne!(
        xml, collided,
        "second numbering instance id must be present"
    );
    package.set_part("/word/numbering.xml", collided.into_bytes());
    let error = f249_open_error("numbering instance", package);
    assert!(
        error.contains("duplicate numbering instance id 1"),
        "{error}"
    );
}

fn f256_dependency_source() -> Document {
    let mut source = Document::new();
    source
        .add_style(StyleBuilder::paragraph("FragmentStyle", "Fragment Style"))
        .unwrap();
    source
        .add_style(StyleBuilder::paragraph(
            "UnusedFragmentStyle",
            "Unused Fragment Style",
        ))
        .unwrap();
    source
        .add_style(StyleBuilder::paragraph(
            "FragmentNumberStyle",
            "Fragment Number Style",
        ))
        .unwrap();
    let unused_numbering = source.add_list_definition(&[ListLevel::decimal()]);
    source
        .add_paragraph("not selected")
        .style("UnusedFragmentStyle")
        .set_numbering(unused_numbering, 0);
    source
        .add_paragraph("selected styled")
        .style("FragmentStyle");
    source.add_paragraph("selected numbered");
    source
        .add_paragraph("selected style numbered")
        .style("FragmentNumberStyle");
    source.add_picture(
        b"f256-image-payload",
        "f256.png",
        Length::pt(24.0),
        Length::pt(18.0),
    );
    source
        .add_chart(
            ChartKind::Bar,
            Length::pt(120.0),
            Length::pt(72.0),
            &ChartData {
                categories: vec!["A".to_owned(), "B".to_owned()],
                series: vec![("Series".to_owned(), vec![1.0, 2.0])],
                ..ChartData::default()
            },
        )
        .unwrap();
    let selected = RunRange {
        start: RunPosition {
            body_index: 1,
            run_index: 0,
        },
        end: RunPosition {
            body_index: 1,
            run_index: 1,
        },
    };
    source.add_bookmark("FragmentMark", selected).unwrap();
    let comment_id = source
        .add_comment(selected, "Reviewer", Some("R"), "fragment comment")
        .unwrap();
    source
        .reply_to(comment_id, "Reply author", "fragment reply")
        .unwrap();
    assert!(source.resolve_comment(comment_id, true).unwrap());

    let mut package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(source.to_bytes().unwrap()))
            .unwrap();
    let styles_xml = String::from_utf8(package.get_part("/word/styles.xml").unwrap().to_vec())
        .unwrap()
        .replacen(
            "<w:name w:val=\"Fragment Number Style\"/></w:style>",
            "<w:name w:val=\"Fragment Number Style\"/><w:pPr><w:numPr><w:ilvl w:val=\"0\"/><w:numId w:val=\"42\"/></w:numPr></w:pPr></w:style>",
            1,
        );
    assert!(styles_xml.contains(r#"<w:numId w:val="42"/>"#));
    package.set_part("/word/styles.xml", styles_xml.into_bytes());
    package.set_part(
        "/word/numbering.xml",
        format!(
            r#"<w:numbering xmlns:w="{W_NS}"><w:abstractNum w:abstractNumId="0"><w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="decimal"/><w:lvlText w:val="%1."/></w:lvl></w:abstractNum><w:abstractNum w:abstractNumId="41"><w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="bullet"/><w:pStyle w:val="FragmentNumberStyle"/><w:lvlText w:val="•"/></w:lvl></w:abstractNum><w:num w:numId="1"><w:abstractNumId w:val="0"/></w:num><w:num w:numId="42"><w:abstractNumId w:val="41"/></w:num></w:numbering>"#
        )
        .into_bytes(),
    );
    let document_xml =
        String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
    let selected_text = "<w:t>selected styled</w:t>";
    let retained = r#"<f:producer xmlns:f="urn:f256" f:kept='exact'></f:producer><w:fldSimple w:instr=" REF FragmentMark \\h "><w:r><w:t>field result</w:t></w:r></w:fldSimple>"#;
    let document_xml =
        document_xml.replacen(selected_text, &format!("{selected_text}{retained}"), 1);
    assert!(document_xml.contains(retained));
    package.set_part("/word/document.xml", document_xml.into_bytes());
    let comments_xml =
        String::from_utf8(package.get_part("/word/comments.xml").unwrap().to_vec()).unwrap();
    let comment_relationship = r#"<f:commentPayload xmlns:f="urn:f256-comment" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:id="rIdF256"/>"#;
    let comments_xml = comments_xml.replacen("</w:p>", &format!("{comment_relationship}</w:p>"), 1);
    assert!(comments_xml.contains(comment_relationship));
    package.set_part("/word/comments.xml", comments_xml.into_bytes());
    package.set_part(
        "/word/commentPayload.bin",
        b"f256-comment-relationship-payload".to_vec(),
    );
    package
        .content_types
        .add_override("/word/commentPayload.bin", "application/octet-stream");
    package
        .get_or_create_part_rels("/word/comments.xml")
        .add_with_id("rIdF256", "urn:f256-comment-payload", "commentPayload.bin");
    let mut bytes = std::io::Cursor::new(Vec::new());
    package.write_to(&mut bytes).unwrap();
    let reopened = Document::from_bytes(bytes.get_ref()).unwrap();
    assert_eq!(reopened.numbering_is_bullet(42), Some(true));
    reopened
}

fn f256_fragment(source: &Document) -> DocumentFragment {
    let body = f254_story(source, StoryKind::Body);
    let items = source.story_items(&body).unwrap();
    DocumentFragment::from_range(
        source,
        items[1].location(),
        &ContentLocation::end(body),
        false,
    )
    .unwrap()
}

#[test]
fn fragment_import_preserves_unmodeled_xml_and_reopens() {
    let source = f256_dependency_source();
    let fragment = f256_fragment(&source);
    let mut destination = Document::new();
    destination
        .add_style(StyleBuilder::paragraph(
            "FragmentStyle",
            "Destination Style",
        ))
        .unwrap();

    for _ in 0..2 {
        let body = f254_story(&destination, StoryKind::Body);
        destination
            .import_fragment(
                &ContentLocation::end(body),
                &fragment,
                FragmentConflictPolicy::reuse_equivalent(),
            )
            .unwrap();
    }

    let bytes = destination.to_bytes().unwrap();
    let reopened = Document::from_bytes(&bytes).unwrap();
    assert_eq!(
        reopened
            .paragraphs()
            .into_iter()
            .filter(|paragraph| paragraph.text() == "selected styled")
            .count(),
        2
    );
    assert_eq!(
        reopened
            .paragraphs()
            .into_iter()
            .filter(|paragraph| paragraph.text() == "selected style numbered")
            .count(),
        2
    );
    assert_eq!(
        reopened
            .paragraphs()
            .into_iter()
            .filter(|paragraph| paragraph.text() == "selected numbered")
            .count(),
        2
    );
    assert!(!reopened.text().contains("not selected"));
    assert_eq!(reopened.bookmarks().len(), 2);
    let comments = reopened.comments();
    assert_eq!(comments.len(), 4);
    assert_eq!(
        comments.iter().filter(|comment| comment.resolved()).count(),
        2
    );
    assert_eq!(
        comments
            .iter()
            .filter(|comment| comment.parent_id().is_some())
            .count(),
        2
    );
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).unwrap();
    let document_xml =
        std::str::from_utf8(package.get_part("/word/document.xml").unwrap()).unwrap();
    assert_eq!(
        document_xml
            .matches(r#"<f:producer xmlns:f="urn:f256" f:kept='exact'></f:producer>"#)
            .count(),
        2,
        "{document_xml}"
    );
    assert_eq!(document_xml.matches("<w:fldSimple ").count(), 2);
    let bookmark_names = reopened
        .bookmarks()
        .into_iter()
        .filter_map(|bookmark| bookmark.name().map(str::to_owned))
        .collect::<HashSet<_>>();
    let field_targets = document_xml
        .split("<w:fldSimple ")
        .skip(1)
        .filter_map(|field| field.split("w:instr=\"").nth(1))
        .filter_map(|instruction| instruction.split('"').next())
        .filter_map(|instruction| instruction.split_whitespace().nth(1))
        .map(str::to_owned)
        .collect::<HashSet<_>>();
    assert_eq!(field_targets, bookmark_names);
    let styles_xml = std::str::from_utf8(package.get_part("/word/styles.xml").unwrap()).unwrap();
    assert!(styles_xml.contains("FragmentNumberStyle"), "{styles_xml}");
    assert!(styles_xml.contains("<w:numId "), "{styles_xml}");
    assert!(!styles_xml.contains("UnusedFragmentStyle"), "{styles_xml}");
    let numbering_xml =
        std::str::from_utf8(package.get_part("/word/numbering.xml").unwrap()).unwrap();
    let style_numbering_id = styles_xml
        .split(r#"w:styleId="FragmentNumberStyle""#)
        .nth(1)
        .and_then(|style| style.split("</w:style>").next())
        .and_then(|style| style.split(r#"<w:numId w:val=""#).nth(1))
        .and_then(|value| value.split('"').next())
        .unwrap();
    assert!(
        numbering_xml.contains(&format!(r#"<w:num w:numId="{style_numbering_id}""#)),
        "{styles_xml}\n{numbering_xml}"
    );
    assert_eq!(
        numbering_xml.matches("<w:num ").count(),
        1,
        "{numbering_xml}"
    );
    assert_eq!(
        package
            .parts
            .values()
            .filter(|bytes| bytes.as_slice() == b"f256-image-payload")
            .count(),
        1
    );
    assert_eq!(
        package
            .parts
            .values()
            .filter(|bytes| bytes.as_slice() == b"f256-comment-relationship-payload")
            .count(),
        1
    );
    let comments_part = package.get_part("/word/comments.xml").unwrap();
    let comments_xml = std::str::from_utf8(comments_part).unwrap();
    assert_eq!(comments_xml.matches("<f:commentPayload ").count(), 2);
    let comment_relationships = package.get_part_rels("/word/comments.xml").unwrap();
    for id in comments_xml
        .split("<f:commentPayload ")
        .skip(1)
        .filter_map(|payload| payload.split("r:id=\"").nth(1))
        .filter_map(|id| id.split('"').next())
    {
        assert!(comment_relationships.get_by_id(id).is_some(), "{id}");
    }
    assert_eq!(
        package
            .parts
            .keys()
            .filter(|part_name| part_name.starts_with("/word/charts/chart"))
            .count(),
        2
    );
    assert_eq!(
        package
            .parts
            .keys()
            .filter(|part_name| part_name.starts_with("/word/embeddings/"))
            .count(),
        1
    );
}

#[test]
fn fragment_conflict_policies_reuse_only_equivalent_graphs() {
    let fragment = f256_fragment(&f256_dependency_source());
    let build = |policy| {
        let mut destination = f256_dependency_source();
        let body = f254_story(&destination, StoryKind::Body);
        destination
            .import_fragment(&ContentLocation::end(body), &fragment, policy)
            .unwrap();
        destination.to_bytes().unwrap()
    };
    let rename_policy = FragmentConflictPolicy::rename_all()
        .with_style_reuse(false)
        .with_numbering_reuse(false)
        .with_related_part_reuse(false);
    assert_eq!(build(rename_policy), build(rename_policy));

    let reused = build(FragmentConflictPolicy::reuse_equivalent());
    let renamed = build(rename_policy);
    let reused_package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(reused)).unwrap();
    let renamed_package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(renamed)).unwrap();
    let reused_styles = String::from_utf8(
        reused_package
            .get_part("/word/styles.xml")
            .unwrap()
            .to_vec(),
    )
    .unwrap();
    let renamed_styles = String::from_utf8(
        renamed_package
            .get_part("/word/styles.xml")
            .unwrap()
            .to_vec(),
    )
    .unwrap();
    assert!(!reused_styles.contains("FragmentStyleMerge"));
    assert!(renamed_styles.contains("FragmentStyleMerge"));
    let reused_numbering =
        std::str::from_utf8(reused_package.get_part("/word/numbering.xml").unwrap()).unwrap();
    let renamed_numbering =
        std::str::from_utf8(renamed_package.get_part("/word/numbering.xml").unwrap()).unwrap();
    assert_eq!(
        reused_numbering.matches("<w:num ").count(),
        2,
        "{reused_numbering}"
    );
    assert_eq!(
        renamed_numbering.matches("<w:num ").count(),
        3,
        "{renamed_numbering}"
    );
    let reused_style_numbering_id = reused_styles
        .split(r#"w:styleId="FragmentNumberStyle""#)
        .nth(1)
        .and_then(|style| style.split("</w:style>").next())
        .and_then(|style| style.split(r#"<w:numId w:val=""#).nth(1))
        .and_then(|value| value.split('"').next())
        .unwrap();
    assert!(reused_numbering.contains(&format!(r#"<w:num w:numId="{reused_style_numbering_id}""#)));
    assert_eq!(
        reused_package
            .parts
            .values()
            .filter(|bytes| bytes.as_slice() == b"f256-image-payload")
            .count(),
        1
    );
    assert_eq!(
        renamed_package
            .parts
            .values()
            .filter(|bytes| bytes.as_slice() == b"f256-image-payload")
            .count(),
        2
    );

    let mut section_source = Document::new();
    section_source.add_paragraph("section fragment");
    let body = f254_story(&section_source, StoryKind::Body);
    let item = f254_item(&section_source, &body, 0);
    let section_fragment =
        DocumentFragment::from_range(&section_source, &item, &ContentLocation::end(body), true)
            .unwrap();
    let mut section_destination = Document::new();
    let body = f254_story(&section_destination, StoryKind::Body);
    section_destination
        .import_fragment(
            &ContentLocation::end(body),
            &section_fragment,
            FragmentConflictPolicy::reuse_equivalent(),
        )
        .unwrap();
    assert_eq!(section_destination.sections().count(), 2);

    let mut authored_source = Document::new();
    let authored_source_numbering = authored_source.add_list_definition(&[ListLevel::bullet()]);
    authored_source
        .add_paragraph("authored equivalent")
        .set_numbering(authored_source_numbering, 0);
    let body = f254_story(&authored_source, StoryKind::Body);
    let item = f254_item(&authored_source, &body, 0);
    let authored_fragment =
        DocumentFragment::from_range(&authored_source, &item, &ContentLocation::end(body), false)
            .unwrap();
    let mut authored_destination = Document::new();
    authored_destination.add_list_definition(&[ListLevel::bullet()]);
    let body = f254_story(&authored_destination, StoryKind::Body);
    authored_destination
        .import_fragment(
            &ContentLocation::end(body),
            &authored_fragment,
            FragmentConflictPolicy::reuse_equivalent(),
        )
        .unwrap();
    let authored_bytes = authored_destination.to_bytes().unwrap();
    let authored_package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(authored_bytes)).unwrap();
    let authored_numbering =
        std::str::from_utf8(authored_package.get_part("/word/numbering.xml").unwrap()).unwrap();
    assert_eq!(authored_numbering.matches("<w:num ").count(), 1);
}

#[test]
fn fragment_import_rejects_incomplete_graph_atomically() {
    let mut source = Document::new();
    let relationship = source.add_hyperlink_relationship("https://example.com/f256");
    source
        .add_paragraph("")
        .add_hyperlink("external", &relationship);
    let body = f254_story(&source, StoryKind::Body);
    let item = f254_item(&source, &body, 0);
    let fragment =
        DocumentFragment::from_range(&source, &item, &ContentLocation::end(body), false).unwrap();

    let mut destination = Document::new();
    destination.add_paragraph("unchanged");
    let body = f254_story(&destination, StoryKind::Body);
    destination
        .import_fragment(
            &ContentLocation::end(body),
            &fragment,
            FragmentConflictPolicy::reuse_equivalent(),
        )
        .unwrap();
    let imported =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(destination.to_bytes().unwrap()))
            .unwrap();
    assert!(
        imported
            .get_part_rels("/word/document.xml")
            .unwrap()
            .items
            .iter()
            .any(
                |relationship| relationship.target == "https://example.com/f256"
                    && relationship.target_mode.as_deref() == Some("External")
            )
    );
    let before = destination.to_bytes().unwrap();

    let mut split_bookmark = Document::new();
    split_bookmark.add_paragraph("start");
    split_bookmark.add_paragraph("end");
    split_bookmark
        .add_bookmark(
            "Split",
            RunRange {
                start: RunPosition {
                    body_index: 0,
                    run_index: 0,
                },
                end: RunPosition {
                    body_index: 1,
                    run_index: 1,
                },
            },
        )
        .unwrap();
    let body = f254_story(&split_bookmark, StoryKind::Body);
    let items = split_bookmark.story_items(&body).unwrap();
    let incomplete = DocumentFragment::from_range(
        &split_bookmark,
        items[0].location(),
        items[1].location(),
        false,
    )
    .unwrap();
    let body = f254_story(&destination, StoryKind::Body);
    let error = destination
        .import_fragment(
            &ContentLocation::end(body),
            &incomplete,
            FragmentConflictPolicy::reuse_equivalent(),
        )
        .unwrap_err();
    assert!(error.to_string().contains("bookmark ownership"), "{error}");
    assert_eq!(destination.to_bytes().unwrap(), before);

    let mut dangling_source = Document::new();
    dangling_source.add_picture(
        b"f256-dangling-image",
        "dangling.png",
        Length::pt(12.0),
        Length::pt(9.0),
    );
    let mut dangling_package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(
        dangling_source.to_bytes().unwrap(),
    ))
    .unwrap();
    let dangling_part = dangling_package
        .parts
        .iter()
        .find_map(|(name, bytes)| {
            (bytes.as_slice() == b"f256-dangling-image").then(|| name.clone())
        })
        .unwrap();
    dangling_package.remove_part(&dangling_part);
    let mut dangling_bytes = std::io::Cursor::new(Vec::new());
    dangling_package.write_to(&mut dangling_bytes).unwrap();
    let dangling_source = Document::from_bytes(dangling_bytes.get_ref()).unwrap();
    let body = f254_story(&dangling_source, StoryKind::Body);
    let item = f254_item(&dangling_source, &body, 0);
    let dangling =
        DocumentFragment::from_range(&dangling_source, &item, &ContentLocation::end(body), false)
            .unwrap();
    let body = f254_story(&destination, StoryKind::Body);
    let error = destination
        .import_fragment(
            &ContentLocation::end(body),
            &dangling,
            FragmentConflictPolicy::reuse_equivalent(),
        )
        .unwrap_err();
    assert!(error.to_string().contains("missing"), "{error}");
    assert_eq!(destination.to_bytes().unwrap(), before);

    let mut picture_source = Document::new();
    picture_source.add_picture(
        b"f256-exhausted-image",
        "exhausted.png",
        Length::pt(12.0),
        Length::pt(9.0),
    );
    let body = f254_story(&picture_source, StoryKind::Body);
    let item = f254_item(&picture_source, &body, 0);
    let picture_fragment =
        DocumentFragment::from_range(&picture_source, &item, &ContentLocation::end(body), false)
            .unwrap();
    let mut exhausted_package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(
        Document::new().to_bytes().unwrap(),
    ))
    .unwrap();
    exhausted_package.set_part("/word/unchanged.bin", b"unchanged".to_vec());
    exhausted_package
        .content_types
        .add_override("/word/unchanged.bin", "application/octet-stream");
    exhausted_package
        .get_or_create_part_rels("/word/document.xml")
        .add_with_id(
            &format!("rId{}", u32::MAX),
            "urn:f256-exhaustion",
            "unchanged.bin",
        );
    let mut exhausted_bytes = std::io::Cursor::new(Vec::new());
    exhausted_package.write_to(&mut exhausted_bytes).unwrap();
    let mut exhausted = Document::from_bytes(exhausted_bytes.get_ref()).unwrap();
    let before_exhausted = exhausted.to_bytes().unwrap();
    let body = f254_story(&exhausted, StoryKind::Body);
    let error = exhausted
        .import_fragment(
            &ContentLocation::end(body),
            &picture_fragment,
            FragmentConflictPolicy::reuse_equivalent(),
        )
        .unwrap_err();
    assert!(error.to_string().contains("exhausted"), "{error}");
    assert_eq!(exhausted.to_bytes().unwrap(), before_exhausted);

    let mut opaque_source = Document::new();
    opaque_source.add_picture(
        b"f276-unsafe-image",
        "unsafe.png",
        Length::pt(10.0),
        Length::pt(10.0),
    );
    let mut source_package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(opaque_source.to_bytes().unwrap()))
            .unwrap();
    let image_part = source_package
        .parts
        .iter()
        .find_map(|(name, bytes)| (bytes.as_slice() == b"f276-unsafe-image").then(|| name.clone()))
        .unwrap();
    source_package.set_part(
        "/word/unsafe.bin",
        b"opaque reference /word/unsafe.bin".to_vec(),
    );
    source_package
        .content_types
        .add_override("/word/unsafe.bin", "application/x-f276-unsafe");
    source_package
        .get_or_create_part_rels(&image_part)
        .add_with_id("unsafeChild", "urn:f276:unsafe", "/word/unsafe.bin");
    let mut source_bytes = std::io::Cursor::new(Vec::new());
    source_package.write_to(&mut source_bytes).unwrap();
    let opaque_source = Document::from_bytes(source_bytes.get_ref()).unwrap();
    let body = f254_story(&opaque_source, StoryKind::Body);
    let opaque_fragment = DocumentFragment::from_range(
        &opaque_source,
        &f254_item(&opaque_source, &body, 0),
        &ContentLocation::end(body),
        false,
    )
    .unwrap();
    let mut destination_package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(
        Document::new().to_bytes().unwrap(),
    ))
    .unwrap();
    destination_package.set_part("/word/unsafe.bin", b"existing payload".to_vec());
    destination_package
        .content_types
        .add_override("/word/unsafe.bin", "application/x-f276-unsafe");
    let mut destination_bytes = std::io::Cursor::new(Vec::new());
    destination_package
        .write_to(&mut destination_bytes)
        .unwrap();
    let mut destination = Document::from_bytes(destination_bytes.get_ref()).unwrap();
    let before = destination.to_bytes().unwrap();
    let body = f254_story(&destination, StoryKind::Body);
    let error = destination
        .import_fragment(
            &ContentLocation::end(body),
            &opaque_fragment,
            FragmentConflictPolicy::rename_all(),
        )
        .unwrap_err();
    assert!(
        error
            .to_string()
            .contains("opaque payload cannot be rewritten safely"),
        "{error}"
    );
    assert_eq!(destination.to_bytes().unwrap(), before);
}

#[test]
fn contributor_document_body_reader_semantics_survive_reopen() {
    let mut seed = Document::new();
    let mut package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap())).unwrap();
    package.set_part(
        "/word/document.xml",
        format!(r#"<w:document xmlns:w="{W_NS}"><w:body><w:p/><w:sectPr/></w:body></w:document>"#)
            .into_bytes(),
    );
    let mut bytes = std::io::Cursor::new(Vec::new());
    package.write_to(&mut bytes).unwrap();

    let mut document = Document::from_bytes(bytes.get_ref()).unwrap();
    let first = document.to_bytes().unwrap();
    let first_package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&first)).unwrap();
    let first_xml = first_package.get_part("/word/document.xml").unwrap();
    assert!(
        first_xml
            .windows(b"<w:p/>".len())
            .any(|window| window == b"<w:p/>"),
        "modeled empty paragraphs must retain the self-closing form"
    );

    let mut reopened = Document::from_bytes(&first).unwrap();
    let second = reopened.to_bytes().unwrap();
    let second_package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(second)).unwrap();
    assert_eq!(
        second_package.get_part("/word/document.xml"),
        Some(first_xml)
    );
}

fn f264_document_bytes(paragraph_properties: &str) -> Vec<u8> {
    let mut seed = Document::new();
    let mut package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap())).unwrap();
    package.set_part(
        "/word/document.xml",
        format!(
            concat!(
                r#"<w:document xmlns:w="{}"><w:body><w:p><w:pPr>{}</w:pPr>"#,
                r#"<w:r><w:t>framed</w:t></w:r></w:p><w:sectPr/></w:body></w:document>"#,
            ),
            W_NS, paragraph_properties
        )
        .into_bytes(),
    );
    let mut bytes = std::io::Cursor::new(Vec::new());
    package.write_to(&mut bytes).unwrap();
    bytes.into_inner()
}

fn f264_document_xml(bytes: &[u8]) -> String {
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).unwrap();
    String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap()
}

#[test]
fn a_paragraph_that_only_gains_a_modeled_frame_keeps_its_producer_attribute_order() {
    let source = f264_document_bytes(concat!(
        r#"<w:framePr xmlns:ext="urn:producer" ext:first="one" w:w="1440""#,
        r#" ext:second="two" w:hRule="exact" w:xAlign="center"/>"#,
    ));
    let mut untouched = Document::from_bytes(&source).unwrap();
    let saved = f264_document_xml(&untouched.to_bytes().unwrap());
    let first = saved
        .find(r#"ext:first="one""#)
        .expect("the first producer attribute");
    let second = saved
        .find(r#"ext:second="two""#)
        .expect("the second producer attribute");
    assert!(first < second, "{saved}");
    assert!(saved.contains(r#"xmlns:ext="urn:producer""#), "{saved}");
    assert!(saved.contains(r#"w:w="1440""#), "{saved}");

    let mut widened = Document::from_bytes(&source).unwrap();
    let frame = widened
        .paragraph(0)
        .unwrap()
        .frame()
        .expect("a typed frame");
    widened.paragraph_mut(0).unwrap().set_frame(ParagraphFrame {
        width: Some(Length::twips(2880)),
        ..frame
    });
    let mutated = f264_document_xml(&widened.to_bytes().unwrap());
    let first = mutated
        .find(r#"ext:first="one""#)
        .expect("the first producer attribute");
    let second = mutated
        .find(r#"ext:second="two""#)
        .expect("the second producer attribute");
    assert!(first < second, "{mutated}");
    assert!(mutated.contains(r#"w:w="2880""#), "{mutated}");
    assert!(mutated.contains(r#"w:hRule="exact""#), "{mutated}");
    assert!(mutated.contains(r#"w:xAlign="center""#), "{mutated}");
}

#[test]
fn logical_indentation_set_through_the_facade_survives_save_and_reopen() {
    let mut document = Document::new();
    {
        let mut paragraph = document.add_paragraph("logical");
        paragraph.set_indent_start(Length::twips(720));
        paragraph.set_indent_end(Length::twips(360));
    }

    let bytes = document.to_bytes().unwrap();
    let xml = f264_document_xml(&bytes);
    assert!(xml.contains(r#"w:start="720""#), "{xml}");
    assert!(xml.contains(r#"w:end="360""#), "{xml}");

    let reopened = Document::from_bytes(&bytes).unwrap();
    let paragraph = reopened.paragraph(0).unwrap();
    assert_eq!(paragraph.indent_start(), Some(Length::twips(720)));
    assert_eq!(paragraph.indent_end(), Some(Length::twips(360)));
}

#[test]
fn clearing_the_last_paragraph_property_removes_the_empty_ppr() {
    let mut document = Document::new();
    document
        .add_paragraph("cleared")
        .set_contextual_spacing(true);
    assert!(f264_document_xml(&document.to_bytes().unwrap()).contains("<w:contextualSpacing/>"),);

    document
        .paragraph_mut(0)
        .unwrap()
        .set_contextual_spacing_value(None);
    let xml = f264_document_xml(&document.to_bytes().unwrap());
    assert!(!xml.contains("<w:pPr"), "{xml}");
    assert_eq!(
        Document::from_bytes(&document.to_bytes().unwrap())
            .unwrap()
            .paragraph(0)
            .unwrap()
            .contextual_spacing_value(),
        None
    );
}

/// A settings remover once rewrote the whole part, which reflowed producer
/// bytes that had nothing to do with the removed child.
#[test]
fn removing_a_setting_does_not_disturb_neighbouring_producer_bytes() {
    let producer = format!(
        concat!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>"#,
            r#"<w:settings xmlns:w="{word}" xmlns:p="urn:producer" p:root="kept">"#,
            r#"<p:before p:v="1"/>"#,
            r#"<w:view w:val="print"/>"#,
            r#"<w:zoom w:val="fullPage" w:percent="120"/>"#,
            r#"<w:mirrorMargins/>"#,
            r#"<w:proofState w:spelling="clean" w:grammar="dirty"/>"#,
            r#"<w:defaultTabStop w:val="720"/>"#,
            r#"<w:consecutiveHyphenLimit w:val="2"/>"#,
            r#"<w:hyphenationZone w:val="360"/>"#,
            r#"<w:defaultTableStyle w:val="TableNormal"/>"#,
            r#"<w:bookFoldPrintingSheets w:val="4"/>"#,
            r#"<w:compat><w:noTabHangInd/><p:inside p:v="2"/></w:compat>"#,
            r#"<w:rsids><w:rsid w:val="00AA00AA"/></w:rsids>"#,
            r#"<w:decimalSymbol w:val="."/>"#,
            r#"<w:listSeparator w:val=","/>"#,
            r#"<p:after>keep me</p:after>"#,
            r#"</w:settings>"#,
        ),
        word = W_NS,
    );
    let mut document = settings_document(&producer);

    assert_eq!(
        document.remove_view().unwrap(),
        Some(rdocx::DocumentView::Print)
    );
    assert!(document.remove_zoom().unwrap().is_some());
    assert_eq!(document.remove_mirror_margins().unwrap(), Some(true));
    assert!(document.remove_proof_state().unwrap().is_some());
    assert_eq!(
        document.remove_default_tab_stop().unwrap(),
        Some(rdocx::Twips(720))
    );
    assert_eq!(document.remove_consecutive_hyphen_limit().unwrap(), Some(2));
    assert_eq!(
        document.remove_hyphenation_zone().unwrap(),
        Some(rdocx::Twips(360))
    );
    assert_eq!(
        document.remove_default_table_style().unwrap().as_deref(),
        Some("TableNormal")
    );
    assert_eq!(
        document.remove_book_fold_printing_sheets().unwrap(),
        Some(4)
    );
    assert_eq!(
        document
            .remove_compatibility_option(rdocx::CompatibilityOption::NoTabHangInd)
            .unwrap(),
        Some(true)
    );
    assert_eq!(
        document.remove_decimal_symbol().unwrap().as_deref(),
        Some(".")
    );
    assert_eq!(
        document.remove_list_separator().unwrap().as_deref(),
        Some(",")
    );

    let settings = settings_part_text(&document.to_bytes().unwrap());
    let expected = format!(
        concat!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>"#,
            r#"<w:settings xmlns:w="{word}" xmlns:p="urn:producer" p:root="kept">"#,
            r#"<p:before p:v="1"/>"#,
            r#"<w:compat><p:inside p:v="2"/></w:compat>"#,
            r#"<w:rsids><w:rsid w:val="00AA00AA"/></w:rsids>"#,
            r#"<p:after>keep me</p:after>"#,
            r#"</w:settings>"#,
        ),
        word = W_NS,
    );
    assert_eq!(settings, expected);
}

/// Removal once reinterpreted a duplicated or malformed occurrence, which
/// silently picked one of several conflicting producer values.
#[test]
fn removing_an_ambiguous_setting_fails_without_changing_the_document() {
    for (producer_child, remove) in [
        (
            r#"<w:mirrorMargins/><w:mirrorMargins w:val="false"/>"#,
            0usize,
        ),
        (r#"<w:mirrorMargins w:val="perhaps"/>"#, 0),
        (
            r#"<w:compat><w:noTabHangInd/><w:noTabHangInd w:val="false"/></w:compat>"#,
            1,
        ),
    ] {
        let producer = format!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:settings xmlns:w="{W_NS}">{producer_child}</w:settings>"#,
        );
        let mut document = settings_document(&producer);
        let before = document.to_bytes().unwrap();
        assert!(!document.settings_diagnostics().is_empty(), "{producer}");

        let outcome = match remove {
            0 => document
                .remove_mirror_margins()
                .map(|value| value.is_some()),
            _ => document
                .remove_compatibility_option(rdocx::CompatibilityOption::NoTabHangInd)
                .map(|value| value.is_some()),
        };
        assert!(outcome.is_err(), "{producer}");
        assert_eq!(
            settings_part_text(&document.to_bytes().unwrap()),
            settings_part_text(&before),
            "{producer}"
        );
    }
}

/// A settings read once matched on the local name alone, so a foreign
/// namespace lookalike shadowed the modeled child, and a write emitted the
/// producer's prefix instead of the fixed one.
#[test]
fn prefix_aliases_and_foreign_lookalikes_do_not_shadow_a_settings_child() {
    let producer = format!(
        concat!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>"#,
            r#"<q:settings xmlns:q="{word}" xmlns:x="urn:foreign">"#,
            r#"<x:view x:val="web"/>"#,
            r#"<q:view q:val="outline"/>"#,
            r#"<x:mirrorMargins/>"#,
            r#"</q:settings>"#,
        ),
        word = W_NS,
    );
    let mut document = settings_document(&producer);

    // The in-scope Word alias is read, the foreign lookalike is not.
    assert_eq!(document.view(), Some(rdocx::DocumentView::Outline));
    assert_eq!(document.mirror_margins(), None);
    assert_eq!(document.settings_diagnostics(), &[]);

    document.set_view(rdocx::DocumentView::Normal).unwrap();
    document.set_mirror_margins(true).unwrap();
    let settings = settings_part_text(&document.to_bytes().unwrap());
    assert!(
        settings.contains(r#"<w:view w:val="normal"/>"#),
        "{settings}"
    );
    assert!(!settings.contains("<q:view"), "{settings}");
    assert!(settings.contains(r#"<x:view x:val="web"/>"#), "{settings}");
    assert!(settings.contains("<w:mirrorMargins/>"), "{settings}");
    assert!(settings.contains("<x:mirrorMargins/>"), "{settings}");

    let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.view(), Some(rdocx::DocumentView::Normal));
    assert_eq!(reopened.mirror_margins(), Some(true));
    assert_eq!(reopened.settings_diagnostics(), &[]);
}

/// Build a Word-compatible package whose settings part carries producer bytes.
fn settings_document(settings_xml: &str) -> Document {
    let mut seeded = Document::new_with_profile(WordCreationProfile::WordCompatible(
        WordPackageClass::Document,
    ));
    seeded.add_paragraph("Settings regression");
    let mut package =
        oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seeded.to_bytes().unwrap()))
            .unwrap();
    package.set_part("/word/settings.xml", settings_xml.as_bytes().to_vec());
    let mut buffer = std::io::Cursor::new(Vec::new());
    package.write_to(&mut buffer).unwrap();
    Document::from_bytes(buffer.get_ref()).unwrap()
}

fn settings_part_text(bytes: &[u8]) -> String {
    let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes.to_vec())).unwrap();
    String::from_utf8(package.get_part("/word/settings.xml").unwrap().to_vec()).unwrap()
}

/// F-265, complete run property and inline authoring.
#[test]
fn comparison_tracks_paragraph_properties_with_revision_identities() {
    for attributes in [
        r#"w:rsidR="00112233""#,
        r#"w:rsidRDefault="00112234""#,
        r#"w:rsidP="00112235""#,
        r#"w:rsidR="00112233" w:rsidRDefault="00112234" w:rsidP="00112235" w:rsidRPr="00112236""#,
    ] {
        let original_xml = wrap_word_body(&format!(
            r#"<w:p {attributes}><w:pPr><w:keepNext/></w:pPr><w:r><w:t>same</w:t></w:r></w:p>"#,
        ));
        let edited_xml = wrap_word_body(&format!(
            r#"<w:p {attributes}><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:t>same</w:t></w:r></w:p>"#,
        ));
        let edited = document_with_content_controls(&edited_xml);
        let mut compared = document_with_content_controls(&original_xml);

        let diagnostics = compared
            .compare(&edited, "Ada", "2026-09-25T09:00:00Z")
            .expect("revision identities must not block paragraph formatting comparison");
        assert!(diagnostics.is_empty(), "{attributes}: {diagnostics:?}");
        assert!(document_xml(&mut compared).contains("<w:pPrChange"));

        let tracked = compared.to_bytes().unwrap();
        let mut accepted = Document::from_bytes(&tracked).unwrap();
        accepted.accept_all().unwrap();
        assert!(
            accepted
                .compare(&edited, "postcondition", "2026-09-25T09:01:00Z")
                .unwrap()
                .is_empty()
        );
        let original = document_with_content_controls(&original_xml);
        let mut rejected = Document::from_bytes(&tracked).unwrap();
        rejected.reject_all().unwrap();
        assert!(
            rejected
                .compare(&original, "postcondition", "2026-09-25T09:01:00Z")
                .unwrap()
                .is_empty()
        );
    }
}

#[test]
fn comparison_treats_empty_paragraph_properties_as_absent() {
    let absent_xml = wrap_word_body(r#"<w:p><w:r><w:t>same</w:t></w:r></w:p>"#);
    let empty_xml = wrap_word_body(r#"<w:p><w:pPr/><w:r><w:t>same</w:t></w:r></w:p>"#);
    let formatted_xml = wrap_word_body(
        r#"<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:t>same</w:t></w:r></w:p>"#,
    );

    let empty = document_with_content_controls(&empty_xml);
    let mut absent = document_with_content_controls(&absent_xml);
    assert!(
        absent
            .compare(&empty, "Ada", "2026-09-25T09:00:00Z")
            .expect("an empty property shell is semantically absent")
            .is_empty()
    );

    let formatted = document_with_content_controls(&formatted_xml);
    let mut empty = document_with_content_controls(&empty_xml);
    let diagnostics = empty
        .compare(&formatted, "Ada", "2026-09-25T09:00:00Z")
        .expect("an empty property shell must not block a formatting revision");
    assert!(diagnostics.is_empty(), "{diagnostics:?}");
    assert!(document_xml(&mut empty).contains("<w:pPrChange"));
}

/// Producer serialization that `compare()` must read as equivalent content.
///
/// None of it is content, so none of it may refuse a pair or become a
/// revision.
mod compare_producer_noise {
    use super::*;
    use rdocx::{ComparisonGranularity, ComparisonOptions, RevisionKind};

    const TIMESTAMP: &str = "2026-09-27T12:00:00Z";

    fn revision_kinds(document: &Document) -> Vec<RevisionKind> {
        document
            .revisions()
            .iter()
            .map(|revision| revision.kind())
            .collect()
    }

    /// Check that accepting gives the edited side and rejecting the original,
    /// each compared again with no diagnostic and no revision.
    fn assert_resolutions(
        tracked: &[u8],
        original: &Document,
        edited: &Document,
        options: &ComparisonOptions,
    ) {
        for (resolve, expected) in [
            (
                Document::accept_all as fn(&mut Document) -> rdocx::Result<usize>,
                edited,
            ),
            (Document::reject_all, original),
        ] {
            let mut resolved = Document::from_bytes(tracked).unwrap();
            resolve(&mut resolved).unwrap();
            let diagnostics = resolved
                .compare_with_options(expected, "postcondition", TIMESTAMP, options)
                .unwrap();
            assert!(diagnostics.is_empty(), "{diagnostics:?}");
            assert_eq!(revision_kinds(&resolved), []);
        }
    }

    /// Compare two bodies and return the revision kinds and the redline.
    fn compared_kinds(original_xml: &str, edited_xml: &str) -> (Vec<RevisionKind>, String) {
        compared_kinds_with(original_xml, edited_xml, &ComparisonOptions::default())
    }

    fn compared_kinds_with(
        original_xml: &str,
        edited_xml: &str,
        options: &ComparisonOptions,
    ) -> (Vec<RevisionKind>, String) {
        let original = document_with_content_controls(original_xml);
        let edited = document_with_content_controls(edited_xml);
        let mut compared = document_with_content_controls(original_xml);
        let diagnostics = compared
            .compare_with_options(&edited, "R", TIMESTAMP, options)
            .expect("producer noise must not refuse the pair");
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        assert_resolutions(&compared.to_bytes().unwrap(), &original, &edited, options);
        (revision_kinds(&compared), document_xml(&mut compared))
    }

    fn table_of_contents_control(id: Option<&str>, first_entry: &str) -> String {
        let id = id.map_or_else(String::new, |value| format!(r#"<w:id w:val="{value}"/>"#));
        wrap_word_body(&format!(
            r#"<w:p><w:r><w:t>Before the content control.</w:t></w:r></w:p><w:sdt><w:sdtPr>{id}<w:docPartObj><w:docPartGallery w:val="Table of Contents"/><w:docPartUnique/></w:docPartObj></w:sdtPr><w:sdtContent><w:p><w:r><w:t>{first_entry} entry</w:t></w:r></w:p><w:p><w:r><w:t>Beta entry</w:t></w:r></w:p><w:p><w:r><w:t>Gamma entry</w:t></w:r></w:p></w:sdtContent></w:sdt><w:p><w:r><w:t>After the content control.</w:t></w:r></w:p>"#
        ))
    }

    fn google_docs_inline_control(id: &str, word: &str) -> String {
        wrap_word_body(&format!(
            r#"<w:p><w:r><w:t xml:space="preserve">Before </w:t></w:r><w:sdt><w:sdtPr><w:tag w:val="goog_rdk_0"/><w:id w:val="{id}"/></w:sdtPr><w:sdtContent><w:r><w:t>{word}</w:t></w:r></w:sdtContent></w:sdt><w:r><w:t xml:space="preserve"> after.</w:t></w:r></w:p>"#
        ))
    }

    #[test]
    fn a_content_control_identity_is_not_content() {
        for (original, edited, kept_id) in [
            (None, Some("-2000000001"), None),
            (Some("-2000000001"), None, Some("-2000000001")),
            (Some("11"), Some("12"), Some("11")),
        ] {
            let (kinds, tracked) = compared_kinds(
                &table_of_contents_control(original, "Alpha"),
                &table_of_contents_control(edited, "Alpha"),
            );
            assert_eq!(kinds, [], "{original:?} -> {edited:?}");
            let ids = [original, edited]
                .into_iter()
                .flatten()
                .filter(|id| tracked.contains(&format!(r#"<w:id w:val="{id}"/>"#)))
                .collect::<Vec<_>>();
            assert_eq!(ids, kept_id.into_iter().collect::<Vec<_>>(), "{tracked}");

            let (kinds, tracked) = compared_kinds(
                &table_of_contents_control(original, "Alpha"),
                &table_of_contents_control(edited, "Delta"),
            );
            assert_eq!(
                kinds,
                [RevisionKind::Deletion, RevisionKind::Insertion],
                "{original:?} -> {edited:?}"
            );
            assert_eq!(tracked.matches("<w:sdtPr>").count(), 1, "{tracked}");
        }

        let (kinds, _) = compared_kinds(
            &google_docs_inline_control("-1854911024", "Alpha"),
            &google_docs_inline_control("1374263513", "Alpha"),
        );
        assert_eq!(kinds, []);
        let (kinds, tracked) = compared_kinds(
            &google_docs_inline_control("-1854911024", "Alpha"),
            &google_docs_inline_control("1374263513", "Delta"),
        );
        assert_eq!(kinds, [RevisionKind::Deletion, RevisionKind::Insertion]);
        assert!(
            tracked.contains(r#"<w:id w:val="-1854911024"/>"#),
            "{tracked}"
        );

        let bare_control = |properties: &str| {
            wrap_word_body(&format!(
                r#"<w:sdt>{properties}<w:sdtContent><w:p><w:r><w:t>Alpha entry</w:t></w:r></w:p></w:sdtContent></w:sdt><w:p><w:r><w:t>After the content control.</w:t></w:r></w:p>"#
            ))
        };
        let id_only = r#"<w:sdtPr><w:id w:val="5"/></w:sdtPr>"#;
        for (original, edited) in [("", id_only), (id_only, "")] {
            let (kinds, tracked) = compared_kinds(&bare_control(original), &bare_control(edited));
            assert_eq!(kinds, [], "{original:?} -> {edited:?}");
            assert_eq!(
                tracked.contains("<w:sdtPr>"),
                !original.is_empty(),
                "{tracked}"
            );
        }
    }

    fn metadata_diagnostic(location: &str, property: &str) -> rdocx::ComparisonDiagnostic {
        rdocx::ComparisonDiagnostic {
            location: location.to_owned(),
            message: format!(
                "content-control {property} differs and the original {property} was retained"
            ),
        }
    }

    /// Compare two bodies whose controls differ by metadata and return the
    /// revision kinds, the diagnostics and the redline.
    ///
    /// Accepting keeps the original metadata, so it reads like the edited
    /// side with the same diagnostics, and rejecting gives the original back.
    fn compared_metadata(
        original_xml: &str,
        edited_xml: &str,
        options: &ComparisonOptions,
    ) -> (Vec<RevisionKind>, Vec<rdocx::ComparisonDiagnostic>, String) {
        let original = document_with_content_controls(original_xml);
        let edited = document_with_content_controls(edited_xml);
        let mut compared = document_with_content_controls(original_xml);
        let diagnostics = compared
            .compare_with_options(&edited, "R", TIMESTAMP, options)
            .expect("content-control metadata must not refuse the pair");
        let tracked = compared.to_bytes().unwrap();
        let mut accepted = Document::from_bytes(&tracked).unwrap();
        accepted.accept_all().unwrap();
        assert_eq!(
            accepted
                .compare_with_options(&edited, "postcondition", TIMESTAMP, options)
                .unwrap(),
            diagnostics
        );
        assert_eq!(revision_kinds(&accepted), []);
        let mut rejected = Document::from_bytes(&tracked).unwrap();
        rejected.reject_all().unwrap();
        assert_eq!(
            rejected
                .compare_with_options(&original, "postcondition", TIMESTAMP, options)
                .unwrap(),
            []
        );
        assert_eq!(revision_kinds(&rejected), []);
        (
            revision_kinds(&compared),
            diagnostics,
            document_xml(&mut compared),
        )
    }

    /// A control's metadata names, protects or files it without changing
    /// what it holds, and Google Docs renumbers its `goog_rdk_N` tags between
    /// exports (#159 section 2). A difference is reported and the original
    /// `w:sdtPr` is kept.
    #[test]
    fn content_control_metadata_is_reported_and_the_original_kept() {
        let block = |properties: &str, first_entry: &str| {
            wrap_word_body(&format!(
                r#"<w:p><w:r><w:t>Before the content control.</w:t></w:r></w:p><w:sdt><w:sdtPr>{properties}</w:sdtPr><w:sdtContent><w:p><w:r><w:t>{first_entry} entry</w:t></w:r></w:p><w:p><w:r><w:t>Beta entry</w:t></w:r></w:p></w:sdtContent></w:sdt><w:p><w:r><w:t>After the content control.</w:t></w:r></w:p>"#
            ))
        };
        let gallery = |value: &str| {
            format!(
                r#"<w:docPartObj><w:docPartGallery w:val="{value}"/><w:docPartUnique/></w:docPartObj>"#
            )
        };
        let placeholder =
            |value: &str| format!(r#"<w:placeholder><w:docPart w:val="{value}"/></w:placeholder>"#);
        let changed = &[RevisionKind::Deletion, RevisionKind::Insertion][..];
        for (property, original, edited) in [
            (
                "tag",
                format!(
                    r#"<w:tag w:val="goog_rdk_0"/><w:id w:val="-2000000001"/>{}"#,
                    gallery("Table of Contents")
                ),
                format!(
                    r#"<w:tag w:val="goog_rdk_3"/><w:id w:val="-2000000001"/>{}"#,
                    gallery("Table of Contents")
                ),
            ),
            (
                "alias",
                r#"<w:alias w:val="Contents"/>"#.to_owned(),
                r#"<w:alias w:val="Summary"/>"#.to_owned(),
            ),
            (
                "lock",
                String::new(),
                r#"<w:lock w:val="sdtContentLocked"/>"#.to_owned(),
            ),
            (
                "placeholder",
                placeholder("DefaultPlaceholder_1"),
                placeholder("DefaultPlaceholder_2"),
            ),
            (
                "docPartGallery",
                gallery("Table of Contents"),
                gallery("Custom Table of Contents"),
            ),
        ] {
            for (first_entry, expected) in [("Alpha", &[][..]), ("Delta", changed)] {
                let (kinds, diagnostics, tracked) = compared_metadata(
                    &block(&original, "Alpha"),
                    &block(&edited, first_entry),
                    &ComparisonOptions::default(),
                );
                assert_eq!(kinds, expected, "{property}");
                assert_eq!(
                    diagnostics,
                    [metadata_diagnostic("body/content-control[1]", property)]
                );
                assert!(
                    tracked.contains(&format!("<w:sdtPr>{original}</w:sdtPr>")),
                    "{tracked}"
                );
            }
        }

        // A renamed tag and a new lock are two diagnostics on one control.
        let (_, diagnostics, _) = compared_metadata(
            &block(r#"<w:tag w:val="goog_rdk_0"/>"#, "Alpha"),
            &block(
                r#"<w:tag w:val="goog_rdk_1"/><w:lock w:val="sdtLocked"/>"#,
                "Alpha",
            ),
            &ComparisonOptions::default(),
        );
        assert_eq!(
            diagnostics,
            [
                metadata_diagnostic("body/content-control[1]", "tag"),
                metadata_diagnostic("body/content-control[1]", "lock"),
            ]
        );

        // Google Docs writes a bookmark around a heading, and bookmarks are
        // indexed by run, so the runs around the control must stay whole.
        let inline = |tag: &str, word: &str| {
            wrap_word_body(&format!(
                r#"<w:p><w:bookmarkStart w:id="0" w:name="h.1"/><w:r><w:t xml:space="preserve">Before </w:t></w:r><w:bookmarkEnd w:id="0"/><w:sdt><w:sdtPr><w:tag w:val="{tag}"/><w:id w:val="1"/></w:sdtPr><w:sdtContent><w:r><w:t>{word}</w:t></w:r></w:sdtContent></w:sdt><w:r><w:t xml:space="preserve"> after.</w:t></w:r></w:p>"#
            ))
        };
        for granularity in [
            ComparisonGranularity::Run,
            ComparisonGranularity::Word,
            ComparisonGranularity::Character,
        ] {
            let options = ComparisonOptions {
                granularity,
                ..Default::default()
            };
            // "Omens" has the length of "Alpha" and none of its characters,
            // so every granularity gives one deletion and one insertion.
            for (word, expected) in [("Alpha", &[][..]), ("Omens", changed)] {
                let (kinds, diagnostics, tracked) = compared_metadata(
                    &inline("goog_rdk_0", "Alpha"),
                    &inline("goog_rdk_5", word),
                    &options,
                );
                assert_eq!(kinds, expected, "{granularity:?}");
                assert_eq!(
                    diagnostics,
                    [metadata_diagnostic(
                        "body/paragraph[0]/content-control[0]",
                        "tag"
                    )],
                    "{granularity:?}"
                );
                assert!(
                    tracked.contains(r#"<w:tag w:val="goog_rdk_0"/>"#),
                    "{tracked}"
                );
                assert!(!tracked.contains("goog_rdk_5"), "{tracked}");
            }
        }
    }

    /// The control type and its data binding decide what a control holds, so
    /// a difference in either still refuses the pair.
    #[test]
    fn a_content_control_type_or_binding_change_still_refuses() {
        let control = |properties: &str| {
            wrap_word_body(&format!(
                r#"<w:sdt><w:sdtPr>{properties}</w:sdtPr><w:sdtContent><w:p><w:r><w:t>Alpha entry</w:t></w:r></w:p></w:sdtContent></w:sdt><w:p><w:r><w:t>After the content control.</w:t></w:r></w:p>"#
            ))
        };
        let binding = |xpath: &str| {
            format!(
                r#"<w:dataBinding w:storeItemID="{{11111111-1111-1111-1111-111111111111}}" w:xpath="{xpath}"/><w:text/>"#
            )
        };
        for (original, edited) in [
            ("<w:text/>".to_owned(), "<w:richText/>".to_owned()),
            (binding("/root/first"), binding("/root/second")),
        ] {
            let mut compared = document_with_content_controls(&control(&original));
            let before = compared.to_bytes().unwrap();
            let error = compared
                .compare(
                    &document_with_content_controls(&control(&edited)),
                    "R",
                    TIMESTAMP,
                )
                .unwrap_err();
            assert!(
                error.to_string().contains(
                    "cannot revise content-control properties at body/content-control[0]"
                ),
                "{error}"
            );
            assert_eq!(compared.to_bytes().unwrap(), before);
        }
    }

    fn replaced_copy(source_xml: &str, old: &str, new: &str) -> String {
        let mut document = document_with_content_controls(source_xml);
        assert_eq!(document.try_replace_text(old, new).unwrap(), 1);
        let mut edited = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        document_xml(&mut edited)
    }

    #[test]
    fn a_rewritten_run_keeps_its_producer_space_flag() {
        let preserved = wrap_word_body(
            r#"<w:p><w:r><w:t xml:space="preserve">Paragraph 1.</w:t></w:r></w:p><w:p><w:r><w:t xml:space="preserve">WORD</w:t></w:r></w:p>"#,
        );
        let edited = replaced_copy(&preserved, "WORD", "WORD");
        assert!(
            edited.contains(r#"<w:t xml:space="preserve">WORD</w:t>"#),
            "{edited}"
        );
        let (kinds, _) = compared_kinds(&preserved, &edited);
        assert_eq!(kinds, []);

        let edge_space_removed = replaced_copy(
            &wrap_word_body(r#"<w:p><w:r><w:t xml:space="preserve">WORD </w:t></w:r></w:p>"#),
            "WORD ",
            "WORD",
        );
        assert!(
            edge_space_removed.contains(r#"<w:t xml:space="preserve">WORD</w:t>"#),
            "{edge_space_removed}"
        );
    }

    #[test]
    fn the_space_flag_is_content_only_at_a_text_edge() {
        let paragraphs = |first: &str, second: &str| {
            wrap_word_body(&format!(
                r#"<w:p><w:r>{first}</w:r></w:p><w:p><w:r>{second}</w:r></w:p>"#
            ))
        };
        let paragraph = |text: &str| paragraphs("<w:t>Paragraph 1.</w:t>", text);
        // Bookmark ends are indexed by run, so an unchanged run must stay whole.
        let bookmarked = |text: &str| {
            wrap_word_body(&format!(
                r#"<w:p><w:bookmarkStart w:id="0" w:name="b"/><w:r>{text}</w:r><w:bookmarkEnd w:id="0"/><w:r><w:t>tail</w:t></w:r></w:p>"#
            ))
        };
        let changed = &[RevisionKind::Deletion, RevisionKind::Insertion][..];
        let unchanged = &[][..];
        // Each case gives the kinds of the whole-run path and of the
        // attributed path. The attributed path writes every unit with edge
        // whitespace with the flag, so the flag is never content there.
        let cases = [
            (
                paragraph(r#"<w:t xml:space="preserve">WORD</w:t>"#),
                paragraph("<w:t>WORD</w:t>"),
                unchanged,
                unchanged,
            ),
            (
                paragraph(r#"<w:t xml:space="preserve">two words</w:t>"#),
                paragraph("<w:t>two words</w:t>"),
                unchanged,
                unchanged,
            ),
            (
                paragraph("<w:t>two  words</w:t>"),
                paragraph(r#"<w:t xml:space="preserve">two  words</w:t>"#),
                unchanged,
                unchanged,
            ),
            (
                paragraph(r#"<w:t xml:space="preserve">WORD </w:t>"#),
                paragraph("<w:t>WORD </w:t>"),
                changed,
                unchanged,
            ),
            (
                bookmarked(r#"<w:t xml:space="preserve">two words </w:t>"#),
                bookmarked("<w:t>two words </w:t>"),
                changed,
                unchanged,
            ),
            (
                paragraph("<w:t>WORD</w:t>"),
                paragraph("<w:t>text</w:t>"),
                changed,
                changed,
            ),
            // Google Docs flags every `w:t` and Word only where needed.
            (
                paragraphs(
                    r#"<w:t xml:space="preserve">two words</w:t>"#,
                    r#"<w:t xml:space="preserve">WORD</w:t>"#,
                ),
                paragraphs("<w:t>two words</w:t>", "<w:t>text</w:t>"),
                changed,
                changed,
            ),
        ];
        for options in [
            ComparisonOptions::default(),
            ComparisonOptions {
                ignore_formatting: true,
                ..Default::default()
            },
            ComparisonOptions {
                granularity: ComparisonGranularity::Word,
                ..Default::default()
            },
            ComparisonOptions {
                granularity: ComparisonGranularity::Character,
                ..Default::default()
            },
        ] {
            for (original, edited, whole_run, attributed) in &cases {
                let expected = if options == ComparisonOptions::default() {
                    whole_run
                } else {
                    attributed
                };
                for (left, right) in [(original, edited), (edited, original)] {
                    let (kinds, _) = compared_kinds_with(left, right, &options);
                    assert_eq!(kinds, *expected, "{options:?}: {left} -> {right}");
                }
            }
        }

        // A space split out of a text keeps reading as a space in the redline.
        for granularity in [
            ComparisonGranularity::Word,
            ComparisonGranularity::Character,
        ] {
            let (kinds, tracked) = compared_kinds_with(
                &paragraph("<w:t>two words</w:t>"),
                &paragraph("<w:t>two wordy</w:t>"),
                &ComparisonOptions {
                    granularity,
                    ..Default::default()
                },
            );
            assert_eq!(kinds, changed, "{granularity:?}");
            assert!(!tracked.contains("<w:t> </w:t>"), "{tracked}");
            assert!(
                tracked.contains(r#"<w:t xml:space="preserve"> </w:t>"#),
                "{tracked}"
            );
        }
    }

    fn page_body(orientation: &str) -> String {
        wrap_word_body(&format!(
            r#"<w:p><w:r><w:t>Paragraph 1, lorem ipsum dolor sit amet.</w:t></w:r></w:p><w:p><w:r><w:t>WORD</w:t></w:r></w:p><w:p><w:r><w:t>Paragraph 3, lorem ipsum dolor sit amet.</w:t></w:r></w:p><w:sectPr><w:pgSz w:w="12240" w:h="15840"{orientation}/></w:sectPr>"#
        ))
    }

    #[test]
    fn the_default_page_orientation_is_not_a_section_change() {
        let portrait = page_body(r#" w:orient="portrait""#);
        let edited = replaced_copy(&portrait, "3, lorem", "3, LOREM");
        assert!(!edited.contains("w:orient"), "{edited}");
        let (kinds, _) = compared_kinds(&portrait, &edited);
        assert_eq!(kinds, [RevisionKind::Deletion, RevisionKind::Insertion]);

        let (kinds, _) = compared_kinds(&portrait, &page_body(""));
        assert_eq!(kinds, []);
        let (kinds, _) = compared_kinds(&page_body(""), &portrait);
        assert_eq!(kinds, []);

        let (kinds, tracked) = compared_kinds(&portrait, &page_body(r#" w:orient="landscape""#));
        assert_eq!(kinds, [RevisionKind::SectionPropertyChange]);
        assert!(tracked.contains(r#"w:orient="landscape""#), "{tracked}");

        // A bookmark makes the section-break paragraph take the complex path,
        // as Google Docs writes around headings.
        let bookmarked_break = |orientation: &str, heading: &str| {
            wrap_word_body(&format!(
                r#"<w:p><w:pPr><w:sectPr><w:pgSz w:w="12240" w:h="15840"{orientation}/></w:sectPr></w:pPr><w:bookmarkStart w:id="0" w:name="h.1"/><w:r><w:t>{heading}</w:t></w:r><w:bookmarkEnd w:id="0"/></w:p><w:p><w:r><w:t>Second section.</w:t></w:r></w:p><w:sectPr><w:pgSz w:w="12240" w:h="15840"/></w:sectPr>"#
            ))
        };
        let portrait = r#" w:orient="portrait""#;
        for (original, edited) in [(portrait, ""), ("", portrait)] {
            let (kinds, _) = compared_kinds(
                &bookmarked_break(original, "Heading"),
                &bookmarked_break(edited, "Heading"),
            );
            assert_eq!(kinds, [], "{original:?} -> {edited:?}");
            let (kinds, _) = compared_kinds(
                &bookmarked_break(original, "Heading"),
                &bookmarked_break(edited, "Title"),
            );
            assert_eq!(
                kinds,
                [RevisionKind::Deletion, RevisionKind::Insertion],
                "{original:?} -> {edited:?}"
            );
        }
    }

    fn document_with_footer(footer_paragraph: &str) -> Document {
        let mut seed = Document::new();
        let mut package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap()))
                .unwrap();
        package.set_part(
            "/word/footer1.xml",
            format!(r#"<w:ftr xmlns:w="{W_NS}">{footer_paragraph}</w:ftr>"#).into_bytes(),
        );
        package.content_types.add_override(
            "/word/footer1.xml",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml",
        );
        let footer_id = package
            .get_or_create_part_rels("/word/document.xml")
            .add(oxml_opc::relationship::rel_types::FOOTER, "footer1.xml");
        package.set_part(
            "/word/document.xml",
            format!(
                r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="{W_NS}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body><w:p><w:r><w:t>Lorem ipsum dolor sit amet.</w:t></w:r></w:p><w:sectPr><w:footerReference w:type="default" r:id="{footer_id}"/><w:pgSz w:w="12240" w:h="15840"/></w:sectPr></w:body></w:document>"#
            )
            .into_bytes(),
        );
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        Document::from_bytes(bytes.get_ref()).unwrap()
    }

    fn page_field(packed: bool, cached: bool) -> String {
        let parts = [
            r#"<w:fldChar w:fldCharType="begin"/>"#,
            r#"<w:instrText xml:space="preserve"> PAGE </w:instrText>"#,
            r#"<w:fldChar w:fldCharType="separate"/>"#,
            if cached { "<w:t>1</w:t>" } else { "" },
            r#"<w:fldChar w:fldCharType="end"/>"#,
        ];
        let field = if packed {
            format!("<w:r>{}</w:r>", parts.concat())
        } else {
            parts
                .iter()
                .filter(|part| !part.is_empty())
                .map(|part| format!("<w:r>{part}</w:r>"))
                .collect()
        };
        format!(r#"<w:p><w:r><w:t xml:space="preserve">Page </w:t></w:r>{field}</w:p>"#)
    }

    /// Compare an explicit stored cache edit in both complex wire forms.
    fn refreshed_field_comparison(packed: bool, cached: bool) -> String {
        let source = document_with_footer(&page_field(packed, cached))
            .to_bytes()
            .unwrap();
        let paragraph = page_field(packed, cached);
        let edited = if cached {
            paragraph.replace("<w:t>1</w:t>", "<w:t>2</w:t>")
        } else if packed {
            paragraph.replace(
                r#"<w:fldChar w:fldCharType="separate"/>"#,
                r#"<w:fldChar w:fldCharType="separate"/><w:t>2</w:t>"#,
            )
        } else {
            paragraph.replace(
                r#"<w:fldChar w:fldCharType="separate"/></w:r>"#,
                r#"<w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>2</w:t></w:r>"#,
            )
        };
        let refreshed = document_with_footer(&edited);
        let mut compared = Document::from_bytes(&source).unwrap();
        let diagnostics = compared
            .compare(&refreshed, "R", TIMESTAMP)
            .unwrap_or_else(|error| panic!("packed={packed} cached={cached}: {error}"));
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        assert_resolutions(
            &compared.to_bytes().unwrap(),
            &Document::from_bytes(&source).unwrap(),
            &refreshed,
            &ComparisonOptions::default(),
        );
        comparison_part_xml(&mut compared, "/word/footer1.xml")
    }

    #[test]
    fn a_packed_field_compares_like_the_same_field_split_into_runs() {
        let separate = r#"<w:fldChar w:fldCharType="separate"/></w:r>"#;
        let result_and_end = |footer: &str| footer[footer.find(separate).unwrap()..].to_owned();
        for (cached, deleted) in [(true, "<w:r><w:delText>1</w:delText></w:r>"), (false, "")] {
            let split = refreshed_field_comparison(false, cached);
            let packed = refreshed_field_comparison(true, cached);
            assert_eq!(
                result_and_end(&split),
                format!(
                    r#"{separate}<w:del w:id="0" w:author="R" w:date="{TIMESTAMP}">{deleted}</w:del><w:ins w:id="1" w:author="R" w:date="{TIMESTAMP}"><w:r><w:t>2</w:t></w:r></w:ins><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p></w:ftr>"#
                ),
                "cached={cached}"
            );
            assert_eq!(
                result_and_end(&packed),
                result_and_end(&split),
                "cached={cached}"
            );
            assert!(
                packed.contains(r#"<w:r><w:fldChar w:fldCharType="begin"/><w:instrText xml:space="preserve"> PAGE </w:instrText><w:fldChar w:fldCharType="separate"/></w:r>"#),
                "{packed}"
            );
        }
    }

    const MARKUP_COMPATIBILITY: &str =
        "http://schemas.openxmlformats.org/markup-compatibility/2006";
    const RELATIONSHIPS: &str =
        "http://schemas.openxmlformats.org/officeDocument/2006/relationships";
    const WORD_2010: &str = "http://schemas.microsoft.com/office/word/2010/wordml";
    const WORD_2012: &str = "http://schemas.microsoft.com/office/word/2012/wordml";

    fn document_with_comments_part(comments: &str) -> Document {
        let mut seed = Document::new();
        let mut package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap()))
                .unwrap();
        package.set_part("/word/comments.xml", comments.as_bytes().to_vec());
        package.content_types.add_override(
            "/word/comments.xml",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml",
        );
        package
            .get_or_create_part_rels("/word/document.xml")
            .add(oxml_opc::relationship::rel_types::COMMENTS, "comments.xml");
        package.set_part(
            "/word/document.xml",
            wrap_word_body("<w:p><w:r><w:t>Lorem ipsum.</w:t></w:r></w:p>").into_bytes(),
        );
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        Document::from_bytes(bytes.get_ref()).unwrap()
    }

    fn with_part(mut document: Document, part_name: &str, xml: &str) -> Document {
        let mut package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
                .unwrap();
        package.set_part(part_name, xml.as_bytes().to_vec());
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        Document::from_bytes(bytes.get_ref()).unwrap()
    }

    /// A comments, notes or header part written again by another producer,
    /// rdocx included, keeps its content: the declaration, namespace
    /// declarations, attribute order and empty-element form are not.
    #[test]
    fn a_reserialized_story_shell_is_not_a_change() {
        // #160 section 3: the empty comments part of a Google Docs export,
        // and the same part as a no-op save used to write it.
        let google_docs = format!(
            r#"<?xml version='1.0' encoding='UTF-8' standalone='yes'?>
<w:comments xmlns:mc="{MARKUP_COMPATIBILITY}" xmlns:r="{RELATIONSHIPS}" xmlns:w="{W_NS}" xmlns:w14="{WORD_2010}" xmlns:w15="{WORD_2012}" mc:Ignorable="w14 w15"/>"#
        );
        let rewritten = format!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:comments xmlns:w="{W_NS}" xmlns:r="{RELATIONSHIPS}" xmlns:mc="{MARKUP_COMPATIBILITY}" xmlns:w15="{WORD_2012}" mc:Ignorable="w14 w15"></w:comments>"#
        );
        let mut saved = document_with_comments_part(&google_docs);
        let saved = Document::from_bytes(&saved.to_bytes().unwrap()).unwrap();
        for edited in [saved, document_with_comments_part(&rewritten)] {
            let mut compared = document_with_comments_part(&google_docs);
            let diagnostics = compared.compare(&edited, "R", TIMESTAMP).unwrap();
            assert!(diagnostics.is_empty(), "{diagnostics:?}");
            assert_eq!(revision_kinds(&compared), []);
        }

        // The owner start tags in Word's order and in rdocx's, next to a
        // separator note and a header root written again.
        let comments = |attributes: &str, text: &str| {
            format!(
                r#"<w:comments xmlns:w="{W_NS}"><w:comment {attributes}><w:p><w:r><w:t>{text} comment</w:t></w:r></w:p></w:comment></w:comments>"#
            )
        };
        let rdocx_order =
            r#"w:author="Ada" w:date="2026-09-04T09:00:00Z" w:initials="AL" w:id="0""#;
        let footnotes = format!(
            r#"<w:footnotes xmlns:w="{W_NS}"><w:footnote w:id="-1" w:type="separator"><w:p xmlns:w="{W_NS}"><w:r><w:separator /></w:r></w:p></w:footnote><w:footnote w:id="0" w:type="continuationSeparator"><w:p><w:r><w:continuationSeparator/></w:r></w:p></w:footnote><w:footnote w:id="1"><w:p><w:r><w:footnoteRef/><w:t xml:space="preserve"> same footnote</w:t></w:r></w:p></w:footnote></w:footnotes>"#
        );
        let header = format!(
            r#"<w:hdr xmlns:r="{RELATIONSHIPS}" xmlns:w="{W_NS}"><w:p><w:r><w:t>edited header</w:t></w:r></w:p></w:hdr>"#
        );
        for text in ["same", "edited"] {
            let original = document_with_comparison_stories("same");
            let mut edited = with_part(
                document_with_comparison_stories("same"),
                "/word/comments.xml",
                &comments(rdocx_order, text),
            );
            edited = with_part(edited, "/word/footnotes.xml", &footnotes);
            edited = with_part(edited, "/word/header1.xml", &header);
            let mut compared = document_with_comparison_stories("same");
            let diagnostics = compared
                .compare(&edited, "R", TIMESTAMP)
                .unwrap_or_else(|error| panic!("{text}: {error}"));
            assert!(diagnostics.is_empty(), "{diagnostics:?}");
            let tracked = compared.to_bytes().unwrap();
            let redline = comparison_part_xml(&mut compared, "/word/comments.xml");
            assert_eq!(
                redline.contains("<w:del ") && redline.contains("<w:ins "),
                text == "edited",
                "{redline}"
            );
            let header = comparison_part_xml(&mut compared, "/word/header1.xml");
            assert!(header.contains("<w:ins "), "{header}");
            for (resolve, expected) in [
                (
                    Document::accept_all as fn(&mut Document) -> rdocx::Result<usize>,
                    &edited,
                ),
                (Document::reject_all, &original),
            ] {
                let mut resolved = Document::from_bytes(&tracked).unwrap();
                resolve(&mut resolved).unwrap();
                let diagnostics = resolved
                    .compare(expected, "postcondition", TIMESTAMP)
                    .unwrap();
                assert!(diagnostics.is_empty(), "{diagnostics:?}");
            }
        }
    }

    /// An unrelated root extension remains outside comment-thread revision.
    #[test]
    fn a_changed_story_shell_still_refuses() {
        let comments = |root_child: &str, date: &str| {
            format!(
                r#"<w:comments xmlns:w="{W_NS}">{root_child}<w:comment w:id="0" w:author="Ada" w:initials="AL" w:date="{date}"><w:p><w:r><w:t>same comment</w:t></w:r></w:p></w:comment></w:comments>"#
            )
        };
        let edited = with_part(
            document_with_comparison_stories("same"),
            "/word/comments.xml",
            &comments(
                r#"<x:extension xmlns:x="urn:producer"/>"#,
                "2026-09-04T09:00:00Z",
            ),
        );
        let mut compared = document_with_comparison_stories("same");
        let error = compared.compare(&edited, "R", TIMESTAMP).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("comments story root shell changed in /word/comments.xml"),
            "{error}"
        );
    }
}

#[test]
fn unmodelled_property_changes_report_a_diagnostic() {
    for (original, edited, expected_location) in [
        (
            r#"<w:p><w:pPr xmlns:x="urn:producer"><w:jc w:val="center"/><x:ext x:val="kept"/></w:pPr><w:r><w:t>same</w:t></w:r></w:p>"#,
            r#"<w:p><w:pPr xmlns:x="urn:producer"><w:jc w:val="center"/><x:ext x:val="edited"/></w:pPr><w:r><w:t>same</w:t></w:r></w:p>"#,
            "body/paragraph[0]",
        ),
        (
            r#"<w:tbl><w:tblPr xmlns:x="urn:producer"><w:tblW w:w="0" w:type="auto"/><x:ext x:val="kept"/></w:tblPr><w:tblGrid><w:gridCol w:w="2000"/></w:tblGrid><w:tr><w:tc><w:p><w:r><w:t>cell</w:t></w:r></w:p></w:tc></w:tr></w:tbl><w:p/>"#,
            r#"<w:tbl><w:tblPr xmlns:x="urn:producer"><w:tblW w:w="0" w:type="auto"/><x:ext x:val="edited"/></w:tblPr><w:tblGrid><w:gridCol w:w="2000"/></w:tblGrid><w:tr><w:tc><w:p><w:r><w:t>cell</w:t></w:r></w:p></w:tc></w:tr></w:tbl><w:p/>"#,
            "body/table[0]",
        ),
    ] {
        let mut compared = document_with_content_controls(&wrap_word_body(original));
        let edited = document_with_content_controls(&wrap_word_body(edited));
        let diagnostics = compared
            .compare(&edited, "Ada", "2026-09-25T09:00:00Z")
            .unwrap();
        assert_eq!(diagnostics.len(), 1, "{expected_location}: {diagnostics:?}");
        assert_eq!(diagnostics[0].location, expected_location);
        assert!(document_xml(&mut compared).contains(r#"x:val="kept""#));
    }
}

#[test]
fn reordered_drawing_paragraphs_accept_without_model_dump() {
    fn picture_document(text_first: bool, reserve_relationship: bool) -> Document {
        let mut document = Document::new();
        if reserve_relationship {
            document.embed_image(b"unused image", "unused.png");
        }
        let picture = document.embed_image(b"same image", "same.png");
        if text_first {
            document.add_paragraph("text paragraph");
        }
        {
            let mut paragraph = document.add_paragraph("");
            paragraph
                .add_run("")
                .add_picture(&picture, Length::pt(12.0), Length::pt(12.0));
        }
        if !text_first {
            document.add_paragraph("text paragraph");
        }
        document
    }

    fn producer_relationship_ids(
        mut document: Document,
        picture_id: &str,
        unused_id: Option<&str>,
    ) -> Document {
        let bytes = document.to_bytes().unwrap();
        let mut package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).unwrap();
        let owner = "/word/document.xml";
        let relationships = package.get_part_rels(owner).unwrap().items.clone();
        let image_id = |payload: &[u8]| {
            relationships
                .iter()
                .find(|relationship| {
                    relationship.rel_type == oxml_opc::relationship::rel_types::IMAGE
                        && package.get_part(&oxml_opc::OpcPackage::resolve_rel_target(
                            owner,
                            &relationship.target,
                        )) == Some(payload)
                })
                .unwrap()
                .id
                .clone()
        };
        let old_picture_id = image_id(b"same image");
        let old_unused_id = unused_id.map(|_| image_id(b"unused image"));
        let document_xml = String::from_utf8(package.get_part(owner).unwrap().to_vec()).unwrap();
        package.set_part(
            owner,
            document_xml
                .replace(
                    &format!(r#"r:embed="{old_picture_id}""#),
                    &format!(r#"r:embed="{picture_id}""#),
                )
                .into_bytes(),
        );
        for relationship in &mut package.get_part_rels_mut(owner).unwrap().items {
            if relationship.id == old_picture_id {
                relationship.id = picture_id.to_owned();
            } else if old_unused_id.as_ref() == Some(&relationship.id) {
                relationship.id = unused_id.unwrap().to_owned();
            }
        }
        let mut output = std::io::Cursor::new(Vec::new());
        package.write_to(&mut output).unwrap();
        Document::from_bytes(output.get_ref()).unwrap()
    }

    let mut original =
        producer_relationship_ids(picture_document(false, false), "producerImage", None);
    let edited = producer_relationship_ids(
        picture_document(true, true),
        "producerEditedImage",
        Some("producerImage"),
    );
    original
        .compare(&edited, "Ada", "2026-09-25T09:00:00Z")
        .expect("relationship-backed drawing paragraphs must compare by semantics");

    let mut accepted = Document::from_bytes(&original.to_bytes().unwrap()).unwrap();
    accepted.accept_all().unwrap();
    assert!(
        accepted
            .compare(&edited, "postcondition", "2026-09-25T09:01:00Z")
            .unwrap()
            .is_empty()
    );
}

#[test]
fn nil_border_tokens_survive_unrelated_document_edits() {
    let xml = wrap_word_body(
        r#"<w:tbl><w:tblPr><w:tblBorders><w:top w:val="nil"/><w:insideH w:val="nil"/></w:tblBorders></w:tblPr><w:tblGrid/><w:tr><w:tc><w:tcPr><w:tcBorders><w:left w:val="nil"/><w:bottom w:val="nil"/></w:tcBorders></w:tcPr><w:p><w:r><w:t>cell</w:t></w:r></w:p></w:tc></w:tr></w:tbl>"#,
    );
    let mut document = document_with_content_controls(&xml);
    document.add_paragraph("unrelated edit");

    let saved = document_xml(&mut document);
    assert_eq!(saved.matches(r#"w:val="nil""#).count(), 4, "{saved}");
    assert!(!saved.contains(r#"w:val="none""#), "{saved}");

    let mut reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let reopened = document_xml(&mut reopened);
    assert_eq!(reopened.matches(r#"w:val="nil""#).count(), 4, "{reopened}");
}

fn zip_entries(package: &[u8]) -> BTreeMap<String, Vec<u8>> {
    use std::io::Read;

    let mut archive = zip::ZipArchive::new(std::io::Cursor::new(package)).unwrap();
    let mut entries = BTreeMap::new();
    for index in 0..archive.len() {
        let mut entry = archive.by_index(index).unwrap();
        let name = entry.name().to_owned();
        let mut bytes = Vec::new();
        entry.read_to_end(&mut bytes).unwrap();
        entries.insert(name, bytes);
    }
    entries
}

#[test]
fn no_op_save_preserves_every_unchanged_part() {
    let mut seed = Document::new();
    seed.add_paragraph("unchanged");
    let seed = seed.to_bytes().unwrap();
    let mut package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed)).unwrap();
    let mut modeled_parts = Vec::new();
    for part in [
        "/word/document.xml",
        "/word/styles.xml",
        "/word/numbering.xml",
        "/docProps/core.xml",
        "/docProps/app.xml",
    ] {
        if let Some(source) = package.get_part(part) {
            let source = String::from_utf8(source.to_vec()).unwrap();
            package.set_part(part, source.replacen("><", ">\n<", 1).into_bytes());
            modeled_parts.push(part.trim_start_matches('/').to_owned());
        }
    }
    assert!(modeled_parts.contains(&"word/document.xml".to_owned()));
    assert!(modeled_parts.contains(&"word/styles.xml".to_owned()));
    let mut source = std::io::Cursor::new(Vec::new());
    package.write_to(&mut source).unwrap();
    let source = source.into_inner();

    let mut document = Document::from_bytes(&source).unwrap();
    let saved = document.to_bytes().unwrap();
    assert_eq!(zip_entries(&saved), zip_entries(&source));

    let mut edited = Document::from_bytes(&source).unwrap();
    edited.add_paragraph("changed");
    let edited = zip_entries(&edited.to_bytes().unwrap());
    let source = zip_entries(&source);
    assert_eq!(
        edited.keys().collect::<Vec<_>>(),
        source.keys().collect::<Vec<_>>()
    );
    let changed = source
        .iter()
        .filter_map(|(name, value)| (edited.get(name) != Some(value)).then_some(name.as_str()))
        .collect::<Vec<_>>();
    assert_eq!(changed, ["word/document.xml"]);
}

/// Part roots written by Word and Google Docs survive a save (#160, section
/// 3). An unchanged comments part keeps its bytes, so a document compares
/// against its own save. A root that a save rewrites keeps `mc:Ignorable`
/// and a declaration for every prefix it lists.
mod producer_part_roots_survive_save {
    use super::*;
    use rdocx::RevisionKind;

    const TIMESTAMP: &str = "2026-09-27T12:00:00Z";
    const COMMENTS: (&str, &str) = (
        "application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml",
        oxml_opc::relationship::rel_types::COMMENTS,
    );
    const HEADER: (&str, &str) = (
        "application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml",
        oxml_opc::relationship::rel_types::HEADER,
    );
    const FOOTER: (&str, &str) = (
        "application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml",
        oxml_opc::relationship::rel_types::FOOTER,
    );
    /// The root declarations of the reproduction in #160, as Word writes them.
    const WORD_ROOT: &str = concat!(
        r#"xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" "#,
        r#"xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" "#,
        r#"xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" "#,
        r#"xmlns:w14="http://schemas.microsoft.com/office/word/2010/wordml" "#,
        r#"xmlns:w15="http://schemas.microsoft.com/office/word/2012/wordml" "#,
        r#"mc:Ignorable="w14 w15""#,
    );
    const DECLARATION: &str = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n";

    /// A document package with the given main part (or rdocx's own), plus
    /// parts related from it as `(relationship id, part, kind, xml)`.
    fn package_with(
        document_xml: Option<&str>,
        parts: &[(&str, &str, (&str, &str), &str)],
    ) -> Vec<u8> {
        let mut seed = Document::new();
        seed.add_paragraph("Lorem ipsum dolor.");
        let mut package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap()))
                .unwrap();
        if let Some(xml) = document_xml {
            package.set_part("/word/document.xml", xml.as_bytes().to_vec());
        }
        for (id, part, (content_type, relationship_type), xml) in parts {
            package.set_part(part, xml.as_bytes().to_vec());
            package.content_types.add_override(part, content_type);
            package
                .get_or_create_part_rels("/word/document.xml")
                .add_with_id(id, relationship_type, part.trim_start_matches("/word/"));
        }
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        bytes.into_inner()
    }

    fn part(package: &[u8], name: &str) -> String {
        let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(package)).unwrap();
        String::from_utf8(package.get_part(name).unwrap().to_vec()).unwrap()
    }

    /// The start tag of the root element of `xml`.
    fn root_tag(xml: &str) -> &str {
        let after_declaration = xml.find("?>").map_or(0, |end| end + 2);
        let start = after_declaration + xml[after_declaration..].find('<').unwrap();
        &xml[start..=start + xml[start..].find('>').unwrap()]
    }

    /// `root` keeps `mc:Ignorable="{ignorable}"` and declares every prefix it lists.
    fn assert_ignorable_declared(root: &str, ignorable: &str) {
        assert!(
            root.contains(&format!(r#"mc:Ignorable="{ignorable}""#)),
            "{root}"
        );
        for prefix in ignorable.split_whitespace() {
            assert!(
                root.contains(&format!("xmlns:{prefix}=")),
                "{prefix}: {root}"
            );
        }
    }

    /// The parts whose bytes differ between two packages with the same parts.
    fn changed_parts(source: &[u8], saved: &[u8]) -> Vec<String> {
        let (source, saved) = (zip_entries(source), zip_entries(saved));
        assert_eq!(
            source.keys().collect::<Vec<_>>(),
            saved.keys().collect::<Vec<_>>()
        );
        source
            .into_iter()
            .filter(|(name, bytes)| saved.get(name) != Some(bytes))
            .map(|(name, _)| name)
            .collect()
    }

    fn revision_kinds(original: &[u8], edited: &[u8]) -> Vec<RevisionKind> {
        let mut compared = Document::from_bytes(original).unwrap();
        compared
            .compare(&Document::from_bytes(edited).unwrap(), "R", TIMESTAMP)
            .unwrap();
        compared
            .revisions()
            .iter()
            .map(|revision| revision.kind())
            .collect()
    }

    fn edited_save(source: &[u8], old: &str, new: &str, expected: usize) -> Vec<u8> {
        let mut document = Document::from_bytes(source).unwrap();
        assert_eq!(document.try_replace_text(old, new).unwrap(), expected);
        document.to_bytes().unwrap()
    }

    /// The reproduction of #160 section 3, with the self-closed root it
    /// reports, the open and close pair of the #158 report fixture, and that
    /// fixture's unused default namespace.
    #[test]
    fn empty_comments_part_keeps_its_bytes_and_compares_against_its_own_save() {
        for comments in [
            format!("{DECLARATION}<w:comments {WORD_ROOT}/>"),
            format!("{DECLARATION}<w:comments {WORD_ROOT}></w:comments>"),
            format!(
                r#"{DECLARATION}<w:comments {WORD_ROOT} xmlns="http://schemas.microsoft.com/office/tasks/2019/documenttasks"></w:comments>"#
            ),
        ] {
            let source = package_with(
                None,
                &[("rId99", "/word/comments.xml", COMMENTS, &comments)],
            );

            let saved = Document::from_bytes(&source).unwrap().to_bytes().unwrap();
            assert_eq!(
                changed_parts(&source, &saved),
                Vec::<String>::new(),
                "{comments}"
            );
            assert_eq!(revision_kinds(&source, &saved), []);

            let edited = edited_save(&source, "Lorem", "LOREM", 1);
            assert_eq!(part(&edited, "/word/comments.xml"), comments);
            assert_eq!(
                revision_kinds(&source, &edited),
                [RevisionKind::Deletion, RevisionKind::Insertion]
            );
        }
    }

    /// A Word document with one comment. Word writes `w:id` first on the
    /// comment and `w14:paraId` on its paragraph, and rdocx writes neither
    /// that way.
    fn word_comment_package() -> (Vec<u8>, String) {
        let document = format!(
            concat!(
                "{}<w:document {}><w:body><w:p w14:paraId=\"1A2B3C4D\" w14:textId=\"77777777\">",
                "<w:commentRangeStart w:id=\"0\"/><w:r><w:t>Lorem</w:t></w:r>",
                "<w:commentRangeEnd w:id=\"0\"/><w:r><w:commentReference w:id=\"0\"/></w:r>",
                "<w:r><w:t xml:space=\"preserve\"> ipsum dolor.</w:t></w:r></w:p>",
                "<w:sectPr/></w:body></w:document>",
            ),
            DECLARATION, WORD_ROOT
        );
        let comments = format!(
            concat!(
                "{}<w:comments {}><w:comment w:id=\"0\" w:author=\"Ada\" ",
                "w:date=\"2026-09-27T10:00:00Z\" w:initials=\"AL\">",
                "<w:p w14:paraId=\"5E6F7A8B\" w14:textId=\"77777777\"><w:r><w:t>Check this.</w:t></w:r></w:p>",
                "</w:comment></w:comments>",
            ),
            DECLARATION, WORD_ROOT
        );
        let source = package_with(
            Some(&document),
            &[("rId99", "/word/comments.xml", COMMENTS, &comments)],
        );
        (source, comments)
    }

    /// A rewrite of the unchanged part made compare refuse any Word file with
    /// comments against its own save.
    #[test]
    fn word_comments_keep_their_bytes_through_a_body_edit() {
        let (source, comments) = word_comment_package();

        let saved = Document::from_bytes(&source).unwrap().to_bytes().unwrap();
        assert_eq!(changed_parts(&source, &saved), Vec::<String>::new());
        assert_eq!(revision_kinds(&source, &saved), []);

        let edited = edited_save(&source, "dolor", "DOLOR", 1);
        assert_eq!(part(&edited, "/word/comments.xml"), comments);
        assert_eq!(
            revision_kinds(&source, &edited),
            [RevisionKind::Deletion, RevisionKind::Insertion]
        );
    }

    /// Removing the last comment leaves no paragraph id, and the rewritten
    /// root used to drop the `w14` declaration that `mc:Ignorable` lists.
    #[test]
    fn rewritten_comments_root_keeps_every_declaration_in_source_order() {
        let (source, comments) = word_comment_package();
        let mut document = Document::from_bytes(&source).unwrap();
        assert!(document.remove_comment(0).unwrap());
        let xml = part(&document.to_bytes().unwrap(), "/word/comments.xml");
        assert!(!xml.contains("w:comment "), "{xml}");
        assert_eq!(root_tag(&xml), root_tag(&comments));
        assert_ignorable_declared(root_tag(&xml), "w14 w15");
    }

    /// The mirror case noted in PR #154: an edited `document.xml` lost
    /// `mc:Ignorable` while its body kept every `w14:paraId`.
    #[test]
    fn edited_main_document_keeps_mc_ignorable_while_its_body_uses_w14() {
        let document = format!(
            concat!(
                "{}<w:document {}><w:body>",
                "<w:p w14:paraId=\"1A2B3C4D\" w14:textId=\"77777777\"><w:r><w:t>Lorem ipsum dolor.</w:t></w:r></w:p>",
                "<w:p w14:paraId=\"2A2B3C4D\" w14:textId=\"77777777\"><w:r><w:t>Second paragraph.</w:t></w:r></w:p>",
                "<w:sectPr/></w:body></w:document>",
            ),
            DECLARATION, WORD_ROOT
        );
        let source = package_with(Some(&document), &[]);

        let edited = edited_save(&source, "Lorem", "LOREM", 1);
        let xml = part(&edited, "/word/document.xml");
        assert_ignorable_declared(root_tag(&xml), "w14 w15");
        assert!(xml.contains(r#"w14:paraId="2A2B3C4D""#), "{xml}");
        assert_eq!(
            revision_kinds(&source, &edited),
            [RevisionKind::Deletion, RevisionKind::Insertion]
        );

        let again = edited_save(&edited, "Second", "SECOND", 1);
        assert_eq!(
            root_tag(&part(&again, "/word/document.xml")),
            root_tag(&xml)
        );
    }

    /// A replacement in a header or footer rewrites its part, and the
    /// rewritten root dropped `mc:Ignorable`.
    #[test]
    fn rewritten_header_and_footer_keep_mc_ignorable_and_its_declarations() {
        let document = format!(
            concat!(
                "{}<w:document {}><w:body><w:p><w:r><w:t>Body</w:t></w:r></w:p>",
                "<w:sectPr><w:headerReference w:type=\"default\" r:id=\"rIdHeader\"/>",
                "<w:footerReference w:type=\"default\" r:id=\"rIdFooter\"/></w:sectPr>",
                "</w:body></w:document>",
            ),
            DECLARATION, WORD_ROOT
        );
        let story = |root: &str, text: &str| {
            format!(
                concat!(
                    "{}<w:{} {}><w:p w14:paraId=\"3A2B3C4D\" w14:textId=\"77777777\">",
                    "<w:r><w:t>{}</w:t></w:r></w:p></w:{}>",
                ),
                DECLARATION, root, WORD_ROOT, text, root
            )
        };
        let source = package_with(
            Some(&document),
            &[
                (
                    "rIdHeader",
                    "/word/header1.xml",
                    HEADER,
                    &story("hdr", "Header margin"),
                ),
                (
                    "rIdFooter",
                    "/word/footer1.xml",
                    FOOTER,
                    &story("ftr", "Footer margin"),
                ),
            ],
        );

        let edited = edited_save(&source, "margin", "MARGIN", 2);
        for name in ["/word/header1.xml", "/word/footer1.xml"] {
            let xml = part(&edited, name);
            assert!(xml.contains("MARGIN"), "{xml}");
            assert_ignorable_declared(root_tag(&xml), "w14 w15");
            assert!(xml.contains(r#"w14:paraId="3A2B3C4D""#), "{xml}");
        }
    }

    #[test]
    fn rewritten_note_parts_keep_mc_ignorable_and_its_declarations() {
        let document = format!(
            concat!(
                "{}<w:document {}><w:body><w:p><w:r><w:t>Body</w:t></w:r>",
                "<w:r><w:footnoteReference w:id=\"1\"/></w:r>",
                "<w:r><w:endnoteReference w:id=\"1\"/></w:r></w:p>",
                "<w:sectPr/></w:body></w:document>",
            ),
            DECLARATION, WORD_ROOT
        );
        let note = |root: &str, item: &str| {
            format!(
                concat!(
                    "{}<w:{} {}><w:{} w:id=\"1\"><w:p w14:paraId=\"3A2B3C4D\" ",
                    "w14:textId=\"77777777\"><w:r><w:t>Note margin</w:t></w:r></w:p>",
                    "</w:{}></w:{}>",
                ),
                DECLARATION, root, WORD_ROOT, item, item, root
            )
        };
        let source = package_with(
            Some(&document),
            &[
                (
                    "rIdFootnote",
                    "/word/footnotes.xml",
                    (
                        "application/vnd.openxmlformats-officedocument.wordprocessingml.footnotes+xml",
                        oxml_opc::relationship::rel_types::FOOTNOTES,
                    ),
                    &note("footnotes", "footnote"),
                ),
                (
                    "rIdEndnote",
                    "/word/endnotes.xml",
                    (
                        "application/vnd.openxmlformats-officedocument.wordprocessingml.endnotes+xml",
                        oxml_opc::relationship::rel_types::ENDNOTES,
                    ),
                    &note("endnotes", "endnote"),
                ),
            ],
        );
        let edited = edited_save(&source, "margin", "MARGIN", 2);
        for name in ["/word/footnotes.xml", "/word/endnotes.xml"] {
            let xml = part(&edited, name);
            assert!(xml.contains("MARGIN"), "{name}: {xml}");
            assert_ignorable_declared(root_tag(&xml), "w14 w15");
            assert!(xml.contains(r#"w14:paraId="3A2B3C4D""#), "{name}: {xml}");
        }
    }
}

mod f265_run_property_regressions {
    use super::*;
    use rdocx::RunFontSlot;

    const WORD_NS_TEXT: &str = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";

    fn producer_run_document(run_properties: &str) -> Document {
        let mut seed = Document::new();
        let mut package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap()))
                .unwrap();
        package.set_part(
            "/word/document.xml",
            format!(
                concat!(
                    r#"<w:document xmlns:w="{}">"#,
                    r#"<w:body><w:p><w:r><w:rPr>{}</w:rPr><w:t>slots</w:t></w:r></w:p>"#,
                    r#"<w:sectPr/></w:body></w:document>"#,
                ),
                WORD_NS_TEXT, run_properties
            )
            .into_bytes(),
        );
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        Document::from_bytes(bytes.get_ref()).unwrap()
    }

    fn run_properties_xml(document: &mut Document) -> String {
        let bytes = document.to_bytes().unwrap();
        let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).unwrap();
        let xml =
            String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
        let start = xml.find("<w:rFonts").unwrap();
        let end = xml[start..].find("/>").unwrap() + start + 2;
        xml[start..end].to_owned()
    }

    /// Before F-265, setting an explicit font left every theme attribute in
    /// place, so a caller replacing one script slot silently changed nothing
    /// and could clobber the other three.
    #[test]
    fn explicit_font_replacement_clears_only_its_own_theme_slot() {
        let mut document = producer_run_document(concat!(
            r#"<w:rFonts w:hint="eastAsia" w:ascii="Arial" w:hAnsi="Arial""#,
            r#" w:eastAsia="MS Mincho" w:cs="Arial" w:asciiTheme="minorHAnsi""#,
            r#" w:hAnsiTheme="minorHAnsi" w:eastAsiaTheme="minorEastAsia""#,
            r#" w:cstheme="minorBidi"/>"#,
        ));
        {
            let mut paragraph = document.paragraph_mut(0).unwrap();
            let mut run = paragraph.run_mut(0).unwrap();
            run.set_slot_font(RunFontSlot::Ascii, Some("Courier New"));
        }

        let xml = run_properties_xml(&mut document);
        assert!(xml.contains(r#"w:ascii="Courier New""#), "{xml}");
        assert!(!xml.contains("w:asciiTheme"), "{xml}");
        assert!(xml.contains(r#"w:hAnsiTheme="minorHAnsi""#), "{xml}");
        assert!(xml.contains(r#"w:eastAsiaTheme="minorEastAsia""#), "{xml}");
        assert!(xml.contains(r#"w:cstheme="minorBidi""#), "{xml}");
        assert!(xml.contains(r#"w:hint="eastAsia""#), "{xml}");

        // Setting the theme font for a slot clears that slot's explicit name.
        {
            let mut paragraph = document.paragraph_mut(0).unwrap();
            let mut run = paragraph.run_mut(0).unwrap();
            run.set_slot_theme_font(RunFontSlot::EastAsia, Some("majorEastAsia"));
        }
        let xml = run_properties_xml(&mut document);
        assert!(!xml.contains(r#"w:eastAsia="MS Mincho""#), "{xml}");
        assert!(xml.contains(r#"w:eastAsiaTheme="majorEastAsia""#), "{xml}");

        // Clearing a slot clears both attributes for that slot, and only that
        // slot.
        {
            let mut paragraph = document.paragraph_mut(0).unwrap();
            let mut run = paragraph.run_mut(0).unwrap();
            run.set_slot_font(RunFontSlot::EastAsia, None);
        }
        let xml = run_properties_xml(&mut document);
        assert!(!xml.contains("w:eastAsiaTheme"), "{xml}");
        assert!(!xml.contains(r#"w:eastAsia="#), "{xml}");
        assert!(xml.contains(r#"w:hint="eastAsia""#), "{xml}");
        assert!(xml.contains(r#"w:hAnsiTheme="minorHAnsi""#), "{xml}");
    }

    /// `set_font` documents that it writes all four slots, so it now clears
    /// all four theme attributes. Leaving them meant Word resolved the theme
    /// font and the caller's family did nothing.
    #[test]
    fn set_font_clears_every_theme_font_so_the_explicit_family_is_not_ignored() {
        let mut document = producer_run_document(concat!(
            r#"<w:rFonts w:asciiTheme="minorHAnsi" w:hAnsiTheme="minorHAnsi""#,
            r#" w:eastAsiaTheme="minorEastAsia" w:cstheme="minorBidi" w:hint="eastAsia"/>"#,
        ));
        {
            let mut paragraph = document.paragraph_mut(0).unwrap();
            let mut run = paragraph.run_mut(0).unwrap();
            run.set_font("Courier New");
        }

        let xml = run_properties_xml(&mut document);
        assert!(!xml.contains("Theme"), "{xml}");
        assert!(!xml.contains("cstheme"), "{xml}");
        assert!(xml.contains(r#"w:ascii="Courier New""#), "{xml}");
        // `w:hint` is independent, so no font operation clears it.
        assert!(xml.contains(r#"w:hint="eastAsia""#), "{xml}");
    }

    /// Before F-265, `w:themeTint` and `w:themeShade` were dropped on save and
    /// an explicit colour left `w:themeColor` in place, so the authored colour
    /// was ignored by Word.
    #[test]
    fn explicit_colour_replacement_clears_theme_colour_tint_and_shade() {
        let mut document = producer_run_document(
            r#"<w:color w:val="4472C4" w:themeColor="accent1" w:themeTint="66" w:themeShade="BF"/>"#,
        );
        {
            let paragraphs = document.paragraphs();
            let run = paragraphs[0].runs().next().unwrap();
            assert_eq!(run.color_theme(), Some("accent1"));
            assert_eq!(run.color_theme_tint(), Some(0x66));
            assert_eq!(run.color_theme_shade(), Some(0xBF));
        }
        {
            let mut paragraph = document.paragraph_mut(0).unwrap();
            let mut run = paragraph.run_mut(0).unwrap();
            run.set_color("FF0000");
        }
        {
            let paragraphs = document.paragraphs();
            let run = paragraphs[0].runs().next().unwrap();
            assert_eq!(run.color(), Some("FF0000"));
            assert_eq!(run.color_theme(), None);
            assert_eq!(run.color_theme_tint(), None);
            assert_eq!(run.color_theme_shade(), None);
        }

        // `set_color_theme` authors the reference and leaves `w:val` as the
        // literal Word caches beside it.
        {
            let mut paragraph = document.paragraph_mut(0).unwrap();
            let mut run = paragraph.run_mut(0).unwrap();
            run.set_color_theme(Some("accent2"), Some(0x33), None);
        }
        {
            let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
            let paragraphs = reopened.paragraphs();
            let run = paragraphs[0].runs().next().unwrap();
            assert_eq!(run.color(), Some("FF0000"));
            assert_eq!(run.color_theme(), Some("accent2"));
            assert_eq!(run.color_theme_tint(), Some(0x33));
            assert_eq!(run.color_theme_shade(), None);
        }

        // Clearing the reference clears its tint and shade, because Word has
        // nothing to apply them to without one.
        {
            let mut paragraph = document.paragraph_mut(0).unwrap();
            let mut run = paragraph.run_mut(0).unwrap();
            run.set_color_theme(None, Some(0x33), Some(0x44));
        }
        let paragraphs = document.paragraphs();
        let run = paragraphs[0].runs().next().unwrap();
        assert_eq!(run.color_theme(), None);
        assert_eq!(run.color_theme_tint(), None);
        assert_eq!(run.color_theme_shade(), None);
    }

    /// A parsed `w:rFonts` carrying both an explicit and a theme attribute for
    /// one slot is retained exactly until a caller sets that slot. Normalising
    /// it on read would discard producer intent and break the no-op save.
    #[test]
    fn a_producer_font_slot_carrying_both_forms_is_not_normalised_on_read() {
        let mut document =
            producer_run_document(r#"<w:rFonts w:ascii="Courier New" w:asciiTheme="minorHAnsi"/>"#);
        let xml = run_properties_xml(&mut document);
        assert_eq!(
            xml,
            r#"<w:rFonts w:ascii="Courier New" w:asciiTheme="minorHAnsi"/>"#
        );

        let paragraphs = document.paragraphs();
        let run = paragraphs[0].runs().next().unwrap();
        assert_eq!(run.slot_font(RunFontSlot::Ascii), Some("Courier New"));
        assert_eq!(run.slot_theme_font(RunFontSlot::Ascii), Some("minorHAnsi"));
    }

    /// `rdocx_oxml::theme::apply_tint_shade` uses Word's 0-255 convention and
    /// a naive sRGB interpolation, and F-265 gave it its first production
    /// caller. Making it live must not change what it computes, so correcting
    /// it here would move every theme-derived colour in a rendered PDF.
    #[test]
    fn apply_tint_shade_arithmetic_is_unchanged() {
        use rdocx_oxml::theme::apply_tint_shade;

        assert_eq!(apply_tint_shade("FF0000", Some(128), None), "FF8080");
        assert_eq!(apply_tint_shade("FF0000", None, None), "FF0000");
        assert_eq!(apply_tint_shade("FF0000", None, Some(128)), "800000");
        assert_eq!(apply_tint_shade("4472C4", Some(0x66), None), "8EAADB");
        assert_eq!(apply_tint_shade("4472C4", None, Some(0xBF)), "325592");
        // A tint wins over a shade, and a short value is returned unchanged.
        assert_eq!(apply_tint_shade("FF0000", Some(0), Some(255)), "FF0000");
        assert_eq!(apply_tint_shade("FFF", Some(128), None), "FFF");
    }

    /// Word prefers the theme attribute when a producer presents both for one
    /// slot. rdocx prefers the explicit name. This is a pre-declared
    /// deliberate divergence, recorded under rule 5 of
    /// `.claude/skills/differential-testing.md`, and asserting it here stops a
    /// later change dropping the decision silently.
    #[test]
    fn explicit_font_priority_divergence_from_word_is_deliberate() {
        const WORD_WOULD_RESOLVE: &str = "the theme attribute";
        assert!(WORD_WOULD_RESOLVE.contains("theme"));

        let both =
            producer_run_document(r#"<w:rFonts w:ascii="Courier New" w:asciiTheme="minorHAnsi"/>"#)
                .render_page_to_png_deterministic(0, 150.0)
                .unwrap();
        let explicit_only = producer_run_document(r#"<w:rFonts w:ascii="Courier New"/>"#)
            .render_page_to_png_deterministic(0, 150.0)
            .unwrap();
        let theme_only = producer_run_document(r#"<w:rFonts w:asciiTheme="minorHAnsi"/>"#)
            .render_page_to_png_deterministic(0, 150.0)
            .unwrap();

        assert_eq!(
            both, explicit_only,
            "rdocx resolves the explicit family when a producer presents both"
        );
        assert_ne!(
            both, theme_only,
            "the two families must differ for this assertion to mean anything"
        );
    }

    /// `w:lastRenderedPageBreak` is a producer hint. It must stay in
    /// positioned raw capture with a read-only classification, so a no-op save
    /// writes back exactly what was read and no authoring surface can create
    /// one.
    #[test]
    fn last_rendered_page_break_is_read_only_and_keeps_its_source_position() {
        let mut seed = Document::new();
        let mut package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap()))
                .unwrap();
        package.set_part(
            "/word/document.xml",
            format!(
                concat!(
                    r#"<w:document xmlns:w="{}">"#,
                    r#"<w:body><w:p><w:r><w:t>a</w:t><w:lastRenderedPageBreak/>"#,
                    r#"<w:t>b</w:t></w:r></w:p><w:sectPr/></w:body></w:document>"#,
                ),
                WORD_NS_TEXT
            )
            .into_bytes(),
        );
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        let mut document = Document::from_bytes(bytes.get_ref()).unwrap();

        {
            let paragraphs = document.paragraphs();
            let run = paragraphs[0].runs().next().unwrap();
            let items = run.items().collect::<Vec<_>>();
            assert!(matches!(items[0], RunItemRef::Text("a")));
            assert!(
                matches!(items[1], RunItemRef::LastRenderedPageBreak(raw) if raw
                    .windows(21)
                    .any(|window| window == b"lastRenderedPageBreak")),
                "{:?}",
                items[1]
            );
            assert!(matches!(items[2], RunItemRef::Text("b")));
        }

        let saved = document.to_bytes().unwrap();
        let saved_xml = {
            let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(saved)).unwrap();
            String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap()
        };
        assert!(
            saved_xml.find("<w:t>a</w:t>").unwrap()
                < saved_xml.find("<w:lastRenderedPageBreak/>").unwrap(),
            "{saved_xml}"
        );
        assert!(
            saved_xml.find("<w:lastRenderedPageBreak/>").unwrap()
                < saved_xml.find("<w:t>b</w:t>").unwrap(),
            "{saved_xml}"
        );
    }
}

/// F-269, section page semantics.
///
/// The defect this story closes is authored columns that never reached
/// pagination, and the two guards around it are the untouched one-column path
/// and the round-trip-only section children.
mod f269_section_page_semantics {
    use super::*;
    use rdocx_oxml::document::CT_PaperSource;

    /// Positioned elements of every page, as a comparable record.
    fn page_records(document: &Document) -> Vec<String> {
        document
            .layout_deterministic()
            .unwrap()
            .layout
            .pages
            .iter()
            .map(|page| format!("{}x{} {:?}", page.width, page.height, page.elements))
            .collect()
    }

    /// Left edge of every shaped run on a page, in document order.
    fn glyph_origins(page: &oxml_layout::PageFrame) -> Vec<f64> {
        let mut origins = Vec::new();
        oxml_layout::walk(&page.elements, &mut |element, _| {
            if let oxml_layout::PositionedElement::Text(run) = element
                && !run.text.trim().is_empty()
            {
                origins.push(run.origin.x);
            }
        });
        origins
    }

    fn filled_document(paragraphs: usize) -> Document {
        let mut document = Document::new();
        for index in 0..paragraphs {
            document.add_paragraph(&format!("Line {index:02}"));
        }
        document
    }

    #[test]
    fn authored_columns_no_longer_lay_out_as_a_single_full_width_column() {
        // `Section::set_columns` wrote valid `w:cols` that `sect_pr_to_geometry`
        // never read, so every section laid out at the full text measure
        // whatever it authored. This locks the authored value to the page.
        let mut document = filled_document(80);
        document
            .section_mut(0)
            .expect("final section")
            .set_columns(2, Length::twips(720))
            .unwrap();
        let laid_out = document.layout_deterministic().unwrap();
        let origins = glyph_origins(&laid_out.layout.pages[0]);

        // Two equal tracks across 468 points of text measure, separated by 36
        // points, put the second track's left edge at 72 + 216 + 36.
        let track_one = 324.0;
        assert!(
            origins.iter().any(|x| (x - 72.0).abs() < 0.01),
            "{origins:?}"
        );
        assert!(
            origins.iter().any(|x| (x - track_one).abs() < 0.01),
            "track one received no text: {origins:?}"
        );

        // Two columns hold twice the lines, so the same body needs fewer pages
        // than the single-column layout it used to produce.
        let single = filled_document(80);
        let single = single.layout_deterministic().unwrap();
        assert!(
            laid_out.layout.pages.len() < single.layout.pages.len(),
            "{} column pages against {} single-column pages",
            laid_out.layout.pages.len(),
            single.layout.pages.len()
        );
    }

    #[test]
    fn a_single_column_section_keeps_its_exact_content_width() {
        // The column resolver must bypass the track arithmetic at one column
        // rather than evaluate a neutral form of it. A reassociated f64 here
        // moves every recorded PNG and PDF in the hash harness with no visible
        // change, so the guard compares the placed elements bit for bit.
        let plain = filled_document(40);
        let expected = page_records(&plain);

        let mut authored = filled_document(40);
        authored
            .section_mut(0)
            .expect("final section")
            .set_columns(1, Length::twips(720))
            .unwrap();
        assert_eq!(page_records(&authored), expected);

        // An explicit single track takes the same bypass.
        let mut single_track = filled_document(40);
        single_track
            .section_mut(0)
            .expect("final section")
            .set_column_widths(&[(Length::twips(9360), Length::twips(0))])
            .unwrap();
        assert_eq!(page_records(&single_track), expected);

        // Two columns do move, so the comparisons above are not vacuous.
        let mut two = filled_document(40);
        two.section_mut(0)
            .expect("final section")
            .set_columns(2, Length::twips(720))
            .unwrap();
        assert_ne!(page_records(&two), expected);
    }

    #[test]
    fn each_paragraph_breaks_to_the_measure_of_the_section_it_ends_in() {
        // A paragraph `w:sectPr` ends its section, so its geometry governs the
        // paragraphs before it. Line breaking used the previous section's
        // measure instead, and the final section's for the first section, so
        // the 2 inch section broke at 5 inches and ran off its page.
        use rdocx::SectionBreak;
        let text = "The old bridge was repainted in three weeks while it stayed open to \
                    traffic, and the new deck was poured in the spring before the river \
                    rose again, so the crossing reopened on time and under budget.";
        let mut document = Document::new();
        for section in 1..=3 {
            for paragraph in 1..=2 {
                let owned = document.add_paragraph(&format!("S{section}P{paragraph}. {text}"));
                if paragraph == 2 && section < 3 {
                    owned.section_break(SectionBreak::NextPage);
                }
            }
        }
        let measures = [144.0, 252.0, 360.0];
        for (index, measure) in measures.into_iter().enumerate() {
            let mut section = document.section_mut(index).expect("section");
            section
                .set_page_size(Length::pt(measure + 144.0), Length::inches(11.0))
                .unwrap();
            let inch = Length::inches(1.0);
            section.set_margins(inch, inch, inch, inch).unwrap();
        }

        let laid_out = document.layout_deterministic().unwrap();
        assert_eq!(laid_out.layout.pages.len(), 3);
        for (page, measure) in laid_out.layout.pages.iter().zip(measures) {
            // The rightmost glyph edge of any line, from the one inch margin.
            let mut widest = 0.0_f64;
            oxml_layout::walk(&page.elements, &mut |element, _| {
                if let oxml_layout::PositionedElement::Text(run) = element
                    && !run.text.trim().is_empty()
                {
                    widest = widest.max(run.origin.x + run.advances.iter().sum::<f64>() - 72.0);
                }
            });
            assert!(
                widest <= measure + 0.5 && widest >= measure - 40.0,
                "page {}x{} broke its lines to {widest}pt, not its {measure}pt measure",
                page.width,
                page.height
            );
        }
    }

    #[test]
    fn paper_source_and_book_fold_settings_do_not_change_page_geometry() {
        // Tray selection and book fold are print-time choices. Word leaves the
        // document's page count and page geometry alone for both, and so does
        // this workspace.
        let plain = filled_document(60);
        let expected = page_records(&plain);
        let expected_pages = plain.layout_deterministic().unwrap().layout.pages.len();

        let mut configured = filled_document(60);
        configured
            .section_mut(0)
            .expect("final section")
            .set_paper_source(Some(15), Some(7));
        configured.set_book_fold_printing(true).unwrap();
        configured.set_book_fold_printing_sheets(4).unwrap();
        configured.set_book_fold_rev_printing(true).unwrap();

        assert_eq!(page_records(&configured), expected);
        assert_eq!(
            configured
                .layout_deterministic()
                .unwrap()
                .layout
                .pages
                .len(),
            expected_pages
        );

        // The values survive the save that the geometry ignored.
        let reopened = Document::from_bytes(&configured.to_bytes().unwrap()).unwrap();
        assert_eq!(
            reopened.sections().next().unwrap().paper_source(),
            Some((Some(15), Some(7)))
        );
        assert_eq!(reopened.book_fold_printing(), Some(true));
        assert_eq!(reopened.book_fold_printing_sheets(), Some(4));
        assert_eq!(reopened.book_fold_rev_printing(), Some(true));
        assert_eq!(page_records(&reopened), expected);

        // A tray authored through the oxml type reaches the same place.
        let mut direct = filled_document(60);
        direct
            .section_mut(0)
            .expect("final section")
            .properties_mut()
            .paper_source = Some(Box::new(CT_PaperSource {
            first: Some(1),
            other: Some(1),
            extra_attributes: Vec::new(),
        }));
        assert_eq!(page_records(&direct), expected);
    }
}

/// F-267. Table style and conditional formatting precedence.
///
/// Each test is named as the failure it prevents, so a reintroduced
/// precedence inversion is obvious from the test name rather than the diff.
mod f267_table_style_regressions {
    use super::*;
    use rdocx::table::TableLook;
    use rdocx::{StyleBuilder, TableStyleRegion};
    use rdocx_oxml::properties::CT_Shd;
    use rdocx_oxml::table::CT_TcPr;

    /// A cell shading region, as a builder argument.
    fn shaded(fill: &str) -> Option<CT_TcPr> {
        Some(CT_TcPr {
            shading: Some(CT_Shd {
                val: "clear".to_owned(),
                color: Some("auto".to_owned()),
                fill: Some(fill.to_owned()),
                ..CT_Shd::default()
            }),
            ..CT_TcPr::default()
        })
    }

    /// A conditional region carrying only cell shading.
    fn shaded_region(region: TableStyleRegion, fill: &str) -> (TableStyleRegion, Option<CT_TcPr>) {
        (region, shaded(fill))
    }

    /// The conditional region selection every test in this module starts from.
    fn plain_look() -> TableLook {
        TableLook {
            first_row: false,
            last_row: false,
            first_column: false,
            last_column: false,
            horizontal_banding: true,
            vertical_banding: true,
        }
    }

    /// Build a document holding one styled table of `rows` by `columns`.
    fn styled_table_document(
        styles: Vec<StyleBuilder>,
        style_id: &str,
        rows: usize,
        columns: usize,
        look: TableLook,
    ) -> Document {
        let mut document = Document::new();
        for style in styles {
            document.add_style(style).expect("table style is valid");
        }
        let mut table = document.add_table(rows, columns);
        table.set_style(style_id);
        table.set_look(look);
        for row in 0..rows {
            for column in 0..columns {
                let mut row_handle = table.row(row).expect("authored row");
                let mut cell = row_handle.cell(column).expect("authored cell");
                cell.set_text("x");
            }
        }
        document
    }

    /// The resolved cell fills of page one, ordered by row then column.
    ///
    /// Cell shading reaches the page as a filled rectangle, which is the only
    /// place the resolved region is observable from outside the layout crate.
    fn resolved_cell_fills(document: &Document) -> Vec<(i64, i64, String)> {
        let layout = document
            .layout_with_fonts_and_bundled_fallback(&[])
            .expect("deterministic styled-table layout");
        let page = &layout.layout.pages[0];
        let mut fills = compatibility_page_elements(&page.elements)
            .into_iter()
            .filter_map(|element| match element {
                oxml_layout::PositionedElement::FilledRect { rect, color } => Some((
                    (rect.y * 100.0).round() as i64,
                    (rect.x * 100.0).round() as i64,
                    format!(
                        "{:02X}{:02X}{:02X}",
                        (color.r * 255.0).round() as u8,
                        (color.g * 255.0).round() as u8,
                        (color.b * 255.0).round() as u8
                    ),
                )),
                _ => None,
            })
            .collect::<Vec<_>>();
        fills.sort();
        fills
    }

    /// The fills alone, in row then column order.
    fn fill_sequence(document: &Document) -> Vec<String> {
        resolved_cell_fills(document)
            .into_iter()
            .map(|(_, _, fill)| fill)
            .collect()
    }

    fn banded_style(regions: &[(TableStyleRegion, Option<CT_TcPr>)]) -> StyleBuilder {
        let mut builder = StyleBuilder::table("Banded", "Banded");
        for (region, cell_properties) in regions {
            builder = builder.conditional_table_style(
                *region,
                None,
                None,
                None,
                None,
                cell_properties.clone(),
            );
        }
        builder
    }

    #[test]
    fn a_vertical_band_no_longer_overrides_the_horizontal_band_it_should_lose_to() {
        // Both bands select the single cell. Word gives the horizontal band
        // the higher priority, so the vertical band must lose.
        let document = styled_table_document(
            vec![banded_style(&[
                shaded_region(TableStyleRegion::Band1Vert, "AA1111"),
                shaded_region(TableStyleRegion::Band1Horz, "22BB22"),
            ])],
            "Banded",
            1,
            1,
            plain_look(),
        );
        assert_eq!(fill_sequence(&document), vec!["22BB22".to_owned()]);

        // The source order of the two regions must not change the answer.
        let reversed = styled_table_document(
            vec![banded_style(&[
                shaded_region(TableStyleRegion::Band1Horz, "22BB22"),
                shaded_region(TableStyleRegion::Band1Vert, "AA1111"),
            ])],
            "Banded",
            1,
            1,
            plain_look(),
        );
        assert_eq!(fill_sequence(&reversed), vec!["22BB22".to_owned()]);
    }

    #[test]
    fn a_derived_whole_table_region_no_longer_beats_a_base_style_first_row() {
        // The chain flattens per region before region precedence applies, so
        // the base style's higher-priority region still wins.
        let base = StyleBuilder::table("ChainBase", "Chain Base").conditional_table_style(
            TableStyleRegion::FirstRow,
            None,
            None,
            None,
            None,
            shaded("112233"),
        );
        let derived = StyleBuilder::table("ChainDerived", "Chain Derived")
            .based_on("ChainBase")
            .conditional_table_style(
                TableStyleRegion::WholeTable,
                None,
                None,
                None,
                None,
                shaded("445566"),
            );
        let look = TableLook {
            first_row: true,
            ..plain_look()
        };
        let document = styled_table_document(vec![base, derived], "ChainDerived", 2, 1, look);
        assert_eq!(
            fill_sequence(&document),
            vec!["112233".to_owned(), "445566".to_owned()]
        );
    }

    #[test]
    fn banding_no_longer_ignores_band_size_and_the_header_row_offset() {
        // Two rows per band, counted after the header row. The header row is
        // in no band at all.
        let style = banded_style(&[
            shaded_region(TableStyleRegion::FirstRow, "303030"),
            shaded_region(TableStyleRegion::Band1Horz, "101010"),
            shaded_region(TableStyleRegion::Band2Horz, "202020"),
        ]);
        let look = TableLook {
            first_row: true,
            ..plain_look()
        };
        let mut document = styled_table_document(vec![style], "Banded", 5, 1, look);
        document
            .table_mut(0)
            .expect("authored table")
            .set_row_band_size(2)
            .expect("two rows per band");
        eprintln!(
            "PROBE band size = {:?}",
            document.table(0).unwrap().row_band_size()
        );

        assert_eq!(
            fill_sequence(&document),
            vec![
                "303030".to_owned(),
                "101010".to_owned(),
                "101010".to_owned(),
                "202020".to_owned(),
                "202020".to_owned(),
            ]
        );

        // Column banding counts the same way against the first column.
        let column_style = banded_style(&[
            shaded_region(TableStyleRegion::FirstCol, "303030"),
            shaded_region(TableStyleRegion::Band1Vert, "101010"),
            shaded_region(TableStyleRegion::Band2Vert, "202020"),
        ]);
        let look = TableLook {
            first_column: true,
            ..plain_look()
        };
        let mut columns = styled_table_document(vec![column_style], "Banded", 1, 5, look);
        columns
            .table_mut(0)
            .expect("authored table")
            .set_column_band_size(2)
            .expect("two columns per band");
        assert_eq!(
            fill_sequence(&columns),
            vec![
                "303030".to_owned(),
                "101010".to_owned(),
                "101010".to_owned(),
                "202020".to_owned(),
                "202020".to_owned(),
            ]
        );
    }

    #[test]
    fn an_unrecognised_conditional_region_no_longer_risks_refusing_the_file() {
        let mut document = Document::new();
        document
            .add_style(StyleBuilder::table("Mystery", "Mystery"))
            .expect("table style is valid");
        let mut table = document.add_table(1, 1);
        table.set_style("Mystery");
        table.set_look(plain_look());
        table.row(0).unwrap().cell(0).unwrap().set_text("x");
        let mystery = concat!(
            r#"<w:tblStylePr w:type="mysteryRegion" x:note="kept" xmlns:x="urn:producer">"#,
            r#"<w:tcPr><w:shd w:val="clear" w:fill="FF00FF"/></w:tcPr>"#,
            r#"<x:unmodelled x:value="kept"/>"#,
            r#"</w:tblStylePr>"#
        );
        let mut package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
                .expect("authored package opens");
        let styles =
            String::from_utf8(package.get_part("/word/styles.xml").unwrap().to_vec()).unwrap();
        let injected = styles.replace(
            r#"<w:name w:val="Mystery"/>"#,
            &format!(r#"<w:name w:val="Mystery"/>{mystery}"#),
        );
        package.set_part("/word/styles.xml", injected.into_bytes());
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();

        // The file opens rather than being refused.
        let reopened = Document::from_bytes(bytes.get_ref()).expect("unknown region reopens");
        reopened
            .validate_style_graph()
            .expect("an unknown region is not an invalid style graph");
        let style = reopened.style("Mystery").unwrap();
        let regions = style.conditional_table_styles();
        assert_eq!(regions.len(), 1);
        assert_eq!(regions[0].region(), None);

        // It serialises back from its preserved bytes, unmodelled child and
        // foreign attribute included.
        let mut reopened = reopened;
        let saved = reopened.to_bytes().expect("unknown region saves");
        let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(saved)).unwrap();
        let styles =
            String::from_utf8(package.get_part("/word/styles.xml").unwrap().to_vec()).unwrap();
        assert!(styles.contains(mystery), "{styles}");

        // It contributes nothing to resolution.
        assert_eq!(fill_sequence(&reopened), Vec::<String>::new());
    }

    #[test]
    fn a_table_look_change_no_longer_drops_the_legacy_bitmask() {
        let mut document = Document::new();
        document
            .add_style(StyleBuilder::table("Looked", "Looked"))
            .expect("table style is valid");
        let mut table = document.add_table(1, 1);
        table.set_style("Looked");
        table.set_look(TableLook {
            first_row: true,
            last_row: false,
            first_column: true,
            last_column: false,
            horizontal_banding: true,
            vertical_banding: false,
        });
        let saved = document.to_bytes().expect("look saves");
        let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(saved)).unwrap();
        let body =
            String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
        // 0x0020 firstRow, 0x0080 firstColumn, 0x0400 noVBand.
        assert!(
            body.contains(
                r#"<w:tblLook w:val="04A0" w:firstRow="1" w:lastRow="0" w:firstColumn="1" w:lastColumn="0" w:noHBand="0" w:noVBand="1"/>"#
            ),
            "{body}"
        );

        // The mask a reader falls back to agrees with the booleans beside it.
        let reopened = Document::from_bytes(
            &Document::from_bytes(&document.to_bytes().unwrap())
                .unwrap()
                .to_bytes()
                .unwrap(),
        )
        .unwrap();
        let look = reopened.table(0).unwrap().look().expect("look reopens");
        assert!(look.first_row);
        assert!(look.first_column);
        assert!(!look.last_row);
        assert!(!look.last_column);
        assert!(look.horizontal_banding);
        assert!(!look.vertical_banding);

        let mut cleared = reopened;
        cleared.table_mut(0).unwrap().clear_look();
        assert_eq!(cleared.table(0).unwrap().look(), None);
    }

    #[test]
    fn removing_one_conditional_region_leaves_its_siblings() {
        let mut document = Document::new();
        document
            .add_style(banded_style(&[
                shaded_region(TableStyleRegion::FirstRow, "111111"),
                shaded_region(TableStyleRegion::LastRow, "222222"),
                shaded_region(TableStyleRegion::Band1Horz, "333333"),
            ]))
            .expect("table style is valid");
        document
            .set_style(
                StyleBuilder::table("Banded", "Banded")
                    .remove_conditional_table_style(TableStyleRegion::LastRow),
            )
            .expect("one region is removable");
        let style = document.style("Banded").unwrap();
        let surviving = style
            .conditional_table_styles()
            .iter()
            .map(|region| region.region())
            .collect::<Vec<_>>();
        assert_eq!(
            surviving,
            vec![
                Some(TableStyleRegion::FirstRow),
                Some(TableStyleRegion::Band1Horz)
            ]
        );

        // Clearing is still all or nothing, which is what per-region removal
        // is not.
        document
            .set_style(StyleBuilder::table("Banded", "Banded").clear_conditional_table_styles())
            .expect("clearing is still available");
        assert!(
            document
                .style("Banded")
                .unwrap()
                .conditional_table_styles()
                .is_empty()
        );
    }
}

/// F-268a, the layout facts advanced table geometry must keep.
mod advanced_table_geometry_regressions {
    use rdocx_oxml::styles::CT_Styles;
    use rdocx_oxml::table::{
        CT_Row, CT_Tbl, CT_TblGrid, CT_TblGridCol, CT_TblPr, CT_TblWidth, CT_Tc, CT_TcPr, CT_TrPr,
    };
    use rdocx_oxml::units::Twips;

    fn layout_input() -> rdocx_layout::LayoutInput {
        rdocx_layout::LayoutInput {
            sequence_snapshot: None,
            automatic_hyphenation: false,
            clamp_tabs_past_margin: false,
            modern_footnote_layout: false,
            footnote_layout_like_word8: false,
            mirror_margins: false,
            gutter_at_top: false,
            do_not_use_html_paragraph_auto_spacing: false,
            default_tab_stop: None,
            math_properties: None,
            note_defaults: [None, None],
            document: rdocx_oxml::document::CT_Document {
                body: rdocx_oxml::document::CT_Body {
                    content: Vec::new(),
                    sect_pr: None,
                },
                extra_namespaces: Vec::new(),
                background_xml: None,
                background_extra_xml: Vec::new(),
                root_attributes: Vec::new(),
            },
            styles: CT_Styles::new_default(),
            numbering: None,
            story_part_names: Default::default(),
            story_bodies: Default::default(),
            headers: std::collections::HashMap::new(),
            footers: std::collections::HashMap::new(),
            images: std::collections::HashMap::new(),
            charts: std::collections::HashMap::new(),
            chart_theme: oxml_drawing::theme::CT_OfficeStyleSheet::office_default(),
            chart_color_map: oxml_drawing::color::ColorMap::default(),
            core_properties: None,
            hyperlink_urls: std::collections::HashMap::new(),
            footnotes: None,
            endnotes: None,
            theme: None,
            fonts: Vec::new(),
            revision_view: rdocx_layout::RevisionView::Accepted,
        }
    }

    fn lay_out_with(
        table: &CT_Tbl,
        styles: &CT_Styles,
        available_width: f64,
    ) -> rdocx_layout::table::TableBlock {
        let input = layout_input();
        let media = rdocx_layout::MediaRegistry::new(&input.images);
        let mut fonts =
            oxml_layout::FontManager::new_deterministic().expect("deterministic fonts load");
        let mut numbering = rdocx_layout::style_resolver::NumberingState::new();
        let mut diagnostics = Vec::new();
        rdocx_layout::table::layout_table(
            table,
            available_width,
            styles,
            &input,
            &media,
            &mut fonts,
            &mut numbering,
            &mut diagnostics,
            None,
        )
        .expect("table lays out")
    }

    fn lay_out(table: &CT_Tbl, available_width: f64) -> rdocx_layout::table::TableBlock {
        lay_out_with(table, &CT_Styles::new_default(), available_width)
    }

    /// A fixed-layout table whose cells carry one shaded paragraph each.
    fn shaded_table(columns: &[i32], rows: &[&[&str]]) -> CT_Tbl {
        let mut table = CT_Tbl::new();
        table.properties = Some(CT_TblPr {
            layout: Some("fixed".to_owned()),
            width: Some(CT_TblWidth::dxa(columns.iter().sum())),
            ..CT_TblPr::default()
        });
        table.grid = Some(CT_TblGrid {
            columns: columns
                .iter()
                .map(|width| CT_TblGridCol {
                    width: Twips(*width),
                })
                .collect(),
            ..CT_TblGrid::default()
        });
        for cells in rows {
            let mut row = CT_Row::new();
            for text in cells.iter() {
                let mut cell = CT_Tc::new();
                cell.paragraphs_mut()[0].add_run(text);
                cell.properties = Some(CT_TcPr {
                    shading: Some(rdocx_oxml::properties::CT_Shd {
                        val: "clear".to_owned(),
                        color: None,
                        fill: Some("DDDDDD".to_owned()),
                        ..Default::default()
                    }),
                    ..CT_TcPr::default()
                });
                row.cells.push(cell);
            }
            table.rows.push(row);
        }
        table
    }

    /// Every painted cell rectangle on the document's pages, in paint order.
    ///
    /// Cell shading is what marks a painted cell, so a document whose cells
    /// are shaded reports one `(x, width)` pair per cell.
    fn painted_cells(document: &rdocx::Document) -> Vec<(f64, f64)> {
        fn collect(elements: &[oxml_layout::PositionedElement], output: &mut Vec<(f64, f64)>) {
            let round = |value: f64| (value * 100.0).round() / 100.0;
            for element in elements {
                match element {
                    oxml_layout::PositionedElement::FilledRect { rect, .. } => {
                        output.push((round(rect.x), round(rect.width)))
                    }
                    oxml_layout::PositionedElement::Group(group) => {
                        collect(&group.children, output)
                    }
                    oxml_layout::PositionedElement::MarkedContent { children, .. } => {
                        collect(children, output)
                    }
                    _ => {}
                }
            }
        }

        let layout = document
            .layout_deterministic()
            .expect("document lays out in deterministic font mode");
        let mut output = Vec::new();
        for page in &layout.layout.pages {
            collect(&page.elements, &mut output);
        }
        output
    }

    /// A three-column shaded table authored through the public facade.
    fn shaded_document(columns: &[i32], rows: &[&[&str]]) -> rdocx::Document {
        let mut document = rdocx::Document::new();
        {
            let mut table = document.add_table(rows.len(), columns.len());
            table
                .set_grid_widths(
                    &columns
                        .iter()
                        .map(|width| rdocx::Length::twips(*width))
                        .collect::<Vec<_>>(),
                )
                .expect("grid widths are valid");
            table.set_layout(rdocx::table::TableLayout::Fixed);
            for (row_index, texts) in rows.iter().enumerate() {
                let mut row = table.row(row_index).expect("row");
                for (cell_index, text) in texts.iter().enumerate() {
                    if text.is_empty() {
                        // An untouched cell stays discardable for a grid
                        // omission and paints nothing.
                        continue;
                    }
                    let mut cell = row.cell(cell_index).expect("cell");
                    cell.set_text(text);
                    cell.set_shading("DDDDDD");
                }
            }
        }
        document
    }

    #[test]
    fn a_bidi_visual_table_reverses_columns_without_changing_logical_cell_order() {
        let columns = [1440, 2880, 4320];
        let rows: [&[&str]; 1] = [&["first", "second", "third"]];
        let forward = shaded_document(&columns, &rows);
        let mut reversed = shaded_document(&columns, &rows);
        reversed
            .table_mut(0)
            .expect("table")
            .set_bidi_visual(Some(true));

        // The painted cells reverse. A left-to-right row paints the narrow
        // first column at the table origin, and a bidirectional row paints it
        // last, at the table's trailing edge.
        assert_eq!(
            painted_cells(&forward),
            vec![(72.0, 72.0), (144.0, 144.0), (288.0, 216.0)]
        );
        assert_eq!(
            painted_cells(&reversed),
            vec![(72.0, 216.0), (288.0, 144.0), (432.0, 72.0)]
        );

        // Logical cell ownership does not reverse. Every cell keeps its source
        // order, its text, its grid column and its width.
        let logical = |document: &rdocx::Document| {
            let table = document.table(0).expect("table");
            let row = table.row(0).expect("row");
            (0..row.cell_count())
                .map(|index| row.cell(index).expect("cell").text())
                .collect::<Vec<_>>()
        };
        assert_eq!(logical(&forward), logical(&reversed));

        let mut table = shaded_table(&columns, &rows);
        let forward_block = lay_out(&table, 468.0);
        table
            .properties
            .as_mut()
            .expect("table properties")
            .bidi_visual = Some(true);
        let reversed_block = lay_out(&table, 468.0);
        assert!(!forward_block.bidi_visual);
        assert!(reversed_block.bidi_visual);
        let logical_geometry = |block: &rdocx_layout::table::TableBlock| {
            block.rows[0]
                .cells
                .iter()
                .map(|cell| (cell.col_index, (cell.width * 100.0).round() / 100.0))
                .collect::<Vec<_>>()
        };
        assert_eq!(
            logical_geometry(&forward_block),
            logical_geometry(&reversed_block)
        );
        assert_eq!(forward_block.col_widths, reversed_block.col_widths);
        assert_eq!(forward_block.table_width, reversed_block.table_width);
    }

    #[test]
    fn grid_before_and_width_before_offset_the_row_without_moving_the_table() {
        let mut table = shaded_table(
            &[1440, 2880, 4320],
            &[&["a", "b", "c"], &["a", "b", "c"], &["a", "b", "c"]],
        );
        let plain = lay_out(&table, 468.0);

        // The middle row omits its first grid column.
        table.rows[1].cells.remove(0);
        table.rows[1].properties = Some(CT_TrPr {
            grid_before: Some(1),
            ..CT_TrPr::default()
        });
        let omitted = lay_out(&table, 468.0);
        assert_eq!(omitted.table_width, plain.table_width);
        assert_eq!(omitted.rows[0].offset_left, 0.0);
        assert_eq!(omitted.rows[2].offset_left, 0.0);
        assert_eq!(omitted.rows[1].offset_left, 72.0);
        // The remaining cells take the grid columns they actually occupy.
        assert_eq!(
            omitted.rows[1]
                .cells
                .iter()
                .map(|cell| cell.col_index)
                .collect::<Vec<_>>(),
            vec![1, 2]
        );
        assert_eq!(
            omitted.rows[0]
                .cells
                .iter()
                .map(|cell| (cell.col_index, cell.width))
                .collect::<Vec<_>>(),
            plain.rows[0]
                .cells
                .iter()
                .map(|cell| (cell.col_index, cell.width))
                .collect::<Vec<_>>()
        );

        // The same omission through the facade shifts only the painted cells
        // of that one row.
        let columns = [1440, 2880, 4320];
        // The middle row's leading cell is empty, which is what lets it be
        // replaced by a grid omission.
        let rows: [&[&str]; 3] = [&["a", "b", "c"], &["", "b", "c"], &["a", "b", "c"]];
        let mut document = shaded_document(&columns, &rows);
        document
            .table_mut(0)
            .expect("table")
            .set_row_grid_omissions(1, Some(1), None)
            .expect("the leading column is empty and can be omitted");
        assert_eq!(
            painted_cells(&document),
            vec![
                (72.0, 72.0),
                (144.0, 144.0),
                (288.0, 216.0),
                (144.0, 144.0),
                (288.0, 216.0),
                (72.0, 72.0),
                (144.0, 144.0),
                (288.0, 216.0),
            ]
        );

        // An explicit `w:wBefore` replaces the omitted columns' own width.
        table.rows[1]
            .properties
            .as_mut()
            .expect("row properties")
            .width_before = Some(CT_TblWidth::dxa(400));
        let authored = lay_out(&table, 468.0);
        assert_eq!(authored.rows[1].offset_left, 20.0);
        assert_eq!(authored.table_width, plain.table_width);
    }

    #[test]
    fn a_conditional_region_row_height_reaches_layout() {
        let styles = CT_Styles::from_xml(
            format!(
                concat!(
                    r#"<w:styles xmlns:w="{ns}">"#,
                    r#"<w:style w:type="table" w:styleId="Banded">"#,
                    r#"<w:tblStylePr w:type="firstRow"><w:trPr>"#,
                    r#"<w:trHeight w:val="1440" w:hRule="exact"/><w:tblHeader/>"#,
                    r#"</w:trPr></w:tblStylePr></w:style></w:styles>"#
                ),
                ns = rdocx_oxml::namespace::W_NS
            )
            .as_bytes(),
        )
        .expect("conditional table style parses");
        assert!(
            styles
                .get_by_id("Banded")
                .expect("style is present")
                .conditional_table_styles
                .iter()
                .any(|conditional| conditional.row_properties.is_some()),
            "the conditional region carries row properties"
        );

        let mut table = shaded_table(&[2880, 2880], &[&["a", "b"], &["c", "d"]]);
        let properties = table.properties.as_mut().expect("table properties");
        properties.style_id = Some("Banded".to_owned());
        properties.look = Some(rdocx_oxml::table::CT_TblLook {
            first_row: Some(true),
            ..rdocx_oxml::table::CT_TblLook::default()
        });

        let block = lay_out_with(&table, &styles, 468.0);
        assert_eq!(block.rows[0].height, 72.0);
        assert_eq!(block.header_row_indices, vec![0]);
        assert!(block.rows[1].height < 72.0);
    }

    #[test]
    fn an_authored_dxa_table_width_never_enters_the_autofit_path() {
        // `Document::add_table` writes `w:tblW` as `dxa` unconditionally, so
        // every authored table keeps its declared grid whatever the layout
        // mode says.
        let mut document = rdocx::Document::new();
        {
            let mut table = document.add_table(1, 3);
            table.set_layout(rdocx::table::TableLayout::AutoFit);
            for index in 0..3 {
                table
                    .row(0)
                    .expect("row")
                    .cell(index)
                    .expect("cell")
                    .set_text("x");
            }
        }
        let bytes = document.to_bytes().expect("document saves");
        let reopened = rdocx::Document::from_bytes(&bytes).expect("document reopens");
        assert_eq!(
            reopened.table(0).expect("table").width_mode(),
            Some(rdocx::table::TableWidth::Fixed(rdocx::Length::twips(9360)))
        );

        let mut table = shaded_table(&[3120, 3120, 3120], &[&["x", "x", "x"]]);
        table.properties.as_mut().expect("table properties").layout = Some("autofit".to_owned());
        let block = lay_out(&table, 468.0);
        assert_eq!(block.col_widths, vec![156.0, 156.0, 156.0]);
        assert_eq!(block.table_width, 468.0);
    }

    #[test]
    fn a_corpus_shaped_auto_width_table_without_explicit_autofit_keeps_its_grid() {
        // Word writes `<w:tblW w:w="0" w:type="auto"/>` with no `w:tblLayout`
        // for an ordinary table, and 131 of the 141 tables in the Word corpus
        // have exactly that shape. Engagement requires the `w:tblLayout`
        // element, so this shape keeps its declared grid. Admitting it moves
        // the reference page count that
        // `scripts/docx_authoring_conformance.py --private-required` pins.
        let mut table = shaded_table(
            &[1440, 7200],
            &[&["ID", "A considerably longer second column heading"]],
        );
        let properties = table.properties.as_mut().expect("table properties");
        properties.layout = None;
        properties.width = Some(CT_TblWidth::auto());

        let untouched = lay_out(&table, 468.0);
        assert_eq!(untouched.col_widths, vec![72.0, 360.0]);

        // Declaring the layout mode autofit opts the same table in, which is
        // the positive arm of the same predicate.
        table.properties.as_mut().expect("table properties").layout = Some("autofit".to_owned());
        let autofitted = lay_out(&table, 468.0);
        let rounded = autofitted
            .col_widths
            .iter()
            .map(|width| (width * 100.0).round() / 100.0)
            .collect::<Vec<_>>();
        assert_eq!(rounded, vec![20.34, 215.19]);
    }
}

mod f_x132_retained_namespace_owner_regressions {
    use rdocx::Document;
    use rdocx_oxml::namespace::W_NS;

    fn document_from_body(body: &str) -> Document {
        super::document_with_content_controls(&super::wrap_word_body(body))
    }

    fn saved_document_xml(bytes: &[u8]) -> String {
        let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(bytes)).unwrap();
        String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap()
    }

    #[test]
    fn accepting_revisions_still_saves_when_runs_carry_revision_identities() {
        // F-X128 retains a run's producer root attributes, and F-X131 keeps the
        // `w` binding those attributes use. Both are written onto the run, so a
        // re-read of the flushed part sees a `w` declaration that rebinds the
        // prefix to the namespace already in scope. Two runs that agree on
        // every retained fact then look like two equally good owners of that
        // declaration, and the save used to fail closed on an ambiguity that
        // only the redundant declaration created.
        let identical_run =
            r#"<w:r w:rsidRPr="00BB1111"><w:rPr><w:b/></w:rPr><w:t>same</w:t></w:r>"#;
        let body = format!(
            r#"<w:p w:rsidR="00AA0000" w:rsidRDefault="00AA0000"><w:ins w:id="1" w:author="Reviewer" w:date="2026-01-01T00:00:00Z">{identical_run}</w:ins><w:r w:rsidRPr="00CC2222"><w:t>tail</w:t></w:r></w:p><w:p w:rsidR="00AA0000" w:rsidRDefault="00AA0000">{identical_run}</w:p>"#
        );
        let mut document = document_from_body(&body);
        assert_eq!(document.accept_all().unwrap(), 1);

        let saved = document.to_bytes().unwrap();
        let saved_xml = saved_document_xml(&saved);
        assert!(!saved_xml.contains("<w:ins"), "{saved_xml}");
        for identity in [
            r#"w:rsidR="00AA0000""#,
            r#"w:rsidRDefault="00AA0000""#,
            r#"w:rsidRPr="00BB1111""#,
            r#"w:rsidRPr="00CC2222""#,
        ] {
            assert!(saved_xml.contains(identity), "{identity} lost: {saved_xml}");
        }

        let mut reopened = Document::from_bytes(&saved).unwrap();
        assert_eq!(reopened.paragraph(0).unwrap().text(), "sametail");
        assert_eq!(reopened.paragraph(1).unwrap().text(), "same");
        assert_eq!(saved_document_xml(&reopened.to_bytes().unwrap()), saved_xml);
    }

    #[test]
    fn indistinguishable_owners_of_a_rebinding_declaration_still_fail_closed() {
        // The same two runs, each carrying a declaration that genuinely binds a
        // prefix the enclosing scope does not. Nothing tells the two apart, so
        // the matcher must still refuse rather than guess which run owns which
        // declaration.
        let identical_run = r#"<w:r w:rsidRPr="00BB1111" xmlns:x="urn:producer"><x:producer/><w:t>same</w:t></w:r>"#;
        let body = format!(
            r#"<w:p w:rsidR="00AA0000">{identical_run}</w:p><w:p w:rsidR="00AA0000">{identical_run}</w:p>"#
        );
        let mut document = document_from_body(&body);
        document.add_paragraph("changed");

        let error = document.to_bytes().unwrap_err();
        assert!(
            error
                .to_string()
                .contains("cannot identify retained `r` nested namespace owner after mutation"),
            "{error}"
        );
    }

    #[test]
    fn a_semantic_difference_still_routes_each_rebinding_declaration_home() {
        // The positive arm of the same predicate. The two runs agree on their
        // retained identity and differ in their text, and that difference is
        // enough for each rebinding declaration to land back on the run that
        // authored it rather than on the other one.
        let body = r#"<w:p w:rsidR="00AA0000"><w:r w:rsidRPr="00BB1111" xmlns:x="urn:producer"><x:producer/><w:t>alpha</w:t></w:r></w:p><w:p w:rsidR="00AA0000"><w:r w:rsidRPr="00BB1111" xmlns:y="urn:other"><y:producer/><w:t>beta</w:t></w:r></w:p>"#;
        let mut document = document_from_body(body);
        document.add_paragraph("changed");

        let saved_xml = saved_document_xml(&document.to_bytes().unwrap());
        let alpha = saved_xml.find("alpha").unwrap();
        let beta = saved_xml.find("beta").unwrap();
        let alpha_owner = saved_xml[..alpha].rfind("<w:r ").unwrap();
        let beta_owner = saved_xml[..beta].rfind("<w:r ").unwrap();
        assert!(saved_xml[alpha_owner..alpha].contains(r#"xmlns:x="urn:producer""#));
        assert!(!saved_xml[alpha_owner..alpha].contains(r#"xmlns:y="urn:other""#));
        assert!(saved_xml[beta_owner..beta].contains(r#"xmlns:y="urn:other""#));
        assert!(!saved_xml[beta_owner..beta].contains(r#"xmlns:x="urn:producer""#));
    }

    #[test]
    fn a_table_redeclaring_the_binding_it_inherits_keeps_none_of_its_own() {
        // The narrowing the fix accepts, stated as a test rather than left
        // silent. The unmodelled child holds the `w` prefix, which is what
        // made the redeclaration a replayed owner before. It resolves through
        // the root binding either way, so the modified save now writes the
        // document's single `w` declaration and the retained child unchanged.
        let body = format!(
            r#"<w:tbl xmlns:w="{W_NS}"><w:tr><w:tc><w:p/></w:tc></w:tr><w:producerOnly/></w:tbl><w:p/>"#
        );
        let mut document = document_from_body(&body);
        document.add_paragraph("changed");

        let saved_xml = saved_document_xml(&document.to_bytes().unwrap());
        assert!(saved_xml.contains("<w:producerOnly/>"), "{saved_xml}");
        assert_eq!(
            saved_xml.matches(&format!(r#"xmlns:w="{W_NS}""#)).count(),
            1,
            "{saved_xml}"
        );
    }
}

/// Each text-box paragraph is parsed on its own. The retained-attribute capture
/// used to find the prefix of the `w:rsid*` identities Word writes on text-box
/// runs unbound there, which dropped the text box from layout, from replacement
/// and from templates. The anchor reader now parses the paragraph with the
/// bindings in scope, so any bound prefix resolves for layout. Replacement and
/// templates still parse it in a scope that names `w` without binding it.
mod text_box_identity_attribute_regressions {
    use rdocx::Document;
    use rdocx_oxml::namespace::W_NS;

    const IDENTITY: &str = r#" w:rsidR="00A1B2C3" w:rsidRPr="00D4E5F6""#;
    const FOREIGN: &str = r#" x:id="00A1B2C3""#;

    /// A text box as Word saves it, the DrawingML shape in `mc:Choice` and its
    /// VML copy in `mc:Fallback`, or the bare `wp:anchor` alone.
    fn text_box_document(run_attributes: &str, compatibility_block: bool, text: &str) -> Document {
        let content = format!(
            r#"<w:txbxContent><w:p><w:r{run_attributes}><w:t>{text}</w:t></w:r></w:p></w:txbxContent>"#
        );
        let drawing = format!(
            r#"<w:drawing><wp:anchor distT="0" distB="0" distL="0" distR="0" simplePos="0" relativeHeight="1" behindDoc="0" locked="0" layoutInCell="1" allowOverlap="1"><wp:simplePos x="0" y="0"/><wp:positionH relativeFrom="column"><wp:posOffset>0</wp:posOffset></wp:positionH><wp:positionV relativeFrom="paragraph"><wp:posOffset>0</wp:posOffset></wp:positionV><wp:extent cx="2743200" cy="457200"/><wp:wrapTopAndBottom/><wp:docPr id="1" name="Text Box 1"/><a:graphic><a:graphicData uri="http://schemas.microsoft.com/office/word/2010/wordprocessingShape"><wps:wsp><wps:cNvSpPr txBox="1"/><wps:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="2743200" cy="457200"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></wps:spPr><wps:txbx>{content}</wps:txbx><wps:bodyPr/></wps:wsp></a:graphicData></a:graphic></wp:anchor></w:drawing>"#
        );
        let shape = if compatibility_block {
            format!(
                r#"<mc:AlternateContent><mc:Choice Requires="wps">{drawing}</mc:Choice><mc:Fallback><w:pict><v:shape style="position:absolute;width:216pt;height:36pt"><v:textbox>{content}</v:textbox></v:shape></w:pict></mc:Fallback></mc:AlternateContent>"#
            )
        } else {
            drawing
        };
        super::document_with_content_controls(&format!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="{W_NS}" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:wps="http://schemas.microsoft.com/office/word/2010/wordprocessingShape" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:x="urn:producer"><w:body><w:p><w:r><w:t>Host paragraph</w:t></w:r><w:r>{shape}</w:r></w:p></w:body></w:document>"#
        ))
    }

    #[test]
    fn a_text_box_is_laid_out_when_its_runs_carry_identity_attributes() {
        // The bare anchor used to fail the document open, and the
        // compatibility block used to lose its shape and text from layout.
        for compatibility_block in [true, false] {
            let page_text = |run_attributes| {
                let document = text_box_document(run_attributes, compatibility_block, "Boxed");
                super::f252_page_text(&document.layout_page(0).unwrap().unwrap())
            };
            let plain = page_text("");
            assert!(plain.contains("Boxed"), "{plain}");
            for run_attributes in [IDENTITY, FOREIGN] {
                assert_eq!(
                    page_text(run_attributes),
                    plain,
                    "{compatibility_block}{run_attributes}"
                );
            }
        }
    }

    #[test]
    fn replacing_text_reaches_a_text_box_whose_runs_carry_identity_attributes() {
        let replace = |run_attributes| {
            let mut document = text_box_document(run_attributes, true, "Boxed text");
            let count = document.try_replace_text("Boxed", "Filled").unwrap();
            (count, super::document_xml(&mut document))
        };
        let (plain_count, _) = replace("");
        let (count, saved) = replace(IDENTITY);
        assert_eq!(count, plain_count);
        assert_eq!(saved.matches("Filled text").count(), 2, "{saved}");
        assert!(!saved.contains("Boxed"), "{saved}");
        assert_eq!(
            saved.matches(r#"w:rsidRPr="00D4E5F6""#).count(),
            2,
            "{saved}"
        );
    }

    #[test]
    fn replacing_text_keeps_the_identities_of_the_text_box_paragraph() {
        // The replacement parses a text-box paragraph without its start tag,
        // so the paragraph it edited used to lose its own identities.
        let paragraph = r#"<w:p w:rsidR="00A1B2C3" w14:paraId="1A2B3C4D" w14:textId="5E6F7A8B">"#;
        let mut document = super::document_with_content_controls(&format!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="{W_NS}" xmlns:w14="http://schemas.microsoft.com/office/word/2010/wordml" xmlns:v="urn:schemas-microsoft-com:vml"><w:body><w:p><w:r><w:t>Host paragraph</w:t></w:r><w:r><w:pict><v:shape style="position:absolute;width:216pt;height:36pt"><v:textbox><w:txbxContent>{paragraph}<w:r{IDENTITY}><w:t>Boxed text</w:t></w:r></w:p></w:txbxContent></v:textbox></v:shape></w:pict></w:r></w:p></w:body></w:document>"#
        ));
        assert_eq!(document.try_replace_text("Boxed", "Filled").unwrap(), 1);
        let saved = super::document_xml(&mut document);
        assert!(saved.contains("Filled text"), "{saved}");
        assert!(saved.contains(paragraph), "{saved}");
    }

    #[test]
    fn a_template_fills_a_text_box_whose_runs_carry_identity_attributes() {
        let data = serde_json::json!({"name": "Ada"});
        let render = |run_attributes| {
            let mut document = text_box_document(run_attributes, true, "Dear {{ name }}");
            let count = document.render_template(&data).unwrap();
            (count, super::document_xml(&mut document))
        };
        let (plain_count, _) = render("");
        let (count, saved) = render(IDENTITY);
        assert_eq!(count, plain_count);
        assert_eq!(saved.matches("Dear Ada").count(), 2, "{saved}");
        assert!(!saved.contains("{{"), "{saved}");
    }
}

/// F-266a, script identity and font slot resolution.
mod f266a_script_and_font_slot_regressions {
    use super::*;
    use oxml_layout::{PositionedElement, TextScript};
    use rdocx::RunFontSlot;

    const HEBREW: &str = "שלום עולם";
    const ARABIC_WORD: &str = "العربية";

    /// Every rich run on the page, in paint order.
    fn rich_runs(
        result: &rdocx_layout::WordLayoutResult,
    ) -> Vec<oxml_layout::MultilingualGlyphRun> {
        let mut runs = Vec::new();
        for page in &result.layout.pages {
            oxml_layout::walk(&page.elements, &mut |element, _| {
                if let PositionedElement::MultilingualText(run) = element {
                    runs.push(run.clone());
                }
            });
        }
        runs
    }

    /// Every legacy run on the page. A numbering marker with no complex
    /// script is painted here, not on the rich path.
    fn legacy_runs(result: &rdocx_layout::WordLayoutResult) -> Vec<oxml_layout::GlyphRun> {
        let mut runs = Vec::new();
        for page in &result.layout.pages {
            oxml_layout::walk(&page.elements, &mut |element, _| {
                if let PositionedElement::Text(run) = element {
                    runs.push(run.clone());
                }
            });
        }
        runs
    }

    fn family_of(result: &rdocx_layout::WordLayoutResult, id: oxml_layout::FontId) -> String {
        result
            .layout
            .fonts
            .iter()
            .find(|font| font.id == id)
            .map(|font| font.family.clone())
            .expect("every painted run names a font in the result font table")
    }

    fn style_hebrew(run: &mut rdocx::Run<'_>) {
        run.set_slot_font(RunFontSlot::ComplexScript, Some("Noto Sans Hebrew"));
        run.set_rtl_value(Some(true));
        run.set_complex_script_value(Some(true));
        run.set_language_bidi_value(Some("he-IL"));
    }

    fn style_arabic(run: &mut rdocx::Run<'_>) {
        run.set_slot_font(RunFontSlot::ComplexScript, Some("Noto Sans Arabic"));
        run.set_rtl_value(Some(true));
        run.set_complex_script_value(Some(true));
        run.set_language_bidi_value(Some("ar-SA"));
    }

    /// A space that ends a wrapped right-to-left line hangs off its visual
    /// left. Drawing it inside the line pushed the ink up to a space width
    /// past the right margin.
    #[test]
    fn a_wrapped_right_to_left_line_keeps_its_ink_inside_the_margins() {
        const TEXT: &str =
            "שלום עולם זה טקסט ארוך בעברית שנשבר לכמה שורות בתוך התיבה הזאת היום ועוד";
        let mut document = Document::new();
        {
            let mut section = document.section_mut(0).unwrap();
            section
                .set_page_size(Length::pt(612.0), Length::pt(792.0))
                .unwrap();
            section
                .set_margins(
                    Length::pt(72.0),
                    Length::pt(72.0),
                    Length::pt(72.0),
                    Length::pt(72.0),
                )
                .unwrap();
        }
        for step in 0..70 {
            let mut paragraph = document
                .add_paragraph("")
                .right_to_left(true)
                .alignment(rdocx::paragraph::Alignment::Left)
                .indent_left(Length::pt(100.0 + 2.0 * f64::from(step)));
            style_hebrew(&mut paragraph.add_run(TEXT));
        }

        let result = document
            .layout_deterministic()
            .expect("deterministic right-to-left layout");
        let runs = rich_runs(&result);
        assert!(runs.len() > 70);
        for run in runs.iter().filter(|run| run.logical_text.trim() != "") {
            let right = run.origin.x + run.x_advances.iter().sum::<f64>();
            assert!(
                right <= 540.01,
                "{:?} ends at {right}, past the 540 pt margin",
                run.logical_text
            );
        }
    }

    #[test]
    fn a_right_to_left_paragraph_keeps_logical_order_in_extracted_text() {
        let mut document = Document::new();
        {
            let mut paragraph = document.add_paragraph("").right_to_left(true);
            style_hebrew(&mut paragraph.add_run(HEBREW));
        }

        let result = document
            .layout_deterministic()
            .expect("deterministic right-to-left layout");
        let mut runs = rich_runs(&result);
        assert!(runs.len() > 1, "the paragraph splits into several spans");

        // Painted order is reversed. The first logical span sits furthest
        // right, which is the only thing UAX 9 reordering is allowed to
        // change.
        runs.sort_by_key(|run| run.logical_index);
        let painted = runs.iter().map(|run| run.origin.x).collect::<Vec<_>>();
        assert!(
            painted.windows(2).all(|pair| pair[0] > pair[1]),
            "logical order must paint right to left, got {painted:?}"
        );

        // Logical order survives everywhere the text is read back.
        let logical = runs
            .iter()
            .map(|run| run.logical_text.as_str())
            .collect::<String>();
        assert_eq!(logical, HEBREW, "rich runs retain logical text");

        // Each run's cluster map still points at logical character indices,
        // which is what carries the reversal back to a reader.
        for run in &runs {
            let characters = run.logical_text.chars().count() as u32;
            assert!(
                run.clusters
                    .iter()
                    .all(|cluster| cluster.char_end <= characters),
                "cluster ranges stay inside the logical text"
            );
        }

        let svg = document
            .render_page_to_svg_deterministic(0)
            .expect("deterministic SVG")
            .expect("page one exists");
        for run in &runs {
            assert!(
                svg.svg.contains(&format!(">{}</text>", run.logical_text)),
                "SVG keeps {:?} searchable in logical order",
                run.logical_text
            );
        }

        let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.paragraphs()[0].text(), HEBREW);
    }

    /// Joining is contextual, so a shaper told the wrong script or the wrong
    /// direction silently emits isolated forms that still pass a glyph-count
    /// check.
    ///
    /// The control arm is the same word inside the same single `w:r` with a
    /// zero-width non-joiner between every letter, which is the one thing
    /// that suppresses joining without changing the run structure. A control
    /// built from one run per letter would instead encode the current
    /// no-joining-across-runs behaviour as the expected baseline, and would
    /// then fail with a misleading message if that behaviour were ever fixed.
    ///
    /// Joining does not currently cross a `w:r` boundary, because Word
    /// multilingual reassembly requires every shaped span to stay inside the
    /// inline item it came from. That gap is recorded in the F-266a entry of
    /// `docs/hld/14-development-backlog.md` and is not this story's diff.
    #[test]
    fn arabic_shaping_applies_contextual_joining_forms_within_one_run() {
        let glyphs_of = |text: &str| {
            let mut document = Document::new();
            {
                let mut paragraph = document.add_paragraph("").right_to_left(true);
                style_arabic(&mut paragraph.add_run(text));
            }
            let result = document
                .layout_deterministic()
                .expect("deterministic Arabic layout");
            let mut runs = rich_runs(&result);
            runs.sort_by_key(|run| run.logical_index);
            runs.iter()
                .flat_map(|run| run.glyph_ids.clone())
                .collect::<Vec<_>>()
        };

        let connected = glyphs_of(ARABIC_WORD);
        let disjoined = glyphs_of(
            &ARABIC_WORD
                .chars()
                .map(|character| character.to_string())
                .collect::<Vec<_>>()
                .join("\u{200c}"),
        );

        assert!(!connected.is_empty(), "the Arabic word reaches the shaper");
        assert_ne!(
            connected, disjoined,
            "one connected Arabic word must not shape to the same glyphs as the \
             same letters separated by zero-width non-joiners"
        );
        // Differing is not enough on its own, since the separator adds glyphs
        // of its own. Joining must produce a contextual form that the same
        // letters never produce unjoined.
        assert!(
            connected.iter().any(|glyph| !disjoined.contains(glyph)),
            "joining must produce a form the unjoined letters never take, \
             connected {connected:?} against disjoined {disjoined:?}"
        );
    }

    #[test]
    fn numbering_markers_stay_on_the_leading_edge_of_a_right_to_left_paragraph() {
        let mut document = Document::new();
        let num_id = document.add_list_definition(&[ListLevel::decimal()]);
        {
            let mut paragraph = document.add_paragraph("").right_to_left(true);
            paragraph.set_numbering(num_id, 0);
            style_hebrew(&mut paragraph.add_run(HEBREW));
        }

        let result = document
            .layout_deterministic()
            .expect("deterministic numbered right-to-left layout");
        let marker = legacy_runs(&result)
            .into_iter()
            .find(|run| run.text.starts_with('1'))
            .expect("the decimal marker reaches the page");
        let rightmost_text = rich_runs(&result)
            .iter()
            .filter(|run| run.script == TextScript::Hebrew)
            .map(|run| run.origin.x)
            .fold(f64::MIN, f64::max);
        assert!(
            marker.origin.x > rightmost_text,
            "a right-to-left list marker paints on the leading, right-hand edge, \
             marker at {} against text at {rightmost_text}",
            marker.origin.x
        );
    }

    /// `w:rFonts/@w:hint` must reach a rendered font family.
    ///
    /// The attribute is the one F-265 handed over specifically so this story
    /// could consume it, and a slot table that classified Word's ambiguous
    /// set by codepoint would leave it inert on exactly the characters a
    /// document writes it for. Nothing proves it arrives unless a test drives
    /// it through layout, so dropping `font_hint` at the production call
    /// sites would otherwise leave the suite green.
    ///
    /// The run is punctuation only, because the two faces have to share a
    /// repertoire for the hint to be the thing that decides. Noto Sans SC and
    /// Noto Sans JP both approve ASCII comma and space, per their
    /// `SUBSET-*.md` records, and comma is in Word's ambiguous set, so
    /// coverage fallback cannot move either answer.
    #[test]
    fn a_font_hint_reaches_the_rendered_font_family() {
        let resolved_family = |hint: Option<&str>| {
            let mut document = Document::new();
            {
                let mut paragraph = document.add_paragraph("");
                let mut run = paragraph.add_run(", , ,");
                run.set_slot_font(RunFontSlot::Ascii, Some("Noto Sans SC"));
                run.set_slot_font(RunFontSlot::EastAsia, Some("Noto Sans JP"));
                run.set_font_hint(hint);
            }
            let result = document
                .layout_deterministic()
                .expect("deterministic hinted layout");
            let runs = legacy_runs(&result)
                .into_iter()
                .filter(|run| !run.text.trim().is_empty())
                .collect::<Vec<_>>();
            assert!(!runs.is_empty(), "the hinted run reaches the page");
            let families = runs
                .iter()
                .map(|run| family_of(&result, run.font_id))
                .collect::<std::collections::BTreeSet<_>>();
            assert_eq!(
                families.len(),
                1,
                "one family for one run, got {families:?}"
            );
            families.into_iter().next().expect("one family")
        };

        assert_eq!(
            resolved_family(None),
            "Noto Sans SC",
            "an unhinted ambiguous run keeps w:ascii"
        );
        assert_eq!(
            resolved_family(Some("eastAsia")),
            "Noto Sans JP",
            "an eastAsia hint moves an ambiguous run to w:eastAsia"
        );
    }

    #[test]
    fn an_east_asian_run_reads_its_own_font_slot_and_not_the_ascii_one() {
        // Both bundled faces cover these two Kanji, so coverage fallback
        // cannot decide the Kanji paragraph and only the `w:rFonts` slot can.
        // Noto Sans JP carries no Latin letters, per
        // `crates/oxml-layout/fonts/SUBSET-NotoSansJP.md`, so the Latin
        // paragraph proves the ASCII slot still answers rather than that
        // coverage was forced.
        let mut document = Document::new();
        for text in ["世界", "World"] {
            let mut paragraph = document.add_paragraph("");
            let mut run = paragraph.add_run(text);
            run.set_slot_font(RunFontSlot::Ascii, Some("Noto Sans SC"));
            run.set_slot_font(RunFontSlot::EastAsia, Some("Noto Sans JP"));
        }

        let result = document
            .layout_deterministic()
            .expect("deterministic East Asian layout");

        let han = rich_runs(&result)
            .into_iter()
            .filter(|run| run.script == TextScript::Han)
            .collect::<Vec<_>>();
        assert!(!han.is_empty(), "the Kanji reach the page");
        for run in &han {
            assert_eq!(
                family_of(&result, run.font_id),
                "Noto Sans JP",
                "East Asian text reads w:eastAsia, never w:ascii"
            );
        }

        let latin = legacy_runs(&result)
            .into_iter()
            .filter(|run| !run.text.trim().is_empty())
            .collect::<Vec<_>>();
        assert!(!latin.is_empty(), "the Latin word reaches the page");
        for run in &latin {
            assert_eq!(
                family_of(&result, run.font_id),
                "Noto Sans SC",
                "ASCII text keeps reading w:ascii"
            );
        }
    }
}

/// F-266b, ruby phonetic guides and East Asian emphasis marks.
mod f266b_ruby_and_emphasis_regressions {
    use super::*;
    use rdocx::ST_Em;
    use rdocx_oxml::units::HalfPoint;

    const RUBY_BASE: &str = "漢字";
    const RUBY_TEXT: &str = "かんじ";

    fn ruby_document() -> Document {
        let mut document = Document::new();
        {
            let mut paragraph = document.add_paragraph("");
            paragraph.add_run("Zephyrine ");
            let index = paragraph.add_ruby(RUBY_BASE, RUBY_TEXT);
            paragraph.ruby_mut(index).unwrap().properties = Some(rdocx::CT_RubyPr {
                hps: Some(HalfPoint(10)),
                hps_raise: Some(HalfPoint(22)),
                ..Default::default()
            });
            paragraph.add_run(" Quarkite");
        }
        document
    }

    /// The phonetic line is an annotation, not content. Returning it from
    /// text extraction would double count every annotated word for search,
    /// redaction, `ActualText` and the differential corpus.
    #[test]
    fn ruby_phonetic_text_is_not_returned_by_paragraph_text_extraction() {
        let mut document = ruby_document();
        let expected = format!("Zephyrine {RUBY_BASE} Quarkite");

        let paragraphs = document.paragraphs();
        assert_eq!(paragraphs[0].text(), expected);
        assert!(!paragraphs[0].text().contains(RUBY_TEXT));
        drop(paragraphs);

        // The same holds after a save and a reopen, which is the path a
        // producer file takes.
        let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        let paragraphs = reopened.paragraphs();
        assert_eq!(paragraphs[0].text(), expected);
        assert!(!paragraphs[0].text().contains(RUBY_TEXT));
        assert_eq!(
            paragraphs[0].ruby(0).map(|ruby| ruby.ruby_text[0].text()),
            Some(RUBY_TEXT.to_owned()),
            "the phonetic line is still reachable through the typed model"
        );
    }

    /// Redaction steps over `w:ruby` so a base and a phonetic line are never
    /// rewritten into each other. Modelling the element must not change that.
    #[test]
    fn redaction_still_steps_over_ruby_after_it_is_modeled() {
        let mut document = ruby_document();
        let report = document.redact_text("Zephyrine").unwrap();
        assert!(report.word_text > 0, "the ordinary run text is redacted");

        let paragraphs = document.paragraphs();
        assert!(
            !paragraphs[0].text().contains("Zephyrine"),
            "the selector is gone from the ordinary runs"
        );
        assert!(
            paragraphs[0].text().contains(RUBY_BASE),
            "the ruby base line is untouched"
        );
        assert_eq!(
            paragraphs[0].ruby(0).map(|ruby| ruby.ruby_text[0].text()),
            Some(RUBY_TEXT.to_owned()),
            "the phonetic line is untouched"
        );
    }

    /// A run split before a ruby shifts every later run by one. A span that
    /// did not move with it would wrap the wrong runs, so the annotation
    /// would jump onto its neighbour's text on the next save.
    #[test]
    fn splitting_a_run_before_a_ruby_keeps_the_annotation_on_its_own_base() {
        let mut document = ruby_document();
        {
            let mut paragraph = document.paragraph_mut(0).expect("the paragraph exists");
            assert_eq!(paragraph.ruby(0).unwrap().base_range(), 1..2);
            paragraph.split_run(0, 4).expect("the leading run splits");
            assert_eq!(
                paragraph.ruby(0).unwrap().base_range(),
                2..3,
                "the span moved with its base run"
            );
        }

        let package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
                .unwrap();
        let xml =
            String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
        let ruby = xml
            .split_once("<w:rubyBase>")
            .expect("the ruby base is written")
            .1;
        assert!(
            ruby.contains(RUBY_BASE) && !ruby.split("</w:rubyBase>").next().unwrap().contains("yr"),
            "the annotation still wraps its own base run: {xml}"
        );
        let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(
            reopened.paragraphs()[0].text(),
            format!("Zephyrine {RUBY_BASE} Quarkite")
        );
    }

    /// Word places an emphasis mark without changing the base metrics, so a
    /// marked run must advance exactly as far as an unmarked one. A mark that
    /// consumed advance would move every line containing one.
    #[test]
    fn an_emphasis_mark_does_not_change_the_base_advance() {
        fn advances(mark: Option<ST_Em>) -> Vec<f64> {
            let mut document = Document::new();
            {
                let mut paragraph = document.add_paragraph("");
                let mut run = paragraph.add_run("marked words");
                run.set_font("Carlito");
                run.set_emphasis_mark_value(mark);
            }
            let result = document
                .layout_deterministic()
                .expect("deterministic layout");
            let mut widths = Vec::new();
            for page in &result.layout.pages {
                oxml_layout::walk(&page.elements, &mut |element, _| {
                    if let oxml_layout::PositionedElement::Text(run) = element
                        && !run.text.is_empty()
                        && run.text != "\u{2022}"
                    {
                        widths.extend(run.advances.iter().copied());
                    }
                });
            }
            widths
        }

        let plain = advances(None);
        assert!(!plain.is_empty(), "the control run is painted");
        assert_eq!(
            advances(Some(ST_Em::UnderDot)),
            plain,
            "a marked run keeps the unmarked run's advances"
        );
    }
}

mod floating_table_placement_regressions {
    use rdocx::table::{
        TableAnchor, TableFloatPosition, TableFloatX, TableFloatY, TableOverlap, TableTextDistance,
    };
    use rdocx::{Document, Length};

    /// Letter page, one inch margins, which is what `Document::new` produces.
    const MARGIN_LEFT: f64 = 72.0;
    const MARGIN_TOP: f64 = 72.0;
    const CONTENT_BOTTOM: f64 = 720.0;

    /// A float position with the four from-text distances every case shares.
    /// 180 twips is 9 points and 80 twips is 4 points.
    fn float_at(
        anchor_h: TableAnchor,
        anchor_v: TableAnchor,
        x: i32,
        y: i32,
    ) -> TableFloatPosition {
        TableFloatPosition {
            horizontal_anchor: anchor_h,
            vertical_anchor: anchor_v,
            horizontal: TableFloatX::Offset(Length::twips(x)),
            vertical: TableFloatY::Offset(Length::twips(y)),
            distance_from_text: TableTextDistance {
                top: Length::twips(80),
                right: Length::twips(180),
                bottom: Length::twips(80),
                left: Length::twips(180),
            },
        }
    }

    /// A two by two table 100 points wide, labelled so its cells stay
    /// distinguishable from body text in the placed elements.
    fn add_float(
        document: &mut Document,
        label: &str,
        position: Option<TableFloatPosition>,
        overlap: Option<TableOverlap>,
    ) {
        let mut table = document.add_table(2, 2);
        table.set_column_width(0, Length::twips(1000));
        table.set_column_width(1, Length::twips(1000));
        table.set_width(Length::twips(2000));
        table
            .set_float_position(position)
            .expect("float position is valid");
        table.set_overlap(overlap);
        for row in 0..2 {
            for column in 0..2 {
                table
                    .cell(row, column)
                    .expect("cell exists")
                    .set_text(&format!("{label}{row}{column}"));
            }
        }
    }

    fn prose(document: &mut Document, from: usize, to: usize) {
        for index in from..to {
            document.add_paragraph(&format!(
                "Body line {index:02} with enough words to wrap across the measure of the page and show the reservation."
            ));
        }
    }

    fn round(value: f64) -> f64 {
        (value * 100.0).round() / 100.0
    }

    fn placed(
        result: &rdocx_layout::WordLayoutResult,
        body_index: usize,
    ) -> Vec<(usize, f64, f64, f64, f64)> {
        result
            .body_layout_fragments(body_index)
            .expect("body index is in range")
            .iter()
            .map(|fragment| {
                (
                    fragment.physical_page,
                    round(fragment.x),
                    round(fragment.y),
                    round(fragment.width),
                    round(fragment.height),
                )
            })
            .collect()
    }

    /// Body line boxes of one page as (baseline, left edge, right edge), with
    /// the float's own labelled cell text left out.
    fn body_line_boxes(page: &oxml_layout::PageFrame) -> Vec<(f64, f64, f64)> {
        let mut lines: Vec<(f64, f64, f64)> = Vec::new();
        oxml_layout::walk(&page.elements, &mut |element, _| {
            let oxml_layout::PositionedElement::Text(run) = element else {
                return;
            };
            let is_cell_label = run.text.len() == 3
                && run.text.starts_with(['A', 'B', 'M', 'T'])
                && run.text[1..].chars().all(|glyph| glyph.is_ascii_digit());
            if run.text.trim().is_empty() || is_cell_label {
                return;
            }
            let baseline = round(run.origin.y);
            let left = run.origin.x;
            let right = run.origin.x + run.advances.iter().sum::<f64>();
            match lines.iter_mut().find(|line| line.0 == baseline) {
                Some(line) => {
                    line.1 = line.1.min(left);
                    line.2 = line.2.max(right);
                }
                None => lines.push((baseline, left, right)),
            }
        });
        lines.sort_by(|left, right| left.0.total_cmp(&right.0));
        lines
            .into_iter()
            .map(|(baseline, left, right)| (baseline, round(left), round(right)))
            .collect()
    }

    /// The paginator used to advance the cursor row by row for every table, so
    /// a float that ran past the bottom margin was cut in half across the page
    /// boundary and had its header row repeated on the continuation.
    #[test]
    fn a_floating_table_that_does_not_fit_moves_whole_to_the_next_page() {
        // Six rows, with the first marked as a repeating header. An inline
        // table this tall splits at the page boundary and repeats that header
        // on the continuation, which is exactly what a float must not do.
        let build = |position: Option<TableFloatPosition>| {
            let mut document = Document::new();
            prose(&mut document, 0, 25);
            {
                let mut table = document.add_table(6, 2);
                table.set_column_width(0, Length::twips(1000));
                table.set_column_width(1, Length::twips(1000));
                table.set_width(Length::twips(2000));
                table
                    .set_float_position(position)
                    .expect("float position is valid");
                table.row(0).expect("header row").set_header();
                for row in 0..6 {
                    for column in 0..2 {
                        table
                            .cell(row, column)
                            .expect("cell exists")
                            .set_text(&format!("T{row}{column}"));
                    }
                }
            }
            prose(&mut document, 25, 29);
            document.layout_deterministic().expect("document lays out")
        };

        let inline = build(None);
        let inline_fragments = placed(&inline, 25);
        assert!(
            inline_fragments.len() > 1,
            "an inline table this tall is expected to split: {inline_fragments:?}"
        );

        let result = build(Some(float_at(TableAnchor::Text, TableAnchor::Text, 0, 0)));
        assert_eq!(result.layout.pages.len(), 2);

        // One fragment, on the second page, at its full six-row height. A
        // split float would report two fragments, and a repeated header row
        // would make the continuation taller than the rows it carries.
        assert_eq!(placed(&result, 25), [(2, 72.0, 72.0, 100.0, 134.94)]);

        // The prose that follows shares the second page with the float and
        // flows beside it rather than under it, which is what tells the float
        // apart from a table that simply moved to the next page.
        let second = body_line_boxes(&result.layout.pages[1]);
        assert_eq!(second[0].1, 181.0, "the float did not push the text aside");

        // Nothing the float placed crosses the bottom margin of either page.
        for page in &result.layout.pages {
            for (baseline, ..) in body_line_boxes(page) {
                assert!(
                    baseline < CONTENT_BOTTOM,
                    "line at {baseline} ran past the margin"
                );
            }
        }
    }

    /// A `w:vertAnchor="text"` float has no vertical position until the flow
    /// places the block that carries it, so the first pass cannot offer one to
    /// the text above it. The paginator records where the first pass put it and
    /// the second offers that, which is the whole of the fixed point.
    #[test]
    fn a_text_anchored_float_converges_in_the_existing_two_passes() {
        let build = || {
            let mut document = Document::new();
            prose(&mut document, 0, 3);
            document.add_paragraph("A short neighbour line.");
            add_float(
                &mut document,
                "T",
                Some(float_at(TableAnchor::Text, TableAnchor::Text, 0, -400)),
                None,
            );
            prose(&mut document, 4, 8);
            document.layout_deterministic().expect("document lays out")
        };

        let result = build();
        // The float sits 20 points above its own block, which is where the
        // flow left it. The second pass reflowed the line above it without
        // moving it, so the rect the first pass recorded still holds.
        assert_eq!(placed(&result, 4), [(1, 72.0, 141.96, 100.0, 44.98)]);

        // The neighbour above the float is the one the second pass reflowed.
        let boxes = body_line_boxes(&result.layout.pages[0]);
        assert_eq!(
            boxes[3],
            (149.95, 181.0, 283.23),
            "the line above a text-anchored float was not pushed aside"
        );
        assert_eq!(boxes[2].1, MARGIN_LEFT, "the line clear of the float moved");

        // Two runs of the same document agree, so the two passes settle rather
        // than leaving the geometry dependent on run order.
        let again = build();
        assert_eq!(placed(&again, 4), placed(&result, 4));
        assert_eq!(body_line_boxes(&again.layout.pages[0]), boxes);
    }

    /// `lookahead_wraps` saw only `para.anchored`, so a float anchored to a
    /// later block never pushed the text above it aside.
    #[test]
    fn a_paragraph_before_a_floating_table_is_pushed_aside_by_it() {
        let boxes_for = |position: Option<TableFloatPosition>| {
            let mut document = Document::new();
            prose(&mut document, 0, 2);
            add_float(&mut document, "M", position, None);
            prose(&mut document, 2, 6);
            let result = document.layout_deterministic().expect("document lays out");
            body_line_boxes(&result.layout.pages[0])
        };

        let float = float_at(TableAnchor::Margin, TableAnchor::Margin, 0, 0);
        let wrapped = boxes_for(Some(float));
        assert_eq!(wrapped[0], (82.47, 181.0, 522.9));
        assert_eq!(wrapped[1], (96.96, 181.0, 277.95));

        // The same table in the flow leaves the measure alone, which is what
        // makes the assertion above about the float and not about the table.
        let inline = boxes_for(None);
        assert_eq!(inline[0].1, MARGIN_LEFT);
        assert_eq!(inline[1].1, MARGIN_LEFT);
    }

    /// `w:tblOverlap` is a rule between floating tables, resolved within one
    /// page. Facing-page and section-scoped resolution stays out of scope,
    /// because no reviewed geometry exercises it.
    #[test]
    fn two_floats_that_forbid_overlap_stack_instead_of_intersecting() {
        let origins = |overlap: Option<TableOverlap>| {
            let mut document = Document::new();
            prose(&mut document, 0, 2);
            add_float(
                &mut document,
                "A",
                Some(float_at(TableAnchor::Margin, TableAnchor::Margin, 0, 0)),
                overlap,
            );
            add_float(
                &mut document,
                "B",
                Some(float_at(TableAnchor::Margin, TableAnchor::Margin, 200, 200)),
                overlap,
            );
            prose(&mut document, 2, 6);
            let result = document.layout_deterministic().expect("document lays out");
            (placed(&result, 2), placed(&result, 3))
        };

        // The first float keeps its anchor. The second drops to the bottom of
        // the first one's keep-out band, which is 72 plus the 44.98 point
        // table plus the 4 point bottom clearance, plus its own 4 point top.
        let (first, second) = origins(Some(TableOverlap::Never));
        assert_eq!(first, [(1, MARGIN_LEFT, MARGIN_TOP, 100.0, 44.98)]);
        assert_eq!(second, [(1, 82.0, 124.98, 100.0, 44.98)]);

        // Two floats that both allow the overlap are left intersecting.
        let (first, second) = origins(None);
        assert_eq!(first, [(1, MARGIN_LEFT, MARGIN_TOP, 100.0, 44.98)]);
        assert_eq!(second, [(1, 82.0, 82.0, 100.0, 44.98)]);
    }
}

/// F-266c regressions, the East Asian character grid and vertical text.
///
/// Each test is named as the failure it prevents. The character grid touches
/// line advance and the transposed box touches cell measurement, so the two
/// ways this story could quietly move existing geometry are pinned here.
mod f266c_character_grid_and_vertical_text_regressions {
    use oxml_layout::PositionedElement;
    use rdocx::table::CellTextDirection;
    use rdocx::{CT_DocGrid, Document, Length, ST_DocGrid};
    use rdocx_oxml::units::Twips;

    /// Every painted run on the page, as text with its page-space origin.
    fn painted(document: &Document) -> Vec<(String, String)> {
        let result = document
            .layout_deterministic()
            .expect("deterministic layout");
        let mut runs = Vec::new();
        for page in &result.layout.pages {
            oxml_layout::walk(&page.elements, &mut |element, transform| {
                if let PositionedElement::Text(run) = element
                    && !run.text.trim().is_empty()
                {
                    let point = transform.apply(run.origin);
                    runs.push((run.text.clone(), format!("{:.4},{:.4}", point.x, point.y)));
                }
            });
        }
        runs
    }

    /// A `default` grid must produce geometry identical to no grid at all.
    ///
    /// The `default` type is deliberately kept off the grid arithmetic. A
    /// no-op multiply that still runs is a floating-point step on every
    /// existing line, which is exactly how a silent baseline delta is made.
    #[test]
    fn the_default_doc_grid_type_does_not_change_line_advance() {
        let build = |grid: Option<ST_DocGrid>| {
            let mut document = Document::new();
            document.add_paragraph("first paragraph of the gridded section");
            document.add_paragraph("second paragraph of the gridded section");
            if let Some(grid_type) = grid {
                document
                    .section_mut(0)
                    .expect("final section")
                    .set_doc_grid(Some(CT_DocGrid {
                        grid_type: Some(grid_type),
                        line_pitch: Some(Twips(360)),
                        char_space: Some(120),
                        extra_attributes: Vec::new(),
                    }));
            }
            painted(&document)
        };

        let ungridded = build(None);
        assert!(!ungridded.is_empty(), "the fixture paints");
        assert_eq!(
            build(Some(ST_DocGrid::Default)),
            ungridded,
            "a default grid takes the ungridded branch, character space and all"
        );
        assert_ne!(
            build(Some(ST_DocGrid::LinesAndChars)),
            ungridded,
            "a snapping grid does change the geometry, or the test proves nothing"
        );
    }

    /// Adding a rotated neighbour must not move a horizontal cell.
    #[test]
    fn a_horizontal_cell_beside_a_vertical_cell_keeps_its_geometry() {
        let build = |direction: CellTextDirection| {
            let mut document = Document::new();
            {
                let mut table = document.add_table(1, 2);
                table.cell(0, 0).expect("control cell").set_text("Across");
                let mut neighbour = table.cell(0, 1).expect("neighbour cell");
                neighbour.set_text_direction(Some(direction));
                neighbour.set_text("Down");
            }
            painted(&document)
                .into_iter()
                .filter(|(text, _)| text.trim() == "Across")
                .collect::<Vec<_>>()
        };

        let horizontal = build(CellTextDirection::LeftToRightTopToBottom);
        assert!(!horizontal.is_empty(), "the control cell paints");
        assert_eq!(
            build(CellTextDirection::TopToBottomRightToLeft),
            horizontal,
            "a rotated neighbour must not move the horizontal cell"
        );
    }

    /// Rotation is a painting concern, so every text projection stays logical.
    #[test]
    fn vertical_cell_text_is_extracted_in_logical_order() {
        let mut document = Document::new();
        {
            let mut table = document.add_table(1, 1);
            let mut cell = table.cell(0, 0).expect("authored cell");
            cell.set_text_direction(Some(CellTextDirection::TopToBottomRightToLeft));
            cell.set_text("Logical order");
        }

        let mut reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        let tables = reopened.tables();
        let table = tables.first().expect("the authored table");
        assert_eq!(
            table.cell(0, 0).expect("the authored cell").text(),
            "Logical order"
        );

        let painted = painted(&reopened)
            .into_iter()
            .map(|(text, _)| text)
            .collect::<Vec<_>>()
            .concat();
        assert!(
            painted.contains("Logical") && painted.contains("order"),
            "the rotated cell still paints its own words: {painted}"
        );
        let svg = reopened
            .render_page_to_svg_deterministic(0)
            .expect("the page renders to SVG")
            .expect("one page");
        assert!(
            svg.svg.contains("Logical"),
            "the SVG projection carries the logical text: {}",
            svg.svg
        );
        let saved = String::from_utf8(
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(reopened.to_bytes().unwrap()))
                .unwrap()
                .get_part("/word/document.xml")
                .unwrap()
                .to_vec(),
        )
        .unwrap();
        assert!(
            saved.contains("<w:t>Logical order</w:t>"),
            "the saved XML keeps the logical run: {saved}"
        );
    }

    const W_NS: &str = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";

    /// A rotated cell must paint inside its own column.
    ///
    /// The line direction of a rotated cell runs down the cell, so wrapping it
    /// at the column width would wrap on the stacking axis instead. The stack
    /// would then be taller than the column is wide and the content would
    /// paint outside the table and past the page margin.
    #[test]
    fn a_vertical_cell_paints_inside_its_own_column() {
        let source = format!(
            concat!(
                r#"<w:document xmlns:w="{ns}"><w:body><w:tbl>"#,
                r#"<w:tblGrid><w:gridCol w:w="720"/><w:gridCol w:w="7200"/></w:tblGrid>"#,
                r#"<w:tr>"#,
                r#"<w:tc><w:tcPr><w:textDirection w:val="tbRl"/></w:tcPr>"#,
                r#"<w:p><w:r><w:t>A much longer stretch of vertical cell text</w:t>"#,
                r#"</w:r></w:p></w:tc>"#,
                r#"<w:tc><w:p><w:r><w:t>neighbour</w:t></w:r></w:p></w:tc>"#,
                r#"</w:tr></w:tbl><w:sectPr/></w:body></w:document>"#,
            ),
            ns = W_NS,
        );
        let mut seed = Document::new();
        let mut package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap()))
                .unwrap();
        package.set_part("/word/document.xml", source.into_bytes());
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        let document = Document::from_bytes(&bytes.into_inner()).unwrap();
        let result = document
            .layout_deterministic()
            .expect("deterministic vertical cell layout");

        // The first column is 720 twips, 36 points, from the page's left
        // margin at 72 points.
        const COLUMN_LEFT: f64 = 72.0;
        const COLUMN_RIGHT: f64 = 108.0;
        let mut painted = 0usize;
        for page in &result.layout.pages {
            oxml_layout::walk(&page.elements, &mut |element, transform| {
                let PositionedElement::Text(run) = element else {
                    return;
                };
                if run.text.trim().is_empty() || run.text.trim() == "neighbour" {
                    return;
                }
                painted += 1;
                let x = transform.apply(run.origin).x;
                assert!(
                    (COLUMN_LEFT..=COLUMN_RIGHT).contains(&x),
                    "{:?} paints inside its own column, at {x}",
                    run.text
                );
            });
        }
        assert!(painted > 0, "the rotated cell paints");
    }

    /// A gridded paragraph that reflows around a float stays on the grid.
    ///
    /// The float reflow re-breaks lines through the generic line breaker,
    /// which knows nothing about the section grid, so the snap has to be
    /// applied again over its result or a gridded section loses its advance
    /// wherever a floating table or a wrapping drawing pushes text aside.
    #[test]
    fn a_gridded_paragraph_that_reflows_around_a_float_stays_on_the_grid() {
        let advances = |float: bool| {
            let mut document = Document::new();
            if float {
                let mut table = document.add_table(1, 1);
                table
                    .set_float_position(Some(rdocx::table::TableFloatPosition {
                        horizontal_anchor: rdocx::table::TableAnchor::Text,
                        vertical_anchor: rdocx::table::TableAnchor::Text,
                        horizontal: rdocx::table::TableFloatX::Offset(Length::twips(0)),
                        vertical: rdocx::table::TableFloatY::Offset(Length::twips(0)),
                        distance_from_text: rdocx::table::TableTextDistance {
                            top: Length::twips(0),
                            right: Length::twips(180),
                            bottom: Length::twips(0),
                            left: Length::twips(0),
                        },
                    }))
                    .expect("the float position is authored");
                table.cell(0, 0).expect("float cell").set_text("float");
            }
            for _ in 0..4 {
                document.add_paragraph(
                    "A paragraph long enough to wrap beside the floating table above it",
                );
            }
            document
                .section_mut(0)
                .expect("final section")
                .set_doc_grid(Some(CT_DocGrid {
                    grid_type: Some(ST_DocGrid::Lines),
                    line_pitch: Some(Twips(720)),
                    char_space: None,
                    extra_attributes: Vec::new(),
                }));
            let result = document
                .layout_deterministic()
                .expect("deterministic gridded layout");
            let mut origins = Vec::new();
            for page in &result.layout.pages {
                oxml_layout::walk(&page.elements, &mut |element, _| {
                    if let PositionedElement::Text(run) = element
                        && run.text.starts_with('A')
                    {
                        origins.push(run.origin.y);
                    }
                });
            }
            origins
                .windows(2)
                .map(|pair| pair[1] - pair[0])
                .collect::<Vec<_>>()
        };

        // A 720 twip pitch is 36 points, so every baseline-to-baseline advance
        // is a whole number of grid rows plus the paragraph spacing, which the
        // ungridded first advance states. A float legitimately moves the text
        // it pushes aside, so the rule is asserted rather than the numbers.
        const PITCH: f64 = 36.0;
        let plain = advances(false);
        assert!(!plain.is_empty(), "the gridded fixture paints its lines");
        let spacing = plain[0] - PITCH;
        assert!(
            (0.0..PITCH).contains(&spacing),
            "the ungridded advance is one grid row plus its spacing: {plain:?}"
        );
        let floated = advances(true);
        assert_eq!(
            floated.len(),
            plain.len(),
            "the float does not lose a paragraph: {floated:?}"
        );
        assert_ne!(
            floated, plain,
            "the float really does reflow the text, or the test proves nothing"
        );
        for advance in plain.iter().chain(&floated) {
            let rows = (advance - spacing) / PITCH;
            assert!(
                rows >= 1.0 && (rows - rows.round()).abs() < 1e-6,
                "{advance} is not a whole number of grid rows plus {spacing}: \
                 {plain:?} against {floated:?}"
            );
        }
    }

    /// A revised paragraph in a rotated cell keeps its change bar.
    ///
    /// The bar spans the whole row band for a rotated cell, so it is drawn
    /// once. Recording that a paragraph was seen rather than that a bar was
    /// drawn would let an unrevised first paragraph suppress the bar of the
    /// revised paragraph after it.
    #[test]
    fn a_revised_paragraph_after_a_plain_one_in_a_vertical_cell_keeps_its_bar() {
        let bars = |direction: &str, paragraphs: &str| {
            let source = format!(
                concat!(
                    r#"<w:document xmlns:w="{ns}"><w:body><w:tbl>"#,
                    r#"<w:tblGrid><w:gridCol w:w="4000"/></w:tblGrid>"#,
                    r#"<w:tr><w:tc><w:tcPr><w:textDirection w:val="{direction}"/></w:tcPr>"#,
                    r#"{paragraphs}</w:tc></w:tr>"#,
                    r#"</w:tbl><w:sectPr/></w:body></w:document>"#,
                ),
                ns = W_NS,
                direction = direction,
                paragraphs = paragraphs,
            );
            let mut seed = Document::new();
            let mut package =
                oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap()))
                    .unwrap();
            package.set_part("/word/document.xml", source.into_bytes());
            let mut bytes = std::io::Cursor::new(Vec::new());
            package.write_to(&mut bytes).unwrap();
            let document = Document::from_bytes(&bytes.into_inner()).unwrap();
            let result = document
                .layout_deterministic_with_options(rdocx::RenderOptions {
                    revision_view: rdocx_layout::RevisionView::Tracked,
                })
                .expect("deterministic tracked layout");
            let mut bars = 0usize;
            for page in &result.layout.pages {
                oxml_layout::walk(&page.elements, &mut |element, _| {
                    if let PositionedElement::Line { start, end, .. } = element
                        && (start.x - end.x).abs() < 1e-9
                    {
                        bars += 1;
                    }
                });
            }
            bars
        };

        let plain = r#"<w:p><w:r><w:t>plain</w:t></w:r></w:p>"#;
        let revised = concat!(
            r#"<w:p><w:pPr><w:pPrChange w:id="1" w:author="A" w:date="2026-01-01T00:00:00Z">"#,
            r#"<w:pPr/></w:pPrChange></w:pPr><w:r><w:t>revised</w:t></w:r></w:p>"#,
        );
        assert_eq!(
            bars("tbRl", &format!("{revised}{plain}")),
            1,
            "a revised first paragraph draws the cell's bar"
        );
        assert_eq!(
            bars("tbRl", &format!("{plain}{revised}")),
            1,
            "a plain first paragraph must not suppress the bar after it"
        );
        assert_eq!(
            bars("tbRl", &format!("{revised}{revised}")),
            1,
            "the bar spans the row band and is drawn once"
        );
        // The rule has two sides. A horizontal cell still marks each revised
        // paragraph on its own, because only a rotated cell's bar covers the
        // whole row band, and a de-duplication that reached the horizontal
        // path would silently drop every bar after the first.
        assert_eq!(
            bars("lrTb", &format!("{revised}{revised}")),
            2,
            "a horizontal cell keeps one bar for every revised paragraph"
        );
    }

    /// Autofit must not size a rotated column from its text length.
    ///
    /// A rotated cell is measured in its transposed box, so the width it needs
    /// is the stacked height of its lines. Measuring it the way a horizontal
    /// cell is measured hands it a column as wide as its text is long, and
    /// measuring it at the narrow trial width hands its minimum the largest
    /// number it can produce, which then rescales every other column.
    #[test]
    fn autofit_does_not_size_a_vertical_column_from_its_text_length() {
        let table = |direction: &str| {
            format!(
                concat!(
                    r#"<w:document xmlns:w="{ns}"><w:body><w:tbl>"#,
                    r#"<w:tblPr><w:tblW w:w="0" w:type="auto"/>"#,
                    r#"<w:tblLayout w:type="autofit"/></w:tblPr>"#,
                    r#"<w:tr>"#,
                    r#"<w:tc><w:tcPr><w:textDirection w:val="{direction}"/></w:tcPr>"#,
                    r#"<w:p><w:r><w:t>A much longer stretch of vertical cell text</w:t>"#,
                    r#"</w:r></w:p></w:tc>"#,
                    r#"<w:tc><w:p><w:r><w:t>neighbour</w:t></w:r></w:p></w:tc>"#,
                    r#"</w:tr></w:tbl><w:sectPr/></w:body></w:document>"#,
                ),
                ns = W_NS,
                direction = direction,
            )
        };
        let neighbour_origin = |direction: &str| {
            let mut seed = Document::new();
            let mut package =
                oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap()))
                    .unwrap();
            package.set_part("/word/document.xml", table(direction).into_bytes());
            let mut bytes = std::io::Cursor::new(Vec::new());
            package.write_to(&mut bytes).unwrap();
            let document = Document::from_bytes(&bytes.into_inner()).unwrap();
            let result = document
                .layout_deterministic()
                .expect("deterministic autofit layout");
            let mut origin = None;
            for page in &result.layout.pages {
                oxml_layout::walk(&page.elements, &mut |element, transform| {
                    if let PositionedElement::Text(run) = element
                        && run.text.trim() == "neighbour"
                        && origin.is_none()
                    {
                        origin = Some(transform.apply(run.origin).x);
                    }
                });
            }
            origin.expect("the neighbouring cell paints")
        };

        // The neighbour starts where the first column ends, so its origin is
        // how wide autofit made that column.
        let horizontal = neighbour_origin("lrTb");
        let rotated = neighbour_origin("tbRl");
        assert!(
            rotated < horizontal,
            "a rotated cell needs less width than the same text laid out across, \
             {rotated} against {horizontal}"
        );
        // One line of eleven-point text is under twenty points tall, and the
        // default cell margins add under eleven more, so a column sized from
        // the stacked height sits well inside the text length.
        assert!(
            rotated < horizontal / 2.0,
            "the rotated column is sized from the stacked height, \
             {rotated} against {horizontal}"
        );
    }
}

mod paragraph_spacing_collapse_regressions {
    use rdocx::{CompatibilityOption, Document, Length};

    /// One single-line body paragraph on an exact 14 point line, so the gap
    /// between two of them is their spacing alone and no font enters it.
    fn add_spaced(document: &mut Document, text: &str, before: f64, after: f64) {
        let mut paragraph = document.add_paragraph(text);
        paragraph.set_line_spacing(14.0);
        paragraph.set_space_before(Length::pt(before));
        paragraph.set_space_after(Length::pt(after));
    }

    fn round(value: f64) -> f64 {
        (value * 100.0).round() / 100.0
    }

    /// The first fragment of every body item as (page, top of its lines).
    fn tops(document: &Document) -> Vec<(usize, f64)> {
        let result = document
            .layout_deterministic()
            .expect("document lays out in deterministic font mode");
        (0..document.content_count())
            .map(|index| {
                let fragment = &result
                    .body_layout_fragments(index)
                    .expect("body index is in range")[0];
                (fragment.physical_page, round(fragment.y))
            })
            .collect()
    }

    /// The gap between the lines of each pair of consecutive body items.
    fn gaps(document: &Document) -> Vec<f64> {
        tops(document)
            .windows(2)
            .map(|pair| round(pair[1].1 - pair[0].1 - 14.0))
            .collect()
    }

    /// How many body items start on each page.
    fn items_per_page(document: &Document) -> Vec<usize> {
        let mut counts = Vec::new();
        for (page, _) in tops(document) {
            if counts.len() < page {
                counts.resize(page, 0);
            }
            counts[page - 1] += 1;
        }
        counts
    }

    /// Word's own probe: the space after of one paragraph and the space
    /// before of the next, larger on either side in turn.
    fn boundary_probe() -> Document {
        let mut document = Document::new();
        add_spaced(&mut document, "P1", 0.0, 20.0);
        add_spaced(&mut document, "P2", 10.0, 0.0);
        add_spaced(&mut document, "P3", 30.0, 5.0);
        add_spaced(&mut document, "P4", 0.0, 0.0);
        add_spaced(&mut document, "P5", 12.0, 0.0);
        document
    }

    /// The shape of the issue: eighty single-line paragraphs with 6 points
    /// before and 7 after, which is a table of contents in miniature.
    fn toc_probe() -> Document {
        let mut document = Document::new();
        for index in 0..80 {
            add_spaced(&mut document, &format!("Entry {index:02}"), 6.0, 7.0);
        }
        document
    }

    fn sum_spacing(document: &mut Document) {
        document
            .set_compatibility_option(CompatibilityOption::DoNotUseHTMLParagraphAutoSpacing, true)
            .expect("the compatibility option is set");
    }

    /// Layout added the two, which put 24 entries on a page where Word puts
    /// 31 and spread a table of contents over one more page than Word.
    #[test]
    fn consecutive_paragraphs_keep_the_larger_of_space_after_and_space_before() {
        // Word 16 separates these five paragraphs by 20, 30, 5 and 12 points.
        assert_eq!(gaps(&boundary_probe()), vec![20.0, 30.0, 5.0, 12.0]);
        // 31 lines of 14 points and 30 gaps of 7 fill 644 of the 648 points.
        assert_eq!(items_per_page(&toc_probe()), vec![31, 31, 18]);

        // The compatibility option is the one case where Word adds them.
        let mut document = boundary_probe();
        sum_spacing(&mut document);
        assert_eq!(gaps(&document), vec![30.0, 30.0, 5.0, 12.0]);
        let mut document = toc_probe();
        sum_spacing(&mut document);
        assert_eq!(items_per_page(&document), vec![24, 24, 24, 8]);
    }

    /// Each painted line of the first page as (text, baseline).
    fn baselines(document: &Document) -> Vec<(String, f64)> {
        let result = document
            .layout_deterministic()
            .expect("document lays out in deterministic font mode");
        let mut lines = Vec::new();
        oxml_layout::walk(&result.layout.pages[0].elements, &mut |element, _| {
            if let oxml_layout::PositionedElement::Text(run) = element
                && !run.text.trim().is_empty()
            {
                lines.push((run.text.trim().to_owned(), round(run.origin.y)));
            }
        });
        lines
    }

    fn pitches(lines: &[(String, f64)]) -> Vec<f64> {
        lines
            .windows(2)
            .map(|pair| round(pair[1].1 - pair[0].1))
            .collect()
    }

    /// A paragraph, then a one-cell table, then a paragraph. Word adds the
    /// spacing that meets across each table edge rather than collapsing it.
    #[test]
    fn a_table_boundary_adds_the_space_after_and_space_before_that_meet_there() {
        let mut document = Document::new();
        add_spaced(&mut document, "above", 0.0, 20.0);
        {
            let mut table = document.add_table(1, 1);
            table.set_cell_margins(
                Length::pt(0.0),
                Length::pt(5.0),
                Length::pt(0.0),
                Length::pt(5.0),
            );
            let mut cell = table.cell(0, 0).expect("cell exists");
            cell.set_text("inside");
            let mut paragraph = cell.paragraph_mut(0).expect("cell paragraph");
            paragraph.set_line_spacing(14.0);
            paragraph.set_space_before(Length::pt(10.0));
            paragraph.set_space_after(Length::pt(20.0));
        }
        add_spaced(&mut document, "below", 10.0, 0.0);

        let lines = baselines(&document);
        assert_eq!(
            lines.iter().map(|line| line.0.as_str()).collect::<Vec<_>>(),
            ["above", "inside", "below"]
        );
        // 14 points of line, then 20 after and 10 before on each side.
        assert_eq!(pitches(&lines), vec![44.0, 44.0]);
    }

    /// Three paragraphs in one cell with exact 14 point lines, spaced like the
    /// Word probe: 20 after, then 10 before and 10 after, then 30 before.
    fn cell_probe(summed: bool) -> Document {
        let mut document = Document::new();
        {
            let mut table = document.add_table(1, 1);
            table.set_cell_margins(
                Length::pt(0.0),
                Length::pt(5.0),
                Length::pt(0.0),
                Length::pt(5.0),
            );
            let mut cell = table.cell(0, 0).expect("cell exists");
            cell.set_text("C1");
            cell.add_paragraph("C2");
            cell.add_paragraph("C3");
            for (index, (before, after)) in [(0.0, 20.0), (10.0, 10.0), (30.0, 0.0)]
                .into_iter()
                .enumerate()
            {
                let mut paragraph = cell.paragraph_mut(index).expect("cell paragraph");
                paragraph.set_line_spacing(14.0);
                paragraph.set_space_before(Length::pt(before));
                paragraph.set_space_after(Length::pt(after));
            }
        }
        if summed {
            sum_spacing(&mut document);
        }
        document
    }

    /// Cell paragraphs were drawn at the top of their block with the space
    /// before below them, and the row summed every facing pair of spacing.
    #[test]
    fn consecutive_cell_paragraphs_keep_the_larger_spacing_and_draw_below_their_space_before() {
        // Word 16 separates the three lines by 20 and 30 points.
        let document = cell_probe(false);
        assert_eq!(pitches(&baselines(&document)), vec![34.0, 44.0]);
        let result = document
            .layout_deterministic()
            .expect("document lays out in deterministic font mode");
        let row = &result.body_layout_fragments(0).expect("the table")[0];
        assert_eq!(round(row.height), 92.0, "three lines and gaps of 20 and 30");

        // With the compatibility option Word separates them by 30 and 40.
        assert_eq!(pitches(&baselines(&cell_probe(true))), vec![44.0, 54.0]);
    }
}

mod table_row_border_and_margin_regressions {
    use rdocx::table::{CellBorderEdge, RowHeight, Table, TableBorderEdge};
    use rdocx::{BorderStyle, Document, Length};

    fn round(value: f64) -> f64 {
        (value * 100.0).round() / 100.0
    }

    /// A five-row table of two 4680 twip columns, as in the Word probes: one
    /// exact 14 point line per cell, no vertical cell margin, 5 points left
    /// and right. A paragraph on the same kind of line follows it.
    fn probe(configure: impl FnOnce(&mut Table)) -> Document {
        let mut document = Document::new();
        {
            let mut table = document.add_table(5, 2);
            table.set_cell_margins(
                Length::pt(0.0),
                Length::pt(5.0),
                Length::pt(0.0),
                Length::pt(5.0),
            );
            for row in 0..5 {
                for column in 0..2 {
                    let mut cell = table.cell(row, column).expect("cell exists");
                    cell.set_text(&format!("R{row}{column}"));
                    let mut paragraph = cell.paragraph_mut(0).expect("cell paragraph");
                    paragraph.set_line_spacing(14.0);
                    paragraph.set_space_before(Length::pt(0.0));
                    paragraph.set_space_after(Length::pt(0.0));
                }
            }
            configure(&mut table);
        }
        let mut next = document.add_paragraph("NEXT");
        next.set_line_spacing(14.0);
        next.set_space_before(Length::pt(0.0));
        next.set_space_after(Length::pt(0.0));
        document
    }

    /// Baseline and left edge of each painted line of the first page.
    fn lines(document: &Document) -> Vec<(String, f64, f64)> {
        let result = document
            .layout_deterministic()
            .expect("document lays out in deterministic font mode");
        let mut lines = Vec::new();
        oxml_layout::walk(&result.layout.pages[0].elements, &mut |element, _| {
            if let oxml_layout::PositionedElement::Text(run) = element
                && !run.text.trim().is_empty()
            {
                lines.push((
                    run.text.trim().to_owned(),
                    round(run.origin.y),
                    round(run.origin.x),
                ));
            }
        });
        lines
    }

    /// How far the first row's line sits below where a borderless table puts
    /// it, then the distance from each first-column line to the next and from
    /// the last row to the paragraph after the table.
    fn row_geometry(document: &Document) -> (f64, Vec<f64>) {
        let baselines = |document: &Document| {
            lines(document)
                .into_iter()
                .filter(|(text, ..)| text.ends_with('0') || text == "NEXT")
                .map(|(_, baseline, _)| baseline)
                .collect::<Vec<_>>()
        };
        let plain = baselines(&probe(|_| {}));
        let placed = baselines(document);
        assert_eq!(placed.len(), 6, "five rows and the paragraph after them");
        let pitches = placed
            .windows(2)
            .map(|pair| round(pair[1] - pair[0]))
            .collect();
        (round(placed[0] - plain[0]), pitches)
    }

    fn all_borders(style: BorderStyle, eighths: u32) -> impl FnOnce(&mut Table) {
        move |table: &mut Table| table.set_borders(style, eighths, "000000")
    }

    /// Word 16 measurements. Layout drew horizontal borders over the rows
    /// without reserving any height for them, so every bordered row was
    /// shorter than Word's by the border width, about a point per row for a
    /// Google Docs export, which moved table page breaks a row later.
    #[test]
    fn horizontal_table_borders_take_their_width_between_rows() {
        assert_eq!(row_geometry(&probe(|_| {})), (0.0, vec![14.0; 5]));
        // A 1 point border above every row and below the last one.
        assert_eq!(
            row_geometry(&probe(all_borders(BorderStyle::Single, 8))),
            (1.0, vec![15.0; 5])
        );
        assert_eq!(
            row_geometry(&probe(all_borders(BorderStyle::Single, 24))),
            (3.0, vec![17.0; 5])
        );
        // A double border is two lines and their gap, three widths in all.
        assert_eq!(
            row_geometry(&probe(all_borders(BorderStyle::Double, 4))),
            (1.5, vec![15.5; 5])
        );
        // Top 6, inside 1, bottom 3: each band is the edge on that boundary.
        let mixed = probe(|table| {
            for (edge, eighths) in [
                (TableBorderEdge::Top, 48),
                (TableBorderEdge::InsideHorizontal, 8),
                (TableBorderEdge::Bottom, 24),
            ] {
                table
                    .set_border_checked(edge, BorderStyle::Single, eighths, "000000")
                    .expect("border is valid");
            }
        });
        assert_eq!(
            row_geometry(&mixed),
            (6.0, vec![15.0, 15.0, 15.0, 15.0, 17.0])
        );
        // Inside borders alone leave the top of the table and its end alone.
        let inside = probe(|table| {
            table
                .set_border_checked(
                    TableBorderEdge::InsideHorizontal,
                    BorderStyle::Single,
                    24,
                    "000000",
                )
                .expect("border is valid");
        });
        assert_eq!(
            row_geometry(&inside),
            (0.0, vec![17.0, 17.0, 17.0, 17.0, 14.0])
        );
    }

    /// The borders straddled each row boundary, so half of every line was
    /// painted over the row above it.
    #[test]
    fn horizontal_table_borders_paint_inside_the_band_they_reserve() {
        let document = probe(all_borders(BorderStyle::Single, 24));
        let result = document
            .layout_deterministic()
            .expect("document lays out in deterministic font mode");
        let table = &result.body_layout_fragments(0).expect("the table")[0];
        assert_eq!(
            round(table.height),
            88.0,
            "five rows of 17 and a 3 point bottom"
        );
        let mut centres = Vec::new();
        oxml_layout::walk(&result.layout.pages[0].elements, &mut |element, _| {
            if let oxml_layout::PositionedElement::Line {
                start, end, width, ..
            } = element
                && start.y == end.y
            {
                assert_eq!(*width, 3.0);
                centres.push(round(start.y - table.y));
            }
        });
        centres.sort_by(f64::total_cmp);
        centres.dedup();
        // Each 3 point line fills the band below a row boundary, and the
        // table's bottom line fills the last 3 points of the table.
        assert_eq!(centres, vec![1.5, 18.5, 35.5, 52.5, 69.5, 86.5]);
    }

    #[test]
    fn a_cell_border_widens_only_the_row_boundary_it_sits_on() {
        let cell_edge = |edge: CellBorderEdge, eighths: u32| {
            move |table: &mut Table| {
                table
                    .cell(1, 0)
                    .expect("cell exists")
                    .set_border_checked(edge, BorderStyle::Single, eighths, "000000")
                    .expect("border is valid");
            }
        };
        // A 3 point top on one cell of the second row.
        assert_eq!(
            row_geometry(&probe(cell_edge(CellBorderEdge::Top, 24))),
            (0.0, vec![17.0, 14.0, 14.0, 14.0, 14.0])
        );
        // A 3 point bottom on the same cell.
        assert_eq!(
            row_geometry(&probe(cell_edge(CellBorderEdge::Bottom, 24))),
            (0.0, vec![14.0, 17.0, 14.0, 14.0, 14.0])
        );
        // Over 1 point table borders, the widest edge on a boundary wins.
        let widest = probe(|table| {
            table.set_borders(BorderStyle::Single, 8, "000000");
            cell_edge(CellBorderEdge::Top, 48)(table);
        });
        assert_eq!(
            row_geometry(&widest),
            (1.0, vec![20.0, 15.0, 15.0, 15.0, 15.0])
        );
    }

    #[test]
    fn exact_row_heights_include_the_border_above_and_minimum_heights_exclude_it() {
        let heights = |height: RowHeight| {
            move |table: &mut Table| {
                table.set_borders(BorderStyle::Single, 24, "000000");
                for row in 0..5 {
                    table
                        .row(row)
                        .expect("row exists")
                        .set_height_checked(height)
                        .expect("height is valid");
                }
            }
        };
        // Exact 20 points: the 3 point band is inside the 20, and the table's
        // bottom border still follows the last row.
        let (shift, pitches) = row_geometry(&probe(heights(RowHeight::Exact(Length::pt(20.0)))));
        assert_eq!(pitches, vec![20.0, 20.0, 20.0, 20.0, 20.0]);
        let (exact_shift, _) = row_geometry(&probe(|table| {
            table.set_borders(BorderStyle::Single, 24, "000000")
        }));
        assert_eq!(shift, exact_shift, "the content starts below the band");
        // At least 30 points: the minimum is for the content, the band is added.
        assert_eq!(
            row_geometry(&probe(heights(RowHeight::AtLeast(Length::pt(30.0))))).1[..4],
            [33.0, 33.0, 33.0, 33.0]
        );
    }

    /// Layout read only the table's `w:tblCellMar` and ignored a cell's own
    /// `w:tcMar`, which Google Docs writes on every cell.
    #[test]
    fn per_cell_margins_override_the_table_cell_margins() {
        let cell_margins = |top: f64, left: f64, table_vertical: f64| {
            move |table: &mut Table| {
                table.set_cell_margins(
                    Length::pt(table_vertical),
                    Length::pt(5.0),
                    Length::pt(table_vertical),
                    Length::pt(5.0),
                );
                for row in 0..5 {
                    for column in 0..2 {
                        table
                            .cell(row, column)
                            .expect("cell exists")
                            .set_margins_checked(
                                Length::pt(top),
                                Length::pt(5.0),
                                Length::pt(top),
                                Length::pt(left),
                            )
                            .expect("margins are valid");
                    }
                }
            }
        };
        // 5 points on every side of every cell over a table default of none.
        assert_eq!(
            row_geometry(&probe(cell_margins(5.0, 5.0, 0.0))),
            (5.0, vec![24.0, 24.0, 24.0, 24.0, 19.0])
        );
        // No vertical cell margin over a table default of 5 points.
        assert_eq!(
            row_geometry(&probe(cell_margins(0.0, 5.0, 5.0))),
            (0.0, vec![14.0; 5])
        );
        // The left margin moves the text and the table default does not.
        let left_edge = |document: &Document| {
            lines(document)
                .into_iter()
                .find(|(text, ..)| text == "R00")
                .expect("the first cell paints")
                .2
        };
        assert_eq!(
            round(left_edge(&probe(cell_margins(0.0, 15.0, 0.0))) - left_edge(&probe(|_| {}))),
            10.0
        );
    }
}

#[test]
fn issue_159_content_control_identity_only_comparison_has_no_revision() {
    let source = |id| {
        wrap_word_body(&format!(
            r#"<w:sdt><w:sdtPr><w:id w:val="{id}"/><w:tag w:val="stable"/></w:sdtPr><w:sdtContent><w:p><w:r><w:t>Same text</w:t></w:r></w:p></w:sdtContent></w:sdt>"#
        ))
    };
    let mut compared = document_with_content_controls(&source("11"));
    let edited = document_with_content_controls(&source("12"));

    let diagnostics = compared
        .compare(&edited, "R", "2026-09-30T00:00:00Z")
        .unwrap();
    assert!(diagnostics.is_empty(), "{diagnostics:?}");
    assert!(compared.revisions().is_empty());
}

mod keep_with_next_regressions {
    use rdocx::{Document, Length};

    const BODY: &str = "Sed ut perspiciatis unde omnis iste natus error sit voluptatem \
        accusantium doloremque laudantium, totam rem aperiam, eaque ipsa quae ab illo \
        inventore veritatis et quasi architecto beatae vitae dicta sunt explicabo. Nemo \
        enim ipsam voluptatem quia voluptas sit aspernatur aut odit aut fugit, sed quia \
        consequuntur magni dolores eos qui ratione voluptatem sequi nesciunt.";

    /// A paragraph on an exact line, with its spacing set directly.
    fn add_line(document: &mut Document, text: &str, line: f64, after: f64) {
        let mut paragraph = document.add_paragraph(text);
        paragraph.set_line_spacing(line);
        paragraph.set_space_before(Length::pt(0.0));
        paragraph.set_space_after(Length::pt(after));
    }

    /// `count` single-line fillers of 14 points, 14 * `count` points in all.
    fn fillers(count: usize) -> Document {
        let mut document = Document::new();
        for index in 0..count {
            add_line(&mut document, &format!("Filler {index:02}"), 14.0, 0.0);
        }
        document
    }

    /// An 18 point heading line in the Heading 1 style, which keeps with next.
    fn add_heading(document: &mut Document, text: &str, after: f64) {
        add_line(document, text, 18.0, after);
        let last = document.content_count() - 1;
        document
            .paragraph_mut(last)
            .expect("the heading was just added")
            .set_style("Heading1");
    }

    /// The physical page each body item from `first` on starts on.
    fn pages_from(document: &Document, first: usize) -> Vec<usize> {
        let result = document
            .layout_deterministic()
            .expect("document lays out in deterministic font mode");
        (first..document.content_count())
            .map(|index| {
                result
                    .body_layout_fragments(index)
                    .expect("body index is in range")[0]
                    .physical_page
            })
            .collect()
    }

    /// The 648 point page holds 44 fillers (616 points) and an 18 point
    /// heading. The next line would still fit under the heading, but not under
    /// its 6 points after, so the body opens page 2 and the heading goes with
    /// it. Layout left out the space after and kept the heading on page 1.
    #[test]
    fn a_heading_follows_its_next_line_past_its_own_space_after() {
        let mut document = fillers(44);
        add_heading(&mut document, "Heading", 6.0);
        add_line(&mut document, BODY, 14.0, 0.0);
        assert_eq!(pages_from(&document, 44), vec![2, 2]);

        // Without the space after, the heading and the first line fit.
        let mut document = fillers(44);
        add_heading(&mut document, "Heading", 0.0);
        let mut body = document.add_paragraph(BODY);
        body.set_line_spacing(14.0);
        body.set_space_before(Length::pt(0.0));
        body.set_space_after(Length::pt(0.0));
        body.set_widow_control(false);
        assert_eq!(pages_from(&document, 44), vec![1, 1]);
    }

    /// One line of the next paragraph fits under the heading, but widow
    /// control does not leave a single line at the foot of the page, so that
    /// paragraph opens page 2 and the heading, kept with next by direct
    /// formatting here, goes with it. Layout measured the next paragraph's
    /// first line only.
    #[test]
    fn a_kept_paragraph_follows_a_widow_controlled_next_paragraph() {
        let build = |widow_control: bool| {
            let mut document = fillers(44);
            add_line(&mut document, "Kept with next", 18.0, 0.0);
            document
                .paragraph_mut(44)
                .expect("the kept paragraph was just added")
                .set_keep_with_next(true);
            add_line(&mut document, BODY, 14.0, 0.0);
            document
                .paragraph_mut(45)
                .expect("the body was just added")
                .set_widow_control(widow_control);
            document
        };
        assert_eq!(pages_from(&build(true), 44), vec![2, 2]);
        // Without widow control the body leaves its first line on page 1.
        assert_eq!(pages_from(&build(false), 44), vec![1, 1]);
    }

    /// Two headings that keep with next and the body after them share a page:
    /// the whole chain moves when the body's first line does not fit. Layout
    /// checked each heading against the paragraph after it only, which left
    /// the first heading alone at the foot of page 1.
    #[test]
    fn a_chain_of_kept_paragraphs_moves_as_one() {
        let mut document = fillers(43);
        add_heading(&mut document, "Heading", 0.0);
        add_heading(&mut document, "Subheading", 0.0);
        add_line(&mut document, BODY, 14.0, 0.0);
        assert_eq!(pages_from(&document, 43), vec![2, 2, 2]);

        // A chain no page can hold still leaves from its first heading, as in
        // Word, and then breaks where page 2 ends: 36 headings of 18 points
        // fill its 648 points.
        let mut document = fillers(43);
        for index in 0..40 {
            add_heading(&mut document, &format!("Heading {index:02}"), 0.0);
        }
        add_line(&mut document, BODY, 14.0, 0.0);
        let mut expected = vec![2; 36];
        expected.resize(41, 3);
        assert_eq!(pages_from(&document, 43), expected);
    }

    /// A paragraph that keeps with next stays with the first row of the table
    /// after it, whose exact 24 point row fits under the paragraph but not
    /// under its 8 points after.
    #[test]
    fn a_kept_paragraph_follows_the_first_row_of_a_table() {
        let mut document = fillers(43);
        add_line(&mut document, "Kept with next", 18.0, 8.0);
        document
            .paragraph_mut(43)
            .expect("the kept paragraph was just added")
            .set_keep_with_next(true);
        {
            let mut table = document.add_table(2, 1);
            for row in 0..2 {
                table
                    .cell(row, 0)
                    .expect("cell exists")
                    .set_text(&format!("Row {row}"));
                table
                    .row(row)
                    .expect("row exists")
                    .set_height_exact(Length::pt(24.0));
            }
        }
        assert_eq!(pages_from(&document, 43), vec![2, 2]);
    }
}

mod row_minimum_height_split_regressions {
    use rdocx::{Document, Length};

    /// 43 fillers of 14 points leave 46 of the 648 point page, then a
    /// borderless one-cell table whose row holds four 14 point lines, with a
    /// minimum height of `minimum` points when there is one. Three lines, 42
    /// points, fit on page 1.
    fn probe(minimum: Option<f64>) -> Document {
        let mut document = Document::new();
        for index in 0..43 {
            let mut paragraph = document.add_paragraph(&format!("Filler {index:02}"));
            paragraph.set_line_spacing(14.0);
            paragraph.set_space_before(Length::pt(0.0));
            paragraph.set_space_after(Length::pt(0.0));
        }
        {
            let mut table = document.add_table(1, 1);
            table.set_cell_margins(
                Length::pt(0.0),
                Length::pt(5.0),
                Length::pt(0.0),
                Length::pt(5.0),
            );
            let mut cell = table.cell(0, 0).expect("cell exists");
            cell.set_text("Row line 0");
            for line in 1..4 {
                cell.add_paragraph(&format!("Row line {line}"));
            }
            for line in 0..4 {
                let mut paragraph = cell.paragraph_mut(line).expect("cell paragraph");
                paragraph.set_line_spacing(14.0);
                paragraph.set_space_before(Length::pt(0.0));
                paragraph.set_space_after(Length::pt(0.0));
            }
            if let Some(minimum) = minimum {
                table
                    .row(0)
                    .expect("row exists")
                    .set_height(Length::pt(minimum));
            }
        }
        document
    }

    /// The pages the table's row lands on.
    fn row_pages(document: &Document) -> Vec<usize> {
        let result = document
            .layout_deterministic()
            .expect("document lays out in deterministic font mode");
        result
            .body_layout_fragments(43)
            .expect("the table is body item 43")
            .iter()
            .map(|fragment| fragment.physical_page)
            .collect()
    }

    /// Word 16 splits a row with a minimum height only when the part that
    /// stays on the first page reaches that minimum, and otherwise moves the
    /// row whole. Layout split it whatever its minimum.
    #[test]
    fn a_row_splits_only_when_its_first_part_reaches_its_minimum_height() {
        assert_eq!(row_pages(&probe(None)), vec![1, 2]);
        assert_eq!(row_pages(&probe(Some(40.0))), vec![1, 2]);
        assert_eq!(row_pages(&probe(Some(44.0))), vec![2]);
        assert_eq!(row_pages(&probe(Some(100.0))), vec![2]);
    }
}

/// A border style the model did not list read as `none` and was written back
/// as `none` by the next edit, which removed the border in Word. Every
/// `ST_Border` token now survives an edit and a save, the picture borders of
/// a page frame included.
#[test]
fn every_border_style_token_survives_an_edit_and_save() {
    let xml = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:pPr><w:pBdr><w:top w:val="dashSmallGap" w:sz="12" w:space="1" w:color="FF0000"/><w:left w:val="dashDotStroked" w:sz="8" w:space="4"/><w:bottom w:val="thinThickThinSmallGap" w:sz="12" w:space="1"/><w:right w:val="thinThickThinLargeGap" w:sz="12" w:space="4"/></w:pBdr></w:pPr><w:r><w:t>Bordered</w:t></w:r></w:p><w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="720" w:footer="720" w:gutter="0"/><w:pgBorders w:offsetFrom="page"><w:top w:val="apples" w:sz="20" w:space="24"/><w:left w:val="thinThickThinMediumGap" w:sz="12" w:space="24"/><w:bottom w:val="zigZagStitch" w:sz="10" w:space="24"/><w:right w:val="custom" w:sz="10" w:space="24"/></w:pgBorders></w:sectPr></w:body></w:document>"#;
    let mut document = document_with_content_controls(xml);
    document.add_paragraph("Edited");
    let saved = document_xml(&mut document);
    for edge in [
        r#"<w:top w:val="dashSmallGap" w:sz="12" w:space="1" w:color="FF0000"/>"#,
        r#"<w:left w:val="dashDotStroked" w:sz="8" w:space="4"/>"#,
        r#"<w:bottom w:val="thinThickThinSmallGap" w:sz="12" w:space="1"/>"#,
        r#"<w:right w:val="thinThickThinLargeGap" w:sz="12" w:space="4"/>"#,
        r#"<w:top w:val="apples" w:sz="20" w:space="24"/>"#,
        r#"<w:left w:val="thinThickThinMediumGap" w:sz="12" w:space="24"/>"#,
        r#"<w:bottom w:val="zigZagStitch" w:sz="10" w:space="24"/>"#,
        r#"<w:right w:val="custom" w:sz="10" w:space="24"/>"#,
    ] {
        assert!(saved.contains(edge), "{edge} is missing from {saved}");
    }
    assert!(!saved.contains(r#"w:val="none""#), "{saved}");
}

/// Text holding a character XML 1.0 cannot carry reached `w:t`, `w:instrText`
/// and every other Word part raw, so the saved part was not well-formed and
/// Word could not open it. python-docx refuses such text, so the fallible
/// entry points refuse it naming the character and its position, and no save
/// writes it into any part, whichever setter stored it.
#[test]
fn text_xml_cannot_carry_is_refused_at_entry_and_never_saved() {
    let mut document = Document::new();
    document.add_paragraph("Dear {{NAME}}");
    let error = document
        .try_replace_text("{{NAME}}", "Ada\u{1}")
        .unwrap_err();
    assert!(
        error
            .to_string()
            .contains("replacement text holds U+0001 at character 4"),
        "{error}"
    );
    assert!(
        document
            .replace_all_regex(&[("NAME".to_owned(), "\u{b}".to_owned())])
            .is_err()
    );
    let range = RunRange {
        start: RunPosition {
            body_index: 0,
            run_index: 0,
        },
        end: RunPosition {
            body_index: 0,
            run_index: 1,
        },
    };
    let error = document
        .add_comment(range, "Ada", None, "see \u{c}")
        .unwrap_err();
    assert!(
        error
            .to_string()
            .contains("comment text holds U+000C at character 5"),
        "{error}"
    );
    let error = document
        .paragraph_mut(0)
        .unwrap()
        .run_mut(0)
        .unwrap()
        .add_field("PAGE\u{1f}", "1")
        .unwrap_err();
    assert!(
        error
            .to_string()
            .contains("field instruction holds U+001F at character 5"),
        "{error}"
    );
    document.to_bytes().expect("refused text changed nothing");

    // An infallible setter stores the text, and the save refuses it.
    document.add_paragraph("tab\tand\u{1}");
    let error = document.to_bytes().unwrap_err().to_string();
    assert!(
        error.contains("/word/document.xml holds U+0001 at line"),
        "{error}"
    );

    let mut document = Document::new();
    document.set_header("Header \u{ffff}");
    let error = document.to_bytes().unwrap_err().to_string();
    assert!(error.contains("holds U+FFFF at line"), "{error}");
    assert!(error.contains("/word/header"), "{error}");

    let mut document = Document::new();
    document.add_footnote("note \u{2}");
    let error = document.to_bytes().unwrap_err().to_string();
    assert!(
        error.contains("/word/footnotes.xml holds U+0002 at line"),
        "{error}"
    );
}

mod run_text_around_a_complex_field {
    use rdocx::Document;

    use super::{document_with_content_controls, document_xml, f252_page_text, wrap_word_body};

    fn text(value: &str) -> String {
        format!(r#"<w:t xml:space="preserve">{value}</w:t>"#)
    }

    fn field(instruction: &str, result: Option<&str>) -> String {
        let mut xml = format!(
            r#"<w:fldChar w:fldCharType="begin"/><w:instrText xml:space="preserve"> {instruction} </w:instrText>"#
        );
        if let Some(result) = result {
            xml.push_str(r#"<w:fldChar w:fldCharType="separate"/>"#);
            xml.push_str(&format!("<w:t>{result}</w:t>"));
        }
        xml.push_str(r#"<w:fldChar w:fldCharType="end"/>"#);
        xml
    }

    /// `Page {PAGE} of the report` in one run, as some producers write it.
    fn page_of_the_report() -> String {
        format!(
            "<w:r>{}{}{}</w:r>",
            text("Page "),
            field("PAGE", Some("1")),
            text(" of the report")
        )
    }

    fn document(paragraph: &str) -> Document {
        document_with_content_controls(&wrap_word_body(&format!("<w:p>{paragraph}</w:p>")))
    }

    #[test]
    fn text_in_the_run_of_a_complex_field_is_read_in_order() {
        let cases = [
            (page_of_the_report(), "Page 1 of the report"),
            (
                format!("<w:r>{}{}</w:r>", text("Page "), field("PAGE", Some("1"))),
                "Page 1",
            ),
            (
                format!(
                    "<w:r>{}{}</w:r>",
                    field("PAGE", Some("1")),
                    text(" of the report")
                ),
                "1 of the report",
            ),
            (
                format!(
                    "<w:r>{}{}{}{}{}</w:r>",
                    text("Page "),
                    field("PAGE", Some("1")),
                    text(" of "),
                    field("NUMPAGES", Some("3")),
                    text(" pages")
                ),
                "Page 1 of 3 pages",
            ),
            (
                format!(
                    "<w:r>{}{}{}</w:r>",
                    text("Page "),
                    field("PAGE", None),
                    text(" of the report")
                ),
                "Page  of the report",
            ),
            (
                format!(
                    "<w:r>{}<w:tab/>{}<w:br/>{}</w:r>",
                    text("A"),
                    field("PAGE", Some("1")),
                    text("B")
                ),
                "A\t1\nB",
            ),
            (
                format!(
                    r#"<w:r>{}<w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> PAGE </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>1</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/>{}</w:r>"#,
                    text("Page "),
                    text(" of the report")
                ),
                "Page 1 of the report",
            ),
        ];
        for (paragraph, expected) in cases {
            let mut document = document(&paragraph);
            assert_eq!(document.paragraphs()[0].text(), expected, "{paragraph}");
            assert_eq!(document.text(), format!("{expected}\n"), "{paragraph}");
            let saved = document_xml(&mut document);
            assert!(
                saved.contains(&format!("<w:p>{paragraph}</w:p>")),
                "an unedited save keeps the run bytes: {saved}"
            );
        }
    }

    #[test]
    fn text_around_a_field_is_read_in_cells_controls_and_insertions() {
        let run = page_of_the_report();
        let bodies = [
            format!(r#"<w:tbl><w:tr><w:tc><w:p>{run}</w:p></w:tc></w:tr></w:tbl>"#),
            format!(r#"<w:p><w:sdt><w:sdtPr/><w:sdtContent>{run}</w:sdtContent></w:sdt></w:p>"#),
            format!(
                r#"<w:p><w:ins w:id="1" w:author="A" w:date="2026-01-01T00:00:00Z">{run}</w:ins></w:p>"#
            ),
        ];
        for body in bodies {
            let mut document = document_with_content_controls(&wrap_word_body(&body));
            assert!(
                document.text().contains("Page 1 of the report"),
                "{body}: {:?}",
                document.text()
            );
            assert!(document_xml(&mut document).contains(&body), "{body}");
        }
    }

    /// A document whose body holds `pages` pages and whose footer holds
    /// `footer_paragraph`, with the footer part name and its exact XML.
    fn footer_document(footer_paragraph: &str, pages: usize) -> (Document, String, String) {
        let mut seed = Document::new();
        for page in 0..pages {
            seed.add_paragraph("Body text")
                .set_page_break_before(page > 0);
        }
        seed.set_footer("placeholder");
        let mut package =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(seed.to_bytes().unwrap()))
                .unwrap();
        let footer = (1..=3)
            .map(|index| format!("/word/footer{index}.xml"))
            .find(|name| package.contains_part(name))
            .expect("a footer part");
        let footer_xml = format!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:ftr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:p>{footer_paragraph}</w:p></w:ftr>"#
        );
        package.set_part(&footer, footer_xml.clone().into_bytes());
        let mut bytes = std::io::Cursor::new(Vec::new());
        package.write_to(&mut bytes).unwrap();
        (
            Document::from_bytes(&bytes.into_inner()).unwrap(),
            footer,
            footer_xml,
        )
    }

    #[test]
    fn the_renderer_paints_text_around_a_footer_page_field() {
        let (mut document, footer, footer_xml) = footer_document(&page_of_the_report(), 1);

        assert_eq!(
            document.footer_text().as_deref(),
            Some("Page 1 of the report")
        );
        let layout = document.layout_deterministic().unwrap();
        let page = f252_page_text(&layout.layout.pages[0]);
        assert!(page.contains("Page 1 of the report"), "{page:?}");

        let saved =
            oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(document.to_bytes().unwrap()))
                .unwrap();
        assert_eq!(saved.get_part(&footer).unwrap(), footer_xml.as_bytes());
    }

    #[test]
    fn replacing_text_around_a_field_keeps_the_field() {
        let mut document = document(&page_of_the_report());
        assert_eq!(document.replace_text("Page", "Folio"), 1);
        assert_eq!(document.replace_text("report", "summary"), 1);
        let saved = document.to_bytes().unwrap();
        let xml = {
            let mut reopened = Document::from_bytes(&saved).unwrap();
            document_xml(&mut reopened)
        };
        assert_eq!(xml.matches(r#"w:fldCharType="begin""#).count(), 1, "{xml}");
        assert_eq!(xml.matches("Folio").count(), 1, "{xml}");
        assert!(!xml.contains("report"), "{xml}");
        let reopened = Document::from_bytes(&saved).unwrap();
        assert_eq!(reopened.paragraphs()[0].text(), "Folio 1 of the summary");

        // Two fields in one run, with the text between them edited.
        let mut document = self::document(&format!(
            "<w:r>{}{}{}{}</w:r>",
            text("Page "),
            field("PAGE", Some("1")),
            text(" of "),
            field("NUMPAGES", Some("3"))
        ));
        assert_eq!(document.replace_text(" of ", " out of "), 1);
        let xml = document_xml(&mut document);
        assert_eq!(xml.matches(r#"w:fldCharType="begin""#).count(), 2, "{xml}");
        assert_eq!(xml.matches("Page ").count(), 1, "{xml}");
        let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.paragraphs()[0].text(), "Page 1 out of 3");
    }

    #[test]
    fn a_comment_can_anchor_on_text_around_a_field() {
        let mut document = document(&page_of_the_report());
        document
            .add_comment_on_text("the report", 0, "Ada", None, "Here", None)
            .unwrap();
        let xml = document_xml(&mut document);
        let start = xml.find("<w:commentRangeStart").expect("a comment range");
        let end = xml.find("<w:commentRangeEnd").expect("a comment range");
        assert!(xml[start..end].contains("the report"), "{xml}");
        assert_eq!(xml.matches(r#"w:fldCharType="begin""#).count(), 1, "{xml}");
        let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.paragraphs()[0].text(), "Page 1 of the report");
    }

    #[test]
    fn comparison_sees_text_around_a_field() {
        let mut original = document(&page_of_the_report());
        let edited = document(&page_of_the_report().replace("the report", "the summary"));
        original
            .compare(&edited, "R", "2026-09-30T00:00:00Z")
            .unwrap();
        assert!(!original.revisions().is_empty(), "the edit is a revision");
        let xml = document_xml(&mut original);
        assert_eq!(xml.matches(r#"w:fldCharType="begin""#).count(), 1, "{xml}");
        assert!(xml.contains(" of the report</w:delText>"), "{xml}");
        let reopened = Document::from_bytes(&original.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.paragraphs()[0].text(), "Page 1 of the summary");
    }

    #[test]
    fn updating_a_field_keeps_the_text_of_its_run() {
        let mut document = document(&page_of_the_report());
        let body = document.stories().unwrap().remove(0);
        let field = document
            .story_items(&body)
            .unwrap()
            .into_iter()
            .find(|item| item.kind() == rdocx::StoryItemKind::Field)
            .expect("the PAGE field is a story item")
            .location()
            .clone();
        document.set_story_text(&field, "7").unwrap();
        let xml = document_xml(&mut document);
        assert_eq!(xml.matches("Page ").count(), 1, "{xml}");
        assert_eq!(xml.matches(" of the report").count(), 1, "{xml}");
        let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.paragraphs()[0].text(), "Page 7 of the report");
    }

    /// Field A begins in the first run and ends in the second, where field B
    /// begins, and B ends in the third.
    fn overlapping_fields() -> String {
        concat!(
            r#"<w:r><w:t xml:space="preserve">A </w:t><w:fldChar w:fldCharType="begin"/><w:instrText> PAGE </w:instrText><w:fldChar w:fldCharType="separate"/><w:t>1</w:t></w:r>"#,
            r#"<w:r><w:fldChar w:fldCharType="end"/><w:t xml:space="preserve"> mid </w:t><w:fldChar w:fldCharType="begin"/><w:instrText> NUMPAGES </w:instrText><w:fldChar w:fldCharType="separate"/></w:r>"#,
            r#"<w:r><w:t>9</w:t><w:fldChar w:fldCharType="end"/><w:t xml:space="preserve"> Z</w:t></w:r>"#,
        )
        .to_owned()
    }

    #[test]
    fn fields_that_share_a_run_keep_every_run_through_a_save() {
        let paragraphs = format!(
            "<w:p>{}</w:p><w:p><w:r><w:t>Hello world</w:t></w:r></w:p>",
            overlapping_fields()
        );
        let source = document_with_content_controls(&wrap_word_body(&paragraphs));
        assert_eq!(source.paragraphs()[0].text(), "A 1 mid 9 Z");

        let mut edited = document_with_content_controls(&wrap_word_body(&paragraphs));
        assert_eq!(edited.replace_text("Hello", "Bye"), 1);
        let xml = document_xml(&mut edited);
        assert!(xml.contains(&overlapping_fields()), "{xml}");
        assert_eq!(xml.matches("NUMPAGES").count(), 1, "{xml}");
        let reopened = Document::from_bytes(&edited.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.paragraphs()[0].text(), "A 1 mid 9 Z");

        let mut compared = document_with_content_controls(&wrap_word_body(&paragraphs));
        compared
            .compare(&reopened, "R", "2026-09-30T00:00:00Z")
            .unwrap();
        let xml = document_xml(&mut compared);
        assert!(xml.contains(&overlapping_fields()), "{xml}");
    }

    #[test]
    fn layout_backed_updates_reach_two_fields_in_one_footer_run() {
        let run = format!(
            "<w:r>{}{}{}{}</w:r>",
            text("Page "),
            field("PAGE", Some("9")),
            text(" of "),
            field("NUMPAGES", Some("9"))
        );
        let (mut document, footer, _) = footer_document(&run, 2);
        let report = document.update_layout_backed_fields().unwrap();
        assert_eq!(report.updated_count(), 0);
        assert_eq!(document.footer_text().as_deref(), Some("Page 9 of 9"));

        let saved = document.to_bytes().unwrap();
        let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&saved)).unwrap();
        let xml = std::str::from_utf8(package.get_part(&footer).unwrap()).unwrap();
        assert_eq!(xml.matches(r#"w:fldCharType="begin""#).count(), 2, "{xml}");
        assert_eq!(xml.matches("Page ").count(), 1, "{xml}");
        let reopened = Document::from_bytes(&saved).unwrap();
        assert_eq!(reopened.footer_text().as_deref(), Some("Page 9 of 9"));

        // The same run in the body.
        let mut document = self::document(&run);
        document.update_layout_backed_fields().unwrap();
        assert_eq!(document.paragraphs()[0].text(), "Page 1 of 1");
        let reopened = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.paragraphs()[0].text(), "Page 1 of 1");
    }
}

