#[test]
fn all_sequence_story_controls_match_authenticated_word_and_physical_pages() {
    use base64::Engine as _;
    // Source SHA ff0937b6623d1ab52f4eea4d75980c62e26d9d5a80684ac12f15bc779a9dd9dd.
    // Native post-close SHA e0127ff029da72d1b861ce825d1924d18ccaed625fefb56980a57ed747cffa6c.
    // Actual no-F9 reopened SHA d870d0a4e355ecee5c067b77c004de4ad48f58488b6af15775a3f49c91ee848f.
    // The shared header/footer saved cache is lifecycle-dependent. Native actual pages repeat 14 then 16.
    let bytes = base64::engine::general_purpose::STANDARD.decode("").unwrap();
    let expected = [
        ("SEQ Control \\n", "1", "B-NEXT", false),
        ("SEQ Control \\c", "1", "B-REPEAT", false),
        ("SEQ Control \\r 7", "7", "B-RESTART", false),
        ("SEQ Control", "8", "B-AFTER-RESTART", false),
        ("SEQ Control \\h", "", "B-HIDDEN", false),
        ("SEQ Control", "10", "B-AFTER-HIDDEN", false),
        ("SEQ Control \\h \\* ARABIC", "11", "B-HIDDEN-ARABIC", false),
        ("SEQ Control \\h \\* roman", "xii", "B-HIDDEN-roman", false),
        ("SEQ Control", "13", "B-AFTER-HIDDEN-FORMAT", false),
        ("SEQ cOnTrOl", "14", "B-CASE-IDENTIFIER", false),
        ("SEQ ChapterFigure \\s 1", "1", "B-HEADING-A-FIRST", false),
        ("SEQ ChapterFigure \\s 1", "2", "B-HEADING-A-SECOND", false),
        ("SEQ ChapterFigure \\s 1", "3", "B-HEADING2-CONTINUE", false),
        ("SEQ ChapterFigure \\s 1", "1", "B-HEADING-B-FIRST", false),
        ("SEQ ChapterFigure \\c", "1", "B-HEADING-B-REPEAT", false),
        ("SEQ Control", "Error! Main Document Only.", "H-NEXT", false),
        ("SEQ Control \\c", "16", "H-REPEAT", true),
        (
            "SEQ Control",
            "Error! Main Document Only.",
            "H-AFTER",
            false,
        ),
        ("SEQ Control", "Error! Main Document Only.", "F-NEXT", false),
        ("SEQ Control \\c", "16", "F-REPEAT", true),
        (
            "SEQ Control",
            "Error! Main Document Only.",
            "F-AFTER",
            false,
        ),
        (
            "SEQ Control",
            "Error! Main Document Only.",
            "FN1-NEXT",
            false,
        ),
        ("SEQ Control \\c", "14", "FN1-REPEAT", false),
        (
            "SEQ Control",
            "Error! Main Document Only.",
            "FN1-AFTER",
            false,
        ),
        (
            "SEQ Control",
            "Error! Main Document Only.",
            "FN2-NEXT",
            false,
        ),
        ("SEQ Control \\c", "14", "FN2-REPEAT", false),
        (
            "SEQ Control",
            "Error! Main Document Only.",
            "FN2-AFTER",
            false,
        ),
        (
            "SEQ Control",
            "Error! Main Document Only.",
            "EN-NEXT",
            false,
        ),
        ("SEQ Control \\c", "14", "EN-REPEAT", false),
        (
            "SEQ Control",
            "Error! Main Document Only.",
            "EN-AFTER",
            false,
        ),
        ("SEQ Control", "15", "BOX-NEXT", false),
        ("SEQ Control \\c", "15", "BOX-REPEAT", false),
        ("SEQ Control", "16", "BOX-AFTER", false),
    ];
    let mut document = Document::from_bytes(&bytes).unwrap();
    let before = document.to_bytes().unwrap();
    let fields = document.evaluate_fields(&Default::default()).unwrap();
    assert_eq!(fields.len(), expected.len());
    for (field, (instruction, value, label, repeat)) in fields.iter().zip(expected) {
        assert_eq!(field.instruction.trim(), instruction, "{label}");
        if repeat {
            assert!(
                matches!(&field.outcome, FieldOutcome::KeepStored { diagnostic } if diagnostic.contains("no unique physical document context")),
                "{label}: {:?}",
                field.outcome
            );
        } else {
            assert_eq!(
                field.outcome,
                FieldOutcome::Resolved(value.into()),
                "{label}"
            );
        }
    }
    assert_eq!(document.to_bytes().unwrap(), before);
    let mut overridden = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&bytes)).unwrap();
    let mut xml =
        String::from_utf8(overridden.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
    let style = xml.find("<w:pStyle w:val=\"Heading1\"/>").unwrap();
    let end = style + xml[style..].find("</w:pPr>").unwrap();
    xml.insert_str(end, "<w:outlineLvl w:val=\"9\"/>");
    overridden.set_part("/word/document.xml", xml.into_bytes());
    let mut override_bytes = std::io::Cursor::new(Vec::new());
    overridden.write_to(&mut override_bytes).unwrap();
    let explicit_override = Document::from_bytes(override_bytes.get_ref()).unwrap();
    let outcomes = explicit_override
        .evaluate_fields(&Default::default())
        .unwrap();
    let first = outcomes
        .iter()
        .find(|field| field.cached_result == "OLD-B-HEADING-A-FIRST")
        .unwrap();
    assert!(
        matches!(&first.outcome, FieldOutcome::KeepStored {diagnostic} if diagnostic.contains("no matching heading")),
        "explicit outline override remains authoritative: {:?}",
        first.outcome
    );
    for pass in 0..2 {
        let layout = document.layout_deterministic().unwrap();
        assert_eq!(layout.layout.pages.len(), 2, "pass {pass}");
        for (index, page) in layout.layout.pages.iter().enumerate() {
            let text = f252_page_text(page);
            let mut repeats = Vec::new();
            oxml_layout::walk(&page.elements, &mut |element, _| match element {
                oxml_layout::PositionedElement::Text(run)
                    if run.field_kind == Some(oxml_layout::FieldKind::SequenceRepeat) =>
                {
                    repeats.push(run.text.clone())
                }
                oxml_layout::PositionedElement::MultilingualText(run)
                    if run.field_kind == Some(oxml_layout::FieldKind::SequenceRepeat) =>
                {
                    repeats.push(run.logical_text.clone())
                }
                _ => {}
            });
            assert_eq!(
                repeats,
                vec![if index == 0 { "14" } else { "16" }; 2],
                "one substituted segment per furniture repeat"
            );
            for story in ["H", "F"] {
                assert!(
                    text.contains(&format!(
                        "{story}-REPEAT = {}",
                        if index == 0 { 14 } else { 16 }
                    )),
                    "pass {pass} page {index}: {text}"
                );
                assert!(
                    text.contains(&format!("{story}-NEXT = Error! Main Document Only.")),
                    "{text}"
                );
                assert!(
                    text.contains(&format!("{story}-AFTER = Error! Main Document Only.")),
                    "{text}"
                );
            }
        }
        let text = layout
            .layout
            .pages
            .iter()
            .map(|page| f252_page_text(page))
            .collect::<String>();
        for (_, value, label, repeat) in expected {
            if !repeat {
                assert!(
                    text.contains(&format!("{label} = {value}")),
                    "{label}: {text}"
                );
            }
        }
        assert_eq!(
            document.update_fields(&Default::default()).unwrap(),
            expected.len()
        );
        document = Document::from_bytes(&document.to_bytes().unwrap()).unwrap();
        for (field, (instruction, value, label, repeat)) in document
            .evaluate_fields(&Default::default())
            .unwrap()
            .iter()
            .zip(expected)
        {
            assert_eq!(field.instruction.trim(), instruction, "{label}");
            if !repeat {
                assert_eq!(field.cached_result, value, "{label}");
            }
        }
    }
}

#[test]
fn ref_f_all_captured_story_owners_preserve_selected_and_fallback_graphs() {
    use base64::Engine as _;
    // Authenticated source SHA 850f3e823b02dc1c20aed0cb684a90f2be150b1e4f6b7a9d06b45e6e6b2b2758.
    // Completed five-context native update and actual no-F9 reopen SHA 1fa8d987b9b9bf28784347dd6fc5a4c1f53f45352e2bfa06fb553810d28be78c.
    // All31 native rich wire contracts are stable. The library selects22 owners and preserves9 unselected fallback caches.
    let bytes = base64::engine::general_purpose::STANDARD.decode("").unwrap();
    let expected = [
        ("REF F280_FN_MARK \\f", "", "B-F-BEFORE"),
        ("REF F280_FN_MARK \\f", "", "B-F-AFTER"),
        (
            "REF F280_FN_WHOLE \\f",
            "FN-PRODUCER-SOURCE = ",
            "B-F-WHOLE",
        ),
        ("REF F280_FN_MARK \\f \\h", "", "B-F-HYPERLINK"),
        ("REF F280_FN_MARK", "", "B-TEXT-CONTROL"),
        ("REF F280_FN_MARK \\f", "", "HEADER-MARK"),
        (
            "REF F280_FN_WHOLE \\f",
            "FN-PRODUCER-SOURCE = ",
            "HEADER-WHOLE",
        ),
        ("REF F280_FN_MARK", "", "HEADER-TEXT"),
        ("REF F280_FN_MARK \\f", "", "FOOTER-MARK"),
        (
            "REF F280_FN_WHOLE \\f",
            "FN-PRODUCER-SOURCE = ",
            "FOOTER-WHOLE",
        ),
        ("REF F280_FN_MARK", "", "FOOTER-TEXT"),
        ("REF F280_FN_MARK \\f", "", "NOTE-F-BEFORE-CONTEXT"),
        (
            "REF F280_FN_WHOLE \\f",
            "FN-PRODUCER-SOURCE = ",
            "NOTE-F-AFTER-CONTEXT",
        ),
        ("REF F280_FN_MARK \\f", "", "BODY-BOX-MARK"),
        (
            "REF F280_FN_WHOLE \\f",
            "FN-PRODUCER-SOURCE = ",
            "BODY-BOX-WHOLE",
        ),
        ("REF F280_FN_MARK", "", "BODY-BOX-TEXT"),
        ("REF F280_FN_MARK \\f", "", "HEADER-BOX-MARK"),
        (
            "REF F280_FN_WHOLE \\f",
            "FN-PRODUCER-SOURCE = ",
            "HEADER-BOX-WHOLE",
        ),
        ("REF F280_FN_MARK", "", "HEADER-BOX-TEXT"),
        ("REF F280_FN_MARK \\f", "", "FOOTER-BOX-MARK"),
        (
            "REF F280_FN_WHOLE \\f",
            "FN-PRODUCER-SOURCE = ",
            "FOOTER-BOX-WHOLE",
        ),
        ("REF F280_FN_MARK", "", "FOOTER-BOX-TEXT"),
    ];
    let source = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&bytes)).unwrap();
    let fallbacks = [
        "/word/document.xml",
        "/word/header1.xml",
        "/word/footer1.xml",
    ]
    .map(|part| {
        let xml = String::from_utf8(source.get_part(part).unwrap().to_vec()).unwrap();
        let start = xml.find("<mc:Fallback").unwrap();
        let end = start + xml[start..].find("</mc:Fallback>").unwrap() + "</mc:Fallback>".len();
        (part, xml[start..end].to_owned())
    });
    let mut document = Document::from_bytes(&bytes).unwrap();
    let before = document.to_bytes().unwrap();
    let fields = document.evaluate_fields(&Default::default()).unwrap();
    assert_eq!(fields.len(), expected.len());
    for (field, (instruction, value, label)) in fields.iter().zip(expected) {
        assert_eq!(field.instruction.trim(), instruction, "{label}");
        assert_eq!(
            field.outcome,
            FieldOutcome::Resolved(value.into()),
            "{label}"
        );
    }
    assert_eq!(document.to_bytes().unwrap(), before);
    for _ in 0..2 {
        assert_eq!(
            document.update_fields(&Default::default()).unwrap(),
            expected.len()
        );
        let bytes = document.to_bytes().unwrap();
        let package = oxml_opc::OpcPackage::from_reader(std::io::Cursor::new(&bytes)).unwrap();
        for (part, fallback) in &fallbacks {
            let xml = String::from_utf8(package.get_part(part).unwrap().to_vec()).unwrap();
            assert!(
                xml.contains(fallback),
                "unselected fallback {part} remains verbatim"
            );
        }
        let body =
            String::from_utf8(package.get_part("/word/document.xml").unwrap().to_vec()).unwrap();
        let notes =
            String::from_utf8(package.get_part("/word/footnotes.xml").unwrap().to_vec()).unwrap();
        assert_eq!(body.matches("<w:footnoteReference ").count(), 6);
        assert_eq!(
            notes.matches("<w:footnote ").count(),
            6,
            "six normal owners, no growth"
        );
        document = Document::from_bytes(&bytes).unwrap();
        let fields = document.evaluate_fields(&Default::default()).unwrap();
        assert_eq!(fields.len(), expected.len());
        for (field, (instruction, value, label)) in fields.iter().zip(expected) {
            assert_eq!(field.instruction.trim(), instruction, "{label}");
            assert_eq!(field.cached_result, value, "{label}");
        }
        let layout = document.layout_deterministic().unwrap();
        let painted = layout
            .layout
            .pages
            .iter()
            .map(|page| f252_page_text(page))
            .collect::<String>();
        for label in [
            "BODY-BOX-WHOLE",
            "HEADER-WHOLE",
            "HEADER-BOX-WHOLE",
            "FOOTER-WHOLE",
            "FOOTER-BOX-WHOLE",
        ] {
            assert!(
                painted.contains(&format!("{label} = FN-PRODUCER-SOURCE = ")),
                "{label}: {painted}"
            );
        }
    }
}

#[test]
fn generated_table_authoring_smoke_test() {
    let mut document = Document::new();
    document.add_paragraph("Alpha");
    let story = f254_story(&document, StoryKind::Body);
    let location = f254_item(&document, &story, 0);
    let position = StoryRunPosition {
        location: location.clone(),
        run_index: 0,
    };
    document
        .insert_index_entry(
            &position,
            &rdocx::IndexEntry {
                levels: vec!["Alpha".into()],
                identifier: None,
                page_range_bookmark: None,
                cross_reference: None,
                bold_page_numbers: false,
                italic_page_numbers: false,
            },
        )
        .unwrap();
    let story = f254_story(&document, StoryKind::Body);
    let location = f254_item(&document, &story, 0);
    document
        .insert_index(&location, &rdocx::IndexOptions::default())
        .unwrap();
    let report = document.rebuild_generated_tables().unwrap();
    assert_eq!(report.index_entries, 1);
}

fn f281_paragraph(d: &mut Document, index: &mut usize, text: &str, page: bool) -> usize {
    let n = *index;
    d.add_paragraph(text).set_page_break_before(page);
    *index += 1;
    n
}
fn f281_field(
    d: &mut Document,
    index: &mut usize,
    label: &str,
    instr: &str,
    cache: &str,
    hidden: bool,
) -> rdocx::Result<usize> {
    let n = *index;
    let mut p = d.add_paragraph(label);
    let mut r = p.add_run("");
    r.set_hidden(hidden);
    if hidden {
        let mut cached = CT_R::new(cache);
        cached.properties = Some(CT_RPr {
            vanish: Some(true),
            ..Default::default()
        });
        r.add_field_value(rdocx_oxml::text::Field::from_raw(
            instr,
            rdocx_oxml::text::FieldForm::Complex,
            vec![cached],
        )?)?;
    } else {
        r.add_field(instr, cache)?;
    }
    *index += 1;
    Ok(n)
}
fn f281_output(d: &mut Document, index: &mut usize, label: &str, instr: &str) -> rdocx::Result<()> {
    f281_paragraph(d, index, &format!("F281_OUTPUT_BEGIN_{label}"), false);
    f281_field(
        d,
        index,
        "",
        instr,
        &format!("OLD_F281_OUTPUT_{label}"),
        false,
    )?;
    f281_paragraph(d, index, &format!("F281_OUTPUT_END_{label}"), false);
    Ok(())
}
fn f281_save(mut d: Document) -> rdocx::Result<Document> {
    for i in 0..d.paragraphs().len() {
        if let Some(mut p) = d.paragraph_mut(i) {
            for j in 0..p.run_count() {
                if let Some(mut r) = p.run_mut(j) {
                    r.set_language("en-US");
                }
            }
        }
    }
    let bytes = d.to_bytes()?;
    let mut reopened = Document::from_bytes(&bytes)?;
    let _ = reopened.to_bytes()?;
    Ok(reopened)
}
fn f281_index_probe(changed: bool) -> rdocx::Result<Document> {
    f281_index_probe_with_chapters(changed, false)
}
fn f281_index_probe_with_chapters(changed: bool, chapters: bool) -> rdocx::Result<Document> {
    let mut d = Document::new();
    let mut n = 0;
    f281_paragraph(
        &mut d,
        &mut n,
        "F281 INDEX source probe. OLD caches are not Word evidence.",
        false,
    );
    if chapters {
        let value = if changed { 3 } else { 2 };
        f281_field(
            &mut d,
            &mut n,
            "F281_SEQ_CHAPTER_PAGE_1 ",
            &format!("SEQ Chapter \\r {value}"),
            &value.to_string(),
            false,
        )?;
    }
    f281_field(
        &mut d,
        &mut n,
        "SRC_X01 ",
        if changed {
            r#"XE "Zebra renamed""#
        } else {
            r#"XE "Zebra""#
        },
        "OLD_XE_X01",
        true,
    )?;
    f281_field(
        &mut d,
        &mut n,
        "SRC_X02 ",
        r#"XE "Alpha:Beta:Gamma" \b"#,
        "OLD_XE_X02",
        true,
    )?;
    f281_field(
        &mut d,
        &mut n,
        "SRC_X03 ",
        r#"XE "Alpha:Delta" \i"#,
        "OLD_XE_X03",
        true,
    )?;
    if !changed {
        f281_field(
            &mut d,
            &mut n,
            "SRC_X04 ",
            r#"XE "Alpha:Beta:Gamma" \b"#,
            "OLD_XE_X04",
            true,
        )?;
    }
    f281_field(
        &mut d,
        &mut n,
        "SRC_X05 ",
        r#"XE "Alias" \t "See Alpha""#,
        "OLD_XE_X05",
        true,
    )?;
    f281_field(
        &mut d,
        &mut n,
        "SRC_X06 ",
        r#"XE "Filtered A" \f "a""#,
        "OLD_XE_X06",
        true,
    )?;
    f281_field(
        &mut d,
        &mut n,
        "SRC_X07 ",
        r#"XE "Filtered B" \f "b""#,
        "OLD_XE_X07",
        true,
    )?;
    let start = f281_paragraph(&mut d, &mut n, "F281_RANGE_START", false);
    f281_paragraph(&mut d, &mut n, "SOURCE_PAGE_2", true);
    if chapters {
        let value = if changed { 8 } else { 7 };
        f281_field(
            &mut d,
            &mut n,
            "F281_SEQ_CHAPTER_PAGE_2 ",
            &format!("SEQ Chapter \\r {value}"),
            &value.to_string(),
            false,
        )?;
    }

    f281_field(
        &mut d,
        &mut n,
        "SRC_X08 ",
        r#"XE "Alpha:Beta:Gamma" \i"#,
        "OLD_XE_X08",
        true,
    )?;
    f281_field(
        &mut d,
        &mut n,
        "SRC_X09 ",
        r#"XE "Range Alpha" \r F281IndexRange \b \i"#,
        "OLD_XE_X09",
        true,
    )?;
    f281_field(
        &mut d,
        &mut n,
        "SRC_X10 ",
        r#"XE "alpha""#,
        "OLD_XE_X10",
        true,
    )?;
    f281_paragraph(&mut d, &mut n, "SOURCE_PAGE_3", true);
    if chapters {
        let value = if changed { 12 } else { 11 };
        f281_field(
            &mut d,
            &mut n,
            "F281_SEQ_CHAPTER_PAGE_3 ",
            &format!("SEQ Chapter \\r {value}"),
            &value.to_string(),
            false,
        )?;
    }

    let end = f281_paragraph(&mut d, &mut n, "F281_RANGE_END", false);
    d.add_bookmark(
        "F281IndexRange",
        RunRange {
            start: RunPosition {
                body_index: start,
                run_index: 0,
            },
            end: RunPosition {
                body_index: end,
                run_index: 1,
            },
        },
    )?;
    if changed {
        f281_field(
            &mut d,
            &mut n,
            "SRC_MUT_X11 ",
            r#"XE "Aardvark:Inserted" \b"#,
            "OLD_XE_MUT_X11",
            true,
        )?;
        f281_field(
            &mut d,
            &mut n,
            "SRC_MUT_X12 ",
            r#"XE "Zebra""#,
            "OLD_XE_MUT_X12",
            true,
        )?;
    }
    f281_paragraph(&mut d, &mut n, "GENERATED_RESULTS_ONLY", true);
    f281_output(&mut d, &mut n, "INDEX_DEFAULT", r#"INDEX \z 1033"#)?;
    f281_output(
        &mut d,
        &mut n,
        "INDEX_SEPARATORS",
        r#"INDEX \z 1033 \h "A" \e " | " \l "; " \g " to " \k " => ""#,
    )?;
    f281_output(&mut d, &mut n, "INDEX_RUNIN", r#"INDEX \z 1033 \r"#)?;
    f281_output(&mut d, &mut n, "INDEX_A", r#"INDEX \z 1033 \f "a""#)?;
    if chapters {
        f281_output(
            &mut d,
            &mut n,
            "INDEX_CHAPTER_DEFAULT",
            r#"INDEX \z 1033 \h "A" \e " | " \l "; " \g " to " \s Chapter"#,
        )?;
        f281_output(
            &mut d,
            &mut n,
            "INDEX_CHAPTER_K",
            r#"INDEX \z 1033 \h "A" \e " | " \l "; " \g " to " \s Chapter \k " => ""#,
        )?;
    }
    f281_save(d)
}
fn f281_figure_probe(changed: bool) -> rdocx::Result<Document> {
    let mut d = Document::new();
    let mut n = 0;
    d.add_style(StyleBuilder::paragraph("F281Caption", "F281 Caption"))?;
    d.add_style(StyleBuilder::paragraph("F281Other", "F281 Other"))?;
    f281_paragraph(
        &mut d,
        &mut n,
        "F281 caption and style sources. All SEQ caches are OLD.",
        false,
    );
    for (i, label, title, style, page) in [
        (1, "Figure", "Mercury", "F281Caption", false),
        (2, "Table", "Counts", "F281Caption", false),
        (3, "Equation", "Energy", "F281Other", true),
        (4, "Figure", "Venus", "F281Other", false),
        (5, "Exhibit", "Custom label", "F281Caption", true),
    ] {
        if changed && label == "Table" {
            continue;
        }
        let title = if changed && title == "Venus" {
            "Venus renamed"
        } else {
            title
        };
        let mut p = d.add_paragraph(&format!("{label} "));
        p.set_style(style);
        p.set_page_break_before(page);
        p.add_run("")
            .add_field(&format!("SEQ {label} \\* ARABIC"), &format!("OLD_SEQ_{i}"))?;
        p.add_run(&format!(": {title} [SRC_C{i:02}]"));
        n += 1;
    }
    d.add_paragraph("Figure 99: Plain text decoy [SRC_C06]")
        .set_style("F281Other");
    n += 1;
    d.add_paragraph("Styled text without a sequence [SRC_C07]")
        .set_style("F281Caption");
    n += 1;
    if changed {
        let mut p = d.add_paragraph("Figure ");
        p.set_style("F281Caption");
        p.add_run("")
            .add_field("SEQ Figure \\* ARABIC", "OLD_SEQ_MUT_C08")?;
        p.add_run(": Mars inserted [SRC_MUT_C08]");
        n += 1;
    }
    f281_paragraph(&mut d, &mut n, "GENERATED_RESULTS_ONLY", true);
    for (label, instr) in [
        ("FIGURE_FULL", r#"TOC \c "Figure" \h"#),
        ("FIGURE_TEXT", r#"TOC \a "Figure" \h"#),
        ("TABLE", r#"TOC \c "Table" \h"#),
        ("EQUATION", r#"TOC \c "Equation" \h"#),
        ("EXHIBIT", r#"TOC \c "Exhibit" \h"#),
        ("STYLE", r#"TOC \t "F281 Caption,1" \h"#),
        ("FIGURE_STYLE", r#"TOC \c "Figure" \t "F281 Caption,1" \h"#),
    ] {
        f281_output(&mut d, &mut n, label, instr)?;
    }
    f281_save(d)
}
fn f281_authority_probe(changed: bool) -> rdocx::Result<Document> {
    let mut d = Document::new();
    let mut n = 0;
    f281_paragraph(
        &mut d,
        &mut n,
        "F281 authority sources. Show hidden text OFF before pagination.",
        false,
    );
    let mut start = 0;
    let mut end = 0;
    for page in 1..=6 {
        f281_paragraph(&mut d, &mut n, &format!("SOURCE_PAGE_{page}"), page > 1);
        if page == 2 {
            start = f281_paragraph(&mut d, &mut n, "F281_AUTH_RANGE_START", false);
        }
        f281_field(
            &mut d,
            &mut n,
            &format!("SRC_TA_ALPHA_{page} "),
            r#"TA \l "Alpha v. Zenith, 100 F.3d 200 (2000)" \s "Alpha" \c 1"#,
            &format!("OLD_TA_ALPHA_{page}"),
            true,
        )?;
        if page <= 4 {
            f281_field(
                &mut d,
                &mut n,
                &format!("SRC_TA_BETA_{page} "),
                r#"TA \l "Beta v. Delta, 200 F.3d 300 (2001)" \s "Beta" \c 1"#,
                &format!("OLD_TA_BETA_{page}"),
                true,
            )?;
        }
        if page == 1 {
            f281_field(
                &mut d,
                &mut n,
                "SRC_TA_DUPLICATE ",
                r#"TA \l "Alpha v. Zenith, 100 F.3d 200 (2000)" \s "Alpha" \c 1 \b"#,
                "OLD_TA_DUPLICATE",
                true,
            )?;
            f281_field(
                &mut d,
                &mut n,
                "SRC_TA_ZETA ",
                if changed {
                    r#"TA \l "Zeta renamed v. Able, 300 F.3d 400 (2002)" \s "Zeta renamed" \c 1 \i"#
                } else {
                    r#"TA \l "Zeta v. Able, 300 F.3d 400 (2002)" \s "Zeta" \c 1 \i"#
                },
                "OLD_TA_ZETA",
                true,
            )?;
            f281_field(
                &mut d,
                &mut n,
                "SRC_TA_STATUTE ",
                r#"TA \l "F281 Statute section 12" \s "Section 12" \c 2"#,
                "OLD_TA_STATUTE",
                true,
            )?;
            f281_field(
                &mut d,
                &mut n,
                "SRC_TA_TREATISE ",
                r#"TA \l "F281 Treatise, chapter 9" \s "Treatise" \c 5"#,
                "OLD_TA_TREATISE",
                true,
            )?;
        }
        if page == 3 {
            f281_field(
                &mut d,
                &mut n,
                "SRC_TA_RANGE ",
                r#"TA \l "Range v. Pages, 400 F.3d 500 (2003)" \s "Range" \c 1 \r F281AuthorityRange \b \i"#,
                "OLD_TA_RANGE",
                true,
            )?;
        }
        if page == 4 {
            end = f281_paragraph(&mut d, &mut n, "F281_AUTH_RANGE_END", false);
        }
        if changed && page == 5 {
            f281_field(
                &mut d,
                &mut n,
                "SRC_MUT_TA_BETA_5 ",
                r#"TA \l "Beta v. Delta, 200 F.3d 300 (2001)" \s "Beta" \c 1"#,
                "OLD_TA_MUT_BETA_5",
                true,
            )?;
            f281_field(
                &mut d,
                &mut n,
                "SRC_MUT_TA_AARDVARK ",
                r#"TA \l "Aardvark v. New, 500 F.3d 600 (2004)" \s "Aardvark" \c 1"#,
                "OLD_TA_MUT_AARDVARK",
                true,
            )?;
        }
    }
    d.add_bookmark(
        "F281AuthorityRange",
        RunRange {
            start: RunPosition {
                body_index: start,
                run_index: 0,
            },
            end: RunPosition {
                body_index: end,
                run_index: 1,
            },
        },
    )?;
    f281_paragraph(&mut d, &mut n, "GENERATED_RESULTS_ONLY", true);
    f281_output(&mut d, &mut n, "TOA_CASES", r#"TOA \c 1 \h"#)?;
    f281_output(&mut d, &mut n, "TOA_PASSIM", r#"TOA \c 1 \h \p"#)?;
    f281_output(
        &mut d,
        &mut n,
        "TOA_SEPARATORS",
        r#"TOA \c 1 \e " | " \l "; " \g " to ""#,
    )?;
    f281_output(&mut d, &mut n, "TOA_STATUTES", r#"TOA \c 2 \h"#)?;
    f281_output(&mut d, &mut n, "TOA_TREATISES", r#"TOA \c 5 \h"#)?;
    f281_save(d)
}

// Captured using Word 16.113.2 build 16.113.26092012, en-US source language.
// Fresh F9 saves and independent no-F9 reopen receipts are retained under
// /private/tmp/S90-F281-oracle and /private/tmp/S90-Word-captures.
const WORD_F281_ORACLE: &str = "Microsoft Word 16.113.2 build 16.113.26092012";
const WORD_F281_LOCALE: &str = "en-US";

fn f281_cache_records(xml: &str) -> Vec<(String, Vec<String>)> {
    let mut reader = XmlReader::from_str(xml);
    reader.config_mut().trim_text(false);
    let mut buffer = Vec::new();
    let mut fields = Vec::<(String, bool, Vec<String>)>::new();
    let mut instruction = false;
    let mut text = false;
    let mut paragraph = String::new();
    let mut properties_depth = 0usize;
    let mut result = Vec::new();
    loop {
        match reader.read_event_into(&mut buffer).unwrap() {
            XmlEvent::Start(start) => match start.local_name().as_ref() {
                b"p" => paragraph.clear(),
                b"pPr" | b"rPr" => properties_depth += 1,
                b"instrText" => instruction = true,
                b"t" => text = true,
                _ => {}
            },
            XmlEvent::Empty(start) => match start.local_name().as_ref() {
                b"fldChar" => {
                    let kind = start
                        .attributes()
                        .flatten()
                        .find(|attribute| attribute.key.local_name().as_ref() == b"fldCharType")
                        .map(|attribute| String::from_utf8(attribute.value.into_owned()).unwrap());
                    match kind.as_deref() {
                        Some("begin") => fields.push((String::new(), false, Vec::new())),
                        Some("separate") => {
                            if let Some(field) = fields.last_mut() {
                                field.1 = true;
                            }
                        }
                        Some("end") => {
                            if let Some(field) = fields.pop()
                                && ["INDEX", "TOA", "TOC"].contains(
                                    &rdocx_oxml::text::Field::new(&field.0, "")
                                        .instruction
                                        .name
                                        .as_str(),
                                )
                            {
                                if !paragraph.is_empty() {
                                    let mut field = field;
                                    field.2.push(std::mem::take(&mut paragraph));
                                    result.push((field.0.trim().into(), field.2));
                                } else {
                                    result.push((field.0.trim().into(), field.2));
                                }
                            }
                        }
                        _ => {}
                    }
                }
                b"tab" if properties_depth == 0 && fields.iter().any(|field| field.1) => {
                    paragraph.push('\t')
                }
                b"br" if properties_depth == 0 && fields.iter().any(|field| field.1) => {
                    paragraph.push('\n')
                }
                _ => {}
            },
            XmlEvent::Text(value) => {
                let value = quick_xml::escape::unescape(&value.decode().unwrap())
                    .unwrap()
                    .into_owned();
                if instruction {
                    if let Some(field) = fields.last_mut() {
                        field.0.push_str(&value);
                    }
                } else if text && properties_depth == 0 && fields.iter().any(|field| field.1) {
                    paragraph.push_str(&value);
                }
            }
            XmlEvent::GeneralRef(reference) => {
                let encoded = format!("&{};", reference.decode().unwrap());
                let value = quick_xml::escape::unescape(&encoded).unwrap();
                if instruction {
                    if let Some(field) = fields.last_mut() {
                        field.0.push_str(&value);
                    }
                } else if text && properties_depth == 0 && fields.iter().any(|field| field.1) {
                    paragraph.push_str(&value);
                }
            }
            XmlEvent::End(end) => match end.local_name().as_ref() {
                b"pPr" | b"rPr" => properties_depth -= 1,
                b"instrText" => instruction = false,
                b"t" => text = false,
                b"p" => {
                    if !paragraph.is_empty()
                        && let Some(field) = fields.iter_mut().find(|field| {
                            field.1
                                && ["INDEX", "TOA", "TOC"].contains(
                                    &rdocx_oxml::text::Field::new(&field.0, "")
                                        .instruction
                                        .name
                                        .as_str(),
                                )
                        })
                    {
                        field.2.push(std::mem::take(&mut paragraph));
                    }
                }
                _ => {}
            },
            XmlEvent::Eof => break,
            _ => {}
        }
        buffer.clear();
    }
    assert!(fields.is_empty());
    result
}

